--
-- Name: listar_proyectos(); Type: FUNCTION; Schema: constructora; Owner: -
--

CREATE FUNCTION constructora.listar_proyectos() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
    v_result jsonb;
BEGIN

    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(

                -- ============================================
                -- PROYECTO
                -- ============================================

                'id', p.id,
                'titulo', p.titulo,
                'slug', p.slug,
                'descripcion', p.descripcion,
                'descripcion_corta', p.descripcion_corta,
                'ubicacion', p.ubicacion,
                'estado', p.estado,

                'fecha_inicio', p.fecha_inicio,
                'fecha_fin', p.fecha_fin,

                'progreso', p.progreso,

                'imagen_portada', p.imagen_portada,

                'destacado', p.destacado,
                'publicado', p.publicado,
                'orden', p.orden,

                'detalles', p.detalles,

                'created_at', p.created_at,
                'updated_at', p.updated_at,


                -- ============================================
                -- CRONOGRAMA / ACTIVIDADES
                -- ============================================

                'cronograma',
                COALESCE(
                    (
                        SELECT jsonb_agg(
                            jsonb_build_object(

                                'id', c.id,
                                'nombre', c.nombre,
                                'descripcion', c.descripcion,
                                'fecha_inicio', c.fecha_inicio,
                                'fecha_fin', c.fecha_fin,
                                'progreso', c.progreso,
                                'orden', c.orden,
                                'detalles', c.detalles,
                                'created_at', c.created_at,
                                'updated_at', c.updated_at,


                                -- ====================================
                                -- AVANCES DE ESTA ACTIVIDAD
                                -- ====================================

                                'avances',
                                COALESCE(
                                    (
                                        SELECT jsonb_agg(
                                            jsonb_build_object(

                                                'id', a.id,
                                                'proyecto_id', a.proyecto_id,
                                                'cronograma_id', a.cronograma_id,
                                                'titulo', a.titulo,
                                                'descripcion', a.descripcion,
                                                'fecha', a.fecha,
                                                'publicado', a.publicado,
                                                'created_at', a.created_at,
                                                'updated_at', a.updated_at,


                                                -- ====================
                                                -- IMÁGENES DEL AVANCE
                                                -- ====================

                                                'imagenes',
                                                COALESCE(
                                                    (
                                                        SELECT jsonb_agg(
                                                            jsonb_build_object(
                                                                'id', ai.id,
                                                                'imagen_origen_id', ai.imagen_origen_id,
                                                                'url', ai.url,
                                                                'descripcion', ai.descripcion,
                                                                'orden', ai.orden,
                                                                'created_at', ai.created_at
                                                            )
                                                            ORDER BY
                                                                ai.orden,
                                                                ai.created_at
                                                        )
                                                        FROM constructora.avance_imagenes ai
                                                        WHERE ai.avance_id = a.id
                                                    ),
                                                    '[]'::jsonb
                                                )

                                            )
                                            ORDER BY
                                                a.fecha DESC,
                                                a.created_at DESC
                                        )
                                        FROM constructora.avances a
                                        WHERE a.cronograma_id = c.id
                                    ),
                                    '[]'::jsonb
                                )

                            )
                            ORDER BY
                                c.orden,
                                c.fecha_inicio
                        )
                        FROM constructora.cronograma c
                        WHERE c.proyecto_id = p.id
                    ),
                    '[]'::jsonb
                ),


                -- ============================================
                -- GALERÍA
                -- ============================================

                'imagenes',
                COALESCE(
                    (
                        SELECT jsonb_agg(
                            jsonb_build_object(
                                'id', i.id,
                                'url', i.url,
                                'titulo', i.titulo,
                                'descripcion', i.descripcion,
                                'tipo', i.tipo,
                                'orden', i.orden,
                                'publicada', i.publicada,
                                'created_at', i.created_at
                            )
                            ORDER BY
                                i.orden,
                                i.created_at
                        )
                        FROM constructora.proyecto_imagenes i
                        WHERE i.proyecto_id = p.id
                    ),
                    '[]'::jsonb
                ),


                -- ============================================
                -- IMÁGENES PENDIENTES
                -- ============================================

                'imagenes_pendientes',
                COALESCE(
                    (
                        SELECT jsonb_agg(
                            jsonb_build_object(
                                'id', ip.id,
                                'archivo', ip.archivo,
                                'url_temporal', ip.url_temporal,
                                'url_editada', ip.url_editada,
                                'titulo', ip.titulo,
                                'descripcion', ip.descripcion,
                                'estado', ip.estado,
                                'created_at', ip.created_at,
                                'revisado_at', ip.revisado_at
                            )
                            ORDER BY ip.created_at DESC
                        )
                        FROM constructora.imagenes_pendientes ip
                        WHERE ip.proyecto_id = p.id
                    ),
                    '[]'::jsonb
                )

            )
            ORDER BY
                p.orden,
                p.created_at DESC
        ),
        '[]'::jsonb
    )
    INTO v_result

    FROM constructora.proyectos p;

    RETURN v_result;

END;
$$;


--
-- Name: listar_proyectos_publicos(); Type: FUNCTION; Schema: constructora; Owner: -
--

CREATE FUNCTION constructora.listar_proyectos_publicos() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
    v_result jsonb;
BEGIN

    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(

                -- ============================================
                -- PROYECTO
                -- ============================================

                'id', p.id,
                'titulo', p.titulo,
                'slug', p.slug,
                'descripcion', p.descripcion,
                'descripcion_corta', p.descripcion_corta,
                'ubicacion', p.ubicacion,
                'estado', p.estado,

                'fecha_inicio', p.fecha_inicio,
                'fecha_fin', p.fecha_fin,

                'progreso', p.progreso,

                'imagen_portada', p.imagen_portada,

                'destacado', p.destacado,
                'orden', p.orden,

                'detalles', p.detalles,


                -- ============================================
                -- CRONOGRAMA / ACTIVIDADES
                -- ============================================

                'cronograma',
                COALESCE(
                    (
                        SELECT jsonb_agg(
                            jsonb_build_object(

                                'id', c.id,
                                'nombre', c.nombre,
                                'descripcion', c.descripcion,
                                'fecha_inicio', c.fecha_inicio,
                                'fecha_fin', c.fecha_fin,
                                'progreso', c.progreso,
                                'orden', c.orden,
                                'detalles', c.detalles,


                                -- ====================================
                                -- AVANCES PUBLICADOS DE LA ACTIVIDAD
                                -- ====================================

                                'avances',
                                COALESCE(
                                    (
                                        SELECT jsonb_agg(
                                            jsonb_build_object(

                                                'id', a.id,
                                                'titulo', a.titulo,
                                                'descripcion', a.descripcion,
                                                'fecha', a.fecha,

                                                -- ====================
                                                -- IMÁGENES DEL AVANCE
                                                -- ====================

                                                'imagenes',
                                                COALESCE(
                                                    (
                                                        SELECT jsonb_agg(
                                                            jsonb_build_object(
                                                                'id', ai.id,
                                                                'url', ai.url,
                                                                'descripcion', ai.descripcion,
                                                                'orden', ai.orden
                                                            )
                                                            ORDER BY
                                                                ai.orden,
                                                                ai.created_at
                                                        )
                                                        FROM constructora.avance_imagenes ai
                                                        WHERE ai.avance_id = a.id
                                                    ),
                                                    '[]'::jsonb
                                                )

                                            )
                                            ORDER BY
                                                a.fecha DESC,
                                                a.created_at DESC
                                        )
                                        FROM constructora.avances a
                                        WHERE a.cronograma_id = c.id
                                          AND a.publicado = true
                                    ),
                                    '[]'::jsonb
                                )

                            )
                            ORDER BY
                                c.orden,
                                c.fecha_inicio
                        )
                        FROM constructora.cronograma c
                        WHERE c.proyecto_id = p.id
                    ),
                    '[]'::jsonb
                ),


                -- ============================================
                -- GALERÍA / PORTADA
                -- ============================================

                'imagenes',
                COALESCE(
                    (
                        SELECT jsonb_agg(
                            jsonb_build_object(
                                'id', i.id,
                                'url', i.url,
                                'titulo', i.titulo,
                                'descripcion', i.descripcion,
                                'tipo', i.tipo,
                                'orden', i.orden
                            )
                            ORDER BY
                                CASE
                                    WHEN i.tipo = 'portada' THEN 0
                                    ELSE 1
                                END,
                                i.orden,
                                i.created_at
                        )
                        FROM constructora.proyecto_imagenes i
                        WHERE i.proyecto_id = p.id
                          AND i.publicada = true
                    ),
                    '[]'::jsonb
                )

            )
            ORDER BY
                p.destacado DESC,
                p.orden,
                p.created_at DESC
        ),
        '[]'::jsonb
    )
    INTO v_result

    FROM constructora.proyectos p

    WHERE p.publicado = true;


    RETURN v_result;

END;
$$;


--
-- Name: obtener_plan_secretaria(); Type: FUNCTION; Schema: constructora; Owner: -
--

CREATE FUNCTION constructora.obtener_plan_secretaria() RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_resultado jsonb;
BEGIN

    SELECT jsonb_build_object(
        'id', ps.id,
        'estado', ps.estado,
        'plan', ps.plan,
        'creado_at', ps.creado_at,
        'actualizado_at', ps.actualizado_at
    )
    INTO v_resultado
    FROM constructora.plan_secretaria ps
    WHERE ps.estado = 'consulta'
    ORDER BY ps.actualizado_at DESC
    LIMIT 1;


    RETURN v_resultado;

END;
$$;


--
-- Name: recalcular_progreso_actividad(uuid); Type: FUNCTION; Schema: constructora; Owner: -
--

CREATE FUNCTION constructora.recalcular_progreso_actividad(p_cronograma_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_total_avances integer;
    v_avances_con_imagen integer;
    v_progreso integer;
BEGIN

    -- Total de avances definidos para esta actividad
    SELECT COUNT(*)
    INTO v_total_avances
    FROM constructora.avances a
    WHERE a.cronograma_id = p_cronograma_id;


    -- Avances que tienen AL MENOS una imagen
    SELECT COUNT(*)
    INTO v_avances_con_imagen
    FROM constructora.avances a
    WHERE a.cronograma_id = p_cronograma_id
      AND EXISTS (
          SELECT 1
          FROM constructora.avance_imagenes ai
          WHERE ai.avance_id = a.id
      );


    -- Si todavía no existen avances, progreso = 0
    IF v_total_avances = 0 THEN
        v_progreso := 0;
    ELSE
        v_progreso := ROUND(
            (v_avances_con_imagen::numeric / v_total_avances::numeric) * 100
        )::integer;
    END IF;


    -- Actualizar actividad
    UPDATE constructora.cronograma
    SET
        progreso = v_progreso,
        updated_at = now()
    WHERE id = p_cronograma_id;

END;
$$;


--
-- Name: registrar_conversacion_secretaria(text, text, jsonb); Type: FUNCTION; Schema: constructora; Owner: -
--

CREATE FUNCTION constructora.registrar_conversacion_secretaria(p_mensaje_jefe text, p_respuesta_secretaria text, p_memoria_semantica jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'constructora', 'public'
    AS $$
DECLARE
    v_id uuid;
    v_creado_at timestamptz;
BEGIN
    IF p_mensaje_jefe IS NULL
       OR btrim(p_mensaje_jefe) = '' THEN
        RAISE EXCEPTION
            'agenda_CONVERSACION_MENSAJE_REQUERIDO';
    END IF;

    IF p_respuesta_secretaria IS NULL
       OR btrim(p_respuesta_secretaria) = '' THEN
        RAISE EXCEPTION
            'agenda_CONVERSACION_RESPUESTA_REQUERIDA';
    END IF;

    IF p_memoria_semantica IS NULL THEN
        p_memoria_semantica := '[]'::jsonb;
    END IF;

    IF jsonb_typeof(p_memoria_semantica) <> 'array' THEN
        RAISE EXCEPTION
            'agenda_CONVERSACION_MEMORIA_DEBE_SER_ARRAY';
    END IF;

    INSERT INTO constructora.conversacion_secretaria (
        mensaje_jefe,
        respuesta_secretaria,
        memoria_semantica
    )
    VALUES (
        btrim(p_mensaje_jefe),
        btrim(p_respuesta_secretaria),
        p_memoria_semantica
    )
    RETURNING id, creado_at
    INTO v_id, v_creado_at;

    RETURN jsonb_build_object(
        'ok', true,
        'id', v_id,
        'creado_at', v_creado_at
    );
END;
$$;


--
-- Name: retroceder_avance(uuid); Type: FUNCTION; Schema: constructora; Owner: -
--

CREATE FUNCTION constructora.retroceder_avance(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_result jsonb;
BEGIN

    UPDATE constructora.avances
    SET
        publicado = false,
        updated_at = now()
    WHERE id = p_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Avance no encontrado: %', p_id;
    END IF;

    SELECT jsonb_build_object(
        'id', a.id,
        'proyecto_id', a.proyecto_id,
        'titulo', a.titulo,
        'descripcion', a.descripcion,
        'fecha', a.fecha,
        'publicado', a.publicado,
        'created_at', a.created_at,
        'updated_at', a.updated_at
    )
    INTO v_result
    FROM constructora.avances a
    WHERE a.id = p_id;

    RETURN v_result;

END;
$$;


--
-- Name: trigger_recalcular_progreso_actividad(); Type: FUNCTION; Schema: constructora; Owner: -
--

CREATE FUNCTION constructora.trigger_recalcular_progreso_actividad() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_cronograma_id uuid;
BEGIN

    -- --------------------------------------------------------
    -- DELETE
    -- --------------------------------------------------------

    IF TG_OP = 'DELETE' THEN

        SELECT cronograma_id
        INTO v_cronograma_id
        FROM constructora.avances
        WHERE id = OLD.avance_id;

        IF v_cronograma_id IS NOT NULL THEN
            PERFORM constructora.recalcular_progreso_actividad(
                v_cronograma_id
            );
        END IF;

        RETURN OLD;

    END IF;


    -- --------------------------------------------------------
    -- INSERT
    -- --------------------------------------------------------

    IF TG_OP = 'INSERT' THEN

        SELECT cronograma_id
        INTO v_cronograma_id
        FROM constructora.avances
        WHERE id = NEW.avance_id;

        IF v_cronograma_id IS NOT NULL THEN
            PERFORM constructora.recalcular_progreso_actividad(
                v_cronograma_id
            );
        END IF;

        RETURN NEW;

    END IF;


    -- --------------------------------------------------------
    -- UPDATE
    -- --------------------------------------------------------

    IF TG_OP = 'UPDATE' THEN

        -- Si una imagen cambia de avance,
        -- recalculamos primero el avance anterior.

        IF OLD.avance_id IS DISTINCT FROM NEW.avance_id THEN

            SELECT cronograma_id
            INTO v_cronograma_id
            FROM constructora.avances
            WHERE id = OLD.avance_id;

            IF v_cronograma_id IS NOT NULL THEN
                PERFORM constructora.recalcular_progreso_actividad(
                    v_cronograma_id
                );
            END IF;

        END IF;


        -- Recalcular actividad actual

        SELECT cronograma_id
        INTO v_cronograma_id
        FROM constructora.avances
        WHERE id = NEW.avance_id;

        IF v_cronograma_id IS NOT NULL THEN
            PERFORM constructora.recalcular_progreso_actividad(
                v_cronograma_id
            );
        END IF;

        RETURN NEW;

    END IF;


    RETURN NULL;

END;
$$;


--
-- Name: upsert_avance(jsonb); Type: FUNCTION; Schema: constructora; Owner: -
--

CREATE FUNCTION constructora.upsert_avance(p_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_id uuid;
    v_proyecto_id uuid;
    v_cronograma_id uuid;
    v_cronograma_anterior_id uuid;
    v_result jsonb;
BEGIN

    -- ========================================================
    -- UPDATE
    -- ========================================================

    IF NULLIF(p_data->>'id', '') IS NOT NULL THEN

        v_id := (p_data->>'id')::uuid;

        -- Obtener estado actual
        SELECT
            proyecto_id,
            cronograma_id
        INTO
            v_proyecto_id,
            v_cronograma_anterior_id
        FROM constructora.avances
        WHERE id = v_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Avance no encontrado: %', v_id;
        END IF;

        -- Por defecto conserva su actividad actual
        v_cronograma_id := v_cronograma_anterior_id;


        -- ====================================================
        -- CAMBIO DE ACTIVIDAD
        -- ====================================================

        IF p_data ? 'cronograma_id' THEN

            v_cronograma_id :=
                NULLIF(p_data->>'cronograma_id', '')::uuid;

            IF v_cronograma_id IS NULL THEN
                RAISE EXCEPTION 'cronograma_id es obligatorio';
            END IF;

            -- La actividad debe pertenecer al mismo proyecto
            IF NOT EXISTS (
                SELECT 1
                FROM constructora.cronograma c
                WHERE c.id = v_cronograma_id
                  AND c.proyecto_id = v_proyecto_id
            ) THEN
                RAISE EXCEPTION
                    'La actividad no existe o pertenece a otro proyecto';
            END IF;

        END IF;


        -- ====================================================
        -- ACTUALIZAR AVANCE
        -- ====================================================

        UPDATE constructora.avances
        SET
            cronograma_id = v_cronograma_id,

            titulo = CASE
                WHEN p_data ? 'titulo'
                    THEN NULLIF(TRIM(p_data->>'titulo'), '')
                ELSE titulo
            END,

            descripcion = CASE
                WHEN p_data ? 'descripcion'
                    THEN NULLIF(p_data->>'descripcion', '')
                ELSE descripcion
            END,

            fecha = CASE
                WHEN p_data ? 'fecha'
                    THEN NULLIF(p_data->>'fecha', '')::date
                ELSE fecha
            END,

            publicado = CASE
                WHEN p_data ? 'publicado'
                    THEN (p_data->>'publicado')::boolean
                ELSE publicado
            END,

            updated_at = now()

        WHERE id = v_id;


        -- ====================================================
        -- RECALCULAR SI CAMBIÓ DE ACTIVIDAD
        -- ====================================================

        IF v_cronograma_anterior_id
            IS DISTINCT FROM v_cronograma_id
        THEN

            -- Actividad de donde salió
            PERFORM constructora.recalcular_progreso_actividad(
                v_cronograma_anterior_id
            );

            -- Actividad a donde llegó
            PERFORM constructora.recalcular_progreso_actividad(
                v_cronograma_id
            );

        END IF;


    -- ========================================================
    -- INSERT
    -- ========================================================

    ELSE

        IF NULLIF(p_data->>'proyecto_id', '') IS NULL THEN
            RAISE EXCEPTION 'proyecto_id es obligatorio';
        END IF;

        IF NULLIF(p_data->>'cronograma_id', '') IS NULL THEN
            RAISE EXCEPTION 'cronograma_id es obligatorio';
        END IF;


        v_proyecto_id :=
            (p_data->>'proyecto_id')::uuid;

        v_cronograma_id :=
            (p_data->>'cronograma_id')::uuid;


        -- Verificar proyecto
        IF NOT EXISTS (
            SELECT 1
            FROM constructora.proyectos
            WHERE id = v_proyecto_id
        ) THEN
            RAISE EXCEPTION 'Proyecto no encontrado';
        END IF;


        -- Verificar actividad y pertenencia
        IF NOT EXISTS (
            SELECT 1
            FROM constructora.cronograma c
            WHERE c.id = v_cronograma_id
              AND c.proyecto_id = v_proyecto_id
        ) THEN
            RAISE EXCEPTION
                'La actividad no existe o pertenece a otro proyecto';
        END IF;


        INSERT INTO constructora.avances (
            proyecto_id,
            cronograma_id,
            titulo,
            descripcion,
            fecha,
            publicado
        )
        VALUES (
            v_proyecto_id,
            v_cronograma_id,

            NULLIF(
                TRIM(p_data->>'titulo'),
                ''
            ),

            NULLIF(
                p_data->>'descripcion',
                ''
            ),

            COALESCE(
                NULLIF(p_data->>'fecha', '')::date,
                CURRENT_DATE
            ),

            COALESCE(
                (p_data->>'publicado')::boolean,
                true
            )
        )
        RETURNING id INTO v_id;


        -- ====================================================
        -- NUEVO AVANCE = CAMBIÓ EL DENOMINADOR
        -- ====================================================

        PERFORM constructora.recalcular_progreso_actividad(
            v_cronograma_id
        );

    END IF;


    -- ========================================================
    -- RESPUESTA COMPLETA
    -- ========================================================

    SELECT jsonb_build_object(
        'id', a.id,
        'proyecto_id', a.proyecto_id,
        'cronograma_id', a.cronograma_id,
        'titulo', a.titulo,
        'descripcion', a.descripcion,
        'fecha', a.fecha,
        'publicado', a.publicado,
        'created_at', a.created_at,
        'updated_at', a.updated_at,

        'imagenes',
        COALESCE(
            (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'id', ai.id,
                        'imagen_origen_id', ai.imagen_origen_id,
                        'url', ai.url,
                        'descripcion', ai.descripcion,
                        'orden', ai.orden,
                        'created_at', ai.created_at
                    )
                    ORDER BY ai.orden, ai.created_at
                )
                FROM constructora.avance_imagenes ai
                WHERE ai.avance_id = a.id
            ),
            '[]'::jsonb
        )
    )
    INTO v_result
    FROM constructora.avances a
    WHERE a.id = v_id;


    RETURN v_result;

END;
$$;


--
-- Name: upsert_cronograma(jsonb); Type: FUNCTION; Schema: constructora; Owner: -
--

CREATE FUNCTION constructora.upsert_cronograma(p_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_id uuid;
    v_proyecto_id uuid;
    v_result jsonb;
BEGIN

    -- ========================================================
    -- UPDATE
    -- ========================================================

    IF NULLIF(p_data->>'id', '') IS NOT NULL THEN

        v_id := (p_data->>'id')::uuid;

        -- Verificar existencia
        SELECT proyecto_id
        INTO v_proyecto_id
        FROM constructora.cronograma
        WHERE id = v_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION
                'Actividad de cronograma no encontrada: %', v_id;
        END IF;


        UPDATE constructora.cronograma
        SET
            nombre = CASE
                WHEN p_data ? 'nombre'
                    THEN NULLIF(TRIM(p_data->>'nombre'), '')
                ELSE nombre
            END,

            descripcion = CASE
                WHEN p_data ? 'descripcion'
                    THEN NULLIF(p_data->>'descripcion', '')
                ELSE descripcion
            END,

            fecha_inicio = CASE
                WHEN p_data ? 'fecha_inicio'
                    THEN NULLIF(p_data->>'fecha_inicio', '')::date
                ELSE fecha_inicio
            END,

            fecha_fin = CASE
                WHEN p_data ? 'fecha_fin'
                    THEN NULLIF(p_data->>'fecha_fin', '')::date
                ELSE fecha_fin
            END,

            -- progreso NO se modifica manualmente

            orden = CASE
                WHEN p_data ? 'orden'
                    THEN (p_data->>'orden')::integer
                ELSE orden
            END,

            detalles = CASE
                WHEN p_data ? 'detalles'
                    THEN COALESCE(
                        p_data->'detalles',
                        '{}'::jsonb
                    )
                ELSE detalles
            END,

            updated_at = now()

        WHERE id = v_id;


    -- ========================================================
    -- INSERT
    -- ========================================================

    ELSE

        IF NULLIF(p_data->>'proyecto_id', '') IS NULL THEN
            RAISE EXCEPTION 'proyecto_id es obligatorio';
        END IF;

        v_proyecto_id :=
            (p_data->>'proyecto_id')::uuid;


        IF COALESCE(TRIM(p_data->>'nombre'), '') = '' THEN
            RAISE EXCEPTION
                'El nombre de la actividad es obligatorio';
        END IF;


        IF NULLIF(p_data->>'fecha_inicio', '') IS NULL THEN
            RAISE EXCEPTION 'fecha_inicio es obligatoria';
        END IF;


        IF NULLIF(p_data->>'fecha_fin', '') IS NULL THEN
            RAISE EXCEPTION 'fecha_fin es obligatoria';
        END IF;


        INSERT INTO constructora.cronograma (
            proyecto_id,
            nombre,
            descripcion,
            fecha_inicio,
            fecha_fin,
            progreso,
            orden,
            detalles
        )
        VALUES (
            v_proyecto_id,
            TRIM(p_data->>'nombre'),
            NULLIF(p_data->>'descripcion', ''),
            (p_data->>'fecha_inicio')::date,
            (p_data->>'fecha_fin')::date,

            -- Una actividad siempre nace en 0
            0,

            COALESCE(
                (p_data->>'orden')::integer,
                0
            ),

            COALESCE(
                p_data->'detalles',
                '{}'::jsonb
            )
        )
        RETURNING id INTO v_id;

    END IF;


    -- ========================================================
    -- RESPUESTA
    -- ========================================================

    SELECT to_jsonb(c)
    INTO v_result
    FROM constructora.cronograma c
    WHERE c.id = v_id;

    RETURN v_result;

END;
$$;


--
-- Name: upsert_imagen_pendiente(jsonb); Type: FUNCTION; Schema: constructora; Owner: -
--

CREATE FUNCTION constructora.upsert_imagen_pendiente(p_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_id uuid;
    v_result jsonb;
BEGIN

    -- ========================================================
    -- UPDATE
    -- ========================================================

    IF NULLIF(p_data->>'id', '') IS NOT NULL THEN

        v_id := (p_data->>'id')::uuid;

        UPDATE constructora.imagenes_pendientes
        SET
            proyecto_id = CASE
                WHEN p_data ? 'proyecto_id'
                    THEN NULLIF(p_data->>'proyecto_id', '')::uuid
                ELSE proyecto_id
            END,

            archivo = CASE
                WHEN p_data ? 'archivo'
                    THEN NULLIF(TRIM(p_data->>'archivo'), '')
                ELSE archivo
            END,

            url_temporal = CASE
                WHEN p_data ? 'url_temporal'
                    THEN NULLIF(TRIM(p_data->>'url_temporal'), '')
                ELSE url_temporal
            END,

            titulo = CASE
                WHEN p_data ? 'titulo'
                    THEN NULLIF(TRIM(p_data->>'titulo'), '')
                ELSE titulo
            END,

            descripcion = CASE
                WHEN p_data ? 'descripcion'
                    THEN NULLIF(p_data->>'descripcion', '')
                ELSE descripcion
            END

        WHERE id = v_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Imagen pendiente no encontrada: %', v_id;
        END IF;


    -- ========================================================
    -- INSERT
    -- ========================================================

    ELSE

        -- proyecto obligatorio
        IF NULLIF(p_data->>'proyecto_id', '') IS NULL THEN
            RAISE EXCEPTION 'proyecto_id es obligatorio';
        END IF;

        -- archivo obligatorio
        IF COALESCE(TRIM(p_data->>'archivo'), '') = '' THEN
            RAISE EXCEPTION 'archivo es obligatorio';
        END IF;

        -- URL temporal obligatoria
        IF COALESCE(TRIM(p_data->>'url_temporal'), '') = '' THEN
            RAISE EXCEPTION 'url_temporal es obligatoria';
        END IF;


        INSERT INTO constructora.imagenes_pendientes (
            proyecto_id,
            archivo,
            url_temporal,
            titulo,
            descripcion,
            estado
        )
        VALUES (
            (p_data->>'proyecto_id')::uuid,
            TRIM(p_data->>'archivo'),
            TRIM(p_data->>'url_temporal'),
            NULLIF(TRIM(p_data->>'titulo'), ''),
            NULLIF(p_data->>'descripcion', ''),
            'pendiente'
        )
        RETURNING id INTO v_id;

    END IF;


    -- ========================================================
    -- RESPUESTA
    -- ========================================================

    SELECT to_jsonb(ip)
    INTO v_result
    FROM constructora.imagenes_pendientes ip
    WHERE ip.id = v_id;

    RETURN v_result;

END;
$$;


--
-- Name: upsert_proyecto(jsonb); Type: FUNCTION; Schema: constructora; Owner: -
--

CREATE FUNCTION constructora.upsert_proyecto(p_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_id uuid;
    v_result jsonb;
BEGIN

    -- ========================================================
    -- UPDATE
    -- ========================================================

    IF NULLIF(p_data->>'id', '') IS NOT NULL THEN

        v_id := (p_data->>'id')::uuid;

        UPDATE constructora.proyectos
        SET
            titulo = CASE
                WHEN p_data ? 'titulo'
                    THEN COALESCE(NULLIF(TRIM(p_data->>'titulo'), ''), titulo)
                ELSE titulo
            END,

            slug = CASE
                WHEN p_data ? 'slug'
                    THEN COALESCE(NULLIF(TRIM(p_data->>'slug'), ''), slug)
                ELSE slug
            END,

            descripcion = CASE
                WHEN p_data ? 'descripcion'
                    THEN NULLIF(p_data->>'descripcion', '')
                ELSE descripcion
            END,

            descripcion_corta = CASE
                WHEN p_data ? 'descripcion_corta'
                    THEN NULLIF(p_data->>'descripcion_corta', '')
                ELSE descripcion_corta
            END,

            ubicacion = CASE
                WHEN p_data ? 'ubicacion'
                    THEN NULLIF(p_data->>'ubicacion', '')
                ELSE ubicacion
            END,

            estado = CASE
                WHEN p_data ? 'estado'
                    THEN COALESCE(NULLIF(p_data->>'estado', ''), estado)
                ELSE estado
            END,

            fecha_inicio = CASE
                WHEN p_data ? 'fecha_inicio'
                    THEN NULLIF(p_data->>'fecha_inicio', '')::date
                ELSE fecha_inicio
            END,

            fecha_fin = CASE
                WHEN p_data ? 'fecha_fin'
                    THEN NULLIF(p_data->>'fecha_fin', '')::date
                ELSE fecha_fin
            END,

            imagen_portada = CASE
                WHEN p_data ? 'imagen_portada'
                    THEN NULLIF(p_data->>'imagen_portada', '')
                ELSE imagen_portada
            END,

            destacado = CASE
                WHEN p_data ? 'destacado'
                    THEN (p_data->>'destacado')::boolean
                ELSE destacado
            END,

            publicado = CASE
                WHEN p_data ? 'publicado'
                    THEN (p_data->>'publicado')::boolean
                ELSE publicado
            END,

            orden = CASE
                WHEN p_data ? 'orden'
                    THEN (p_data->>'orden')::integer
                ELSE orden
            END,

            detalles = CASE
                WHEN p_data ? 'detalles'
                    THEN COALESCE(p_data->'detalles', '{}'::jsonb)
                ELSE detalles
            END,

            updated_at = now()

        WHERE id = v_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Proyecto no encontrado: %', v_id;
        END IF;


    -- ========================================================
    -- INSERT
    -- ========================================================

    ELSE

        -- Solo al crear son obligatorios
        IF COALESCE(TRIM(p_data->>'titulo'), '') = '' THEN
            RAISE EXCEPTION 'El titulo es obligatorio';
        END IF;

        IF COALESCE(TRIM(p_data->>'slug'), '') = '' THEN
            RAISE EXCEPTION 'El slug es obligatorio';
        END IF;


        INSERT INTO constructora.proyectos (
            titulo,
            slug,
            descripcion,
            descripcion_corta,
            ubicacion,
            estado,
            fecha_inicio,
            fecha_fin,
            imagen_portada,
            destacado,
            publicado,
            orden,
            detalles
        )
        VALUES (
            TRIM(p_data->>'titulo'),
            TRIM(p_data->>'slug'),
            NULLIF(p_data->>'descripcion', ''),
            NULLIF(p_data->>'descripcion_corta', ''),
            NULLIF(p_data->>'ubicacion', ''),

            COALESCE(
                NULLIF(p_data->>'estado', ''),
                'en_construccion'
            ),

            NULLIF(p_data->>'fecha_inicio', '')::date,
            NULLIF(p_data->>'fecha_fin', '')::date,
            NULLIF(p_data->>'imagen_portada', ''),

            COALESCE(
                (p_data->>'destacado')::boolean,
                false
            ),

            COALESCE(
                (p_data->>'publicado')::boolean,
                false
            ),

            COALESCE(
                (p_data->>'orden')::integer,
                0
            ),

            COALESCE(
                p_data->'detalles',
                '{}'::jsonb
            )
        )

        RETURNING id INTO v_id;

    END IF;


    -- ========================================================
    -- RESPUESTA
    -- ========================================================

    SELECT to_jsonb(p)
    INTO v_result
    FROM constructora.proyectos p
    WHERE p.id = v_id;

    RETURN v_result;

END;
$$;


