-- Name: depositos; Type: TABLE; Schema: reciclaje; Owner: -
--

CREATE TABLE reciclaje.depositos (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    codigo text NOT NULL,
    nombre text NOT NULL,
    direccion text,
    activo boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: actualizar_deposito(uuid, uuid, text, text); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.actualizar_deposito(p_company_id uuid, p_id uuid, p_nombre text, p_direccion text) RETURNS reciclaje.depositos
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE

    v_deposito reciclaje.depositos;

BEGIN

    IF trim(p_nombre) = '' THEN
        RAISE EXCEPTION 'El nombre es obligatorio.';
    END IF;

    UPDATE reciclaje.depositos

    SET

        nombre = trim(p_nombre),

        direccion = nullif(trim(p_direccion), ''),

        updated_at = now()

    WHERE company_id = p_company_id
      AND id = p_id

    RETURNING *
    INTO v_deposito;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Depósito no encontrado.';
    END IF;

    RETURN v_deposito;

END;
$$;


--
-- Name: finanzas; Type: TABLE; Schema: reciclaje; Owner: -
--

CREATE TABLE reciclaje.finanzas (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    origen_tipo text DEFAULT 'manual'::text,
    origen_id uuid,
    fecha_emision timestamp with time zone DEFAULT now() NOT NULL,
    fecha_vencimiento timestamp with time zone,
    tipo_cambio numeric(14,6) NOT NULL,
    importe_base numeric(14,2) NOT NULL,
    observaciones text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    tipo text NOT NULL,
    anulado boolean DEFAULT false NOT NULL,
    responsable_nombre text,
    responsable_telefono text,
    responsable_tipo text,
    CONSTRAINT finanzas_importe_base_check CHECK ((importe_base >= (0)::numeric)),
    CONSTRAINT finanzas_origen_tipo_check CHECK ((origen_tipo = ANY (ARRAY['manual'::text, 'orden_compra'::text, 'orden_venta'::text, 'recepcion'::text, 'gasto'::text, 'ingreso'::text, 'prestamo'::text, 'ajuste'::text]))),
    CONSTRAINT finanzas_tipo_cambio_check CHECK ((tipo_cambio > (0)::numeric)),
    CONSTRAINT finanzas_tipo_check CHECK ((tipo = ANY (ARRAY['cxp'::text, 'cxc'::text])))
);


--
-- Name: actualizar_finanza(uuid, uuid, text, numeric, numeric, text, uuid, timestamp with time zone, text, text, text, text); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.actualizar_finanza(p_company_id uuid, p_finanza_id uuid, p_tipo text, p_tipo_cambio numeric, p_importe_base numeric, p_origen_tipo text DEFAULT 'manual'::text, p_origen_id uuid DEFAULT NULL::uuid, p_fecha_vencimiento timestamp with time zone DEFAULT NULL::timestamp with time zone, p_observaciones text DEFAULT NULL::text, p_responsable_nombre text DEFAULT NULL::text, p_responsable_telefono text DEFAULT NULL::text, p_responsable_tipo text DEFAULT NULL::text) RETURNS reciclaje.finanzas
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_finanza reciclaje.finanzas;
BEGIN

    UPDATE reciclaje.finanzas
       SET tipo = p_tipo,
           origen_tipo = p_origen_tipo,
           origen_id = p_origen_id,
           fecha_vencimiento = p_fecha_vencimiento,
           tipo_cambio = p_tipo_cambio,
           importe_base = p_importe_base,
           observaciones = p_observaciones,
           responsable_nombre = p_responsable_nombre,
           responsable_telefono = p_responsable_telefono,
           responsable_tipo = p_responsable_tipo
     WHERE id = p_finanza_id
       AND company_id = p_company_id
    RETURNING *
      INTO v_finanza;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Finanza no encontrada.';
    END IF;

    RETURN v_finanza;

END;
$$;


--
-- Name: materiales; Type: TABLE; Schema: reciclaje; Owner: -
--

CREATE TABLE reciclaje.materiales (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    codigo text NOT NULL,
    nombre text NOT NULL,
    unidad text DEFAULT 'kg'::text NOT NULL,
    stock numeric(14,3) DEFAULT 0 NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    activo boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    precio_base numeric(14,2) DEFAULT 0 NOT NULL,
    precio_mayorista numeric(14,2) DEFAULT 0 NOT NULL,
    imagen_url text,
    compuesto boolean DEFAULT false NOT NULL,
    CONSTRAINT materiales_precio_base_check CHECK ((precio_base >= (0)::numeric)),
    CONSTRAINT materiales_precio_mayorista_check CHECK ((precio_mayorista >= (0)::numeric))
);


--
-- Name: actualizar_material(uuid, uuid, text, text, jsonb, numeric, numeric, text); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.actualizar_material(p_company_id uuid, p_id uuid, p_nombre text, p_unidad text, p_metadata jsonb, p_precio_base numeric DEFAULT 0, p_precio_mayorista numeric DEFAULT 0, p_imagen_url text DEFAULT NULL::text) RETURNS reciclaje.materiales
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE

    v_material reciclaje.materiales;

BEGIN

    IF trim(p_nombre) = '' THEN
        RAISE EXCEPTION 'El nombre es obligatorio.';
    END IF;

    IF trim(p_unidad) = '' THEN
        RAISE EXCEPTION 'La unidad es obligatoria.';
    END IF;

    IF coalesce(p_precio_base, 0) < 0 THEN
        RAISE EXCEPTION 'El precio base no puede ser negativo.';
    END IF;

    IF coalesce(p_precio_mayorista, 0) < 0 THEN
        RAISE EXCEPTION 'El precio mayorista no puede ser negativo.';
    END IF;

    UPDATE reciclaje.materiales

    SET
        nombre = trim(p_nombre),

        unidad = lower(trim(p_unidad)),

        metadata = coalesce(p_metadata, '{}'),

        precio_base = coalesce(p_precio_base, 0),

        precio_mayorista = coalesce(p_precio_mayorista, 0),

        imagen_url = CASE
            WHEN p_imagen_url IS NULL
                THEN imagen_url
            ELSE reciclaje.texto_nulo(p_imagen_url)
        END,

        updated_at = now()

    WHERE company_id = p_company_id
      AND id = p_id

    RETURNING *
    INTO v_material;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Material no encontrado.';
    END IF;

    RETURN v_material;

END;
$$;


--
-- Name: ordenes_compra; Type: TABLE; Schema: reciclaje; Owner: -
--

CREATE TABLE reciclaje.ordenes_compra (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    codigo text NOT NULL,
    socio_id uuid NOT NULL,
    transportista_id uuid NOT NULL,
    estado reciclaje.estado_orden DEFAULT 'borrador'::reciclaje.estado_orden NOT NULL,
    observaciones text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    subtotal numeric(14,2) DEFAULT 0 NOT NULL,
    total numeric(14,2) DEFAULT 0 NOT NULL
);


--
-- Name: actualizar_orden_compra(uuid, uuid, jsonb); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.actualizar_orden_compra(p_company_id uuid, p_orden_id uuid, p_orden jsonb) RETURNS reciclaje.ordenes_compra
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE

    v_orden reciclaje.ordenes_compra;

    v_material jsonb;

    v_pago jsonb;

    v_subtotal numeric(14,2) := 0;

BEGIN

    ----------------------------------------------------
    -- Buscar orden
    ----------------------------------------------------

    SELECT *
    INTO v_orden
    FROM reciclaje.ordenes_compra
    WHERE company_id = p_company_id
      AND id = p_orden_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'La orden de compra no existe.';
    END IF;

    IF v_orden.estado <> 'borrador' THEN
        RAISE EXCEPTION 'La orden ya no puede modificarse.';
    END IF;

    ----------------------------------------------------
    -- Actualizar cabecera
    ----------------------------------------------------

    UPDATE reciclaje.ordenes_compra

    SET

        socio_id = (p_orden->>'socio_id')::uuid,

        transportista_id = (p_orden->>'transportista_id')::uuid,

        observaciones = reciclaje.texto_nulo(
            p_orden->>'observaciones'
        ),

        updated_at = now()

    WHERE id = p_orden_id;

    ----------------------------------------------------
    -- Eliminar detalle anterior
    ----------------------------------------------------

    DELETE
    FROM reciclaje.ordenes_compra_detalle
    WHERE orden_compra_id = p_orden_id;

    ----------------------------------------------------
    -- Insertar nuevo detalle
    ----------------------------------------------------

    FOR v_material IN

        SELECT *
        FROM jsonb_array_elements(
            p_orden->'materiales'
        )

    LOOP

        INSERT INTO reciclaje.ordenes_compra_detalle(

            orden_compra_id,

            material_id,

            cantidad,

            precio_unitario,

            subtotal

        )

        VALUES(

            p_orden_id,

            (v_material->>'material_id')::uuid,

            (v_material->>'cantidad')::numeric,

            (v_material->>'precio_unitario')::numeric,

            (v_material->>'cantidad')::numeric
            *
            (v_material->>'precio_unitario')::numeric

        );

        v_subtotal :=

            v_subtotal +

            (

                (v_material->>'cantidad')::numeric

                *

                (v_material->>'precio_unitario')::numeric

            );

    END LOOP;

    ----------------------------------------------------
    -- Eliminar pagos anteriores
    ----------------------------------------------------

    DELETE
    FROM reciclaje.ordenes_compra_pagos
    WHERE orden_compra_id = p_orden_id;

    ----------------------------------------------------
    -- Insertar nuevos pagos
    ----------------------------------------------------

    FOR v_pago IN

        SELECT *
        FROM jsonb_array_elements(
            p_orden->'pagos'
        )

    LOOP

        INSERT INTO reciclaje.ordenes_compra_pagos(

            orden_compra_id,

            forma_pago_id,

            moneda_id,

            monto,

            referencia,

            observaciones

        )

        VALUES(

            p_orden_id,

            (v_pago->>'forma_pago_id')::uuid,

            (v_pago->>'moneda_id')::uuid,

            (v_pago->>'monto')::numeric,

            reciclaje.texto_nulo(
                v_pago->>'referencia'
            ),

            reciclaje.texto_nulo(
                v_pago->>'observaciones'
            )

        );

    END LOOP;

    ----------------------------------------------------
    -- Actualizar totales
    ----------------------------------------------------

    UPDATE reciclaje.ordenes_compra

    SET

        subtotal = v_subtotal,

        total = v_subtotal,

        updated_at = now()

    WHERE id = p_orden_id

    RETURNING *
    INTO v_orden;

    ----------------------------------------------------
    -- Resultado
    ----------------------------------------------------

    RETURN v_orden;

END;
$$;


--
-- Name: recepciones; Type: TABLE; Schema: reciclaje; Owner: -
--

CREATE TABLE reciclaje.recepciones (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    codigo text NOT NULL,
    orden_compra_id uuid NOT NULL,
    estado reciclaje.estado_recepcion DEFAULT 'borrador'::reciclaje.estado_recepcion NOT NULL,
    recibido_por text,
    observaciones text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    confirmed_at timestamp with time zone,
    deposito_id uuid
);


--
-- Name: actualizar_recepcion(uuid, uuid, jsonb); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.actualizar_recepcion(p_company_id uuid, p_recepcion_id uuid, p_recepcion jsonb) RETURNS reciclaje.recepciones
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE

    v_recepcion reciclaje.recepciones;

    v_material jsonb;

BEGIN

    SELECT *
    INTO v_recepcion
    FROM reciclaje.recepciones
    WHERE company_id = p_company_id
      AND id = p_recepcion_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'La recepción no existe.';
    END IF;

    IF v_recepcion.estado <> 'borrador' THEN
        RAISE EXCEPTION 'La recepción ya fue confirmada.';
    END IF;

    IF jsonb_array_length(
        coalesce(
            p_recepcion->'materiales',
            '[]'::jsonb
        )
    ) = 0 THEN

        RAISE EXCEPTION
        'La recepción debe contener al menos un material.';

    END IF;

    UPDATE reciclaje.recepciones

    SET

        deposito_id =
            nullif(p_recepcion->>'deposito_id', '')::uuid,

        recibido_por = reciclaje.texto_nulo(
            p_recepcion->>'recibido_por'
        ),

        observaciones = reciclaje.texto_nulo(
            p_recepcion->>'observaciones'
        )

    WHERE company_id = p_company_id
      AND id = p_recepcion_id;

    DELETE
    FROM reciclaje.recepciones_detalle
    WHERE recepcion_id = p_recepcion_id;

    FOR v_material IN

        SELECT *
        FROM jsonb_array_elements(
            p_recepcion->'materiales'
        )

    LOOP

        INSERT INTO reciclaje.recepciones_detalle (

            recepcion_id,

            material_id,

            cantidad,

            precio_unitario,

            subtotal,

            observaciones

        )
        VALUES (

            p_recepcion_id,

            (v_material->>'material_id')::uuid,

            (v_material->>'cantidad')::numeric,

            (v_material->>'precio_unitario')::numeric,

            (v_material->>'cantidad')::numeric
            *
            (v_material->>'precio_unitario')::numeric,

            reciclaje.texto_nulo(
                v_material->>'observaciones'
            )

        );

    END LOOP;

    SELECT *
    INTO v_recepcion
    FROM reciclaje.recepciones
    WHERE company_id = p_company_id
      AND id = p_recepcion_id;

    RETURN v_recepcion;

END;
$$;


--
-- Name: socios; Type: TABLE; Schema: reciclaje; Owner: -
--

CREATE TABLE reciclaje.socios (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    codigo text NOT NULL,
    nombre text NOT NULL,
    documento text,
    telefono text,
    direccion text,
    observaciones text,
    activo boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    latitud numeric(10,7),
    longitud numeric(10,7)
);


--
-- Name: actualizar_socio(uuid, uuid, text, text, text, text, text, numeric, numeric); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.actualizar_socio(p_company_id uuid, p_id uuid, p_nombre text, p_documento text DEFAULT NULL::text, p_telefono text DEFAULT NULL::text, p_direccion text DEFAULT NULL::text, p_observaciones text DEFAULT NULL::text, p_latitud numeric DEFAULT NULL::numeric, p_longitud numeric DEFAULT NULL::numeric) RETURNS reciclaje.socios
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE

    v_socio reciclaje.socios;

BEGIN

    IF trim(coalesce(p_nombre, '')) = '' THEN
        RAISE EXCEPTION 'El nombre es obligatorio.';
    END IF;

    ----------------------------------------------------
    -- Validar coordenadas
    ----------------------------------------------------

    IF p_latitud IS NOT NULL
       AND (p_latitud < -90 OR p_latitud > 90) THEN

        RAISE EXCEPTION
        'La latitud debe estar entre -90 y 90.';

    END IF;

    IF p_longitud IS NOT NULL
       AND (p_longitud < -180 OR p_longitud > 180) THEN

        RAISE EXCEPTION
        'La longitud debe estar entre -180 y 180.';

    END IF;

    ----------------------------------------------------
    -- Actualizar
    ----------------------------------------------------

    UPDATE reciclaje.socios

    SET
        nombre = trim(p_nombre),

        documento =
            reciclaje.texto_nulo(p_documento),

        telefono =
            reciclaje.texto_nulo(p_telefono),

        direccion =
            reciclaje.texto_nulo(p_direccion),

        observaciones =
            reciclaje.texto_nulo(p_observaciones),

        latitud = p_latitud,

        longitud = p_longitud,

        updated_at = now()

    WHERE company_id = p_company_id
      AND id = p_id

    RETURNING *
    INTO v_socio;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Socio no encontrado.';
    END IF;

    RETURN v_socio;

END;
$$;


--
-- Name: actualizar_stock_material(uuid, uuid, numeric); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.actualizar_stock_material(p_company_id uuid, p_material_id uuid, p_cantidad numeric) RETURNS reciclaje.materiales
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE

    v_material reciclaje.materiales;

BEGIN

    IF p_cantidad = 0 THEN
        RAISE EXCEPTION 'La cantidad no puede ser cero.';
    END IF;

    UPDATE reciclaje.materiales

    SET

        stock = stock + p_cantidad,

        updated_at = now()

    WHERE company_id = p_company_id
      AND id = p_material_id
      AND stock + p_cantidad >= 0

    RETURNING *
    INTO v_material;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Material no encontrado.';
    END IF;

    IF v_material.stock < 0 THEN
        RAISE EXCEPTION 'Stock insuficiente.';
    END IF;

    RETURN v_material;

END;
$$;


--
-- Name: transportistas; Type: TABLE; Schema: reciclaje; Owner: -
--

CREATE TABLE reciclaje.transportistas (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    codigo text NOT NULL,
    nombre text NOT NULL,
    telefono text,
    placa text NOT NULL,
    activo boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: actualizar_transportista(uuid, uuid, text, text, text); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.actualizar_transportista(p_company_id uuid, p_id uuid, p_nombre text, p_telefono text, p_placa text) RETURNS reciclaje.transportistas
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE

    v_transportista reciclaje.transportistas;

BEGIN

    IF trim(p_nombre) = '' THEN
        RAISE EXCEPTION 'El nombre es obligatorio.';
    END IF;

    IF trim(p_placa) = '' THEN
        RAISE EXCEPTION 'La placa es obligatoria.';
    END IF;

    UPDATE reciclaje.transportistas

    SET

        nombre = trim(p_nombre),

        telefono = nullif(trim(p_telefono), ''),

        placa = upper(trim(p_placa)),

        updated_at = now()

    WHERE company_id = p_company_id
      AND id = p_id

    RETURNING *
    INTO v_transportista;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Transportista no encontrado.';
    END IF;

    RETURN v_transportista;

END;
$$;


--
-- Name: anular_finanza(uuid, uuid); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.anular_finanza(p_company_id uuid, p_finanza_id uuid) RETURNS reciclaje.finanzas
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_finanza reciclaje.finanzas;
BEGIN

    UPDATE reciclaje.finanzas
       SET anulado = true
     WHERE id = p_finanza_id
       AND company_id = p_company_id
       AND anulado = false
    RETURNING *
      INTO v_finanza;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Finanza no encontrada o ya anulada.';
    END IF;

    RETURN v_finanza;

END;
$$;


--
-- Name: bootstrap(uuid); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.bootstrap(p_company_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$

SELECT jsonb_build_object(

    ----------------------------------------------------
    -- Monedas
    ----------------------------------------------------

    'monedas',

    COALESCE(
        (
            SELECT jsonb_agg(
                jsonb_build_object(
                    'id', m.id,
                    'codigo', m.codigo,
                    'nombre', m.nombre,
                    'simbolo', m.simbolo
                )
                ORDER BY m.nombre
            )
            FROM reciclaje.monedas m
            WHERE m.activo = true
        ),
        '[]'::jsonb
    ),

    ----------------------------------------------------
    -- Formas de pago
    ----------------------------------------------------

    'formas_pago',

    COALESCE(
        (
            SELECT jsonb_agg(
                jsonb_build_object(
                    'id', fp.id,
                    'codigo', fp.codigo,
                    'nombre', fp.nombre
                )
                ORDER BY fp.nombre
            )
            FROM reciclaje.formas_pago fp
            WHERE fp.activo = true
        ),
        '[]'::jsonb
    ),

    ----------------------------------------------------
    -- Materiales
    ----------------------------------------------------

    'materiales',

    COALESCE(
        (
            SELECT jsonb_agg(
                jsonb_build_object(
                    'id', m.id,
                    'codigo', m.codigo,
                    'nombre', m.nombre,
                    'unidad', m.unidad,
                    'stock', m.stock,
                    'compuesto', m.compuesto,
                    'precio_base', m.precio_base,
                    'precio_mayorista', m.precio_mayorista,
                    'imagen_url', m.imagen_url
                )
                ORDER BY m.nombre
            )
            FROM reciclaje.listar_materiales(p_company_id) m
        ),
        '[]'::jsonb
    ),

    ----------------------------------------------------
    -- Socios
    ----------------------------------------------------

    'socios',

    COALESCE(
        (
            SELECT jsonb_agg(
                jsonb_build_object(
                    'id', s.id,
                    'codigo', s.codigo,
                    'nombre', s.nombre,
                    'direccion', s.direccion,
                    'latitud', s.latitud,
                    'longitud', s.longitud
                )
                ORDER BY s.nombre
            )
            FROM reciclaje.listar_socios(p_company_id) s
        ),
        '[]'::jsonb
    ),

    ----------------------------------------------------
    -- Transportistas
    ----------------------------------------------------

    'transportistas',

    COALESCE(
        (
            SELECT jsonb_agg(
                jsonb_build_object(
                    'id', t.id,
                    'codigo', t.codigo,
                    'nombre', t.nombre,
                    'placa', t.placa
                )
                ORDER BY t.nombre
            )
            FROM reciclaje.listar_transportistas(p_company_id) t
        ),
        '[]'::jsonb
    ),

    ----------------------------------------------------
    -- Depósitos
    ----------------------------------------------------

    'depositos',

    COALESCE(
        (
            SELECT jsonb_agg(
                jsonb_build_object(
                    'id', d.id,
                    'codigo', d.codigo,
                    'nombre', d.nombre
                )
                ORDER BY d.nombre
            )
            FROM reciclaje.listar_depositos(p_company_id) d
        ),
        '[]'::jsonb
    ),

    ----------------------------------------------------
    -- ENUMS LEGADOS
    ----------------------------------------------------

    'estados_orden',
    reciclaje.enum_to_json('estado_orden'),

    'estados_recepcion',
    reciclaje.enum_to_json('estado_recepcion'),

    'tipos_movimiento',
    reciclaje.enum_to_json('tipo_movimiento'),

    ----------------------------------------------------
    -- ENUMS OPERACIONES / PIPELINE
    ----------------------------------------------------

    'tipos_operacion',
    reciclaje.enum_to_json('tipo_operacion'),

    'etapas_operacion',
    reciclaje.enum_to_json('etapa_operacion')

);

$$;


--
-- Name: cancelar_recepcion(uuid, uuid); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.cancelar_recepcion(p_company_id uuid, p_recepcion_id uuid) RETURNS reciclaje.recepciones
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE

    v_recepcion reciclaje.recepciones;

BEGIN

    SELECT *
    INTO v_recepcion
    FROM reciclaje.recepciones
    WHERE company_id = p_company_id
      AND id = p_recepcion_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'La recepción no existe.';
    END IF;

    IF v_recepcion.estado <> 'borrador' THEN
        RAISE EXCEPTION 'Solo se puede cancelar una recepción en borrador.';
    END IF;

    UPDATE reciclaje.recepciones

    SET

        estado = 'cancelada'

    WHERE id = p_recepcion_id

    RETURNING *

    INTO v_recepcion;

    UPDATE reciclaje.ordenes_compra

    SET

        estado = 'borrador',

        updated_at = now()

    WHERE id = v_recepcion.orden_compra_id;

    RETURN v_recepcion;

END;
$$;


--
-- Name: confirmar_operacion(uuid, uuid); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.confirmar_operacion(p_company_id uuid, p_operacion_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE

    v_operacion reciclaje.operaciones;

    v_orden reciclaje.ordenes_compra;

    v_recepcion reciclaje.recepciones;

    v_orden_json jsonb;

    v_recepcion_json jsonb;

BEGIN

    ------------------------------------------------------------
    -- 1. BLOQUEAR OPERACIÓN
    ------------------------------------------------------------

    SELECT *
    INTO v_operacion
    FROM reciclaje.operaciones
    WHERE company_id = p_company_id
      AND id = p_operacion_id
    FOR UPDATE;


    IF NOT FOUND THEN

        RAISE EXCEPTION
            'La operación no existe.';

    END IF;


    ------------------------------------------------------------
    -- 2. IDEMPOTENCIA
    ------------------------------------------------------------

    IF v_operacion.finalizada = true THEN

        RETURN jsonb_build_object(

            'ok', true,

            'ya_finalizada', true,

            'operacion_id', v_operacion.id,

            'orden_compra_id',
                v_operacion.orden_compra_id,

            'recepcion_id',
                v_operacion.recepcion_id,

            'finanza_id',
                v_operacion.finanza_id

        );

    END IF;


    ------------------------------------------------------------
    -- VALIDAR OPERACIÓN COMPLETA
    ------------------------------------------------------------

    IF v_operacion.socio_id IS NULL THEN

        RAISE EXCEPTION
            'Debe indicar el socio.';

    END IF;


    IF v_operacion.transportista_id IS NULL THEN

        RAISE EXCEPTION
            'Debe indicar el transportista.';

    END IF;


    IF v_operacion.deposito_id IS NULL THEN

        RAISE EXCEPTION
            'Debe indicar el depósito de recepción.';

    END IF;


    IF v_operacion.monto IS NULL THEN

        RAISE EXCEPTION
            'Debe indicar el monto definitivo de la compra.';

    END IF;


    IF jsonb_array_length(
        COALESCE(
            v_operacion.materiales,
            '[]'::jsonb
        )
    ) = 0 THEN

        RAISE EXCEPTION
            'Debe indicar al menos un material.';

    END IF;


    IF jsonb_array_length(
        COALESCE(
            v_operacion.pagos,
            '[]'::jsonb
        )
    ) = 0 THEN

        RAISE EXCEPTION
            'Debe indicar al menos un pago.';

    END IF;


    ------------------------------------------------------------
    -- CONSTRUIR ORDEN
    ------------------------------------------------------------

    v_orden_json :=
        jsonb_build_object(

            'socio_id',
                v_operacion.socio_id,

            'transportista_id',
                v_operacion.transportista_id,

            'materiales',
                v_operacion.materiales,

            'pagos',
                v_operacion.pagos,

            'observaciones',
                v_operacion.observaciones

        );


    ------------------------------------------------------------
    -- CREAR ORDEN
    ------------------------------------------------------------

    SELECT *
    INTO v_orden
    FROM reciclaje.crear_orden_compra(
        p_company_id,
        v_orden_json
    );


    ------------------------------------------------------------
    -- FIJAR MONTO DEFINITIVO
    ------------------------------------------------------------

    UPDATE reciclaje.ordenes_compra

    SET
        total = v_operacion.monto,
        updated_at = now()

    WHERE company_id = p_company_id
      AND id = v_orden.id

    RETURNING *
    INTO v_orden;


    ------------------------------------------------------------
    -- CREAR RECEPCIÓN
    ------------------------------------------------------------

    SELECT *
    INTO v_recepcion
    FROM reciclaje.crear_recepcion(

        p_company_id,

        v_orden.id,

        v_operacion.recibido_por,

        v_operacion.observaciones

    );


    ------------------------------------------------------------
    -- COMPLETAR RECEPCIÓN
    ------------------------------------------------------------

    v_recepcion_json :=
        jsonb_build_object(

            'deposito_id',
                v_operacion.deposito_id,

            'recibido_por',
                v_operacion.recibido_por,

            'observaciones',
                v_operacion.observaciones,

            'materiales',
                v_operacion.materiales

        );


    SELECT *
    INTO v_recepcion
    FROM reciclaje.actualizar_recepcion(

        p_company_id,

        v_recepcion.id,

        v_recepcion_json

    );


    ------------------------------------------------------------
    -- CONFIRMAR RECEPCIÓN
    ------------------------------------------------------------

    SELECT *
    INTO v_recepcion
    FROM reciclaje.confirmar_recepcion(

        p_company_id,

        v_recepcion.id

    );


    ------------------------------------------------------------
    -- CERRAR OPERACIÓN
    ------------------------------------------------------------

    UPDATE reciclaje.operaciones

    SET

        tipo =
            'compra'::reciclaje.tipo_operacion,

        etapa =
            'finalizada'::reciclaje.etapa_operacion,

        orden_compra_id =
            v_orden.id,

        recepcion_id =
            v_recepcion.id,

        finalizada =
            true,

        finalizada_at =
            now(),

        updated_at =
            now()

    WHERE company_id = p_company_id
      AND id = p_operacion_id

    RETURNING *
    INTO v_operacion;


    ------------------------------------------------------------
    -- RESPUESTA
    ------------------------------------------------------------

    RETURN jsonb_build_object(

        'ok', true,

        'operacion_id',
            v_operacion.id,

        'monto',
            v_operacion.monto,

        'orden_compra',
            jsonb_build_object(

                'id',
                    v_orden.id,

                'subtotal',
                    v_orden.subtotal,

                'total',
                    v_orden.total,

                'estado',
                    v_orden.estado

            ),

        'recepcion',
            jsonb_build_object(

                'id',
                    v_recepcion.id,

                'estado',
                    v_recepcion.estado,

                'deposito_id',
                    v_recepcion.deposito_id,

                'confirmed_at',
                    v_recepcion.confirmed_at

            )

    );

END;
$$;


--
-- Name: confirmar_operaciones_transportista(uuid, uuid, jsonb); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.confirmar_operaciones_transportista(p_company_id uuid, p_transportista_id uuid, p_datos jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE

    ------------------------------------------------------------
    -- DATOS GENERALES
    ------------------------------------------------------------

    v_deposito_id uuid;

    v_movimiento_grupo_id uuid :=
        gen_random_uuid();

    v_operacion reciclaje.operaciones;

    v_orden reciclaje.ordenes_compra;

    v_recepcion reciclaje.recepciones;

    v_orden_json jsonb;

    v_recepcion_json jsonb;

    v_item jsonb;

    v_material_id uuid;

    v_cantidad numeric(14,3);

    v_cantidad_operaciones integer := 0;

    v_cantidad_materiales integer := 0;

    v_resultados jsonb := '[]'::jsonb;


    ------------------------------------------------------------
    -- COMPATIBILIDAD CON PAGOS DEL MODELO ANTERIOR
    ------------------------------------------------------------

    v_pagos_orden jsonb;

    v_forma_pago_id uuid;

    v_moneda_id uuid;

BEGIN

    ------------------------------------------------------------
    -- 1. VALIDACIONES GENERALES
    ------------------------------------------------------------

    IF p_transportista_id IS NULL THEN

        RAISE EXCEPTION
            'Debe indicar el transportista.';

    END IF;


    IF NOT EXISTS (

        SELECT 1
        FROM reciclaje.transportistas

        WHERE company_id = p_company_id
          AND id = p_transportista_id
          AND activo = true

    ) THEN

        RAISE EXCEPTION
            'El transportista no existe o está inactivo.';

    END IF;


    ------------------------------------------------------------
    -- 2. DEPÓSITO
    ------------------------------------------------------------

    v_deposito_id :=
        NULLIF(
            p_datos->>'deposito_id',
            ''
        )::uuid;


    IF v_deposito_id IS NULL THEN

        RAISE EXCEPTION
            'Debe indicar el depósito.';

    END IF;


    IF NOT EXISTS (

        SELECT 1
        FROM reciclaje.depositos

        WHERE company_id = p_company_id
          AND id = v_deposito_id
          AND activo = true

    ) THEN

        RAISE EXCEPTION
            'El depósito no existe o está inactivo.';

    END IF;


    ------------------------------------------------------------
    -- 3. VALIDAR INVENTARIO
    ------------------------------------------------------------

    IF jsonb_typeof(
        COALESCE(
            p_datos->'inventario',
            '[]'::jsonb
        )
    ) <> 'array'
    THEN

        RAISE EXCEPTION
            'inventario debe ser un array.';

    END IF;


    IF jsonb_array_length(
        COALESCE(
            p_datos->'inventario',
            '[]'::jsonb
        )
    ) = 0
    THEN

        RAISE EXCEPTION
            'Debe indicar el inventario físico recibido.';

    END IF;


    ------------------------------------------------------------
    -- 4. RESOLVER MONEDA ARS PARA PAGO TÉCNICO
    ------------------------------------------------------------

    SELECT id
    INTO v_moneda_id
    FROM reciclaje.monedas
    WHERE codigo = 'ARS'
      AND activo = true
    LIMIT 1;


    IF v_moneda_id IS NULL THEN

        RAISE EXCEPTION
            'No existe una moneda ARS activa para generar el pago técnico.';

    END IF;


    ------------------------------------------------------------
    -- 5. RESOLVER FORMA DE PAGO PARA COMPATIBILIDAD
    --
    -- Preferimos "pendiente".
    -- Si no existe, usamos una forma de pago activa disponible.
    ------------------------------------------------------------

    SELECT id
    INTO v_forma_pago_id
    FROM reciclaje.formas_pago
    WHERE codigo = 'pendiente'
      AND activo = true
    LIMIT 1;


    IF v_forma_pago_id IS NULL THEN

        SELECT id
        INTO v_forma_pago_id
        FROM reciclaje.formas_pago
        WHERE activo = true
        ORDER BY created_at, id
        LIMIT 1;

    END IF;


    IF v_forma_pago_id IS NULL THEN

        RAISE EXCEPTION
            'No existe una forma de pago activa para generar el pago técnico.';

    END IF;


    ------------------------------------------------------------
    -- 6. BLOQUEAR TODAS LAS OPERACIONES DEL TRANSPORTISTA
    ------------------------------------------------------------

    PERFORM o.id

    FROM reciclaje.operaciones o

    WHERE o.company_id = p_company_id

      AND o.transportista_id =
          p_transportista_id

      AND o.etapa =
          'en_proceso'::reciclaje.etapa_operacion

      AND COALESCE(
          o.finalizada,
          false
      ) = false

    ORDER BY o.id

    FOR UPDATE;


    ------------------------------------------------------------
    -- 7. VERIFICAR QUE HAYA OPERACIONES
    ------------------------------------------------------------

    SELECT COUNT(*)

    INTO v_cantidad_operaciones

    FROM reciclaje.operaciones o

    WHERE o.company_id = p_company_id

      AND o.transportista_id =
          p_transportista_id

      AND o.etapa =
          'en_proceso'::reciclaje.etapa_operacion

      AND COALESCE(
          o.finalizada,
          false
      ) = false;


    IF v_cantidad_operaciones = 0 THEN

        RAISE EXCEPTION
            'El transportista no tiene operaciones en proceso.';

    END IF;


    ------------------------------------------------------------
    -- 8. VALIDAR INVENTARIO FÍSICO ANTES DE CREAR NADA
    ------------------------------------------------------------

    FOR v_item IN

        SELECT value
        FROM jsonb_array_elements(
            p_datos->'inventario'
        )

    LOOP

        v_material_id :=
            NULLIF(
                v_item->>'material_id',
                ''
            )::uuid;


        v_cantidad :=
            NULLIF(
                v_item->>'cantidad',
                ''
            )::numeric;


        IF v_material_id IS NULL THEN

            RAISE EXCEPTION
                'Todos los movimientos de inventario deben indicar material_id.';

        END IF;


        IF v_cantidad IS NULL THEN

            RAISE EXCEPTION
                'Todos los movimientos de inventario deben indicar cantidad.';

        END IF;


        IF v_cantidad < 0 THEN

            RAISE EXCEPTION
                'La cantidad física recibida no puede ser negativa.';

        END IF;


        IF NOT EXISTS (

            SELECT 1

            FROM reciclaje.materiales m

            WHERE m.company_id = p_company_id
              AND m.id = v_material_id
              AND m.activo = true

        ) THEN

            RAISE EXCEPTION
                'Uno de los materiales enviados no existe o está inactivo.';

        END IF;


        --------------------------------------------------------
        -- EL MATERIAL DEBE EXISTIR EN ALGUNA OPERACIÓN
        --------------------------------------------------------

        IF NOT EXISTS (

            SELECT 1

            FROM reciclaje.operaciones o

            CROSS JOIN LATERAL
                jsonb_array_elements(
                    COALESCE(
                        o.materiales,
                        '[]'::jsonb
                    )
                ) AS mat

            WHERE o.company_id = p_company_id

              AND o.transportista_id =
                  p_transportista_id

              AND o.etapa =
                  'en_proceso'::reciclaje.etapa_operacion

              AND COALESCE(
                  o.finalizada,
                  false
              ) = false

              AND NULLIF(
                    mat->>'material_id',
                    ''
                  )::uuid = v_material_id

        ) THEN

            RAISE EXCEPTION
                'El inventario contiene un material que no pertenece a las operaciones del transportista.';

        END IF;

    END LOOP;


    ------------------------------------------------------------
    -- 9. EVITAR MATERIALES REPETIDOS EN INVENTARIO
    ------------------------------------------------------------

    IF EXISTS (

        SELECT 1

        FROM (

            SELECT
                NULLIF(
                    value->>'material_id',
                    ''
                )::uuid AS material_id,

                COUNT(*) AS cantidad

            FROM jsonb_array_elements(
                p_datos->'inventario'
            )

            GROUP BY
                NULLIF(
                    value->>'material_id',
                    ''
                )::uuid

            HAVING COUNT(*) > 1

        ) duplicados

    ) THEN

        RAISE EXCEPTION
            'El inventario debe estar consolidado: cada material puede aparecer una sola vez.';

    END IF;


    ------------------------------------------------------------
    -- 10. PROCESAR CADA OPERACIÓN COMERCIAL INDIVIDUALMENTE
    ------------------------------------------------------------

    FOR v_operacion IN

        SELECT *

        FROM reciclaje.operaciones

        WHERE company_id = p_company_id

          AND transportista_id =
              p_transportista_id

          AND etapa =
              'en_proceso'::reciclaje.etapa_operacion

          AND COALESCE(
              finalizada,
              false
          ) = false

        ORDER BY created_at, id

    LOOP

        --------------------------------------------------------
        -- VALIDACIONES COMERCIALES
        --------------------------------------------------------

        IF v_operacion.tipo <>
           'compra'::reciclaje.tipo_operacion
        THEN

            RAISE EXCEPTION
                'La confirmación múltiple solo admite operaciones de compra.';

        END IF;


        IF v_operacion.socio_id IS NULL THEN

            RAISE EXCEPTION
                'Una operación no tiene socio.';

        END IF;


        IF v_operacion.monto IS NULL THEN

            RAISE EXCEPTION
                'Una operación no tiene monto definitivo.';

        END IF;


        IF v_operacion.monto < 0 THEN

            RAISE EXCEPTION
                'Una operación tiene un monto definitivo inválido.';

        END IF;


        IF jsonb_array_length(
            COALESCE(
                v_operacion.materiales,
                '[]'::jsonb
            )
        ) = 0
        THEN

            RAISE EXCEPTION
                'Una operación no contiene materiales.';

        END IF;


        --------------------------------------------------------
        -- 11. COMPATIBILIDAD DE PAGOS
        --
        -- Si la operación ya tiene pagos, se respetan.
        --
        -- Si no tiene pagos, creamos uno técnico por exactamente
        -- el mismo monto definitivo de la operación.
        --
        -- Esto permite reutilizar crear_orden_compra() sin
        -- obligar al frontend nuevo a manejar pagos.
        --------------------------------------------------------

        IF jsonb_array_length(
            COALESCE(
                v_operacion.pagos,
                '[]'::jsonb
            )
        ) > 0
        THEN

            v_pagos_orden :=
                v_operacion.pagos;

        ELSE

            v_pagos_orden :=
                jsonb_build_array(

                    jsonb_build_object(

                        'forma_pago_id',
                            v_forma_pago_id,

                        'moneda_id',
                            v_moneda_id,

                        'monto',
                            v_operacion.monto,

                        'referencia',
                            NULL,

                        'observaciones',
                            'Pago técnico generado automáticamente al confirmar la operación'

                    )

                );

        END IF;


        --------------------------------------------------------
        -- 12. CONSTRUIR ORDEN DE ESTA OPERACIÓN
        --------------------------------------------------------

        v_orden_json :=
            jsonb_build_object(

                'socio_id',
                    v_operacion.socio_id,

                'transportista_id',
                    p_transportista_id,

                'materiales',
                    v_operacion.materiales,

                'pagos',
                    v_pagos_orden,

                'observaciones',
                    v_operacion.observaciones

            );


        --------------------------------------------------------
        -- 13. CREAR ORDEN
        --------------------------------------------------------

        SELECT *

        INTO v_orden

        FROM reciclaje.crear_orden_compra(

            p_company_id,

            v_orden_json

        );


        --------------------------------------------------------
        -- 14. FIJAR MONTO ACORDADO
        --------------------------------------------------------

        UPDATE reciclaje.ordenes_compra

        SET

            total =
                v_operacion.monto,

            updated_at =
                now()

        WHERE company_id = p_company_id
          AND id = v_orden.id

        RETURNING *

        INTO v_orden;


        --------------------------------------------------------
        -- 15. CREAR RECEPCIÓN INDIVIDUAL
        --------------------------------------------------------

        SELECT *

        INTO v_recepcion

        FROM reciclaje.crear_recepcion(

            p_company_id,

            v_orden.id,

            v_operacion.recibido_por,

            v_operacion.observaciones

        );


        --------------------------------------------------------
        -- 16. COMPLETAR RECEPCIÓN
        --
        -- Conservamos materiales COMERCIALES de la operación.
        -- El inventario físico se procesa después por separado.
        --------------------------------------------------------

        v_recepcion_json :=
            jsonb_build_object(

                'deposito_id',
                    v_deposito_id,

                'recibido_por',
                    v_operacion.recibido_por,

                'observaciones',
                    v_operacion.observaciones,

                'materiales',
                    v_operacion.materiales

            );


        SELECT *

        INTO v_recepcion

        FROM reciclaje.actualizar_recepcion(

            p_company_id,

            v_recepcion.id,

            v_recepcion_json

        );


        --------------------------------------------------------
        -- 17. CONFIRMAR DOCUMENTALMENTE RECEPCIÓN
        --
        -- NO llamar confirmar_recepcion().
        -- Esa función ingresaría al stock la cantidad comercial.
        --------------------------------------------------------

        UPDATE reciclaje.recepciones

        SET

            estado =
                'confirmada',

            confirmed_at =
                now()

        WHERE company_id = p_company_id
          AND id = v_recepcion.id

        RETURNING *

        INTO v_recepcion;


        --------------------------------------------------------
        -- 18. ORDEN = RECIBIDA
        --
        -- ENUM CORRECTO:
        -- estado_orden = 'recibida'
        --------------------------------------------------------

        UPDATE reciclaje.ordenes_compra

        SET

            estado =
                'recibida'::reciclaje.estado_orden,

            updated_at =
                now()

        WHERE company_id = p_company_id
          AND id = v_orden.id

        RETURNING *

        INTO v_orden;


        --------------------------------------------------------
        -- 19. CERRAR ESTA OPERACIÓN
        --
        -- ENUM CORRECTO:
        -- etapa_operacion = 'finalizada'
        --------------------------------------------------------

        UPDATE reciclaje.operaciones

        SET

            tipo =
                'compra'::reciclaje.tipo_operacion,

            etapa =
                'finalizada'::reciclaje.etapa_operacion,

            deposito_id =
                v_deposito_id,

            orden_compra_id =
                v_orden.id,

            recepcion_id =
                v_recepcion.id,

            finalizada =
                true,

            finalizada_at =
                now(),

            updated_at =
                now()

        WHERE company_id = p_company_id
          AND id = v_operacion.id;


        --------------------------------------------------------
        -- 20. ACUMULAR RESULTADO
        --------------------------------------------------------

        v_resultados :=
            v_resultados
            ||
            jsonb_build_array(

                jsonb_build_object(

                    'operacion_id',
                        v_operacion.id,

                    'socio_id',
                        v_operacion.socio_id,

                    'orden_compra_id',
                        v_orden.id,

                    'recepcion_id',
                        v_recepcion.id,

                    'monto',
                        v_operacion.monto

                )

            );

    END LOOP;


    ------------------------------------------------------------
    -- 21. INVENTARIO FÍSICO REAL
    --
    -- UNA SOLA VEZ por material consolidado.
    ------------------------------------------------------------

    FOR v_item IN

        SELECT value

        FROM jsonb_array_elements(
            p_datos->'inventario'
        )

    LOOP

        v_material_id :=
            NULLIF(
                v_item->>'material_id',
                ''
            )::uuid;


        v_cantidad :=
            NULLIF(
                v_item->>'cantidad',
                ''
            )::numeric;


        --------------------------------------------------------
        -- CANTIDAD 0 ES VÁLIDA
        --------------------------------------------------------

        IF v_cantidad > 0 THEN

            ----------------------------------------------------
            -- STOCK GLOBAL
            ----------------------------------------------------

            UPDATE reciclaje.materiales

            SET

                stock =
                    stock + v_cantidad,

                updated_at =
                    now()

            WHERE company_id = p_company_id
              AND id = v_material_id;


            ----------------------------------------------------
            -- MOVIMIENTO DE INVENTARIO CONSOLIDADO
            ----------------------------------------------------

            INSERT INTO reciclaje.movimientos_stock (

                company_id,

                deposito_id,

                material_id,

                tipo_movimiento,

                cantidad,

                origen,

                origen_id,

                socio_id,

                transportista_id,

                orden_compra_id,

                recepcion_id,

                observaciones,

                movimiento_grupo_id

            )

            VALUES (

                p_company_id,

                v_deposito_id,

                v_material_id,

                'entrada',

                v_cantidad,

                'recepcion_multicarga',

                v_movimiento_grupo_id,

                NULL,

                p_transportista_id,

                NULL,

                NULL,

                'Entrada física consolidada de operaciones del transportista',

                v_movimiento_grupo_id

            );


            v_cantidad_materiales :=
                v_cantidad_materiales + 1;

        END IF;

    END LOOP;


    ------------------------------------------------------------
    -- 22. RESPUESTA
    ------------------------------------------------------------

    RETURN jsonb_build_object(

        'ok',
            true,

        'transportista_id',
            p_transportista_id,

        'deposito_id',
            v_deposito_id,

        'movimiento_grupo_id',
            v_movimiento_grupo_id,

        'operaciones_confirmadas',
            v_cantidad_operaciones,

        'materiales_ingresados',
            v_cantidad_materiales,

        'operaciones',
            v_resultados,

        'inventario',
            p_datos->'inventario'

    );

END;
$$;


--
-- Name: confirmar_recepcion(uuid, uuid); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.confirmar_recepcion(p_company_id uuid, p_recepcion_id uuid) RETURNS reciclaje.recepciones
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE

    v_recepcion reciclaje.recepciones;

    v_detalle record;

    v_socio_id uuid;

    v_transportista_id uuid;

BEGIN

    ----------------------------------------------------
    -- Buscar recepción
    ----------------------------------------------------

    SELECT *
    INTO v_recepcion
    FROM reciclaje.recepciones
    WHERE company_id = p_company_id
      AND id = p_recepcion_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'La recepción no existe.';
    END IF;

    IF v_recepcion.estado <> 'borrador' THEN
        RAISE EXCEPTION 'La recepción ya fue confirmada.';
    END IF;

    IF v_recepcion.deposito_id IS NULL THEN
        RAISE EXCEPTION
        'Debe seleccionar un depósito antes de confirmar la recepción.';
    END IF;

    ----------------------------------------------------
    -- Datos de la orden
    ----------------------------------------------------

    SELECT
        socio_id,
        transportista_id

    INTO
        v_socio_id,
        v_transportista_id

    FROM reciclaje.ordenes_compra

    WHERE company_id = p_company_id
      AND id = v_recepcion.orden_compra_id;

    ----------------------------------------------------
    -- Actualizar stock y movimientos
    ----------------------------------------------------

    FOR v_detalle IN

        SELECT *
        FROM reciclaje.recepciones_detalle
        WHERE recepcion_id = p_recepcion_id

    LOOP

        ------------------------------------------------
        -- Stock global actual
        ------------------------------------------------

        UPDATE reciclaje.materiales

        SET
            stock = stock + v_detalle.cantidad,
            updated_at = now()

        WHERE company_id = p_company_id
          AND id = v_detalle.material_id;

        ------------------------------------------------
        -- Movimiento de inventario
        ------------------------------------------------

        INSERT INTO reciclaje.movimientos_stock(

            company_id,

            deposito_id,

            material_id,

            tipo_movimiento,

            cantidad,

            origen,

            origen_id,

            socio_id,

            transportista_id,

            orden_compra_id,

            recepcion_id,

            observaciones

        )

        VALUES(

            p_company_id,

            v_recepcion.deposito_id,

            v_detalle.material_id,

            'entrada',

            v_detalle.cantidad,

            'recepcion',

            p_recepcion_id,

            v_socio_id,

            v_transportista_id,

            v_recepcion.orden_compra_id,

            p_recepcion_id,

            'Entrada por recepción confirmada'

        );

    END LOOP;

    ----------------------------------------------------
    -- Confirmar recepción
    ----------------------------------------------------

    UPDATE reciclaje.recepciones

    SET
        estado = 'confirmada',
        confirmed_at = now()

    WHERE company_id = p_company_id
      AND id = p_recepcion_id;

    ----------------------------------------------------
    -- Actualizar orden
    ----------------------------------------------------

    UPDATE reciclaje.ordenes_compra

    SET
        estado = 'recibida',
        updated_at = now()

    WHERE company_id = p_company_id
      AND id = v_recepcion.orden_compra_id;

    ----------------------------------------------------
    -- Resultado
    ----------------------------------------------------

    SELECT *
    INTO v_recepcion
    FROM reciclaje.recepciones
    WHERE company_id = p_company_id
      AND id = p_recepcion_id;

    RETURN v_recepcion;

END;
$$;


--
-- Name: crear_deposito(uuid, text, text, boolean); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.crear_deposito(p_company_id uuid, p_nombre text, p_direccion text DEFAULT NULL::text, p_activo boolean DEFAULT true) RETURNS reciclaje.depositos
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE

    v_codigo text;

    v_deposito reciclaje.depositos;

BEGIN

    IF trim(p_nombre) = '' THEN
        RAISE EXCEPTION 'El nombre es obligatorio.';
    END IF;

    v_codigo := reciclaje.generar_codigo(
        p_company_id,
        'DEP'
    );

    INSERT INTO reciclaje.depositos (

        company_id,

        codigo,

        nombre,

        direccion,

        activo

    )
    VALUES (

        p_company_id,

        v_codigo,

        trim(p_nombre),

        nullif(trim(p_direccion), ''),

        coalesce(p_activo, true)

    )
    RETURNING *
    INTO v_deposito;

    RETURN v_deposito;

END;
$$;


--
-- Name: crear_finanza(uuid, text, numeric, numeric, text, uuid, timestamp with time zone, text, text, text, text); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.crear_finanza(p_company_id uuid, p_tipo text, p_tipo_cambio numeric, p_importe_base numeric, p_origen_tipo text DEFAULT 'manual'::text, p_origen_id uuid DEFAULT NULL::uuid, p_fecha_vencimiento timestamp with time zone DEFAULT NULL::timestamp with time zone, p_observaciones text DEFAULT NULL::text, p_responsable_nombre text DEFAULT NULL::text, p_responsable_telefono text DEFAULT NULL::text, p_responsable_tipo text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id uuid;
BEGIN

    INSERT INTO reciclaje.finanzas (
        company_id,
        tipo,
        origen_tipo,
        origen_id,
        fecha_vencimiento,
        tipo_cambio,
        importe_base,
        observaciones,
        responsable_nombre,
        responsable_telefono,
        responsable_tipo
    )
    VALUES (
        p_company_id,
        p_tipo,
        p_origen_tipo,
        p_origen_id,
        p_fecha_vencimiento,
        p_tipo_cambio,
        p_importe_base,
        p_observaciones,
        p_responsable_nombre,
        p_responsable_telefono,
        p_responsable_tipo
    )
    RETURNING id
    INTO v_id;

    RETURN v_id;

END;
$$;


--
-- Name: crear_material(uuid, text, text, jsonb, numeric, numeric, text); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.crear_material(p_company_id uuid, p_nombre text, p_unidad text DEFAULT 'kg'::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_precio_base numeric DEFAULT 0, p_precio_mayorista numeric DEFAULT 0, p_imagen_url text DEFAULT NULL::text) RETURNS reciclaje.materiales
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE

    v_codigo text;
    v_material reciclaje.materiales;

BEGIN

    IF trim(p_nombre) = '' THEN
        RAISE EXCEPTION 'El nombre es obligatorio.';
    END IF;

    IF trim(p_unidad) = '' THEN
        RAISE EXCEPTION 'La unidad es obligatoria.';
    END IF;

    IF coalesce(p_precio_base, 0) < 0 THEN
        RAISE EXCEPTION 'El precio base no puede ser negativo.';
    END IF;

    IF coalesce(p_precio_mayorista, 0) < 0 THEN
        RAISE EXCEPTION 'El precio mayorista no puede ser negativo.';
    END IF;

    v_codigo := reciclaje.generar_codigo(
        p_company_id,
        'MAT'
    );

    INSERT INTO reciclaje.materiales (

        company_id,
        codigo,
        nombre,
        unidad,
        metadata,
        precio_base,
        precio_mayorista,
        imagen_url

    )
    VALUES (

        p_company_id,
        v_codigo,
        trim(p_nombre),
        lower(trim(p_unidad)),
        coalesce(p_metadata, '{}'),
        coalesce(p_precio_base, 0),
        coalesce(p_precio_mayorista, 0),
        reciclaje.texto_nulo(p_imagen_url)

    )
    RETURNING *
    INTO v_material;

    RETURN v_material;

END;
$$;


--
-- Name: crear_orden_compra(uuid, jsonb); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.crear_orden_compra(p_company_id uuid, p_orden jsonb) RETURNS reciclaje.ordenes_compra
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE

    v_codigo text;

    v_orden reciclaje.ordenes_compra;

    v_material jsonb;

    v_pago jsonb;

    v_subtotal numeric(14,2) := 0;

BEGIN

    ----------------------------------------------------
    -- Validaciones
    ----------------------------------------------------

    IF jsonb_array_length(
        coalesce(
            p_orden->'materiales',
            '[]'::jsonb
        )
    ) = 0 THEN

        RAISE EXCEPTION
        'La orden debe contener al menos un material.';

    END IF;

    IF jsonb_array_length(
        coalesce(
            p_orden->'pagos',
            '[]'::jsonb
        )
    ) = 0 THEN

        RAISE EXCEPTION
        'Debe indicar al menos una forma de pago.';

    END IF;

    ----------------------------------------------------
    -- Código
    ----------------------------------------------------

    v_codigo := reciclaje.generar_codigo(

        p_company_id,

        'OC'

    );

    ----------------------------------------------------
    -- Cabecera
    ----------------------------------------------------

    INSERT INTO reciclaje.ordenes_compra(

        company_id,

        codigo,

        socio_id,

        transportista_id,

        estado,

        subtotal,

        total,

        observaciones

    )

    VALUES(

        p_company_id,

        v_codigo,

        (p_orden->>'socio_id')::uuid,

        (p_orden->>'transportista_id')::uuid,

        'borrador',

        0,

        0,

        reciclaje.texto_nulo(
            p_orden->>'observaciones'
        )

    )

    RETURNING *

    INTO v_orden;

    ----------------------------------------------------
    -- Detalle
    ----------------------------------------------------

    FOR v_material IN

        SELECT *

        FROM jsonb_array_elements(
            p_orden->'materiales'
        )

    LOOP

        INSERT INTO reciclaje.ordenes_compra_detalle(

            orden_compra_id,

            material_id,

            cantidad,

            precio_unitario,

            subtotal

        )

        VALUES(

            v_orden.id,

            (v_material->>'material_id')::uuid,

            (v_material->>'cantidad')::numeric,

            (v_material->>'precio_unitario')::numeric,

            (v_material->>'cantidad')::numeric
            *
            (v_material->>'precio_unitario')::numeric

        );

        v_subtotal :=

            v_subtotal +

            (

                (v_material->>'cantidad')::numeric

                *

                (v_material->>'precio_unitario')::numeric

            );

    END LOOP;

    ----------------------------------------------------
    -- Pagos
    ----------------------------------------------------

    FOR v_pago IN

        SELECT *

        FROM jsonb_array_elements(
            p_orden->'pagos'
        )

    LOOP

        INSERT INTO reciclaje.ordenes_compra_pagos(

            orden_compra_id,

            forma_pago_id,

            moneda_id,

            monto,

            referencia,

            observaciones

        )

        VALUES(

            v_orden.id,

            (v_pago->>'forma_pago_id')::uuid,

            (v_pago->>'moneda_id')::uuid,

            (v_pago->>'monto')::numeric,

            reciclaje.texto_nulo(
                v_pago->>'referencia'
            ),

            reciclaje.texto_nulo(
                v_pago->>'observaciones'
            )

        );

    END LOOP;

    ----------------------------------------------------
    -- Totales
    ----------------------------------------------------

    UPDATE reciclaje.ordenes_compra

    SET

        subtotal = v_subtotal,

        total = v_subtotal,

        updated_at = now()

    WHERE id = v_orden.id

    RETURNING *

    INTO v_orden;

    ----------------------------------------------------
    -- Resultado
    ----------------------------------------------------

    RETURN v_orden;

END;
$$;


--
-- Name: crear_recepcion(uuid, uuid, text, text); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.crear_recepcion(p_company_id uuid, p_orden_compra_id uuid, p_recibido_por text DEFAULT NULL::text, p_observaciones text DEFAULT NULL::text) RETURNS reciclaje.recepciones
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE

    v_codigo text;

    v_recepcion reciclaje.recepciones;

    v_orden reciclaje.ordenes_compra;

BEGIN

    SELECT *
    INTO v_orden
    FROM reciclaje.ordenes_compra
    WHERE company_id = p_company_id
      AND id = p_orden_compra_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'La orden de compra no existe.';
    END IF;

    IF v_orden.estado <> 'borrador' THEN
        RAISE EXCEPTION 'La orden ya fue enviada a recepción.';
    END IF;

    IF NOT EXISTS (

        SELECT 1
        FROM reciclaje.ordenes_compra_detalle
        WHERE orden_compra_id = p_orden_compra_id

    ) THEN

        RAISE EXCEPTION
        'La orden de compra no contiene materiales.';

    END IF;

    IF EXISTS (

        SELECT 1
        FROM reciclaje.recepciones
        WHERE company_id = p_company_id
          AND orden_compra_id = p_orden_compra_id
          AND estado <> 'cancelada'

    ) THEN

        RAISE EXCEPTION
        'La orden ya posee una recepción.';

    END IF;

    v_codigo := reciclaje.generar_codigo(
        p_company_id,
        'REC'
    );

    INSERT INTO reciclaje.recepciones (

        company_id,

        codigo,

        orden_compra_id,

        estado,

        recibido_por,

        observaciones

    )
    VALUES (

        p_company_id,

        v_codigo,

        p_orden_compra_id,

        'borrador',

        reciclaje.texto_nulo(p_recibido_por),

        reciclaje.texto_nulo(p_observaciones)

    )
    RETURNING *
    INTO v_recepcion;

    INSERT INTO reciclaje.recepciones_detalle (

        recepcion_id,

        material_id,

        cantidad,

        precio_unitario,

        subtotal,

        observaciones

    )
    SELECT

        v_recepcion.id,

        material_id,

        cantidad,

        precio_unitario,

        subtotal,

        observaciones

    FROM reciclaje.ordenes_compra_detalle

    WHERE orden_compra_id = p_orden_compra_id;

    UPDATE reciclaje.ordenes_compra

    SET
        estado = 'en_ruta',
        updated_at = now()

    WHERE company_id = p_company_id
      AND id = p_orden_compra_id;

    RETURN v_recepcion;

END;
$$;


--
-- Name: crear_socio(uuid, text, text, text, text, text, numeric, numeric); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.crear_socio(p_company_id uuid, p_nombre text, p_documento text DEFAULT NULL::text, p_telefono text DEFAULT NULL::text, p_direccion text DEFAULT NULL::text, p_observaciones text DEFAULT NULL::text, p_latitud numeric DEFAULT NULL::numeric, p_longitud numeric DEFAULT NULL::numeric) RETURNS reciclaje.socios
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE

    v_codigo text;
    v_socio reciclaje.socios;

BEGIN

    IF trim(coalesce(p_nombre, '')) = '' THEN
        RAISE EXCEPTION 'El nombre es obligatorio.';
    END IF;

    ----------------------------------------------------
    -- Validar coordenadas
    ----------------------------------------------------

    IF p_latitud IS NOT NULL
       AND (p_latitud < -90 OR p_latitud > 90) THEN

        RAISE EXCEPTION
        'La latitud debe estar entre -90 y 90.';

    END IF;

    IF p_longitud IS NOT NULL
       AND (p_longitud < -180 OR p_longitud > 180) THEN

        RAISE EXCEPTION
        'La longitud debe estar entre -180 y 180.';

    END IF;

    ----------------------------------------------------
    -- Generar código
    ----------------------------------------------------

    v_codigo := reciclaje.generar_codigo(
        p_company_id,
        'SOC'
    );

    ----------------------------------------------------
    -- Crear socio
    ----------------------------------------------------

    INSERT INTO reciclaje.socios (

        company_id,
        codigo,
        nombre,
        documento,
        telefono,
        direccion,
        observaciones,
        latitud,
        longitud

    )
    VALUES (

        p_company_id,
        v_codigo,
        trim(p_nombre),

        reciclaje.texto_nulo(p_documento),
        reciclaje.texto_nulo(p_telefono),
        reciclaje.texto_nulo(p_direccion),
        reciclaje.texto_nulo(p_observaciones),

        p_latitud,
        p_longitud

    )
    RETURNING *
    INTO v_socio;

    RETURN v_socio;

END;
$$;


--
-- Name: crear_transportista(uuid, text, text, text); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.crear_transportista(p_company_id uuid, p_nombre text, p_telefono text DEFAULT NULL::text, p_placa text DEFAULT NULL::text) RETURNS reciclaje.transportistas
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE

    v_codigo text;

    v_transportista reciclaje.transportistas;

BEGIN

    IF reciclaje.limpiar_texto(p_nombre) = '' THEN
        RAISE EXCEPTION 'El nombre es obligatorio.';
    END IF;

    IF reciclaje.limpiar_texto(p_placa) = '' THEN
        RAISE EXCEPTION 'La placa es obligatoria.';
    END IF;

    v_codigo := reciclaje.generar_codigo(
        p_company_id,
        'CAM'
    );

    INSERT INTO reciclaje.transportistas (

        company_id,

        codigo,

        nombre,

        telefono,

        placa

    )
    VALUES (

        p_company_id,

        v_codigo,

        reciclaje.limpiar_texto(p_nombre),

        reciclaje.texto_nulo(p_telefono),

        upper(
            reciclaje.limpiar_texto(p_placa)
        )

    )
    RETURNING *
    INTO v_transportista;

    RETURN v_transportista;

END;
$$;


--
-- Name: dashboard_diario(uuid, date); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.dashboard_diario(p_company_id uuid, p_fecha date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$

WITH limites AS (
    SELECT
        p_fecha::timestamp AS desde,
        (p_fecha + 1)::timestamp AS hasta
),

operaciones_dia AS (
    SELECT o.*
    FROM reciclaje.operaciones o
    CROSS JOIN limites l
    WHERE o.company_id = p_company_id
      AND o.created_at >= l.desde
      AND o.created_at < l.hasta
),

caja_dia AS (
    SELECT mc.*
    FROM reciclaje.movimientos_caja mc
    CROSS JOIN limites l
    WHERE mc.company_id = p_company_id
      AND mc.created_at >= l.desde
      AND mc.created_at < l.hasta
),

stock_dia AS (
    SELECT ms.*
    FROM reciclaje.movimientos_stock ms
    CROSS JOIN limites l
    WHERE ms.company_id = p_company_id
      AND ms.created_at >= l.desde
      AND ms.created_at < l.hasta
)

SELECT jsonb_build_object(

    'fecha',
        p_fecha,

    -- ========================================================
    -- RESUMEN COMERCIAL
    -- ========================================================

    'comercial',
        jsonb_build_object(

            'compras_cantidad',
                (
                    SELECT COUNT(*)
                    FROM operaciones_dia
                    WHERE tipo = 'compra'
                      AND COALESCE(finalizada, false) = true
                ),

            'compras_monto',
                COALESCE(
                    (
                        SELECT SUM(monto)
                        FROM operaciones_dia
                        WHERE tipo = 'compra'
                          AND COALESCE(finalizada, false) = true
                    ),
                    0
                ),

            'ventas_cantidad',
                (
                    SELECT COUNT(*)
                    FROM operaciones_dia
                    WHERE tipo = 'venta'
                      AND COALESCE(finalizada, false) = true
                ),

            'ventas_monto',
                COALESCE(
                    (
                        SELECT SUM(monto)
                        FROM operaciones_dia
                        WHERE tipo = 'venta'
                          AND COALESCE(finalizada, false) = true
                    ),
                    0
                )
        ),

    -- ========================================================
    -- OPERACIONES
    -- ========================================================

    'operaciones',
        jsonb_build_object(

            'precarga',
                (
                    SELECT COUNT(*)
                    FROM reciclaje.operaciones
                    WHERE company_id = p_company_id
                      AND etapa = 'precarga'
                      AND COALESCE(finalizada, false) = false
                ),

            'en_proceso',
                (
                    SELECT COUNT(*)
                    FROM reciclaje.operaciones
                    WHERE company_id = p_company_id
                      AND etapa = 'en_proceso'
                      AND COALESCE(finalizada, false) = false
                ),

            'finalizadas_hoy',
                (
                    SELECT COUNT(*)
                    FROM operaciones_dia
                    WHERE COALESCE(finalizada, false) = true
                ),

            'transportistas_en_proceso',
                (
                    SELECT COUNT(DISTINCT transportista_id)
                    FROM reciclaje.operaciones
                    WHERE company_id = p_company_id
                      AND etapa = 'en_proceso'
                      AND COALESCE(finalizada, false) = false
                      AND transportista_id IS NOT NULL
                )
        ),

    -- ========================================================
    -- CAJA
    -- ========================================================

    'caja',
        jsonb_build_object(

            'entradas',
                COALESCE(
                    (
                        SELECT SUM(monto_ars)
                        FROM caja_dia
                        WHERE tipo = 'entrada'
                    ),
                    0
                ),

            'salidas',
                COALESCE(
                    (
                        SELECT SUM(monto_ars)
                        FROM caja_dia
                        WHERE tipo = 'salida'
                    ),
                    0
                ),

            'neto',
                COALESCE(
                    (
                        SELECT SUM(
                            CASE
                                WHEN tipo = 'entrada'
                                    THEN monto_ars
                                WHEN tipo = 'salida'
                                    THEN -monto_ars
                                ELSE 0
                            END
                        )
                        FROM caja_dia
                    ),
                    0
                ),

            'movimientos',
                (
                    SELECT COUNT(*)
                    FROM caja_dia
                ),

            'ultimos_movimientos',
                COALESCE(
                    (
                        SELECT jsonb_agg(x.objeto)
                        FROM (
                            SELECT
                                jsonb_build_object(
                                    'id', mc.id,
                                    'tipo', mc.tipo,
                                    'monto', mc.monto,
                                    'moneda', mc.moneda,
                                    'tipo_cambio', mc.tipo_cambio,
                                    'monto_ars', mc.monto_ars,
                                    'concepto', mc.concepto,
                                    'descripcion', mc.descripcion,
                                    'responsable_tipo', mc.responsable_tipo,
                                    'responsable_nombre', mc.responsable_nombre,
                                    'created_at', mc.created_at
                                ) AS objeto
                            FROM caja_dia mc
                            ORDER BY mc.created_at DESC
                            LIMIT 10
                        ) x
                    ),
                    '[]'::jsonb
                )
        ),

    -- ========================================================
    -- INVENTARIO / MOVIMIENTOS DEL DÍA
    -- ========================================================

    'inventario',
        jsonb_build_object(

            'entradas',
                COALESCE(
                    (
                        SELECT SUM(ABS(cantidad))
                        FROM stock_dia
                        WHERE tipo_movimiento = 'entrada'
                    ),
                    0
                ),

            'salidas',
                COALESCE(
                    (
                        SELECT SUM(ABS(cantidad))
                        FROM stock_dia
                        WHERE tipo_movimiento = 'salida'
                    ),
                    0
                ),

            'ajustes',
                (
                    SELECT COUNT(*)
                    FROM stock_dia
                    WHERE tipo_movimiento = 'ajuste'
                ),

            'movimientos',
                (
                    SELECT COUNT(*)
                    FROM stock_dia
                ),

            'ultimos_movimientos',
                COALESCE(
                    (
                        SELECT jsonb_agg(x.objeto)
                        FROM (
                            SELECT
                                jsonb_build_object(
                                    'id', ms.id,
                                    'material_id', ms.material_id,
                                    'material', m.nombre,
                                    'unidad', m.unidad,
                                    'deposito_id', ms.deposito_id,
                                    'tipo', ms.tipo_movimiento,
                                    'cantidad', ms.cantidad,
                                    'origen', ms.origen,
                                    'created_at', ms.created_at
                                ) AS objeto
                            FROM stock_dia ms
                            JOIN reciclaje.materiales m
                              ON m.id = ms.material_id
                             AND m.company_id = p_company_id
                            ORDER BY ms.created_at DESC
                            LIMIT 10
                        ) x
                    ),
                    '[]'::jsonb
                )
        )

);

$$;


--
-- Name: dashboard_mensual(uuid, integer, integer); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.dashboard_mensual(p_company_id uuid, p_anio integer, p_mes integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE

    v_desde date;
    v_hasta date;

    v_resultado jsonb;

BEGIN

    ------------------------------------------------------------
    -- 1. VALIDAR PERÍODO
    ------------------------------------------------------------

    IF p_mes < 1 OR p_mes > 12 THEN
        RAISE EXCEPTION 'El mes debe estar entre 1 y 12.';
    END IF;

    IF p_anio < 2000 OR p_anio > 2100 THEN
        RAISE EXCEPTION 'El año indicado no es válido.';
    END IF;


    v_desde := make_date(
        p_anio,
        p_mes,
        1
    );

    v_hasta := (
        v_desde + INTERVAL '1 month'
    )::date;


    ------------------------------------------------------------
    -- 2. CONSTRUIR DASHBOARD
    ------------------------------------------------------------

    WITH

    ------------------------------------------------------------
    -- OPERACIONES FINALIZADAS DEL MES
    ------------------------------------------------------------

    operaciones_mes AS (

        SELECT o.*

        FROM reciclaje.operaciones o

        WHERE o.company_id = p_company_id

          AND o.finalizada = true

          AND o.finalizada_at >= v_desde
          AND o.finalizada_at < v_hasta

    ),


    ------------------------------------------------------------
    -- MOVIMIENTOS DE CAJA DEL MES
    ------------------------------------------------------------

    caja_mes AS (

        SELECT mc.*

        FROM reciclaje.movimientos_caja mc

        WHERE mc.company_id = p_company_id

          AND mc.created_at >= v_desde
          AND mc.created_at < v_hasta

    ),


    ------------------------------------------------------------
    -- MOVIMIENTOS DE INVENTARIO DEL MES
    ------------------------------------------------------------

    stock_mes AS (

        SELECT ms.*

        FROM reciclaje.movimientos_stock ms

        WHERE ms.company_id = p_company_id

          AND ms.created_at >= v_desde
          AND ms.created_at < v_hasta

    ),


    ------------------------------------------------------------
    -- CALENDARIO COMPLETO DEL MES
    ------------------------------------------------------------

    dias_mes AS (

        SELECT
            generate_series(
                v_desde,
                v_hasta - 1,
                INTERVAL '1 day'
            )::date AS fecha

    ),


    ------------------------------------------------------------
    -- COMPRAS ECONÓMICAS
    ------------------------------------------------------------

    compras AS (

        SELECT

            COALESCE(
                SUM(o.monto),
                0
            ) AS monto,

            COUNT(*) AS cantidad

        FROM operaciones_mes o

        WHERE o.tipo = 'compra'

    ),


    ------------------------------------------------------------
    -- VENTAS ECONÓMICAS
    ------------------------------------------------------------

    ventas AS (

        SELECT

            COALESCE(
                SUM(mc.monto_ars),
                0
            ) AS monto,

            COUNT(*) AS cantidad

        FROM caja_mes mc

        WHERE mc.concepto = 'venta'

    ),


    ------------------------------------------------------------
    -- GASTOS
    ------------------------------------------------------------

    gastos AS (

        SELECT

            COALESCE(
                SUM(mc.monto_ars),
                0
            ) AS monto

        FROM caja_mes mc

        WHERE mc.tipo = 'gasto'

    ),


    ------------------------------------------------------------
    -- CAJA
    ------------------------------------------------------------

    caja AS (

        SELECT

            COALESCE(
                SUM(
                    CASE
                        WHEN mc.tipo = 'entrada'
                        THEN mc.monto_ars
                        ELSE 0
                    END
                ),
                0
            ) AS entradas,


            COALESCE(
                SUM(
                    CASE
                        WHEN mc.tipo = 'salida'
                        THEN mc.monto_ars
                        ELSE 0
                    END
                ),
                0
            ) AS salidas

        FROM caja_mes mc

    ),


    ------------------------------------------------------------
    -- MATERIALES COMPRADOS
    ------------------------------------------------------------

    materiales_comprados AS (

        SELECT

            ms.material_id,

            m.nombre,

            m.unidad,

            SUM(
                ABS(ms.cantidad)
            ) AS cantidad

        FROM stock_mes ms

        JOIN reciclaje.materiales m
          ON m.id = ms.material_id
         AND m.company_id = p_company_id

        WHERE ms.tipo_movimiento = 'entrada'

          AND (
                ms.origen = 'recepcion'
                OR ms.origen = 'compra'
          )

        GROUP BY

            ms.material_id,
            m.nombre,
            m.unidad

    ),


    ------------------------------------------------------------
    -- MATERIALES VENDIDOS
    ------------------------------------------------------------

    materiales_vendidos AS (

        SELECT

            ms.material_id,

            m.nombre,

            m.unidad,

            SUM(
                ABS(ms.cantidad)
            ) AS cantidad

        FROM stock_mes ms

        JOIN reciclaje.materiales m
          ON m.id = ms.material_id
         AND m.company_id = p_company_id

        WHERE ms.tipo_movimiento = 'salida'

          AND ms.origen = 'venta'

        GROUP BY

            ms.material_id,
            m.nombre,
            m.unidad

    ),


    ------------------------------------------------------------
    -- SERIE DIARIA DE COMPRAS
    ------------------------------------------------------------

    compras_dia AS (

        SELECT

            o.finalizada_at::date AS fecha,

            SUM(o.monto) AS monto

        FROM operaciones_mes o

        WHERE o.tipo = 'compra'

        GROUP BY
            o.finalizada_at::date

    ),


    ------------------------------------------------------------
    -- SERIE DIARIA DE VENTAS
    ------------------------------------------------------------

    ventas_dia AS (

        SELECT

            mc.created_at::date AS fecha,

            SUM(mc.monto_ars) AS monto

        FROM caja_mes mc

        WHERE mc.concepto = 'venta'

        GROUP BY
            mc.created_at::date

    ),


    ------------------------------------------------------------
    -- SERIE DIARIA DE CAJA
    ------------------------------------------------------------

    caja_dia AS (

        SELECT

            mc.created_at::date AS fecha,


            SUM(
                CASE
                    WHEN mc.tipo = 'entrada'
                    THEN mc.monto_ars
                    ELSE 0
                END
            ) AS entradas,


            SUM(
                CASE
                    WHEN mc.tipo = 'salida'
                    THEN mc.monto_ars
                    ELSE 0
                END
            ) AS salidas

        FROM caja_mes mc

        GROUP BY
            mc.created_at::date

    )


    ------------------------------------------------------------
    -- 3. JSON FINAL
    ------------------------------------------------------------

    SELECT jsonb_build_object(

        --------------------------------------------------------
        -- PERÍODO
        --------------------------------------------------------

        'periodo',

            jsonb_build_object(

                'anio',
                    p_anio,

                'mes',
                    p_mes

            ),


        --------------------------------------------------------
        -- ECONÓMICO
        --------------------------------------------------------

        'economico',

            jsonb_build_object(

                'compras',
                    (
                        SELECT monto
                        FROM compras
                    ),

                'ventas',
                    (
                        SELECT monto
                        FROM ventas
                    ),

                'gastos',
                    (
                        SELECT monto
                        FROM gastos
                    )

            ),


        --------------------------------------------------------
        -- CAJA
        --------------------------------------------------------

        'caja',

            jsonb_build_object(

                'entradas',
                    (
                        SELECT entradas
                        FROM caja
                    ),

                'salidas',
                    (
                        SELECT salidas
                        FROM caja
                    ),

                'neto',
                    (
                        SELECT
                            entradas - salidas
                        FROM caja
                    )

            ),


        --------------------------------------------------------
        -- MATERIALES
        --------------------------------------------------------

        'materiales',

            jsonb_build_object(

                'comprados',

                    COALESCE(

                        (
                            SELECT jsonb_agg(

                                jsonb_build_object(

                                    'material_id',
                                        material_id,

                                    'nombre',
                                        nombre,

                                    'cantidad',
                                        cantidad,

                                    'unidad',
                                        unidad

                                )

                                ORDER BY nombre

                            )

                            FROM materiales_comprados
                        ),

                        '[]'::jsonb

                    ),


                'vendidos',

                    COALESCE(

                        (
                            SELECT jsonb_agg(

                                jsonb_build_object(

                                    'material_id',
                                        material_id,

                                    'nombre',
                                        nombre,

                                    'cantidad',
                                        cantidad,

                                    'unidad',
                                        unidad

                                )

                                ORDER BY nombre

                            )

                            FROM materiales_vendidos
                        ),

                        '[]'::jsonb

                    )

            ),


        --------------------------------------------------------
        -- CANTIDAD DE OPERACIONES
        --------------------------------------------------------

        'operaciones',

            jsonb_build_object(

                'compras',
                    (
                        SELECT cantidad
                        FROM compras
                    ),

                'ventas',
                    (
                        SELECT cantidad
                        FROM ventas
                    )

            ),


        --------------------------------------------------------
        -- SERIE DIARIA
        --------------------------------------------------------

        'dias',

            COALESCE(

                (
                    SELECT jsonb_agg(

                        jsonb_build_object(

                            'fecha',
                                d.fecha,

                            'compras',
                                COALESCE(
                                    c.monto,
                                    0
                                ),

                            'ventas',
                                COALESCE(
                                    v.monto,
                                    0
                                ),

                            'entradas',
                                COALESCE(
                                    cj.entradas,
                                    0
                                ),

                            'salidas',
                                COALESCE(
                                    cj.salidas,
                                    0
                                )

                        )

                        ORDER BY d.fecha

                    )

                    FROM dias_mes d

                    LEFT JOIN compras_dia c
                      ON c.fecha = d.fecha

                    LEFT JOIN ventas_dia v
                      ON v.fecha = d.fecha

                    LEFT JOIN caja_dia cj
                      ON cj.fecha = d.fecha

                ),

                '[]'::jsonb

            )

    )

    INTO v_resultado;


    ------------------------------------------------------------
    -- 4. RETORNAR
    ------------------------------------------------------------

    RETURN v_resultado;

END;
$$;


--
-- Name: eliminar_deposito(uuid, uuid); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.eliminar_deposito(p_company_id uuid, p_id uuid) RETURNS reciclaje.depositos
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE

    v_deposito reciclaje.depositos;

BEGIN

    UPDATE reciclaje.depositos

    SET

        activo = false,

        updated_at = now()

    WHERE company_id = p_company_id
      AND id = p_id

    RETURNING *
    INTO v_deposito;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Depósito no encontrado.';
    END IF;

    RETURN v_deposito;

END;
$$;


--
-- Name: eliminar_finanza(uuid, uuid); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.eliminar_finanza(p_company_id uuid, p_finanza_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN

    DELETE
      FROM reciclaje.finanzas
     WHERE id = p_finanza_id
       AND company_id = p_company_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Finanza no encontrada.';
    END IF;

END;
$$;


--
-- Name: eliminar_material(uuid, uuid); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.eliminar_material(p_company_id uuid, p_id uuid) RETURNS reciclaje.materiales
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE

    v_material reciclaje.materiales;

BEGIN

    UPDATE reciclaje.materiales

    SET

        activo = false,

        updated_at = now()

    WHERE company_id = p_company_id
      AND id = p_id

    RETURNING *
    INTO v_material;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Material no encontrado.';
    END IF;

    RETURN v_material;

END;
$$;


--
-- Name: operaciones; Type: TABLE; Schema: reciclaje; Owner: -
--

CREATE TABLE reciclaje.operaciones (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    tipo reciclaje.tipo_operacion DEFAULT 'compra'::reciclaje.tipo_operacion NOT NULL,
    etapa reciclaje.etapa_operacion DEFAULT 'precarga'::reciclaje.etapa_operacion NOT NULL,
    socio_id uuid,
    transportista_id uuid,
    deposito_id uuid,
    monto numeric(14,2),
    materiales jsonb DEFAULT '[]'::jsonb NOT NULL,
    pagos jsonb DEFAULT '[]'::jsonb NOT NULL,
    recibido_por text,
    responsable_nombre text,
    responsable_tipo text,
    observaciones text,
    orden_compra_id uuid,
    recepcion_id uuid,
    finanza_id uuid,
    finalizada boolean DEFAULT false NOT NULL,
    finalizada_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    movimiento_salida_id uuid,
    grupo_salida_id uuid,
    CONSTRAINT operaciones_materiales_array_check CHECK ((jsonb_typeof(materiales) = 'array'::text)),
    CONSTRAINT operaciones_monto_check CHECK (((monto IS NULL) OR (monto >= (0)::numeric))),
    CONSTRAINT operaciones_pagos_array_check CHECK ((jsonb_typeof(pagos) = 'array'::text))
);


--
-- Name: eliminar_operacion(uuid, uuid); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.eliminar_operacion(p_company_id uuid, p_operacion_id uuid) RETURNS reciclaje.operaciones
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE

    v_operacion reciclaje.operaciones;

    v_movimiento reciclaje.movimientos_caja%ROWTYPE;

BEGIN

    ------------------------------------------------------------
    -- 1. BUSCAR Y BLOQUEAR OPERACIÓN
    ------------------------------------------------------------

    SELECT *
    INTO v_operacion
    FROM reciclaje.operaciones
    WHERE company_id = p_company_id
      AND id = p_operacion_id
    FOR UPDATE;


    IF NOT FOUND THEN

        RAISE EXCEPTION
            'La operación no existe.';

    END IF;


    ------------------------------------------------------------
    -- 2. FINALIZADA NO SE PUEDE ELIMINAR
    ------------------------------------------------------------

    IF v_operacion.finalizada = true
       OR v_operacion.etapa = 'finalizada'::reciclaje.etapa_operacion
    THEN

        RAISE EXCEPTION
            'Una operación finalizada no puede eliminarse.';

    END IF;


    ------------------------------------------------------------
    -- 3. SI ESTÁ EN PROCESO:
    --    REVERTIR LAS SALIDAS DE CAJA DE ESTA OPERACIÓN
    --
    -- NO borramos el movimiento original.
    -- Creamos una ENTRADA compensatoria para conservar
    -- la trazabilidad.
    ------------------------------------------------------------

    IF v_operacion.etapa = 'en_proceso'::reciclaje.etapa_operacion
    THEN

        FOR v_movimiento IN

            SELECT mc.*
            FROM reciclaje.movimientos_caja mc
            WHERE mc.company_id = p_company_id
              AND mc.origen_tipo = 'operacion'
              AND mc.origen_id = p_operacion_id
              AND mc.tipo = 'salida'
            ORDER BY mc.created_at

        LOOP

            INSERT INTO reciclaje.movimientos_caja (

                company_id,

                tipo,

                monto,

                moneda,

                tipo_cambio,

                monto_ars,

                forma_pago,

                referencia,

                concepto,

                descripcion,

                origen_tipo,

                origen_id,

                responsable_tipo,

                responsable_id,

                responsable_nombre,

                comprobante_url,

                observaciones

            )

            VALUES (

                p_company_id,

                'entrada',

                v_movimiento.monto,

                v_movimiento.moneda,

                v_movimiento.tipo_cambio,

                v_movimiento.monto_ars,

                v_movimiento.forma_pago,

                v_movimiento.referencia,

                'devolucion_cancelacion_operacion',

                'Devolución de fondos por eliminación de operación',

                'operacion',

                p_operacion_id,

                v_movimiento.responsable_tipo,

                v_movimiento.responsable_id,

                v_movimiento.responsable_nombre,

                NULL,

                'Movimiento compensatorio de la salida de caja '
                || v_movimiento.id::text

            );

        END LOOP;

    END IF;


    ------------------------------------------------------------
    -- 4. ELIMINAR OPERACIÓN
    ------------------------------------------------------------

    DELETE FROM reciclaje.operaciones
    WHERE company_id = p_company_id
      AND id = p_operacion_id;


    ------------------------------------------------------------
    -- 5. DEVOLVER OPERACIÓN ELIMINADA
    ------------------------------------------------------------

    RETURN v_operacion;

END;
$$;


--
-- Name: eliminar_operacion_multicarga(uuid, uuid); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.eliminar_operacion_multicarga(p_company_id uuid, p_operacion_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE

    v_operacion reciclaje.operaciones;

    v_grupo_salida_id uuid;
    v_movimiento_salida_id uuid;

    v_movimiento reciclaje.movimientos_caja%ROWTYPE;

    v_operaciones_restantes integer;

    v_movimiento_devolucion_id uuid;

BEGIN

    ------------------------------------------------------------
    -- 1. BUSCAR Y BLOQUEAR OPERACIÓN
    ------------------------------------------------------------

    SELECT *
    INTO v_operacion
    FROM reciclaje.operaciones
    WHERE company_id = p_company_id
      AND id = p_operacion_id
    FOR UPDATE;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'La operación no existe.';
    END IF;


    ------------------------------------------------------------
    -- 2. FINALIZADA NO SE PUEDE ELIMINAR
    ------------------------------------------------------------

    IF COALESCE(v_operacion.finalizada, false) = true
       OR v_operacion.etapa =
          'finalizada'::reciclaje.etapa_operacion
    THEN

        RAISE EXCEPTION
            'Una operación finalizada no puede eliminarse.';

    END IF;


    ------------------------------------------------------------
    -- 3. GUARDAR RELACIÓN ANTES DE ELIMINAR
    ------------------------------------------------------------

    v_grupo_salida_id :=
        v_operacion.grupo_salida_id;

    v_movimiento_salida_id :=
        v_operacion.movimiento_salida_id;


    ------------------------------------------------------------
    -- 4. SI NO PERTENECE A MULTICARGA
    --
    -- Puede ser una precarga normal.
    ------------------------------------------------------------

    IF v_grupo_salida_id IS NULL THEN

        DELETE FROM reciclaje.operaciones
        WHERE company_id = p_company_id
          AND id = p_operacion_id;


        RETURN jsonb_build_object(

            'ok',
                true,

            'operacion_id',
                p_operacion_id,

            'grupo_salida_id',
                NULL,

            'operaciones_restantes',
                0,

            'devolucion_generada',
                false,

            'movimiento_devolucion_id',
                NULL

        );

    END IF;


    ------------------------------------------------------------
    -- 5. BLOQUEAR EL RESTO DEL GRUPO
    ------------------------------------------------------------

    PERFORM o.id
    FROM reciclaje.operaciones o
    WHERE o.company_id = p_company_id
      AND o.grupo_salida_id = v_grupo_salida_id
    ORDER BY o.id
    FOR UPDATE;


    ------------------------------------------------------------
    -- 6. ELIMINAR SOLAMENTE ESTA OPERACIÓN
    ------------------------------------------------------------

    DELETE FROM reciclaje.operaciones
    WHERE company_id = p_company_id
      AND id = p_operacion_id;


    ------------------------------------------------------------
    -- 7. CONTAR CUÁNTAS QUEDAN DEL MISMO GRUPO
    ------------------------------------------------------------

    SELECT COUNT(*)
    INTO v_operaciones_restantes
    FROM reciclaje.operaciones
    WHERE company_id = p_company_id
      AND grupo_salida_id = v_grupo_salida_id;


    ------------------------------------------------------------
    -- 8. SI TODAVÍA QUEDA AL MENOS UNA:
    --    NO TOCAR CAJA
    ------------------------------------------------------------

    IF v_operaciones_restantes > 0 THEN

        RETURN jsonb_build_object(

            'ok',
                true,

            'operacion_id',
                p_operacion_id,

            'grupo_salida_id',
                v_grupo_salida_id,

            'operaciones_restantes',
                v_operaciones_restantes,

            'devolucion_generada',
                false,

            'movimiento_devolucion_id',
                NULL

        );

    END IF;


    ------------------------------------------------------------
    -- 9. ERA LA ÚLTIMA OPERACIÓN DEL GRUPO
    --
    -- Si hubo dinero entregado, recuperamos el movimiento
    -- original.
    ------------------------------------------------------------

    IF v_movimiento_salida_id IS NOT NULL THEN

        SELECT *
        INTO v_movimiento
        FROM reciclaje.movimientos_caja
        WHERE company_id = p_company_id
          AND id = v_movimiento_salida_id
        FOR UPDATE;


        IF NOT FOUND THEN

            RAISE EXCEPTION
                'No se encontró el movimiento de Caja asociado al grupo.';

        END IF;


        --------------------------------------------------------
        -- EVITAR DEVOLUCIÓN DOBLE
        --------------------------------------------------------

        IF EXISTS (

            SELECT 1

            FROM reciclaje.movimientos_caja mc

            WHERE mc.company_id = p_company_id

              AND mc.tipo = 'entrada'

              AND mc.origen_tipo =
                  'devolucion_grupo_operaciones'

              AND mc.origen_id =
                  v_grupo_salida_id

        )
        THEN

            RAISE EXCEPTION
                'La devolución de este grupo ya fue registrada.';

        END IF;


        --------------------------------------------------------
        -- 10. CREAR CONTRAMOVIMIENTO
        --------------------------------------------------------

        INSERT INTO reciclaje.movimientos_caja (

            company_id,

            tipo,

            monto,

            moneda,

            tipo_cambio,

            monto_ars,

            forma_pago,

            referencia,

            concepto,

            descripcion,

            origen_tipo,

            origen_id,

            responsable_tipo,

            responsable_id,

            responsable_nombre,

            comprobante_url,

            observaciones

        )

        VALUES (

            p_company_id,

            'entrada',

            v_movimiento.monto,

            v_movimiento.moneda,

            v_movimiento.tipo_cambio,

            v_movimiento.monto_ars,

            v_movimiento.forma_pago,

            v_movimiento.referencia,

            'devolucion_cancelacion_multicarga',

            'Devolución total de fondos por eliminación de la última operación del grupo',

            'devolucion_grupo_operaciones',

            v_grupo_salida_id,

            v_movimiento.responsable_tipo,

            v_movimiento.responsable_id,

            v_movimiento.responsable_nombre,

            NULL,

            'Contramovimiento de la salida de Caja '
            || v_movimiento.id::text

        )

        RETURNING id
        INTO v_movimiento_devolucion_id;

    END IF;


    ------------------------------------------------------------
    -- 11. RESULTADO
    ------------------------------------------------------------

    RETURN jsonb_build_object(

        'ok',
            true,

        'operacion_id',
            p_operacion_id,

        'grupo_salida_id',
            v_grupo_salida_id,

        'operaciones_restantes',
            0,

        'devolucion_generada',
            v_movimiento_devolucion_id IS NOT NULL,

        'movimiento_salida_id',
            v_movimiento_salida_id,

        'movimiento_devolucion_id',
            v_movimiento_devolucion_id

    );

END;
$$;


--
-- Name: eliminar_orden_compra(uuid, uuid); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.eliminar_orden_compra(p_company_id uuid, p_id uuid) RETURNS reciclaje.ordenes_compra
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE

    v_orden reciclaje.ordenes_compra;

BEGIN

    SELECT *
    INTO v_orden
    FROM reciclaje.ordenes_compra
    WHERE company_id = p_company_id
      AND id = p_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'La orden de compra no existe.';
    END IF;

    IF v_orden.estado <> 'borrador' THEN
        RAISE EXCEPTION 'Solo se puede eliminar una orden en borrador.';
    END IF;

    DELETE FROM reciclaje.ordenes_compra
    WHERE id = p_id
      AND company_id = p_company_id
    RETURNING *
    INTO v_orden;

    RETURN v_orden;

END;
$$;


--
-- Name: eliminar_socio(uuid, uuid); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.eliminar_socio(p_company_id uuid, p_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN

    UPDATE reciclaje.socios

    SET

        activo = false,

        updated_at = now()

    WHERE company_id = p_company_id
    AND id = p_id;

    RETURN FOUND;

END;
$$;


--
-- Name: eliminar_transportista(uuid, uuid); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.eliminar_transportista(p_company_id uuid, p_id uuid) RETURNS reciclaje.transportistas
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE

    v_transportista reciclaje.transportistas;

BEGIN

    UPDATE reciclaje.transportistas

    SET

        activo = false,

        updated_at = now()

    WHERE company_id = p_company_id
      AND id = p_id

    RETURNING *
    INTO v_transportista;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Transportista no encontrado.';
    END IF;

    RETURN v_transportista;

END;
$$;


--
-- Name: enum_to_json(text); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.enum_to_json(p_enum text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$

SELECT COALESCE(

    jsonb_agg(

        jsonb_build_object(

            'id', enumlabel,

            'nombre',
            initcap(
                replace(enumlabel,'_',' ')
            )

        )

        ORDER BY enumsortorder

    ),

    '[]'::jsonb

)

FROM pg_enum e

JOIN pg_type t

ON t.oid = e.enumtypid

JOIN pg_namespace n

ON n.oid = t.typnamespace

WHERE

    n.nspname = 'reciclaje'

AND

    t.typname = p_enum;

$$;


--
-- Name: generar_codigo(uuid, text); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.generar_codigo(p_company_id uuid, p_tipo_documento text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_prefijo text;
    v_numero integer;
BEGIN

    v_prefijo := upper(trim(p_tipo_documento));

    INSERT INTO reciclaje.numeradores (
        company_id,
        tipo_documento,
        ultimo_numero
    )
    VALUES (
        p_company_id,
        v_prefijo,
        1
    )
    ON CONFLICT (
        company_id,
        tipo_documento
    )
    DO UPDATE
    SET ultimo_numero = reciclaje.numeradores.ultimo_numero + 1
    RETURNING ultimo_numero
    INTO v_numero;

    RETURN format(
        '%s-%06s',
        v_prefijo,
        v_numero
    );

END;
$$;


--
-- Name: precios_socios; Type: TABLE; Schema: reciclaje; Owner: -
--

CREATE TABLE reciclaje.precios_socios (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    socio_id uuid NOT NULL,
    material_id uuid NOT NULL,
    precio numeric(14,2) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    observaciones text,
    CONSTRAINT precios_socios_precio_check CHECK ((precio >= (0)::numeric))
);


--
-- Name: guardar_precio_socio(uuid, uuid, uuid, numeric, text); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.guardar_precio_socio(p_company_id uuid, p_socio_id uuid, p_material_id uuid, p_precio numeric, p_observaciones text DEFAULT NULL::text) RETURNS reciclaje.precios_socios
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_precio reciclaje.precios_socios;
BEGIN

    IF p_precio IS NULL OR p_precio < 0 THEN
        RAISE EXCEPTION 'El precio no puede ser nulo ni negativo.';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM reciclaje.socios
        WHERE company_id = p_company_id
          AND id = p_socio_id
          AND activo = true
    ) THEN
        RAISE EXCEPTION 'El socio no existe.';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM reciclaje.materiales
        WHERE company_id = p_company_id
          AND id = p_material_id
          AND activo = true
    ) THEN
        RAISE EXCEPTION 'El material no existe.';
    END IF;


    INSERT INTO reciclaje.precios_socios (
        company_id,
        socio_id,
        material_id,
        precio,
        observaciones
    )
    VALUES (
        p_company_id,
        p_socio_id,
        p_material_id,
        p_precio,
        reciclaje.texto_nulo(p_observaciones)
    )

    ON CONFLICT (company_id, socio_id, material_id)

    DO UPDATE SET
        precio = EXCLUDED.precio,
        observaciones = EXCLUDED.observaciones,
        updated_at = now()

    RETURNING *
    INTO v_precio;


    RETURN v_precio;

END;
$$;


--
-- Name: iniciar_operaciones_multicarga(uuid, jsonb); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.iniciar_operaciones_multicarga(p_company_id uuid, p_datos jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE

    v_operacion_ids uuid[];

    v_transportista_id uuid;
    v_transportista_nombre text;

    v_grupo_salida_id uuid;

    v_caja jsonb;

    v_monto numeric(14,2) := 0;
    v_moneda text;
    v_tipo_cambio numeric(14,6) := 1;
    v_monto_ars numeric(14,2) := 0;

    v_movimiento_salida_id uuid;

    v_cantidad_solicitada integer;
    v_cantidad_valida integer;
    v_cantidad_actualizada integer;

BEGIN

    ------------------------------------------------------------
    -- 1. VALIDAR OPERACIONES
    ------------------------------------------------------------

    IF jsonb_typeof(
        COALESCE(
            p_datos->'operacion_ids',
            '[]'::jsonb
        )
    ) <> 'array'
    THEN
        RAISE EXCEPTION
            'operacion_ids debe ser un array.';
    END IF;


    SELECT ARRAY_AGG(DISTINCT x::uuid)
    INTO v_operacion_ids
    FROM jsonb_array_elements_text(
        COALESCE(
            p_datos->'operacion_ids',
            '[]'::jsonb
        )
    ) AS t(x);


    v_cantidad_solicitada :=
        COALESCE(
            array_length(v_operacion_ids, 1),
            0
        );


    IF v_cantidad_solicitada = 0 THEN
        RAISE EXCEPTION
            'Debe indicar al menos una operación.';
    END IF;


    ------------------------------------------------------------
    -- 2. TRANSPORTISTA
    ------------------------------------------------------------

    v_transportista_id :=
        NULLIF(
            p_datos->>'transportista_id',
            ''
        )::uuid;


    IF v_transportista_id IS NULL THEN
        RAISE EXCEPTION
            'Debe indicar el transportista.';
    END IF;


    SELECT t.nombre
    INTO v_transportista_nombre
    FROM reciclaje.transportistas t
    WHERE t.company_id = p_company_id
      AND t.id = v_transportista_id
      AND t.activo = true;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El transportista no existe o está inactivo.';
    END IF;


    ------------------------------------------------------------
    -- 3. BLOQUEAR OPERACIONES
    ------------------------------------------------------------

    PERFORM o.id
    FROM reciclaje.operaciones o
    WHERE o.company_id = p_company_id
      AND o.id = ANY(v_operacion_ids)
    ORDER BY o.id
    FOR UPDATE;


    ------------------------------------------------------------
    -- 4. VALIDAR QUE TODAS PUEDAN SALIR
    ------------------------------------------------------------

    SELECT COUNT(*)
    INTO v_cantidad_valida
    FROM reciclaje.operaciones o
    WHERE o.company_id = p_company_id
      AND o.id = ANY(v_operacion_ids)
      AND o.etapa = 'precarga'::reciclaje.etapa_operacion
      AND COALESCE(o.finalizada, false) = false
      AND o.grupo_salida_id IS NULL;


    IF v_cantidad_valida <> v_cantidad_solicitada THEN
        RAISE EXCEPTION
            'Todas las operaciones deben existir, estar en precarga y no pertenecer a otra salida.';
    END IF;


    ------------------------------------------------------------
    -- 5. CREAR IDENTIFICADOR COMÚN DEL VIAJE
    ------------------------------------------------------------

    v_grupo_salida_id :=
        gen_random_uuid();


    ------------------------------------------------------------
    -- 6. DATOS DE CAJA
    ------------------------------------------------------------

    v_caja :=
        COALESCE(
            p_datos->'caja',
            '{}'::jsonb
        );


    v_monto :=
        COALESCE(
            NULLIF(
                v_caja->>'monto',
                ''
            )::numeric,
            0
        );


    IF v_monto < 0 THEN
        RAISE EXCEPTION
            'El monto entregado no puede ser negativo.';
    END IF;


    ------------------------------------------------------------
    -- 7. SI HUBO DINERO ENTREGADO
    ------------------------------------------------------------

    IF v_monto > 0 THEN

        v_moneda :=
            NULLIF(
                trim(v_caja->>'moneda'),
                ''
            );


        IF v_moneda IS NULL THEN
            RAISE EXCEPTION
                'Debe indicar la moneda.';
        END IF;


        --------------------------------------------------------
        -- ARS SIEMPRE TC = 1
        --------------------------------------------------------

        IF upper(v_moneda) = 'ARS' THEN

            v_tipo_cambio := 1;

        ELSE

            v_tipo_cambio :=
                COALESCE(
                    NULLIF(
                        v_caja->>'tipo_cambio',
                        ''
                    )::numeric,
                    0
                );


            IF v_tipo_cambio <= 0 THEN
                RAISE EXCEPTION
                    'Debe indicar un tipo de cambio mayor a cero.';
            END IF;

        END IF;


        v_monto_ars :=
            ROUND(
                v_monto * v_tipo_cambio,
                2
            );


        --------------------------------------------------------
        -- UN ÚNICO MOVIMIENTO DE CAJA PARA TODO EL GRUPO
        --------------------------------------------------------

        INSERT INTO reciclaje.movimientos_caja (

            company_id,

            tipo,

            monto,

            moneda,

            tipo_cambio,

            monto_ars,

            forma_pago,

            referencia,

            concepto,

            descripcion,

            origen_tipo,

            origen_id,

            responsable_tipo,

            responsable_id,

            responsable_nombre,

            comprobante_url,

            observaciones

        )

        VALUES (

            p_company_id,

            'salida',

            v_monto,

            v_moneda,

            v_tipo_cambio,

            v_monto_ars,

            reciclaje.texto_nulo(
                v_caja->>'forma_pago'
            ),

            reciclaje.texto_nulo(
                v_caja->>'referencia'
            ),

            'entrega_operacion_multicarga',

            CASE
                WHEN v_cantidad_solicitada = 1
                THEN
                    'Entrega de fondos al transportista para iniciar operación'
                ELSE
                    'Entrega de fondos al transportista para '
                    || v_cantidad_solicitada::text
                    || ' operaciones'
            END,

            'grupo_operaciones',

            v_grupo_salida_id,

            'transportista',

            v_transportista_id,

            v_transportista_nombre,

            reciclaje.texto_nulo(
                v_caja->>'comprobante_url'
            ),

            reciclaje.texto_nulo(
                v_caja->>'observaciones'
            )

        )

        RETURNING id
        INTO v_movimiento_salida_id;

    END IF;


    ------------------------------------------------------------
    -- 8. PASAR TODAS LAS OPERACIONES A EN_PROCESO
    ------------------------------------------------------------

    UPDATE reciclaje.operaciones

    SET

        transportista_id =
            v_transportista_id,

        grupo_salida_id =
            v_grupo_salida_id,

        movimiento_salida_id =
            v_movimiento_salida_id,

        etapa =
            'en_proceso'::reciclaje.etapa_operacion,

        updated_at =
            now()

    WHERE company_id = p_company_id
      AND id = ANY(v_operacion_ids);


    GET DIAGNOSTICS
        v_cantidad_actualizada = ROW_COUNT;


    IF v_cantidad_actualizada <> v_cantidad_solicitada THEN
        RAISE EXCEPTION
            'No fue posible iniciar todas las operaciones.';
    END IF;


    ------------------------------------------------------------
    -- 9. RESPUESTA
    ------------------------------------------------------------

    RETURN jsonb_build_object(

        'ok',
            true,

        'grupo_salida_id',
            v_grupo_salida_id,

        'movimiento_salida_id',
            v_movimiento_salida_id,

        'transportista_id',
            v_transportista_id,

        'transportista_nombre',
            v_transportista_nombre,

        'cantidad_operaciones',
            v_cantidad_solicitada,

        'monto_entregado',
            v_monto,

        'moneda',
            v_moneda,

        'tipo_cambio',
            v_tipo_cambio,

        'monto_ars',
            v_monto_ars,

        'operaciones',
            (
                SELECT COALESCE(
                    jsonb_agg(
                        jsonb_build_object(

                            'id',
                                o.id,

                            'socio_id',
                                o.socio_id,

                            'etapa',
                                o.etapa,

                            'transportista_id',
                                o.transportista_id,

                            'grupo_salida_id',
                                o.grupo_salida_id,

                            'movimiento_salida_id',
                                o.movimiento_salida_id

                        )
                        ORDER BY o.created_at
                    ),
                    '[]'::jsonb
                )

                FROM reciclaje.operaciones o

                WHERE o.company_id = p_company_id
                  AND o.grupo_salida_id = v_grupo_salida_id
            )

    );

END;
$$;


--
-- Name: limpiar_texto(text); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.limpiar_texto(p_texto text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
SELECT trim(coalesce(p_texto, ''));
$$;


--
-- Name: listar_depositos(uuid); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.listar_depositos(p_company_id uuid) RETURNS SETOF reciclaje.depositos
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$

SELECT *

FROM reciclaje.depositos

WHERE company_id = p_company_id
  AND activo = true

ORDER BY nombre;

$$;


--
-- Name: listar_finanzas(uuid); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.listar_finanzas(p_company_id uuid) RETURNS SETOF reciclaje.finanzas
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY

    SELECT *
      FROM reciclaje.finanzas
     WHERE company_id = p_company_id
     ORDER BY fecha_emision DESC, created_at DESC;

END;
$$;


--
-- Name: listar_finanzas(uuid, boolean); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.listar_finanzas(p_company_id uuid, p_incluir_anuladas boolean DEFAULT false) RETURNS SETOF reciclaje.finanzas
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
    SELECT *
      FROM reciclaje.finanzas
     WHERE company_id = p_company_id
       AND (p_incluir_anuladas OR NOT anulado)
     ORDER BY fecha_emision DESC, created_at DESC;

END;
$$;


--
-- Name: listar_inventario(uuid, uuid); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.listar_inventario(p_company_id uuid, p_deposito_id uuid DEFAULT NULL::uuid) RETURNS TABLE(deposito_id uuid, deposito_codigo text, deposito_nombre text, material_id uuid, material_codigo text, material_nombre text, unidad text, imagen_url text, compuesto boolean, entradas numeric, salidas numeric, ajustes numeric, traslados numeric, stock numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$

    SELECT

        d.id AS deposito_id,
        d.codigo AS deposito_codigo,
        d.nombre AS deposito_nombre,

        m.id AS material_id,
        m.codigo AS material_codigo,
        m.nombre AS material_nombre,
        m.unidad,
        m.imagen_url,
        m.compuesto,

        COALESCE(
            SUM(ABS(ms.cantidad))
            FILTER (
                WHERE ms.tipo_movimiento = 'entrada'
            ),
            0
        ) AS entradas,

        COALESCE(
            SUM(ABS(ms.cantidad))
            FILTER (
                WHERE ms.tipo_movimiento = 'salida'
            ),
            0
        ) AS salidas,

        COALESCE(
            SUM(ms.cantidad)
            FILTER (
                WHERE ms.tipo_movimiento = 'ajuste'
            ),
            0
        ) AS ajustes,

        COALESCE(
            SUM(ms.cantidad)
            FILTER (
                WHERE ms.tipo_movimiento = 'traslado'
            ),
            0
        ) AS traslados,

        COALESCE(
            SUM(
                CASE

                    WHEN ms.tipo_movimiento = 'entrada'
                        THEN ABS(ms.cantidad)

                    WHEN ms.tipo_movimiento = 'salida'
                        THEN -ABS(ms.cantidad)

                    WHEN ms.tipo_movimiento = 'ajuste'
                        THEN ms.cantidad

                    WHEN ms.tipo_movimiento = 'traslado'
                        THEN ms.cantidad

                    ELSE 0

                END
            ),
            0
        ) AS stock

    FROM reciclaje.movimientos_stock ms

    JOIN reciclaje.materiales m
      ON m.id = ms.material_id
     AND m.company_id = p_company_id

    JOIN reciclaje.depositos d
      ON d.id = ms.deposito_id
     AND d.company_id = p_company_id

    WHERE ms.company_id = p_company_id

      AND (
          p_deposito_id IS NULL
          OR ms.deposito_id = p_deposito_id
      )

    GROUP BY

        d.id,
        d.codigo,
        d.nombre,

        m.id,
        m.codigo,
        m.nombre,
        m.unidad,
        m.imagen_url,
        m.compuesto

    ORDER BY
        d.nombre,
        m.nombre;

$$;


--
-- Name: listar_materiales(uuid); Type: FUNCTION; Schema: reciclaje; Owner: -
