    END IF;

    RETURN v_material;

END;
$$;


--
-- Name: obtener_operacion(uuid, uuid); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.obtener_operacion(p_company_id uuid, p_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$

SELECT jsonb_build_object(

    ------------------------------------------------------------
    -- OPERACIÓN
    ------------------------------------------------------------

    'id', o.id,
    'company_id', o.company_id,

    'tipo', o.tipo,
    'etapa', o.etapa,

    'monto', o.monto,

    ------------------------------------------------------------
    -- SOCIO
    ------------------------------------------------------------

    'socio',
        CASE
            WHEN s.id IS NULL THEN NULL
            ELSE jsonb_build_object(
                'id', s.id,
                'codigo', s.codigo,
                'nombre', s.nombre,
                'direccion', s.direccion,
                'latitud', s.latitud,
                'longitud', s.longitud
            )
        END,

    ------------------------------------------------------------
    -- TRANSPORTISTA
    ------------------------------------------------------------

    'transportista',
        CASE
            WHEN t.id IS NULL THEN NULL
            ELSE jsonb_build_object(
                'id', t.id,
                'codigo', t.codigo,
                'nombre', t.nombre,
                'telefono', t.telefono,
                'placa', t.placa
            )
        END,

    ------------------------------------------------------------
    -- DEPÓSITO
    ------------------------------------------------------------

    'deposito',
        CASE
            WHEN d.id IS NULL THEN NULL
            ELSE jsonb_build_object(
                'id', d.id,
                'codigo', d.codigo,
                'nombre', d.nombre
            )
        END,

    ------------------------------------------------------------
    -- MATERIALES ENRIQUECIDOS
    ------------------------------------------------------------

    'materiales',

    COALESCE(
        (
            SELECT jsonb_agg(

                jsonb_build_object(

                    'material_id',
                        x.material_id,

                    'codigo',
                        m.codigo,

                    'nombre',
                        m.nombre,

                    'unidad',
                        m.unidad,

                    'imagen_url',
                        m.imagen_url,

                    'cantidad',
                        x.cantidad,

                    'precio_unitario',
                        x.precio_unitario,

                    'subtotal',
                        x.cantidad * x.precio_unitario,

                    'guardar_precio_socio',
                        x.guardar_precio_socio

                )

            )

            FROM (

                SELECT

                    (j->>'material_id')::uuid
                        AS material_id,

                    COALESCE(
                        NULLIF(j->>'cantidad', '')::numeric,
                        0
                    ) AS cantidad,

                    COALESCE(
                        NULLIF(j->>'precio_unitario', '')::numeric,
                        0
                    ) AS precio_unitario,

                    COALESCE(
                        NULLIF(j->>'guardar_precio_socio', '')::boolean,
                        false
                    ) AS guardar_precio_socio

                FROM jsonb_array_elements(
                    COALESCE(
                        o.materiales,
                        '[]'::jsonb
                    )
                ) j

            ) x

            LEFT JOIN reciclaje.materiales m
                   ON m.id = x.material_id
                  AND m.company_id = p_company_id

        ),
        '[]'::jsonb
    ),

    ------------------------------------------------------------
    -- PAGOS ENRIQUECIDOS
    ------------------------------------------------------------

    'pagos',

    COALESCE(
        (
            SELECT jsonb_agg(

                jsonb_build_object(

                    'forma_pago_id',
                        x.forma_pago_id,

                    'forma_pago_codigo',
                        fp.codigo,

                    'forma_pago_nombre',
                        fp.nombre,

                    'moneda_id',
                        x.moneda_id,

                    'moneda_codigo',
                        mo.codigo,

                    'moneda_nombre',
                        mo.nombre,

                    'moneda_simbolo',
                        mo.simbolo,

                    'monto',
                        x.monto,

                    'referencia',
                        x.referencia,

                    'observaciones',
                        x.observaciones

                )

            )

            FROM (

                SELECT

                    (j->>'forma_pago_id')::uuid
                        AS forma_pago_id,

                    (j->>'moneda_id')::uuid
                        AS moneda_id,

                    COALESCE(
                        NULLIF(j->>'monto', '')::numeric,
                        0
                    ) AS monto,

                    NULLIF(
                        trim(j->>'referencia'),
                        ''
                    ) AS referencia,

                    NULLIF(
                        trim(j->>'observaciones'),
                        ''
                    ) AS observaciones

                FROM jsonb_array_elements(
                    COALESCE(
                        o.pagos,
                        '[]'::jsonb
                    )
                ) j

            ) x

            LEFT JOIN reciclaje.formas_pago fp
                   ON fp.id = x.forma_pago_id

            LEFT JOIN reciclaje.monedas mo
                   ON mo.id = x.moneda_id

        ),
        '[]'::jsonb
    ),

    ------------------------------------------------------------
    -- RECEPCIÓN / RESPONSABLE
    ------------------------------------------------------------

    'recibido_por',
        o.recibido_por,

    'responsable_nombre',
        o.responsable_nombre,

    'responsable_tipo',
        o.responsable_tipo,

    'observaciones',
        o.observaciones,

    ------------------------------------------------------------
    -- RESULTADO
    ------------------------------------------------------------

    'finalizada',
        o.finalizada,

    'orden_compra_id',
        o.orden_compra_id,

    'recepcion_id',
        o.recepcion_id,

    'finanza_id',
        o.finanza_id,

    ------------------------------------------------------------
    -- FECHAS
    ------------------------------------------------------------

    'created_at',
        o.created_at,

    'updated_at',
        o.updated_at,

    'finalizada_at',
        o.finalizada_at

)

FROM reciclaje.operaciones o

LEFT JOIN reciclaje.socios s
       ON s.id = o.socio_id
      AND s.company_id = p_company_id

LEFT JOIN reciclaje.transportistas t
       ON t.id = o.transportista_id
      AND t.company_id = p_company_id

LEFT JOIN reciclaje.depositos d
       ON d.id = o.deposito_id
      AND d.company_id = p_company_id

WHERE o.company_id = p_company_id
  AND o.id = p_id;

$$;


--
-- Name: obtener_orden_compra(uuid, uuid); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.obtener_orden_compra(p_company_id uuid, p_id uuid) RETURNS TABLE(id uuid, company_id uuid, codigo text, socio_id uuid, socio_codigo text, socio_nombre text, transportista_id uuid, transportista_codigo text, transportista_nombre text, transportista_placa text, estado reciclaje.estado_orden, observaciones text, subtotal numeric, total numeric, cantidad_materiales bigint, cantidad_total numeric, cantidad_pagos bigint, materiales jsonb, pagos jsonb, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$

SELECT
    oc.id,
    oc.company_id,
    oc.codigo,

    s.id AS socio_id,
    s.codigo AS socio_codigo,
    s.nombre AS socio_nombre,

    t.id AS transportista_id,
    t.codigo AS transportista_codigo,
    t.nombre AS transportista_nombre,
    t.placa AS transportista_placa,

    oc.estado,
    oc.observaciones,

    oc.subtotal,
    oc.total,

    (
        SELECT COUNT(*)
        FROM reciclaje.ordenes_compra_detalle ocd
        WHERE ocd.orden_compra_id = oc.id
    ) AS cantidad_materiales,

    COALESCE(
        (
            SELECT SUM(ocd.cantidad)
            FROM reciclaje.ordenes_compra_detalle ocd
            WHERE ocd.orden_compra_id = oc.id
        ),
        0
    ) AS cantidad_total,

    (
        SELECT COUNT(*)
        FROM reciclaje.ordenes_compra_pagos ocp
        WHERE ocp.orden_compra_id = oc.id
    ) AS cantidad_pagos,

    COALESCE(
        (
            SELECT jsonb_agg(
                jsonb_build_object(
                    'id', ocd.id,
                    'material_id', ocd.material_id,
                    'material_codigo', m.codigo,
                    'material_nombre', m.nombre,
                    'material_unidad', m.unidad,
                    'cantidad', ocd.cantidad,
                    'precio_unitario', ocd.precio_unitario,
                    'subtotal', ocd.subtotal,
                    'observaciones', ocd.observaciones
                )
                ORDER BY m.nombre
            )
            FROM reciclaje.ordenes_compra_detalle ocd
            JOIN reciclaje.materiales m
              ON m.id = ocd.material_id
             AND m.company_id = p_company_id
            WHERE ocd.orden_compra_id = oc.id
        ),
        '[]'::jsonb
    ) AS materiales,

    COALESCE(
        (
            SELECT jsonb_agg(
                jsonb_build_object(
                    'id', ocp.id,
                    'forma_pago_id', ocp.forma_pago_id,
                    'forma_pago_codigo', fp.codigo,
                    'forma_pago_nombre', fp.nombre,
                    'moneda_id', ocp.moneda_id,
                    'moneda_codigo', mo.codigo,
                    'moneda_nombre', mo.nombre,
                    'moneda_simbolo', mo.simbolo,
                    'monto', ocp.monto,
                    'referencia', ocp.referencia,
                    'observaciones', ocp.observaciones
                )
                ORDER BY ocp.created_at
            )
            FROM reciclaje.ordenes_compra_pagos ocp
            JOIN reciclaje.formas_pago fp
              ON fp.id = ocp.forma_pago_id
            JOIN reciclaje.monedas mo
              ON mo.id = ocp.moneda_id
            WHERE ocp.orden_compra_id = oc.id
        ),
        '[]'::jsonb
    ) AS pagos,

    oc.created_at,
    oc.updated_at

FROM reciclaje.ordenes_compra oc

JOIN reciclaje.socios s
  ON s.id = oc.socio_id
 AND s.company_id = p_company_id

JOIN reciclaje.transportistas t
  ON t.id = oc.transportista_id
 AND t.company_id = p_company_id

WHERE oc.company_id = p_company_id
  AND oc.id = p_id;

$$;


--
-- Name: obtener_precios_material_socio(uuid, uuid, uuid); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.obtener_precios_material_socio(p_company_id uuid, p_socio_id uuid, p_material_id uuid) RETURNS TABLE(material_id uuid, precio_base numeric, precio_mayorista numeric, precio_socio numeric, ultimo_precio numeric, ultimo_precio_fecha timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$

SELECT

    m.id AS material_id,

    m.precio_base,

    m.precio_mayorista,

    ps.precio AS precio_socio,

    ultimo.precio_unitario AS ultimo_precio,

    ultimo.fecha AS ultimo_precio_fecha

FROM reciclaje.materiales m

LEFT JOIN reciclaje.precios_socios ps
       ON ps.company_id = p_company_id
      AND ps.socio_id = p_socio_id
      AND ps.material_id = m.id

LEFT JOIN LATERAL (

    SELECT

        ocd.precio_unitario,

        oc.created_at AS fecha

    FROM reciclaje.ordenes_compra_detalle ocd

    JOIN reciclaje.ordenes_compra oc
      ON oc.id = ocd.orden_compra_id

    WHERE oc.company_id = p_company_id
      AND oc.socio_id = p_socio_id
      AND ocd.material_id = m.id

    ORDER BY oc.created_at DESC

    LIMIT 1

) ultimo ON TRUE

WHERE m.company_id = p_company_id
  AND m.id = p_material_id;

$$;


--
-- Name: obtener_recepcion(uuid, uuid); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.obtener_recepcion(p_company_id uuid, p_id uuid) RETURNS TABLE(id uuid, company_id uuid, codigo text, estado reciclaje.estado_recepcion, orden_compra_id uuid, orden_codigo text, orden_estado reciclaje.estado_orden, socio_id uuid, socio_codigo text, socio_nombre text, transportista_id uuid, transportista_codigo text, transportista_nombre text, transportista_placa text, deposito_id uuid, deposito_codigo text, deposito_nombre text, recibido_por text, observaciones text, subtotal numeric, total numeric, cantidad_materiales bigint, cantidad_total numeric, materiales jsonb, pagos jsonb, created_at timestamp with time zone, confirmed_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$

SELECT
    r.id,
    r.company_id,
    r.codigo,
    r.estado,

    oc.id AS orden_compra_id,
    oc.codigo AS orden_codigo,
    oc.estado AS orden_estado,

    s.id AS socio_id,
    s.codigo AS socio_codigo,
    s.nombre AS socio_nombre,

    t.id AS transportista_id,
    t.codigo AS transportista_codigo,
    t.nombre AS transportista_nombre,
    t.placa AS transportista_placa,

    d.id AS deposito_id,
    d.codigo AS deposito_codigo,
    d.nombre AS deposito_nombre,

    r.recibido_por,
    r.observaciones,

    COALESCE(
        (
            SELECT SUM(rd.subtotal)
            FROM reciclaje.recepciones_detalle rd
            WHERE rd.recepcion_id = r.id
        ),
        0
    ) AS subtotal,

    COALESCE(
        (
            SELECT SUM(rd.subtotal)
            FROM reciclaje.recepciones_detalle rd
            WHERE rd.recepcion_id = r.id
        ),
        0
    ) AS total,

    (
        SELECT COUNT(*)
        FROM reciclaje.recepciones_detalle rd
        WHERE rd.recepcion_id = r.id
    ) AS cantidad_materiales,

    COALESCE(
        (
            SELECT SUM(rd.cantidad)
            FROM reciclaje.recepciones_detalle rd
            WHERE rd.recepcion_id = r.id
        ),
        0
    ) AS cantidad_total,

    COALESCE(
        (
            SELECT jsonb_agg(
                jsonb_build_object(
                    'id', rd.id,
                    'material_id', rd.material_id,
                    'material_codigo', m.codigo,
                    'material_nombre', m.nombre,
                    'unidad', m.unidad,
                    'cantidad', rd.cantidad,
                    'precio_unitario', rd.precio_unitario,
                    'subtotal', rd.subtotal,
                    'observaciones', rd.observaciones
                )
                ORDER BY m.nombre
            )
            FROM reciclaje.recepciones_detalle rd
            JOIN reciclaje.materiales m
              ON m.id = rd.material_id
             AND m.company_id = p_company_id
            WHERE rd.recepcion_id = r.id
        ),
        '[]'::jsonb
    ) AS materiales,

    COALESCE(
        (
            SELECT jsonb_agg(
                jsonb_build_object(
                    'id', op.id,
                    'forma_pago_id', op.forma_pago_id,
                    'forma_pago_codigo', fp.codigo,
                    'forma_pago_nombre', fp.nombre,
                    'moneda_id', op.moneda_id,
                    'moneda_codigo', mo.codigo,
                    'moneda_nombre', mo.nombre,
                    'moneda_simbolo', mo.simbolo,
                    'monto', op.monto,
                    'referencia', op.referencia,
                    'observaciones', op.observaciones
                )
                ORDER BY op.created_at
            )
            FROM reciclaje.ordenes_compra_pagos op
            JOIN reciclaje.formas_pago fp
              ON fp.id = op.forma_pago_id
            JOIN reciclaje.monedas mo
              ON mo.id = op.moneda_id
            WHERE op.orden_compra_id = oc.id
        ),
        '[]'::jsonb
    ) AS pagos,

    r.created_at,
    r.confirmed_at

FROM reciclaje.recepciones r

JOIN reciclaje.ordenes_compra oc
  ON oc.id = r.orden_compra_id
 AND oc.company_id = p_company_id

JOIN reciclaje.socios s
  ON s.id = oc.socio_id
 AND s.company_id = p_company_id

JOIN reciclaje.transportistas t
  ON t.id = oc.transportista_id
 AND t.company_id = p_company_id

LEFT JOIN reciclaje.depositos d
  ON d.id = r.deposito_id
 AND d.company_id = p_company_id

WHERE r.company_id = p_company_id
  AND r.id = p_id;

$$;


--
-- Name: obtener_socio(uuid, uuid); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.obtener_socio(p_company_id uuid, p_id uuid) RETURNS reciclaje.socios
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$

SELECT *

FROM reciclaje.socios

WHERE company_id = p_company_id
AND id = p_id
AND activo = true;

$$;


--
-- Name: obtener_transportista(uuid, uuid); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.obtener_transportista(p_company_id uuid, p_id uuid) RETURNS reciclaje.transportistas
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE

    v_transportista reciclaje.transportistas;

BEGIN

    SELECT *
    INTO v_transportista
    FROM reciclaje.transportistas
    WHERE company_id = p_company_id
      AND id = p_id
      AND activo = true;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Transportista no encontrado.';
    END IF;

    RETURN v_transportista;

END;
$$;


--
-- Name: obtener_ultimo_pedido_socio(uuid, uuid); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.obtener_ultimo_pedido_socio(p_company_id uuid, p_socio_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE

    v_orden reciclaje.ordenes_compra;
    v_resultado jsonb;

BEGIN

    ----------------------------------------------------
    -- Validar socio
    ----------------------------------------------------

    IF NOT EXISTS (
        SELECT 1
        FROM reciclaje.socios
        WHERE company_id = p_company_id
          AND id = p_socio_id
          AND activo = true
    ) THEN
        RAISE EXCEPTION 'El socio no existe.';
    END IF;

    ----------------------------------------------------
    -- Buscar última orden
    ----------------------------------------------------

    SELECT oc.*
    INTO v_orden
    FROM reciclaje.ordenes_compra oc
    WHERE oc.company_id = p_company_id
      AND oc.socio_id = p_socio_id
    ORDER BY oc.created_at DESC
    LIMIT 1;

    ----------------------------------------------------
    -- Socio sin pedidos
    ----------------------------------------------------

    IF NOT FOUND THEN
        RETURN NULL;
    END IF;

    ----------------------------------------------------
    -- Construir respuesta
    ----------------------------------------------------

    SELECT jsonb_build_object(

        'id', oc.id,
        'codigo', oc.codigo,

        'socio_id', oc.socio_id,

        'transportista_id', oc.transportista_id,

        'estado', oc.estado,

        'observaciones', oc.observaciones,

        'subtotal', oc.subtotal,
        'total', oc.total,

        'created_at', oc.created_at,

        ------------------------------------------------
        -- Materiales
        ------------------------------------------------

        'materiales',

        COALESCE(
            (
                SELECT jsonb_agg(
                    jsonb_build_object(

                        'material_id', d.material_id,

                        'cantidad', d.cantidad,

                        'precio_unitario', d.precio_unitario,

                        'subtotal', d.subtotal,

                        'material_codigo', m.codigo,

                        'material_nombre', m.nombre,

                        'material_unidad', m.unidad,

                        'precio_base', m.precio_base,

                        'precio_mayorista', m.precio_mayorista,

                        'imagen_url', m.imagen_url

                    )
                    ORDER BY m.nombre
                )

                FROM reciclaje.ordenes_compra_detalle d

                JOIN reciclaje.materiales m
                  ON m.id = d.material_id
                 AND m.company_id = p_company_id

                WHERE d.orden_compra_id = oc.id
            ),
            '[]'::jsonb
        ),

        ------------------------------------------------
        -- Pagos
        ------------------------------------------------

        'pagos',

        COALESCE(
            (
                SELECT jsonb_agg(
                    jsonb_build_object(

                        'forma_pago_id', p.forma_pago_id,

                        'moneda_id', p.moneda_id,

                        'monto', p.monto,

                        'referencia', p.referencia,

                        'observaciones', p.observaciones

                    )
                )

                FROM reciclaje.ordenes_compra_pagos p

                WHERE p.orden_compra_id = oc.id
            ),
            '[]'::jsonb
        )

    )
    INTO v_resultado

    FROM reciclaje.ordenes_compra oc

    WHERE oc.id = v_orden.id
      AND oc.company_id = p_company_id;

    RETURN v_resultado;

END;
$$;


--
-- Name: movimientos_stock; Type: TABLE; Schema: reciclaje; Owner: -
--

CREATE TABLE reciclaje.movimientos_stock (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    material_id uuid NOT NULL,
    tipo_movimiento reciclaje.tipo_movimiento NOT NULL,
    cantidad numeric(14,3) NOT NULL,
    origen text NOT NULL,
    origen_id uuid,
    socio_id uuid,
    transportista_id uuid,
    orden_compra_id uuid,
    recepcion_id uuid,
    observaciones text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    deposito_id uuid,
    movimiento_grupo_id uuid,
    CONSTRAINT movimientos_stock_cantidad_check CHECK ((cantidad <> (0)::numeric))
);


--
-- Name: registrar_ajuste(uuid, uuid, uuid, numeric, text); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.registrar_ajuste(p_company_id uuid, p_deposito_id uuid, p_material_id uuid, p_cantidad numeric, p_observaciones text DEFAULT NULL::text) RETURNS reciclaje.movimientos_stock
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE

    v_stock numeric;
    v_stock_resultante numeric;

    v_movimiento reciclaje.movimientos_stock;

BEGIN

    ----------------------------------------------------
    -- Validaciones
    ----------------------------------------------------

    IF p_cantidad IS NULL OR p_cantidad = 0 THEN
        RAISE EXCEPTION
        'El ajuste no puede ser cero.';
    END IF;


    IF NOT EXISTS (
        SELECT 1
        FROM reciclaje.depositos
        WHERE company_id = p_company_id
          AND id = p_deposito_id
          AND activo = true
    ) THEN
        RAISE EXCEPTION 'Depósito no encontrado.';
    END IF;


    IF NOT EXISTS (
        SELECT 1
        FROM reciclaje.materiales
        WHERE company_id = p_company_id
          AND id = p_material_id
          AND activo = true
    ) THEN
        RAISE EXCEPTION 'Material no encontrado.';
    END IF;


    ----------------------------------------------------
    -- Stock actual
    ----------------------------------------------------

    SELECT COALESCE(stock, 0)
    INTO v_stock
    FROM reciclaje.listar_inventario(
        p_company_id,
        p_deposito_id
    )
    WHERE material_id = p_material_id;


    v_stock := COALESCE(v_stock, 0);

    v_stock_resultante :=
        v_stock + p_cantidad;


    ----------------------------------------------------
    -- No permitir inventario negativo
    ----------------------------------------------------

    IF v_stock_resultante < 0 THEN

        RAISE EXCEPTION
        'El ajuste dejaría stock negativo. Stock actual: %, ajuste: %.',
        v_stock,
        p_cantidad;

    END IF;


    ----------------------------------------------------
    -- Registrar ajuste
    ----------------------------------------------------

    INSERT INTO reciclaje.movimientos_stock (

        company_id,
        deposito_id,
        material_id,

        tipo_movimiento,
        cantidad,

        origen,

        observaciones

    )
    VALUES (

        p_company_id,
        p_deposito_id,
        p_material_id,

        'ajuste',
        p_cantidad,

        'manual',

        reciclaje.texto_nulo(p_observaciones)

    )

    RETURNING *
    INTO v_movimiento;


    ----------------------------------------------------
    -- Stock global
    ----------------------------------------------------

    UPDATE reciclaje.materiales

    SET
        stock = stock + p_cantidad,
        updated_at = now()

    WHERE company_id = p_company_id
      AND id = p_material_id;


    RETURN v_movimiento;

END;
$$;


--
-- Name: registrar_ajuste(uuid, uuid, uuid, numeric, text, text, uuid, uuid); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.registrar_ajuste(p_company_id uuid, p_deposito_id uuid, p_material_id uuid, p_cantidad numeric, p_observaciones text DEFAULT NULL::text, p_origen text DEFAULT 'manual'::text, p_origen_id uuid DEFAULT NULL::uuid, p_movimiento_grupo_id uuid DEFAULT NULL::uuid) RETURNS reciclaje.movimientos_stock
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE

    v_stock numeric;
    v_stock_resultante numeric;

    v_movimiento reciclaje.movimientos_stock;

BEGIN

    ----------------------------------------------------
    -- VALIDACIONES
    ----------------------------------------------------

    IF p_cantidad IS NULL OR p_cantidad = 0 THEN

        RAISE EXCEPTION
            'El ajuste no puede ser cero.';

    END IF;


    IF NOT EXISTS (

        SELECT 1
        FROM reciclaje.depositos

        WHERE company_id = p_company_id
          AND id = p_deposito_id
          AND activo = true

    ) THEN

        RAISE EXCEPTION
            'Depósito no encontrado.';

    END IF;


    IF NOT EXISTS (

        SELECT 1
        FROM reciclaje.materiales

        WHERE company_id = p_company_id
          AND id = p_material_id
          AND activo = true

    ) THEN

        RAISE EXCEPTION
            'Material no encontrado.';

    END IF;


    ----------------------------------------------------
    -- STOCK ACTUAL DEL DEPÓSITO
    ----------------------------------------------------

    SELECT COALESCE(stock, 0)

    INTO v_stock

    FROM reciclaje.listar_inventario(
        p_company_id,
        p_deposito_id
    )

    WHERE material_id = p_material_id;


    v_stock := COALESCE(v_stock, 0);


    v_stock_resultante :=
        v_stock + p_cantidad;


    ----------------------------------------------------
    -- NO PERMITIR STOCK NEGATIVO
    ----------------------------------------------------

    IF v_stock_resultante < 0 THEN

        RAISE EXCEPTION
            'El ajuste dejaría stock negativo. Stock actual: %, ajuste: %.',
            v_stock,
            p_cantidad;

    END IF;


    ----------------------------------------------------
    -- REGISTRAR MOVIMIENTO
    ----------------------------------------------------

    INSERT INTO reciclaje.movimientos_stock (

        company_id,

        deposito_id,

        material_id,

        tipo_movimiento,

        cantidad,

        origen,

        origen_id,

        observaciones,

        movimiento_grupo_id

    )

    VALUES (

        p_company_id,

        p_deposito_id,

        p_material_id,

        'ajuste',

        p_cantidad,

        COALESCE(
            reciclaje.texto_nulo(p_origen),
            'manual'
        ),

        p_origen_id,

        reciclaje.texto_nulo(p_observaciones),

        p_movimiento_grupo_id

    )

    RETURNING *
    INTO v_movimiento;


    ----------------------------------------------------
    -- ACTUALIZAR STOCK GLOBAL
    ----------------------------------------------------

    UPDATE reciclaje.materiales

    SET

        stock = stock + p_cantidad,

        updated_at = now()

    WHERE company_id = p_company_id
      AND id = p_material_id;


    RETURN v_movimiento;

END;
$$;


--
-- Name: registrar_salida(uuid, uuid, uuid, numeric, text); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.registrar_salida(p_company_id uuid, p_deposito_id uuid, p_material_id uuid, p_cantidad numeric, p_observaciones text DEFAULT NULL::text) RETURNS reciclaje.movimientos_stock
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE

    v_stock numeric;
    v_movimiento reciclaje.movimientos_stock;

BEGIN

    ----------------------------------------------------
    -- Validaciones
    ----------------------------------------------------

    IF p_cantidad IS NULL OR p_cantidad <= 0 THEN
        RAISE EXCEPTION
        'La cantidad debe ser mayor que cero.';
    END IF;


    IF NOT EXISTS (
        SELECT 1
        FROM reciclaje.depositos
        WHERE company_id = p_company_id
          AND id = p_deposito_id
          AND activo = true
    ) THEN
        RAISE EXCEPTION 'Depósito no encontrado.';
    END IF;


    IF NOT EXISTS (
        SELECT 1
        FROM reciclaje.materiales
        WHERE company_id = p_company_id
          AND id = p_material_id
          AND activo = true
    ) THEN
        RAISE EXCEPTION 'Material no encontrado.';
    END IF;


    ----------------------------------------------------
    -- Stock disponible
    ----------------------------------------------------

    SELECT COALESCE(stock, 0)
    INTO v_stock
    FROM reciclaje.listar_inventario(
        p_company_id,
        p_deposito_id
    )
    WHERE material_id = p_material_id;


    v_stock := COALESCE(v_stock, 0);


    IF p_cantidad > v_stock THEN

        RAISE EXCEPTION
        'Stock insuficiente. Disponible: %, solicitado: %.',
        v_stock,
        p_cantidad;

    END IF;


    ----------------------------------------------------
    -- Crear salida
    ----------------------------------------------------

    INSERT INTO reciclaje.movimientos_stock (

        company_id,
        deposito_id,
        material_id,

        tipo_movimiento,
        cantidad,

        origen,

        observaciones

    )
    VALUES (

        p_company_id,
        p_deposito_id,
        p_material_id,

        'salida',
        ABS(p_cantidad),

        'manual',

        reciclaje.texto_nulo(p_observaciones)

    )

    RETURNING *
    INTO v_movimiento;


    ----------------------------------------------------
    -- Mantener stock global de materiales
    ----------------------------------------------------

    UPDATE reciclaje.materiales

    SET
        stock = stock - ABS(p_cantidad),
        updated_at = now()

    WHERE company_id = p_company_id
      AND id = p_material_id;


    RETURN v_movimiento;

END;
$$;


--
-- Name: registrar_traslado(uuid, uuid, uuid, uuid, numeric, text); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.registrar_traslado(p_company_id uuid, p_deposito_origen_id uuid, p_deposito_destino_id uuid, p_material_id uuid, p_cantidad numeric, p_observaciones text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE

    v_stock numeric;

    v_grupo_id uuid;

BEGIN

    ----------------------------------------------------
    -- Validaciones
    ----------------------------------------------------

    IF p_cantidad IS NULL OR p_cantidad <= 0 THEN
        RAISE EXCEPTION
        'La cantidad debe ser mayor que cero.';
    END IF;


    IF p_deposito_origen_id = p_deposito_destino_id THEN
        RAISE EXCEPTION
        'El depósito de origen y destino no pueden ser iguales.';
    END IF;


    ----------------------------------------------------
    -- Validar depósito origen
    ----------------------------------------------------

    IF NOT EXISTS (
        SELECT 1
        FROM reciclaje.depositos
        WHERE company_id = p_company_id
          AND id = p_deposito_origen_id
          AND activo = true
    ) THEN
        RAISE EXCEPTION
        'Depósito de origen no encontrado.';
    END IF;


    ----------------------------------------------------
    -- Validar depósito destino
    ----------------------------------------------------

    IF NOT EXISTS (
        SELECT 1
        FROM reciclaje.depositos
        WHERE company_id = p_company_id
          AND id = p_deposito_destino_id
          AND activo = true
    ) THEN
        RAISE EXCEPTION
        'Depósito de destino no encontrado.';
    END IF;


    ----------------------------------------------------
    -- Validar material
    ----------------------------------------------------

    IF NOT EXISTS (
        SELECT 1
        FROM reciclaje.materiales
        WHERE company_id = p_company_id
          AND id = p_material_id
          AND activo = true
    ) THEN
        RAISE EXCEPTION
        'Material no encontrado.';
    END IF;


    ----------------------------------------------------
    -- Stock disponible en origen
    ----------------------------------------------------

    SELECT COALESCE(stock, 0)
    INTO v_stock
    FROM reciclaje.listar_inventario(
        p_company_id,
        p_deposito_origen_id
    )
    WHERE material_id = p_material_id;


    v_stock := COALESCE(v_stock, 0);


    IF p_cantidad > v_stock THEN

        RAISE EXCEPTION
        'Stock insuficiente en depósito origen. Disponible: %, solicitado: %.',
        v_stock,
        p_cantidad;

    END IF;


    ----------------------------------------------------
    -- Identificador del traslado
    ----------------------------------------------------

    v_grupo_id := gen_random_uuid();


    ----------------------------------------------------
    -- SALIDA DEL DEPÓSITO ORIGEN
    ----------------------------------------------------

    INSERT INTO reciclaje.movimientos_stock (

        company_id,
        deposito_id,
        material_id,

        tipo_movimiento,
        cantidad,

        origen,

        movimiento_grupo_id,

        observaciones

    )
    VALUES (

        p_company_id,
        p_deposito_origen_id,
        p_material_id,

        'traslado',
        -ABS(p_cantidad),

        'traslado',

        v_grupo_id,

        reciclaje.texto_nulo(p_observaciones)

    );


    ----------------------------------------------------
    -- ENTRADA AL DEPÓSITO DESTINO
    ----------------------------------------------------

    INSERT INTO reciclaje.movimientos_stock (

        company_id,
        deposito_id,
        material_id,

        tipo_movimiento,
        cantidad,

        origen,

        movimiento_grupo_id,

        observaciones

    )
    VALUES (

        p_company_id,
        p_deposito_destino_id,
        p_material_id,

        'traslado',
        ABS(p_cantidad),

        'traslado',

        v_grupo_id,

        reciclaje.texto_nulo(p_observaciones)

    );


    ----------------------------------------------------
    -- IMPORTANTE:
    -- NO modificamos materiales.stock.
    --
    -- El material solamente cambió de depósito.
    -- El stock global sigue siendo exactamente el mismo.
    ----------------------------------------------------


    RETURN v_grupo_id;

END;
$$;


--
-- Name: registrar_venta(uuid, jsonb); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.registrar_venta(p_company_id uuid, p_venta jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE

    v_deposito_id uuid;

    v_materiales jsonb;

    v_item jsonb;

    v_material_id uuid;

    v_material_nombre text;

    v_cantidad numeric;

    v_monto numeric(14,2);

    v_moneda text;

    v_tipo_cambio numeric(14,6);

    v_monto_ars numeric(14,2);

    v_forma_pago text;

    v_referencia text;

    v_observaciones text;

    v_descripcion text := '';

    v_movimiento_caja reciclaje.movimientos_caja;

    v_movimiento_stock reciclaje.movimientos_stock;

    v_movimientos_stock jsonb := '[]'::jsonb;

BEGIN

    ------------------------------------------------------------
    -- 1. DATOS GENERALES
    ------------------------------------------------------------

    v_deposito_id :=
        NULLIF(
            p_venta->>'deposito_id',
            ''
        )::uuid;


    IF v_deposito_id IS NULL THEN

        RAISE EXCEPTION
            'Debe indicar el depósito.';

    END IF;


    v_materiales :=
        COALESCE(
            p_venta->'materiales',
            '[]'::jsonb
        );


    IF jsonb_typeof(v_materiales) <> 'array'
       OR jsonb_array_length(v_materiales) = 0
    THEN

        RAISE EXCEPTION
            'Debe indicar al menos un material.';

    END IF;


    ------------------------------------------------------------
    -- 2. MONTO
    ------------------------------------------------------------

    v_monto :=
        COALESCE(
            NULLIF(
                p_venta->>'monto',
                ''
            )::numeric,
            0
        );


    IF v_monto <= 0 THEN

        RAISE EXCEPTION
            'El monto de la venta debe ser mayor a cero.';

    END IF;


    ------------------------------------------------------------
    -- 3. MONEDA
    ------------------------------------------------------------

    v_moneda :=
        UPPER(
            COALESCE(
                NULLIF(
                    trim(p_venta->>'moneda'),
                    ''
                ),
                'ARS'
            )
        );


    IF v_moneda = 'ARS' THEN

        v_tipo_cambio := 1;

    ELSE

        v_tipo_cambio :=
            COALESCE(
                NULLIF(
                    p_venta->>'tipo_cambio',
                    ''
                )::numeric,
                0
            );


        IF v_tipo_cambio <= 0 THEN

            RAISE EXCEPTION
                'Debe indicar un tipo de cambio mayor a cero.';

        END IF;

    END IF;


    v_monto_ars :=
        ROUND(
            v_monto * v_tipo_cambio,
            2
        );


    ------------------------------------------------------------
    -- 4. OTROS DATOS
    ------------------------------------------------------------

    v_forma_pago :=
        reciclaje.texto_nulo(
            p_venta->>'forma_pago'
        );


    v_referencia :=
        reciclaje.texto_nulo(
            p_venta->>'referencia'
        );


    v_observaciones :=
        reciclaje.texto_nulo(
            p_venta->>'observaciones'
        );


    ------------------------------------------------------------
    -- 5. RECORRER MATERIALES
    ------------------------------------------------------------

    FOR v_item IN

        SELECT value
        FROM jsonb_array_elements(v_materiales)

    LOOP

        v_material_id :=
            NULLIF(
                v_item->>'material_id',
                ''
            )::uuid;


        v_cantidad :=
            COALESCE(
                NULLIF(
                    v_item->>'cantidad',
                    ''
                )::numeric,
                0
            );


        IF v_material_id IS NULL THEN

            RAISE EXCEPTION
                'Todos los materiales deben indicar material_id.';

        END IF;


        IF v_cantidad <= 0 THEN

            RAISE EXCEPTION
                'Todas las cantidades deben ser mayores a cero.';

        END IF;


        ------------------------------------------------------------
        -- NOMBRE REAL DEL MATERIAL
        ------------------------------------------------------------

        SELECT nombre

        INTO v_material_nombre

        FROM reciclaje.materiales

        WHERE company_id = p_company_id
          AND id = v_material_id
          AND activo = true;


        IF NOT FOUND THEN

            RAISE EXCEPTION
                'Material no encontrado o inactivo: %.',
                v_material_id;

        END IF;


        ------------------------------------------------------------
        -- CONSTRUIR DESCRIPCIÓN AUTOMÁTICAMENTE
        ------------------------------------------------------------

        IF v_descripcion <> '' THEN

            v_descripcion :=
                v_descripcion || ', ';

        END IF;


        v_descripcion :=
            v_descripcion
            || v_material_nombre
            || ' '
            || v_cantidad;


        ------------------------------------------------------------
        -- REGISTRAR SALIDA DE INVENTARIO
        ------------------------------------------------------------

        SELECT *

        INTO v_movimiento_stock

        FROM reciclaje.registrar_salida(

            p_company_id,

            v_deposito_id,

            v_material_id,

            v_cantidad,

            'Venta de ' ||
            v_material_nombre

        );


        ------------------------------------------------------------
        -- GUARDAR RESULTADO
        ------------------------------------------------------------

        v_movimientos_stock :=
            v_movimientos_stock
            ||
            jsonb_build_array(

                jsonb_build_object(

                    'movimiento_id',
                        v_movimiento_stock.id,

                    'material_id',
                        v_material_id,

                    'material_nombre',
                        v_material_nombre,

                    'cantidad',
                        v_cantidad

                )

            );

    END LOOP;


    ------------------------------------------------------------
    -- 6. REGISTRAR ENTRADA EN CAJA
    ------------------------------------------------------------

    INSERT INTO reciclaje.movimientos_caja (

        company_id,

        tipo,

        monto,

        moneda,

        tipo_cambio,

        monto_ars,

        forma_pago,

        referencia,

        concepto,

        descripcion,

        origen_tipo,

        observaciones

    )

    VALUES (

        p_company_id,

        'entrada',

        v_monto,

        v_moneda,

        v_tipo_cambio,

        v_monto_ars,

        v_forma_pago,

        v_referencia,

        'venta',

        'Venta: ' || v_descripcion,

        'venta',

        v_observaciones

    )

    RETURNING *

    INTO v_movimiento_caja;


    ------------------------------------------------------------
    -- 7. RESPUESTA
    ------------------------------------------------------------

    RETURN jsonb_build_object(

        'ok',
            true,

        'movimiento_caja',
            to_jsonb(v_movimiento_caja),

        'materiales',
            v_movimientos_stock,

        'monto',
            v_monto,

        'moneda',
            v_moneda,

        'tipo_cambio',
            v_tipo_cambio,

        'monto_ars',
            v_monto_ars,

        'descripcion',
            'Venta: ' || v_descripcion

    );

END;
$$;


--
-- Name: texto_nulo(text); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.texto_nulo(p_texto text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
SELECT nullif(trim(coalesce(p_texto, '')), '');
$$;


--
-- Name: transformar_material(uuid, uuid, uuid, numeric, jsonb, text); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.transformar_material(p_company_id uuid, p_deposito_id uuid, p_material_origen_id uuid, p_cantidad_origen numeric, p_resultados jsonb, p_observaciones text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE

    v_grupo_id uuid := gen_random_uuid();

    v_item jsonb;

    v_material_destino_id uuid;
    v_cantidad_destino numeric;

    v_movimiento reciclaje.movimientos_stock;

    v_movimientos jsonb := '[]'::jsonb;

    v_total_resultado numeric := 0;
    v_merma numeric := 0;

BEGIN

    ----------------------------------------------------
    -- 1. VALIDAR CANTIDAD DE ORIGEN
    ----------------------------------------------------

    IF p_cantidad_origen IS NULL
       OR p_cantidad_origen <= 0
    THEN

        RAISE EXCEPTION
            'La cantidad a procesar debe ser mayor que cero.';

    END IF;


    ----------------------------------------------------
    -- 2. VALIDAR RESULTADOS
    ----------------------------------------------------

    IF jsonb_typeof(
        COALESCE(
            p_resultados,
            '[]'::jsonb
        )
    ) <> 'array'
    THEN

        RAISE EXCEPTION
            'Los resultados deben ser un array.';

    END IF;


    IF jsonb_array_length(
        COALESCE(
            p_resultados,
            '[]'::jsonb
        )
    ) = 0
    THEN

        RAISE EXCEPTION
            'Debe indicar al menos un material resultante.';

    END IF;


    ----------------------------------------------------
    -- 3. VALIDAR MATERIAL ORIGEN COMO COMPUESTO
    ----------------------------------------------------

    IF NOT EXISTS (

        SELECT 1

        FROM reciclaje.materiales

        WHERE company_id = p_company_id
          AND id = p_material_origen_id
          AND activo = true
          AND compuesto = true

    ) THEN

        RAISE EXCEPTION
            'El material de origen no existe, está inactivo o no es compuesto.';

    END IF;


    ----------------------------------------------------
    -- 4. VALIDAR RESULTADOS Y CALCULAR TOTAL
    --
    -- Todavía NO modificamos inventario.
    ----------------------------------------------------

    FOR v_item IN

        SELECT value

        FROM jsonb_array_elements(
            p_resultados
        )

    LOOP

        v_material_destino_id :=
            NULLIF(
                v_item->>'material_id',
                ''
            )::uuid;


        v_cantidad_destino :=
            NULLIF(
                v_item->>'cantidad',
                ''
            )::numeric;


        IF v_material_destino_id IS NULL THEN

            RAISE EXCEPTION
                'Todos los resultados deben indicar material_id.';

        END IF;


        IF v_cantidad_destino IS NULL
           OR v_cantidad_destino <= 0
        THEN

            RAISE EXCEPTION
                'Todas las cantidades resultantes deben ser mayores que cero.';

        END IF;


        IF v_material_destino_id =
           p_material_origen_id
        THEN

            RAISE EXCEPTION
                'El material resultante no puede ser el mismo material compuesto de origen.';

        END IF;


        IF NOT EXISTS (

            SELECT 1

            FROM reciclaje.materiales

            WHERE company_id = p_company_id
              AND id = v_material_destino_id
              AND activo = true

        ) THEN

            RAISE EXCEPTION
                'Uno de los materiales resultantes no existe o está inactivo.';

        END IF;


        v_total_resultado :=
            v_total_resultado
            + v_cantidad_destino;

    END LOOP;


    ----------------------------------------------------
    -- 5. VALIDAR BALANCE
    ----------------------------------------------------

    IF v_total_resultado > p_cantidad_origen THEN

        RAISE EXCEPTION
            'La cantidad resultante (%) no puede superar la cantidad procesada (%).',
            v_total_resultado,
            p_cantidad_origen;

    END IF;


    v_merma :=
        p_cantidad_origen
        - v_total_resultado;


    ----------------------------------------------------
    -- 6. SACAR MATERIAL COMPUESTO
    --
    -- registrar_ajuste hace:
    -- - validación de stock
    -- - movimiento_stock
    -- - actualización de materiales.stock
    ----------------------------------------------------

    SELECT *

    INTO v_movimiento

    FROM reciclaje.registrar_ajuste(

        p_company_id,

        p_deposito_id,

        p_material_origen_id,

        -ABS(p_cantidad_origen),

        p_observaciones,

        'transformacion',

        v_grupo_id,

        v_grupo_id

    );


    v_movimientos :=
        v_movimientos
        ||
        jsonb_build_array(

            jsonb_build_object(

                'movimiento_id',
                    v_movimiento.id,

                'material_id',
                    p_material_origen_id,

                'cantidad',
                    -ABS(p_cantidad_origen),

                'tipo',
                    'origen'

            )

        );


    ----------------------------------------------------
    -- 7. INGRESAR MATERIALES RESULTANTES
    ----------------------------------------------------

    FOR v_item IN

        SELECT value

        FROM jsonb_array_elements(
            p_resultados
        )

    LOOP

        v_material_destino_id :=
            (v_item->>'material_id')::uuid;


        v_cantidad_destino :=
            (v_item->>'cantidad')::numeric;


        SELECT *

        INTO v_movimiento

        FROM reciclaje.registrar_ajuste(

            p_company_id,

            p_deposito_id,

            v_material_destino_id,

            ABS(v_cantidad_destino),

            p_observaciones,

            'transformacion',

            v_grupo_id,

            v_grupo_id

        );


        v_movimientos :=
            v_movimientos
            ||
            jsonb_build_array(

                jsonb_build_object(

                    'movimiento_id',
                        v_movimiento.id,

                    'material_id',
                        v_material_destino_id,

                    'cantidad',
                        ABS(v_cantidad_destino),

                    'tipo',
                        'resultado'

                )

            );

    END LOOP;


    ----------------------------------------------------
    -- 8. RESULTADO
    ----------------------------------------------------

    RETURN jsonb_build_object(

        'ok',
            true,

        'movimiento_grupo_id',
            v_grupo_id,

        'deposito_id',
            p_deposito_id,

        'material_origen_id',
            p_material_origen_id,

        'cantidad_procesada',
            p_cantidad_origen,

        'cantidad_resultante',
            v_total_resultado,

        'merma',
            v_merma,

        'movimientos',
            v_movimientos

    );

END;
$$;


--
-- Name: upsert_operacion(uuid, jsonb); Type: FUNCTION; Schema: reciclaje; Owner: -
--

CREATE FUNCTION reciclaje.upsert_operacion(p_company_id uuid, p_operacion jsonb) RETURNS reciclaje.operaciones
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE

    v_operacion reciclaje.operaciones;

    v_id uuid;

    ------------------------------------------------------------
    -- NUEVO: CONTROL DE TRANSICIÓN / CAJA
    ------------------------------------------------------------

    v_etapa_anterior reciclaje.etapa_operacion;

    v_caja jsonb;

    v_monto_caja numeric(14,2);

    v_tipo_cambio numeric(14,6);

    v_monto_ars numeric(14,2);

    v_transportista_nombre text;

BEGIN

    ------------------------------------------------------------
    -- ID OPCIONAL
    ------------------------------------------------------------

    v_id :=
        NULLIF(
            p_operacion->>'id',
            ''
        )::uuid;


    ------------------------------------------------------------
    -- VALIDACIONES BÁSICAS
    ------------------------------------------------------------

    IF p_operacion ? 'monto'
       AND NULLIF(p_operacion->>'monto', '') IS NOT NULL
       AND (p_operacion->>'monto')::numeric < 0
    THEN

        RAISE EXCEPTION
            'El monto no puede ser negativo.';

    END IF;


    IF p_operacion ? 'materiales'
       AND jsonb_typeof(
            COALESCE(
                p_operacion->'materiales',
                '[]'::jsonb
            )
       ) <> 'array'
    THEN

        RAISE EXCEPTION
            'materiales debe ser un array.';

    END IF;


    IF p_operacion ? 'pagos'
       AND jsonb_typeof(
            COALESCE(
                p_operacion->'pagos',
                '[]'::jsonb
            )
       ) <> 'array'
    THEN

        RAISE EXCEPTION
            'pagos debe ser un array.';

    END IF;


    ------------------------------------------------------------
    -- CREAR
    ------------------------------------------------------------

    IF v_id IS NULL THEN

        INSERT INTO reciclaje.operaciones (

            company_id,

            tipo,

            etapa,

            socio_id,

            transportista_id,

            deposito_id,

            monto,

            materiales,

            pagos,

            recibido_por,

            responsable_nombre,

            responsable_tipo,

            observaciones,

            updated_at

        )

        VALUES (

            p_company_id,

            COALESCE(
                NULLIF(p_operacion->>'tipo', '')::reciclaje.tipo_operacion,
                'compra'::reciclaje.tipo_operacion
            ),

            COALESCE(
                NULLIF(p_operacion->>'etapa', '')::reciclaje.etapa_operacion,
                'precarga'::reciclaje.etapa_operacion
            ),

            NULLIF(
                p_operacion->>'socio_id',
                ''
            )::uuid,

            NULLIF(
                p_operacion->>'transportista_id',
                ''
            )::uuid,

            NULLIF(
                p_operacion->>'deposito_id',
                ''
            )::uuid,

            NULLIF(
                p_operacion->>'monto',
                ''
            )::numeric,

            COALESCE(
                p_operacion->'materiales',
                '[]'::jsonb
            ),

            COALESCE(
                p_operacion->'pagos',
                '[]'::jsonb
            ),

            reciclaje.texto_nulo(
                p_operacion->>'recibido_por'
            ),

            reciclaje.texto_nulo(
                p_operacion->>'responsable_nombre'
            ),

            reciclaje.texto_nulo(
                p_operacion->>'responsable_tipo'
            ),

            reciclaje.texto_nulo(
                p_operacion->>'observaciones'
            ),

            now()

        )

        RETURNING *
        INTO v_operacion;


    ------------------------------------------------------------
    -- ACTUALIZAR
    ------------------------------------------------------------

    ELSE

        SELECT *
        INTO v_operacion
        FROM reciclaje.operaciones
        WHERE company_id = p_company_id
          AND id = v_id
        FOR UPDATE;


        IF NOT FOUND THEN

            RAISE EXCEPTION
                'La operación no existe.';

        END IF;


        IF v_operacion.finalizada = true THEN

            RAISE EXCEPTION
                'La operación ya fue finalizada y no puede modificarse.';

        END IF;


        ------------------------------------------------------------
        -- GUARDAR ETAPA ANTERIOR
        ------------------------------------------------------------

        v_etapa_anterior :=
            v_operacion.etapa;


        ------------------------------------------------------------
        -- ACTUALIZACIÓN NORMAL
        ------------------------------------------------------------

        UPDATE reciclaje.operaciones

        SET

            tipo =
                CASE
                    WHEN p_operacion ? 'tipo'
                    THEN NULLIF(
                        p_operacion->>'tipo',
                        ''
                    )::reciclaje.tipo_operacion
                    ELSE tipo
                END,

            etapa =
                CASE
                    WHEN p_operacion ? 'etapa'
                    THEN NULLIF(
                        p_operacion->>'etapa',
                        ''
                    )::reciclaje.etapa_operacion
                    ELSE etapa
                END,

            socio_id =
                CASE
                    WHEN p_operacion ? 'socio_id'
                    THEN NULLIF(
                        p_operacion->>'socio_id',
                        ''
                    )::uuid
                    ELSE socio_id
                END,

            transportista_id =
                CASE
                    WHEN p_operacion ? 'transportista_id'
                    THEN NULLIF(
                        p_operacion->>'transportista_id',
                        ''
                    )::uuid
                    ELSE transportista_id
                END,

            deposito_id =
                CASE
                    WHEN p_operacion ? 'deposito_id'
                    THEN NULLIF(
                        p_operacion->>'deposito_id',
                        ''
                    )::uuid
                    ELSE deposito_id
                END,

            monto =
                CASE
                    WHEN p_operacion ? 'monto'
                    THEN NULLIF(
                        p_operacion->>'monto',
                        ''
                    )::numeric
                    ELSE monto
                END,

            materiales =
                CASE
                    WHEN p_operacion ? 'materiales'
                    THEN COALESCE(
                        p_operacion->'materiales',
                        '[]'::jsonb
                    )
                    ELSE materiales
                END,

            pagos =
                CASE
                    WHEN p_operacion ? 'pagos'
                    THEN COALESCE(
                        p_operacion->'pagos',
                        '[]'::jsonb
                    )
                    ELSE pagos
                END,

            recibido_por =
                CASE
                    WHEN p_operacion ? 'recibido_por'
                    THEN reciclaje.texto_nulo(
                        p_operacion->>'recibido_por'
                    )
                    ELSE recibido_por
                END,

            responsable_nombre =
                CASE
                    WHEN p_operacion ? 'responsable_nombre'
                    THEN reciclaje.texto_nulo(
                        p_operacion->>'responsable_nombre'
                    )
                    ELSE responsable_nombre
                END,

            responsable_tipo =
                CASE
                    WHEN p_operacion ? 'responsable_tipo'
                    THEN reciclaje.texto_nulo(
                        p_operacion->>'responsable_tipo'
                    )
                    ELSE responsable_tipo
                END,

            observaciones =
                CASE
                    WHEN p_operacion ? 'observaciones'
                    THEN reciclaje.texto_nulo(
                        p_operacion->>'observaciones'
                    )
                    ELSE observaciones
                END,

            updated_at = now()

        WHERE company_id = p_company_id
          AND id = v_id

        RETURNING *
        INTO v_operacion;


        ------------------------------------------------------------
        -- NUEVO:
        -- PRECARGA -> EN PROCESO
        --
        -- ESTA ES LA ÚNICA TRANSICIÓN QUE PUEDE GENERAR
        -- UNA SALIDA DE CAJA.
        ------------------------------------------------------------

        IF v_etapa_anterior =
                'precarga'::reciclaje.etapa_operacion

           AND v_operacion.etapa =
                'en_proceso'::reciclaje.etapa_operacion

        THEN

            --------------------------------------------------------
            -- CAJA OPCIONAL
            --
            -- Si no viene caja, equivale a monto 0.
            --------------------------------------------------------

            v_caja :=
                COALESCE(
                    p_operacion->'caja',
                    '{}'::jsonb
                );


            v_monto_caja :=
                COALESCE(
                    NULLIF(
                        v_caja->>'monto',
                        ''
                    )::numeric,
                    0
                );


            --------------------------------------------------------
            -- NO PERMITIR SALIDA NEGATIVA
            --------------------------------------------------------

            IF v_monto_caja < 0 THEN

                RAISE EXCEPTION
                    'El monto entregado no puede ser negativo.';

            END IF;


            --------------------------------------------------------
            -- MONTO 0:
            --
            -- La operación igualmente puede salir.
            -- No existe movimiento físico de dinero.
            --------------------------------------------------------

            IF v_monto_caja > 0 THEN

                ----------------------------------------------------
                -- PARA ENTREGAR DINERO DEBE HABER TRANSPORTISTA
                ----------------------------------------------------

                IF v_operacion.transportista_id IS NULL THEN

                    RAISE EXCEPTION
                        'Debe indicar el transportista antes de entregar dinero.';

                END IF;


                ----------------------------------------------------
                -- MONEDA
                ----------------------------------------------------

                IF NULLIF(
                    trim(v_caja->>'moneda'),
                    ''
                ) IS NULL THEN

                    RAISE EXCEPTION
                        'Debe indicar la moneda del dinero entregado.';

                END IF;


                ----------------------------------------------------
                -- TIPO DE CAMBIO
                ----------------------------------------------------

                v_tipo_cambio :=
                    COALESCE(
                        NULLIF(
                            v_caja->>'tipo_cambio',
                            ''
                        )::numeric,
                        1
                    );


                IF v_tipo_cambio <= 0 THEN

                    RAISE EXCEPTION
                        'El tipo de cambio debe ser mayor a cero.';

                END IF;


                ----------------------------------------------------
                -- EQUIVALENTE ARS
                --
                -- Lo calcula el backend.
                -- El front no tiene que enviar monto_ars.
                ----------------------------------------------------

                v_monto_ars :=
                    ROUND(
                        v_monto_caja * v_tipo_cambio,
                        2
                    );


                ----------------------------------------------------
                -- OBTENER NOMBRE REAL DEL TRANSPORTISTA
                ----------------------------------------------------

                SELECT t.nombre
                INTO v_transportista_nombre
                FROM reciclaje.transportistas t
                WHERE t.company_id = p_company_id
                  AND t.id = v_operacion.transportista_id;


                IF NOT FOUND THEN

                    RAISE EXCEPTION
                        'El transportista indicado no existe.';

                END IF;


                ----------------------------------------------------
                -- REGISTRAR SALIDA REAL DE CAJA
                ----------------------------------------------------

                INSERT INTO reciclaje.movimientos_caja (

                    company_id,

                    tipo,

                    monto,

                    moneda,

                    tipo_cambio,

                    monto_ars,

                    forma_pago,

                    referencia,

                    concepto,

                    descripcion,

                    origen_tipo,

                    origen_id,

                    responsable_tipo,

                    responsable_id,

                    responsable_nombre,

                    comprobante_url,

                    observaciones

                )

                VALUES (

                    p_company_id,

                    'salida',

                    v_monto_caja,

                    trim(
                        v_caja->>'moneda'
                    ),

                    v_tipo_cambio,

                    v_monto_ars,

                    reciclaje.texto_nulo(
                        v_caja->>'forma_pago'
                    ),

                    reciclaje.texto_nulo(
                        v_caja->>'referencia'
                    ),

                    'entrega_operacion',

                    COALESCE(
                        reciclaje.texto_nulo(
                            v_caja->>'descripcion'
                        ),
                        'Entrega de fondos al transportista para iniciar operación'
                    ),

                    'operacion',

                    v_operacion.id,

                    'transportista',

                    v_operacion.transportista_id,

                    v_transportista_nombre,

                    reciclaje.texto_nulo(
                        v_caja->>'comprobante_url'
                    ),

                    reciclaje.texto_nulo(
                        v_caja->>'observaciones'
                    )

                );

            END IF;

        END IF;

    END IF;


    ------------------------------------------------------------
    -- RESULTADO
    ------------------------------------------------------------

    RETURN v_operacion;

END;
$$;


--
-- Name: buscar_materiales(uuid, text, uuid, boolean, boolean, integer, integer); Type: FUNCTION; Schema: reciclaje2; Owner: -
--

CREATE FUNCTION reciclaje2.buscar_materiales(p_company_id uuid, p_busqueda text DEFAULT NULL::text, p_socio_id uuid DEFAULT NULL::uuid, p_activo boolean DEFAULT true, p_compuesto boolean DEFAULT NULL::boolean, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'reciclaje2'
    AS $$
 WITH base AS(SELECT m.id,m.codigo,m.nombre,m.unidad,m.precio_base,m.precio_mayorista,
  ars.id precio_referencia_moneda_id,ars.codigo precio_referencia_moneda_codigo,ars.simbolo precio_referencia_moneda_simbolo,
  NULL::uuid precio_mayorista_moneda_id,NULL::text precio_mayorista_moneda_codigo,NULL::text precio_mayorista_moneda_simbolo,
  ps.precio precio_socio,ps.moneda_id precio_socio_moneda_id,pmon.codigo precio_socio_moneda_codigo,pmon.simbolo precio_socio_moneda_simbolo,
  COALESCE(ps.precio,m.precio_base) precio_efectivo,COALESCE(ps.moneda_id,ars.id) precio_efectivo_moneda_id,
  COALESCE(pmon.codigo,ars.codigo) precio_efectivo_moneda_codigo,COALESCE(pmon.simbolo,ars.simbolo) precio_efectivo_moneda_simbolo,
  CASE WHEN ps.id IS NULL THEN 'precio_referencia' ELSE 'precio_socio' END precio_efectivo_origen,
  m.imagen_url,m.compuesto,m.activo FROM reciclaje2.materiales m
  LEFT JOIN reciclaje2.precios_socios ps ON ps.company_id=m.company_id AND ps.material_id=m.id AND ps.socio_id=p_socio_id
  LEFT JOIN reciclaje2.monedas pmon ON pmon.id=ps.moneda_id
  LEFT JOIN reciclaje2.monedas ars ON ars.codigo='ARS'
  WHERE m.company_id=p_company_id AND (p_activo IS NULL OR m.activo=p_activo) AND (p_compuesto IS NULL OR m.compuesto=p_compuesto) AND (NULLIF(btrim(p_busqueda),'') IS NULL OR concat_ws(' ',m.codigo,m.nombre,m.unidad) ILIKE '%'||btrim(p_busqueda)||'%')),paged AS(SELECT * FROM base ORDER BY nombre,id LIMIT greatest(1,least(p_limit,200)) OFFSET greatest(p_offset,0)) SELECT jsonb_build_object('total',(SELECT count(*) FROM base),'items',COALESCE(jsonb_agg(to_jsonb(paged) ORDER BY nombre,id),'[]'::jsonb)) FROM paged;
$$;


--
-- Name: buscar_socios(uuid, text, boolean, boolean, boolean, integer, integer); Type: FUNCTION; Schema: reciclaje2; Owner: -
--

CREATE FUNCTION reciclaje2.buscar_socios(p_company_id uuid, p_busqueda text DEFAULT NULL::text, p_activo boolean DEFAULT true, p_compra boolean DEFAULT NULL::boolean, p_venta boolean DEFAULT NULL::boolean, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'reciclaje2'
    AS $$
 WITH base AS(SELECT id,codigo,nombre,documento,telefono,direccion,latitud,longitud,es_socio_compra,es_socio_venta,activo FROM reciclaje2.socios WHERE company_id=p_company_id AND (p_activo IS NULL OR activo=p_activo) AND (p_compra IS NULL OR es_socio_compra=p_compra) AND (p_venta IS NULL OR es_socio_venta=p_venta) AND (NULLIF(btrim(p_busqueda),'') IS NULL OR concat_ws(' ',codigo,nombre,documento,telefono,direccion) ILIKE '%'||btrim(p_busqueda)||'%')),paged AS(SELECT * FROM base ORDER BY nombre,id LIMIT greatest(1,least(p_limit,200)) OFFSET greatest(p_offset,0)) SELECT jsonb_build_object('total',(SELECT count(*) FROM base),'items',COALESCE(jsonb_agg(to_jsonb(paged) ORDER BY nombre,id),'[]'::jsonb)) FROM paged;
$$;


--
-- Name: buscar_transportistas(uuid, text, boolean, integer, integer); Type: FUNCTION; Schema: reciclaje2; Owner: -
--

CREATE FUNCTION reciclaje2.buscar_transportistas(p_company_id uuid, p_busqueda text DEFAULT NULL::text, p_activo boolean DEFAULT true, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
