    SET search_path TO 'pg_catalog', 'reciclaje2'
    AS $$
 WITH base AS(SELECT id,codigo,nombre,placa,telefono,activo FROM reciclaje2.transportistas WHERE company_id=p_company_id AND (p_activo IS NULL OR activo=p_activo) AND (NULLIF(btrim(p_busqueda),'') IS NULL OR concat_ws(' ',codigo,nombre,placa,telefono) ILIKE '%'||btrim(p_busqueda)||'%')),paged AS(SELECT * FROM base ORDER BY nombre,id LIMIT greatest(1,least(p_limit,200)) OFFSET greatest(p_offset,0)) SELECT jsonb_build_object('total',(SELECT count(*) FROM base),'items',COALESCE(jsonb_agg(to_jsonb(paged) ORDER BY nombre,id),'[]'::jsonb)) FROM paged;
$$;


--
-- Name: listar_catalogos(uuid); Type: FUNCTION; Schema: reciclaje2; Owner: -
--

CREATE FUNCTION reciclaje2.listar_catalogos(p_company_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'reciclaje2'
    AS $$
BEGIN
 IF p_company_id IS NULL THEN RAISE EXCEPTION 'company_id es obligatorio' USING ERRCODE='22004'; END IF;
 RETURN jsonb_build_object(
  'tipos_operacion',(SELECT jsonb_agg(to_jsonb(x) ORDER BY x.codigo) FROM(SELECT id,codigo,nombre,activo FROM reciclaje2.tipos_operacion WHERE activo)x),
  'etapas_operacion',(SELECT jsonb_agg(to_jsonb(x) ORDER BY x.orden,x.codigo) FROM(SELECT id,codigo,nombre,activo,orden FROM reciclaje2.etapas_operacion WHERE activo)x),
  'monedas',(SELECT jsonb_agg(to_jsonb(x) ORDER BY x.codigo) FROM(SELECT id,codigo,nombre,simbolo,activo FROM reciclaje2.monedas WHERE activo)x),
  'formas_pago',(SELECT jsonb_agg(to_jsonb(x) ORDER BY x.codigo) FROM(SELECT id,codigo,nombre,activo FROM reciclaje2.formas_pago WHERE activo)x),
  'tipos_gasto',(SELECT jsonb_agg(to_jsonb(x) ORDER BY x.codigo) FROM(SELECT id,codigo,nombre,activo FROM reciclaje2.tipos_gasto WHERE activo)x));
END;$$;


--
-- Name: listar_depositos(uuid, text, boolean); Type: FUNCTION; Schema: reciclaje2; Owner: -
--

CREATE FUNCTION reciclaje2.listar_depositos(p_company_id uuid, p_busqueda text DEFAULT NULL::text, p_activo boolean DEFAULT true) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'reciclaje2'
    AS $$
 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',id,'codigo',codigo,'nombre',nombre,'direccion',direccion,'activo',activo) ORDER BY nombre,id),'[]'::jsonb) FROM reciclaje2.depositos WHERE company_id=p_company_id AND (p_activo IS NULL OR activo=p_activo) AND (NULLIF(btrim(p_busqueda),'') IS NULL OR concat_ws(' ',codigo,nombre,direccion) ILIKE '%'||btrim(p_busqueda)||'%');
$$;


--
-- Name: listar_finanzas(uuid, text, uuid, text, boolean, integer, uuid, timestamp with time zone, timestamp with time zone, text, integer, integer); Type: FUNCTION; Schema: reciclaje2; Owner: -
--

CREATE FUNCTION reciclaje2.listar_finanzas(p_company_id uuid, p_tipo text DEFAULT NULL::text, p_responsable_id uuid DEFAULT NULL::uuid, p_estado text DEFAULT NULL::text, p_vencidas boolean DEFAULT NULL::boolean, p_proximas_dias integer DEFAULT NULL::integer, p_moneda_id uuid DEFAULT NULL::uuid, p_fecha_desde timestamp with time zone DEFAULT NULL::timestamp with time zone, p_fecha_hasta timestamp with time zone DEFAULT NULL::timestamp with time zone, p_busqueda text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'reciclaje2'
    AS $$
DECLARE r jsonb;
BEGIN
 IF p_company_id IS NULL OR p_limit<1 OR p_limit>200 OR p_offset<0 OR p_proximas_dias<0 THEN RAISE EXCEPTION 'parámetros de listado inválidos' USING ERRCODE='22023'; END IF;
 WITH base AS(SELECT f.id finanza_id,CASE f.tipo WHEN 'por_pagar' THEN 'CxP' ELSE 'CxC' END tipo,f.tipo tipo_codigo,f.responsable_tipo,f.responsable_id,f.responsable_nombre,f.concepto,f.moneda_id,m.codigo moneda_codigo,m.nombre moneda_nombre,m.simbolo moneda_simbolo,f.monto_original,
  (ef.j->>'monto_aplicado')::numeric monto_pagado_cobrado,(ef.j->>'saldo')::numeric saldo,ef.j->>'estado_derivado' estado_derivado,
  (SELECT min((v->>'fecha_vencimiento')::timestamptz) FROM jsonb_array_elements(ef.j->'vencimientos') v WHERE (v->>'saldo')::numeric>0) proximo_vencimiento,
  (SELECT (v->>'saldo')::numeric FROM jsonb_array_elements(ef.j->'vencimientos') v WHERE (v->>'saldo')::numeric>0 ORDER BY (v->>'fecha_vencimiento')::timestamptz LIMIT 1) monto_proximo_vencimiento,
  jsonb_array_length(ef.j->'vencimientos') cantidad_cuotas,(SELECT count(*) FROM jsonb_array_elements(ef.j->'vencimientos') v WHERE (v->>'saldo')::numeric>0) cuotas_pendientes,
  f.operacion_id,(f.operacion_id IS NULL) obligacion_independiente,o.referencia operacion_referencia,f.fecha_emision,f.fecha_vencimiento,f.estado estado_persistido,f.observaciones,f.created_at,f.updated_at
  FROM reciclaje2.finanzas f JOIN reciclaje2.monedas m ON m.id=f.moneda_id LEFT JOIN reciclaje2.operaciones o ON o.company_id=f.company_id AND o.id=f.operacion_id CROSS JOIN LATERAL(SELECT reciclaje2.obtener_estado_finanza(f.company_id,f.id) j)ef
  WHERE f.company_id=p_company_id AND (p_tipo IS NULL OR f.tipo=p_tipo OR CASE f.tipo WHEN 'por_pagar' THEN 'CxP' ELSE 'CxC' END=p_tipo) AND (p_responsable_id IS NULL OR f.responsable_id=p_responsable_id) AND (p_estado IS NULL OR ef.j->>'estado_derivado'=p_estado) AND (p_moneda_id IS NULL OR f.moneda_id=p_moneda_id) AND (p_fecha_desde IS NULL OR f.fecha_emision>=p_fecha_desde) AND (p_fecha_hasta IS NULL OR f.fecha_emision<p_fecha_hasta)
   AND (p_vencidas IS NULL OR ((ef.j->>'estado_derivado' IN('vencida','parcial_vencida'))=p_vencidas))
   AND (p_proximas_dias IS NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements(ef.j->'vencimientos') v WHERE (v->>'saldo')::numeric>0 AND (v->>'fecha_vencimiento')::timestamptz>=now() AND (v->>'fecha_vencimiento')::timestamptz<now()+make_interval(days=>p_proximas_dias)))
   AND (NULLIF(btrim(p_busqueda),'') IS NULL OR concat_ws(' ',f.responsable_nombre,f.responsable_tipo,f.concepto,f.observaciones,o.referencia,m.codigo) ILIKE '%'||btrim(p_busqueda)||'%')),
 paged AS(SELECT * FROM base ORDER BY fecha_emision DESC,finanza_id DESC LIMIT p_limit OFFSET p_offset)
 SELECT jsonb_build_object('total',(SELECT count(*) FROM base),'limit',p_limit,'offset',p_offset,'items',COALESCE(jsonb_agg(to_jsonb(paged) ORDER BY fecha_emision DESC,finanza_id DESC),'[]'::jsonb)) INTO r FROM paged; RETURN r;
END;$$;


--
-- Name: FUNCTION listar_finanzas(p_company_id uuid, p_tipo text, p_responsable_id uuid, p_estado text, p_vencidas boolean, p_proximas_dias integer, p_moneda_id uuid, p_fecha_desde timestamp with time zone, p_fecha_hasta timestamp with time zone, p_busqueda text, p_limit integer, p_offset integer); Type: COMMENT; Schema: reciclaje2; Owner: -
--

COMMENT ON FUNCTION reciclaje2.listar_finanzas(p_company_id uuid, p_tipo text, p_responsable_id uuid, p_estado text, p_vencidas boolean, p_proximas_dias integer, p_moneda_id uuid, p_fecha_desde timestamp with time zone, p_fecha_hasta timestamp with time zone, p_busqueda text, p_limit integer, p_offset integer) IS 'Listado financiero cuyo saldo y estado derivan de pagos/cobros reales.';


--
-- Name: listar_gastos(uuid, timestamp with time zone, timestamp with time zone, uuid, text, text, uuid, integer, integer); Type: FUNCTION; Schema: reciclaje2; Owner: -
--

CREATE FUNCTION reciclaje2.listar_gastos(p_company_id uuid, p_fecha_desde timestamp with time zone DEFAULT NULL::timestamp with time zone, p_fecha_hasta timestamp with time zone DEFAULT NULL::timestamp with time zone, p_tipo_gasto_id uuid DEFAULT NULL::uuid, p_estado text DEFAULT NULL::text, p_origen text DEFAULT NULL::text, p_moneda_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'reciclaje2'
    AS $$
DECLARE r jsonb;
BEGIN
 IF p_company_id IS NULL OR p_limit<1 OR p_limit>200 OR p_offset<0
    OR (p_estado IS NOT NULL AND p_estado NOT IN('pagado','pendiente'))
    OR (p_origen IS NOT NULL AND p_origen NOT IN('independiente','viaje')) THEN
   RAISE EXCEPTION 'parámetros de listado de gastos inválidos' USING ERRCODE='22023';
 END IF;
 WITH originales AS (
  SELECT h.id hecho_id,h.evento_id,h.created_at fecha,h.tipo,h.tipo_gasto_id,
   tg.codigo categoria_codigo,tg.nombre categoria_nombre,h.monto,h.moneda_id,
   m.codigo moneda_codigo,m.nombre moneda_nombre,m.simbolo moneda_simbolo,
   h.tipo_cambio,h.monto_base,h.responsable_tipo,h.responsable_id,h.responsable_nombre,
   h.observaciones,h.operacion_id,o.referencia operacion_referencia,
   h.grupo_dinero_id,h.grupo_transporte_id,h.finanza_id,
   CASE WHEN h.grupo_dinero_id IS NOT NULL OR h.grupo_transporte_id IS NOT NULL THEN 'viaje' ELSE 'independiente' END origen,
   st.id salida_id,NULL::text salida_codigo,
   CASE WHEN h.finanza_id IS NULL THEN h.monto
        ELSE LEAST(h.monto,COALESCE((SELECT sum(p.monto_aplicado) FROM reciclaje2.hechos_dinero p
          WHERE p.company_id=h.company_id AND p.finanza_id=h.finanza_id AND p.tipo='pago'),0)) END monto_pagado,
   CASE WHEN h.finanza_id IS NULL THEN 0
        ELSE GREATEST(h.monto-COALESCE((SELECT sum(p.monto_aplicado) FROM reciclaje2.hechos_dinero p
          WHERE p.company_id=h.company_id AND p.finanza_id=h.finanza_id AND p.tipo='pago'),0),0) END saldo
  FROM reciclaje2.hechos_dinero h
  JOIN reciclaje2.tipos_gasto tg ON tg.id=h.tipo_gasto_id
  JOIN reciclaje2.monedas m ON m.id=h.moneda_id
  LEFT JOIN reciclaje2.operaciones o ON o.company_id=h.company_id AND o.id=h.operacion_id
  LEFT JOIN LATERAL (SELECT s.id FROM reciclaje2.salidas_transporte s
    WHERE s.company_id=h.company_id AND
      ((h.grupo_dinero_id IS NOT NULL AND s.grupo_dinero_id=h.grupo_dinero_id)
       OR (h.grupo_transporte_id IS NOT NULL AND s.grupo_transporte_id=h.grupo_transporte_id))
    ORDER BY s.created_at DESC LIMIT 1) st ON true
  WHERE h.company_id=p_company_id AND h.tipo IN('gasto','gasto_pendiente')
   AND (p_fecha_desde IS NULL OR h.created_at>=p_fecha_desde)
   AND (p_fecha_hasta IS NULL OR h.created_at<p_fecha_hasta)
   AND (p_tipo_gasto_id IS NULL OR h.tipo_gasto_id=p_tipo_gasto_id)
   AND (p_moneda_id IS NULL OR h.moneda_id=p_moneda_id)
 ), filtrados AS (
  SELECT *,CASE WHEN saldo>0 THEN 'pendiente' ELSE 'pagado' END estado FROM originales
  WHERE (p_origen IS NULL OR origen=p_origen)
 ), base AS (SELECT * FROM filtrados WHERE p_estado IS NULL OR estado=p_estado),
 paged AS (SELECT * FROM base ORDER BY fecha DESC,hecho_id DESC LIMIT p_limit OFFSET p_offset)
 SELECT jsonb_build_object('total',(SELECT count(*) FROM base),'limit',p_limit,'offset',p_offset,
  'items',COALESCE(jsonb_agg(to_jsonb(paged) ORDER BY fecha DESC,hecho_id DESC),'[]'::jsonb))
 INTO r FROM paged;
 RETURN r;
END;$$;


--
-- Name: listar_inventario(uuid, uuid, uuid, text, boolean); Type: FUNCTION; Schema: reciclaje2; Owner: -
--

CREATE FUNCTION reciclaje2.listar_inventario(p_company_id uuid, p_deposito_id uuid DEFAULT NULL::uuid, p_material_id uuid DEFAULT NULL::uuid, p_busqueda text DEFAULT NULL::text, p_solo_con_existencia boolean DEFAULT false) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'reciclaje2'
    AS $$
 SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY x.deposito_nombre,x.material_nombre),'[]'::jsonb) FROM(
  SELECT d.id deposito_id,d.codigo deposito_codigo,d.nombre deposito_nombre,m.id material_id,m.codigo material_codigo,m.nombre material_nombre,m.unidad,m.imagen_url,m.compuesto,sum(ms.cantidad) existencia
  FROM reciclaje2.movimientos_stock ms JOIN reciclaje2.depositos d ON d.company_id=ms.company_id AND d.id=ms.deposito_id JOIN reciclaje2.materiales m ON m.company_id=ms.company_id AND m.id=ms.material_id
  WHERE ms.company_id=p_company_id AND (p_deposito_id IS NULL OR ms.deposito_id=p_deposito_id) AND (p_material_id IS NULL OR ms.material_id=p_material_id) AND (NULLIF(btrim(p_busqueda),'') IS NULL OR concat_ws(' ',d.codigo,d.nombre,m.codigo,m.nombre) ILIKE '%'||btrim(p_busqueda)||'%')
  GROUP BY d.id,d.codigo,d.nombre,m.id,m.codigo,m.nombre,m.unidad,m.imagen_url,m.compuesto HAVING NOT p_solo_con_existencia OR sum(ms.cantidad)<>0)x;
$$;


--
-- Name: listar_movimientos_caja(uuid, timestamp with time zone, timestamp with time zone, text, uuid, uuid, uuid, uuid, text, integer, integer); Type: FUNCTION; Schema: reciclaje2; Owner: -
--

CREATE FUNCTION reciclaje2.listar_movimientos_caja(p_company_id uuid, p_fecha_desde timestamp with time zone DEFAULT NULL::timestamp with time zone, p_fecha_hasta timestamp with time zone DEFAULT NULL::timestamp with time zone, p_tipo text DEFAULT NULL::text, p_responsable_id uuid DEFAULT NULL::uuid, p_grupo_dinero_id uuid DEFAULT NULL::uuid, p_operacion_id uuid DEFAULT NULL::uuid, p_moneda_id uuid DEFAULT NULL::uuid, p_busqueda text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'reciclaje2'
    AS $$
DECLARE r jsonb;
BEGIN
 IF p_company_id IS NULL OR p_limit<1 OR p_limit>200 OR p_offset<0 THEN RAISE EXCEPTION 'parámetros de listado inválidos' USING ERRCODE='22023'; END IF;
 WITH base AS(SELECT mc.id movimiento_id,mc.created_at fecha,mc.tipo,mc.monto,mc.moneda_id,m.codigo moneda_codigo,m.nombre moneda_nombre,m.simbolo moneda_simbolo,mc.tipo_cambio,mc.monto_base monto_ars,
  mc.forma_pago_id,fp.codigo forma_pago_codigo,fp.nombre forma_pago_nombre,COALESCE(h.tipo,mc.concepto) tipo_hecho,mc.tipo_gasto_id,tg.codigo tipo_gasto_codigo,tg.nombre tipo_gasto_nombre,
  mc.responsable_tipo,mc.responsable_id,mc.responsable_nombre,mc.operacion_id,o.referencia operacion_referencia,mc.finanza_id,mc.grupo_dinero_id,mc.grupo_transporte_id,mc.hecho_dinero_id,mc.concepto,mc.referencia,mc.observaciones
  FROM reciclaje2.movimientos_caja mc JOIN reciclaje2.monedas m ON m.id=mc.moneda_id LEFT JOIN reciclaje2.formas_pago fp ON fp.id=mc.forma_pago_id LEFT JOIN reciclaje2.tipos_gasto tg ON tg.id=mc.tipo_gasto_id LEFT JOIN reciclaje2.hechos_dinero h ON h.company_id=mc.company_id AND h.id=mc.hecho_dinero_id LEFT JOIN reciclaje2.operaciones o ON o.company_id=mc.company_id AND o.id=mc.operacion_id
  WHERE mc.company_id=p_company_id AND (p_fecha_desde IS NULL OR mc.created_at>=p_fecha_desde) AND (p_fecha_hasta IS NULL OR mc.created_at<p_fecha_hasta) AND (p_tipo IS NULL OR mc.tipo=p_tipo OR h.tipo=p_tipo)
   AND (p_responsable_id IS NULL OR mc.responsable_id=p_responsable_id) AND (p_grupo_dinero_id IS NULL OR mc.grupo_dinero_id=p_grupo_dinero_id) AND (p_operacion_id IS NULL OR mc.operacion_id=p_operacion_id) AND (p_moneda_id IS NULL OR mc.moneda_id=p_moneda_id)
   AND (NULLIF(btrim(p_busqueda),'') IS NULL OR concat_ws(' ',mc.concepto,mc.referencia,mc.responsable_nombre,mc.observaciones,o.referencia,tg.nombre) ILIKE '%'||btrim(p_busqueda)||'%')),
 paged AS(SELECT * FROM base ORDER BY fecha DESC,movimiento_id DESC LIMIT p_limit OFFSET p_offset)
 SELECT jsonb_build_object('total',(SELECT count(*) FROM base),'limit',p_limit,'offset',p_offset,'items',COALESCE(jsonb_agg(to_jsonb(paged) ORDER BY fecha DESC,movimiento_id DESC),'[]'::jsonb)) INTO r FROM paged; RETURN r;
END;$$;


--
-- Name: listar_movimientos_stock(uuid, timestamp with time zone, timestamp with time zone, uuid, uuid, text, uuid, uuid, text, integer, integer); Type: FUNCTION; Schema: reciclaje2; Owner: -
--

CREATE FUNCTION reciclaje2.listar_movimientos_stock(p_company_id uuid, p_fecha_desde timestamp with time zone DEFAULT NULL::timestamp with time zone, p_fecha_hasta timestamp with time zone DEFAULT NULL::timestamp with time zone, p_deposito_id uuid DEFAULT NULL::uuid, p_material_id uuid DEFAULT NULL::uuid, p_tipo text DEFAULT NULL::text, p_operacion_id uuid DEFAULT NULL::uuid, p_grupo_id uuid DEFAULT NULL::uuid, p_busqueda text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'reciclaje2'
    AS $$
DECLARE r jsonb;
BEGIN
 IF p_company_id IS NULL OR p_limit<1 OR p_limit>200 OR p_offset<0 THEN RAISE EXCEPTION 'parámetros de listado inválidos' USING ERRCODE='22023'; END IF;
 WITH base AS(SELECT ms.id movimiento_id,ms.created_at fecha,ms.tipo,ms.cantidad,ms.movimiento_grupo_id,ms.salida_id,ms.evento_operacion_id,ev.accion evento_accion,ms.operacion_id,o.referencia operacion_referencia,ti.codigo operacion_tipo_codigo,ms.operacion_material_id,
  d.id deposito_id,d.codigo deposito_codigo,d.nombre deposito_nombre,m.id material_id,m.codigo material_codigo,m.nombre material_nombre,m.unidad,
  CASE WHEN ms.salida_id IS NOT NULL THEN 'salida_transporte' WHEN ms.operacion_id IS NOT NULL THEN 'operacion_comercial' WHEN ev.accion IS NOT NULL THEN ev.accion ELSE 'base' END origen
  FROM reciclaje2.movimientos_stock ms JOIN reciclaje2.depositos d ON d.company_id=ms.company_id AND d.id=ms.deposito_id JOIN reciclaje2.materiales m ON m.company_id=ms.company_id AND m.id=ms.material_id
  LEFT JOIN reciclaje2.eventos_operacion ev ON ev.company_id=ms.company_id AND ev.id=ms.evento_operacion_id LEFT JOIN reciclaje2.operaciones o ON o.company_id=ms.company_id AND o.id=ms.operacion_id LEFT JOIN reciclaje2.tipos_operacion ti ON ti.id=o.tipo_operacion_id
  WHERE ms.company_id=p_company_id AND (p_fecha_desde IS NULL OR ms.created_at>=p_fecha_desde) AND (p_fecha_hasta IS NULL OR ms.created_at<p_fecha_hasta) AND (p_deposito_id IS NULL OR ms.deposito_id=p_deposito_id) AND (p_material_id IS NULL OR ms.material_id=p_material_id) AND (p_tipo IS NULL OR ms.tipo=p_tipo) AND (p_operacion_id IS NULL OR ms.operacion_id=p_operacion_id) AND (p_grupo_id IS NULL OR ms.movimiento_grupo_id=p_grupo_id) AND (NULLIF(btrim(p_busqueda),'') IS NULL OR concat_ws(' ',d.codigo,d.nombre,m.codigo,m.nombre,o.referencia,ev.accion) ILIKE '%'||btrim(p_busqueda)||'%')),
 paged AS(SELECT * FROM base ORDER BY fecha DESC,movimiento_id DESC LIMIT p_limit OFFSET p_offset)
 SELECT jsonb_build_object('total',(SELECT count(*) FROM base),'limit',p_limit,'offset',p_offset,'items',COALESCE(jsonb_agg(to_jsonb(paged) ORDER BY fecha DESC,movimiento_id DESC),'[]'::jsonb)) INTO r FROM paged; RETURN r;
END;$$;


--
-- Name: listar_operaciones(uuid, uuid, uuid, uuid, uuid, timestamp with time zone, timestamp with time zone, text, text, integer, integer); Type: FUNCTION; Schema: reciclaje2; Owner: -
--

CREATE FUNCTION reciclaje2.listar_operaciones(p_company_id uuid, p_tipo_id uuid DEFAULT NULL::uuid, p_etapa_id uuid DEFAULT NULL::uuid, p_socio_id uuid DEFAULT NULL::uuid, p_transportista_id uuid DEFAULT NULL::uuid, p_fecha_desde timestamp with time zone DEFAULT NULL::timestamp with time zone, p_fecha_hasta timestamp with time zone DEFAULT NULL::timestamp with time zone, p_busqueda text DEFAULT NULL::text, p_estado text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'reciclaje2'
    AS $$
DECLARE r jsonb;
BEGIN
 IF p_company_id IS NULL OR p_limit<1 OR p_limit>200 OR p_offset<0 THEN RAISE EXCEPTION 'parámetros de listado inválidos' USING ERRCODE='22023'; END IF;
 WITH base AS (
  SELECT o.id operacion_id,o.tipo_operacion_id tipo_id,ti.codigo tipo_codigo,ti.nombre tipo_nombre,
   o.etapa_operacion_id etapa_id,e.codigo etapa_codigo,e.nombre etapa_nombre,o.socio_id,s.codigo socio_codigo,s.nombre socio_nombre,
   s.telefono socio_telefono,s.direccion socio_direccion,s.latitud,s.longitud,o.transportista_id,t.codigo transportista_codigo,
   t.nombre transportista_nombre,t.placa,t.telefono transportista_telefono,o.deposito_id,d.codigo deposito_codigo,d.nombre deposito_nombre,
   o.moneda_id,m.codigo moneda_codigo,m.nombre moneda_nombre,m.simbolo moneda_simbolo,o.forma_pago_id,fp.codigo forma_pago_codigo,
   fp.nombre forma_pago_nombre,o.grupo_transporte_id,o.grupo_dinero_id,o.direccion,o.ubicacion,o.monto,o.tipo_cambio,o.monto_ars,
   o.referencia,o.descripcion,o.observaciones,o.detalles,o.eliminada,o.eliminada_at,o.motivo_eliminacion,
   o.created_at,o.updated_at,st.id salida_id,st.estado salida_estado,
   COALESCE(ma.lineas,0) cantidad_lineas,COALESCE(ma.cantidad_total,0) cantidad_total,COALESCE(ma.subtotal_total,0) subtotal_materiales,
   COALESCE(ma.resumen,'') resumen_materiales,COALESCE(ma.materiales,'[]'::jsonb) materiales
  FROM reciclaje2.operaciones o
  JOIN reciclaje2.tipos_operacion ti ON ti.id=o.tipo_operacion_id
  JOIN reciclaje2.etapas_operacion e ON e.id=o.etapa_operacion_id
  LEFT JOIN reciclaje2.socios s ON s.company_id=o.company_id AND s.id=o.socio_id
  LEFT JOIN reciclaje2.transportistas t ON t.company_id=o.company_id AND t.id=o.transportista_id
  LEFT JOIN reciclaje2.depositos d ON d.company_id=o.company_id AND d.id=o.deposito_id
  LEFT JOIN reciclaje2.monedas m ON m.id=o.moneda_id LEFT JOIN reciclaje2.formas_pago fp ON fp.id=o.forma_pago_id
  LEFT JOIN reciclaje2.salida_operaciones so ON so.company_id=o.company_id AND so.operacion_id=o.id AND so.estado='activa'
  LEFT JOIN reciclaje2.salidas_transporte st ON st.company_id=so.company_id AND st.id=so.salida_id
  LEFT JOIN LATERAL (
   SELECT count(*) lineas,sum(om.cantidad) cantidad_total,sum(om.subtotal) subtotal_total,
    string_agg(mt.nombre||' '||om.cantidad::text||' '||mt.unidad,', ' ORDER BY mt.nombre) resumen,
    jsonb_agg(jsonb_build_object('operacion_material_id',om.id,'material_id',mt.id,'material_codigo',mt.codigo,'material_nombre',mt.nombre,'unidad',mt.unidad,'cantidad',om.cantidad,'precio_unitario',om.precio_unitario,'subtotal',om.subtotal) ORDER BY mt.nombre) materiales
   FROM reciclaje2.operacion_materiales om JOIN reciclaje2.materiales mt ON mt.company_id=om.company_id AND mt.id=om.material_id
   WHERE om.company_id=o.company_id AND om.operacion_id=o.id) ma ON true
  WHERE o.company_id=p_company_id AND o.eliminada=false AND (p_tipo_id IS NULL OR o.tipo_operacion_id=p_tipo_id)
   AND (p_etapa_id IS NULL OR o.etapa_operacion_id=p_etapa_id) AND (p_socio_id IS NULL OR o.socio_id=p_socio_id)
   AND (p_transportista_id IS NULL OR o.transportista_id=p_transportista_id)
   AND (p_fecha_desde IS NULL OR o.created_at>=p_fecha_desde) AND (p_fecha_hasta IS NULL OR o.created_at<p_fecha_hasta)
   AND (p_estado IS NULL OR lower(e.codigo)=lower(p_estado) OR lower(st.estado)=lower(p_estado))
   AND (NULLIF(btrim(p_busqueda),'') IS NULL OR concat_ws(' ',o.referencia,o.descripcion,s.codigo,s.nombre,s.telefono,s.direccion,t.codigo,t.nombre,t.placa,ma.resumen) ILIKE '%'||btrim(p_busqueda)||'%')
 ), paged AS (SELECT * FROM base ORDER BY created_at DESC,operacion_id DESC LIMIT p_limit OFFSET p_offset)
 SELECT jsonb_build_object('total',(SELECT count(*) FROM base),'limit',p_limit,'offset',p_offset,'items',COALESCE(jsonb_agg(to_jsonb(paged) ORDER BY created_at DESC,operacion_id DESC),'[]'::jsonb)) INTO r FROM paged;
 RETURN r;
END;$$;


--
-- Name: FUNCTION listar_operaciones(p_company_id uuid, p_tipo_id uuid, p_etapa_id uuid, p_socio_id uuid, p_transportista_id uuid, p_fecha_desde timestamp with time zone, p_fecha_hasta timestamp with time zone, p_busqueda text, p_estado text, p_limit integer, p_offset integer); Type: COMMENT; Schema: reciclaje2; Owner: -
--

COMMENT ON FUNCTION reciclaje2.listar_operaciones(p_company_id uuid, p_tipo_id uuid, p_etapa_id uuid, p_socio_id uuid, p_transportista_id uuid, p_fecha_desde timestamp with time zone, p_fecha_hasta timestamp with time zone, p_busqueda text, p_estado text, p_limit integer, p_offset integer) IS 'Listado comercial enriquecido, filtrado y paginado.';


--
-- Name: listar_precios_socio(uuid, uuid, uuid); Type: FUNCTION; Schema: reciclaje2; Owner: -
--

CREATE FUNCTION reciclaje2.listar_precios_socio(p_company_id uuid, p_socio_id uuid, p_material_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'reciclaje2'
    AS $$
DECLARE r jsonb;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM reciclaje2.socios s WHERE s.company_id=p_company_id AND s.id=p_socio_id) THEN RAISE EXCEPTION 'socio no pertenece a company_id' USING ERRCODE='23503'; END IF;
 SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY x.material_nombre),'[]'::jsonb) INTO r FROM(
  SELECT m.id material_id,m.codigo material_codigo,m.nombre material_nombre,m.unidad,
   m.precio_base precio_referencia,ars.id precio_referencia_moneda_id,ars.codigo precio_referencia_moneda_codigo,ars.simbolo precio_referencia_moneda_simbolo,
   m.precio_mayorista,NULL::uuid precio_mayorista_moneda_id,NULL::text precio_mayorista_moneda_codigo,NULL::text precio_mayorista_moneda_simbolo,
   ps.precio precio_socio,ps.moneda_id precio_socio_moneda_id,pmon.codigo precio_socio_moneda_codigo,pmon.simbolo precio_socio_moneda_simbolo,
   COALESCE(ps.precio,m.precio_base) precio_efectivo,COALESCE(ps.moneda_id,ars.id) precio_efectivo_moneda_id,
   COALESCE(pmon.codigo,ars.codigo) precio_efectivo_moneda_codigo,COALESCE(pmon.simbolo,ars.simbolo) precio_efectivo_moneda_simbolo,
   CASE WHEN ps.id IS NULL THEN 'precio_referencia' ELSE 'precio_socio' END precio_efectivo_origen,
   ult.precio_unitario ultimo_precio,ult.created_at ultimo_precio_fecha,ult.moneda_id ultimo_precio_moneda_id,
   umon.codigo ultimo_precio_moneda_codigo,umon.simbolo ultimo_precio_moneda_simbolo
  FROM reciclaje2.materiales m LEFT JOIN reciclaje2.precios_socios ps ON ps.company_id=m.company_id AND ps.material_id=m.id AND ps.socio_id=p_socio_id
  LEFT JOIN reciclaje2.monedas pmon ON pmon.id=ps.moneda_id LEFT JOIN reciclaje2.monedas ars ON ars.codigo='ARS'
  LEFT JOIN LATERAL(SELECT om.precio_unitario,om.created_at,o.moneda_id FROM reciclaje2.operacion_materiales om JOIN reciclaje2.operaciones o ON o.company_id=om.company_id AND o.id=om.operacion_id WHERE o.company_id=m.company_id AND o.socio_id=p_socio_id AND om.material_id=m.id ORDER BY om.created_at DESC,om.id DESC LIMIT 1)ult ON true
  LEFT JOIN reciclaje2.monedas umon ON umon.id=ult.moneda_id
  WHERE m.company_id=p_company_id AND (p_material_id IS NULL OR m.id=p_material_id))x; RETURN r;
END;$$;


--
-- Name: listar_presupuestos_gastos(uuid, date); Type: FUNCTION; Schema: reciclaje2; Owner: -
--

CREATE FUNCTION reciclaje2.listar_presupuestos_gastos(p_company_id uuid, p_periodo date) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'reciclaje2'
    AS $$
DECLARE v_periodo date;
BEGIN
 IF p_company_id IS NULL OR p_periodo IS NULL THEN RAISE EXCEPTION 'company_id y periodo son obligatorios' USING ERRCODE='22004'; END IF;
 v_periodo:=date_trunc('month',p_periodo)::date;
 RETURN COALESCE((SELECT jsonb_agg(jsonb_build_object('id',p.id,'periodo',p.periodo,'moneda_id',p.moneda_id,
  'moneda_codigo',m.codigo,'moneda_nombre',m.nombre,'moneda_simbolo',m.simbolo,'limite',p.limite)
  ORDER BY m.codigo) FROM reciclaje2.presupuestos_gastos p JOIN reciclaje2.monedas m ON m.id=p.moneda_id
  WHERE p.company_id=p_company_id AND p.periodo=v_periodo),'[]'::jsonb);
END;$$;


--
-- Name: listar_salidas(uuid, text, uuid, timestamp with time zone, timestamp with time zone, text, integer, integer); Type: FUNCTION; Schema: reciclaje2; Owner: -
--

CREATE FUNCTION reciclaje2.listar_salidas(p_company_id uuid, p_estado text DEFAULT NULL::text, p_transportista_id uuid DEFAULT NULL::uuid, p_fecha_desde timestamp with time zone DEFAULT NULL::timestamp with time zone, p_fecha_hasta timestamp with time zone DEFAULT NULL::timestamp with time zone, p_busqueda text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'reciclaje2'
    AS $$
DECLARE r jsonb;
BEGIN
 IF p_company_id IS NULL OR p_limit<1 OR p_limit>200 OR p_offset<0 THEN RAISE EXCEPTION 'parámetros de listado inválidos' USING ERRCODE='22023'; END IF;
 WITH base AS (
  SELECT st.id salida_id,st.grupo_transporte_id,st.grupo_dinero_id,st.estado,st.fecha_salida,st.fecha_finalizacion,st.fecha_cancelacion,st.observaciones,
   t.id transportista_id,t.codigo transportista_codigo,t.nombre transportista_nombre,t.placa,t.telefono transportista_telefono,
   d.id deposito_id,d.codigo deposito_codigo,d.nombre deposito_nombre,COALESCE(x.operaciones,0) cantidad_operaciones,COALESCE(x.monto_previsto,0) monto_previsto,
   COALESCE(mp.montos,'[]'::jsonb) monto_previsto_por_moneda,
   COALESCE(mc.materiales,'[]'::jsonb) materiales_consolidados,COALESCE(h.entregado,0) dinero_entregado,COALESCE(h.usado,0) compras_justificadas,
   COALESCE(h.gastos,0) gastos,COALESCE(h.vueltos,0) vuelto_recibido,COALESCE(h.devuelto,0) devuelto,
   (pos.j->>'consolidado_base')::numeric pendiente,pos.j->'posicion_por_moneda' posicion_por_moneda,
   jsonb_build_object(
     'entregado',COALESCE(h.entregado,0),'utilizado',COALESCE(h.usado,0),'compras',COALESCE(h.usado,0),
     'gastos',COALESCE(h.gastos,0),'vuelto_recibido',COALESCE(h.vueltos,0),'devuelto',COALESCE(h.devuelto,0),
     'pendiente',(pos.j->>'consolidado_base')::numeric,
     'posicion_por_moneda',pos.j->'posicion_por_moneda',
     'consolidado_base',(pos.j->>'consolidado_base')::numeric
   ) dinero
  FROM reciclaje2.salidas_transporte st JOIN reciclaje2.transportistas t ON t.company_id=st.company_id AND t.id=st.transportista_id LEFT JOIN reciclaje2.depositos d ON d.company_id=st.company_id AND d.id=st.deposito_id
  LEFT JOIN LATERAL (SELECT count(*) operaciones,sum(o.monto) monto_previsto
   FROM reciclaje2.salida_operaciones so JOIN reciclaje2.operaciones o ON o.company_id=so.company_id AND o.id=so.operacion_id
   WHERE so.company_id=st.company_id AND so.salida_id=st.id AND so.estado='activa') x ON true
  LEFT JOIN LATERAL (SELECT jsonb_agg(jsonb_build_object('moneda_id',z.moneda_id,'codigo',z.codigo,'simbolo',z.simbolo,'monto',z.monto) ORDER BY z.codigo) montos
   FROM (SELECT o.moneda_id,m.codigo,m.simbolo,sum(o.monto) monto FROM reciclaje2.salida_operaciones so JOIN reciclaje2.operaciones o ON o.company_id=so.company_id AND o.id=so.operacion_id JOIN reciclaje2.monedas m ON m.id=o.moneda_id WHERE so.company_id=st.company_id AND so.salida_id=st.id AND so.estado='activa' GROUP BY o.moneda_id,m.codigo,m.simbolo) z) mp ON true
  LEFT JOIN LATERAL (SELECT jsonb_agg(jsonb_build_object('material_id',z.material_id,'material_codigo',z.codigo,'material_nombre',z.nombre,'unidad',z.unidad,'cantidad',z.cantidad) ORDER BY z.nombre) materiales
   FROM (SELECT mt.id material_id,mt.codigo,mt.nombre,mt.unidad,sum(om.cantidad) cantidad FROM reciclaje2.salida_operaciones so2 JOIN reciclaje2.operacion_materiales om ON om.company_id=so2.company_id AND om.operacion_id=so2.operacion_id JOIN reciclaje2.materiales mt ON mt.company_id=om.company_id AND mt.id=om.material_id WHERE so2.company_id=st.company_id AND so2.salida_id=st.id AND so2.estado='activa' GROUP BY mt.id,mt.codigo,mt.nombre,mt.unidad) z) mc ON true
  LEFT JOIN LATERAL (SELECT sum(hd.monto_base) FILTER(WHERE hd.tipo='entrega') entregado,
   COALESCE(sum(hd.monto_base) FILTER(WHERE hd.tipo IN('justificacion_operacion','pago_fisico_operacion') AND (hd.tipo<>'pago_fisico_operacion' OR hd.origen_fondos='entrega')),0)+COALESCE(sum(round((hd.monto-hd.monto_pendiente)*hd.tipo_cambio,2)) FILTER(WHERE hd.tipo='liquidacion_operacion' AND hd.modelo_version=1 AND hd.impacto_caja IS NULL),0) usado,
   sum(hd.monto_base) FILTER(WHERE hd.tipo='gasto' AND COALESCE(hd.origen_fondos,'entrega')='entrega') gastos,sum(hd.monto_base) FILTER(WHERE hd.tipo='vuelto_recibido') vueltos,sum(hd.monto_base) FILTER(WHERE hd.tipo='devolucion') devuelto
   FROM reciclaje2.hechos_dinero hd WHERE hd.company_id=st.company_id AND hd.grupo_dinero_id=st.grupo_dinero_id) h ON true
  CROSS JOIN LATERAL (SELECT reciclaje2.obtener_posicion_fondos(st.company_id,st.grupo_dinero_id) j) pos
  WHERE st.company_id=p_company_id AND (p_estado IS NULL OR st.estado=p_estado) AND (p_transportista_id IS NULL OR st.transportista_id=p_transportista_id)
   AND (p_fecha_desde IS NULL OR (CASE WHEN p_estado='finalizada' THEN st.fecha_finalizacion ELSE st.fecha_salida END)>=p_fecha_desde)
   AND (p_fecha_hasta IS NULL OR (CASE WHEN p_estado='finalizada' THEN st.fecha_finalizacion ELSE st.fecha_salida END)<p_fecha_hasta)
   AND (NULLIF(btrim(p_busqueda),'') IS NULL OR concat_ws(' ',t.codigo,t.nombre,t.placa,st.grupo_transporte_id::text) ILIKE '%'||btrim(p_busqueda)||'%')
 ),paged AS(SELECT * FROM base ORDER BY fecha_salida DESC,salida_id DESC LIMIT p_limit OFFSET p_offset)
 SELECT jsonb_build_object('total',(SELECT count(*) FROM base),'limit',p_limit,'offset',p_offset,'items',COALESCE(jsonb_agg(to_jsonb(paged) ORDER BY fecha_salida DESC,salida_id DESC),'[]'::jsonb)) INTO r FROM paged; RETURN r;
END;$$;


--
-- Name: obtener_estado_finanza(uuid, uuid); Type: FUNCTION; Schema: reciclaje2; Owner: -
--

CREATE FUNCTION reciclaje2.obtener_estado_finanza(p_company_id uuid, p_finanza_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'reciclaje2'
    AS $$
DECLARE f reciclaje2.finanzas%ROWTYPE; a numeric(14,2); cuotas jsonb;
BEGIN
 SELECT fn.* INTO f FROM reciclaje2.finanzas AS fn WHERE fn.company_id=p_company_id AND fn.id=p_finanza_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'finanza no pertenece a company_id' USING ERRCODE='23503'; END IF;
 SELECT COALESCE(sum(h.monto_aplicado),0) INTO a FROM reciclaje2.hechos_dinero AS h
 WHERE h.company_id=p_company_id AND h.finanza_id=f.id AND h.tipo=CASE WHEN f.tipo='por_pagar' THEN 'pago' ELSE 'cobro' END;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',q.id,'numero',q.numero,'fecha_vencimiento',q.fecha_vencimiento,
  'monto_programado',q.monto_programado,'monto_aplicado',q.aplicado,'saldo',q.monto_programado-q.aplicado,
  'estado',CASE WHEN q.aplicado=q.monto_programado THEN 'saldada' WHEN q.aplicado>0 THEN 'parcial' WHEN q.fecha_vencimiento<now() THEN 'vencida' ELSE 'pendiente' END) ORDER BY q.fecha_vencimiento,q.numero,q.id),'[]') INTO cuotas
 FROM (SELECT v.*,greatest(least(a-COALESCE(sum(v.monto_programado) OVER(ORDER BY v.fecha_vencimiento,v.numero,v.id ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0),v.monto_programado),0) AS aplicado
       FROM reciclaje2.finanza_vencimientos AS v WHERE v.company_id=p_company_id AND v.finanza_id=f.id) AS q;
 RETURN jsonb_build_object('finanza',to_jsonb(f),'monto_aplicado',a,'saldo',f.monto_original-a,
  'estado_derivado',CASE WHEN f.estado='anulada' THEN 'anulada' WHEN a=f.monto_original THEN CASE WHEN f.tipo='por_pagar' THEN 'pagada' ELSE 'cobrada' END
   WHEN a>0 AND COALESCE((SELECT sum(v.monto_programado) FROM reciclaje2.finanza_vencimientos AS v WHERE v.company_id=p_company_id AND v.finanza_id=f.id AND v.fecha_vencimiento<now()),0)>a THEN 'parcial_vencida'
   WHEN a>0 THEN 'parcial' WHEN COALESCE((SELECT sum(v.monto_programado) FROM reciclaje2.finanza_vencimientos AS v WHERE v.company_id=p_company_id AND v.finanza_id=f.id AND v.fecha_vencimiento<now()),0)>a THEN 'vencida' ELSE 'pendiente' END,
  'vencimientos',cuotas);
END;$$;


--
-- Name: FUNCTION obtener_estado_finanza(p_company_id uuid, p_finanza_id uuid); Type: COMMENT; Schema: reciclaje2; Owner: -
--

COMMENT ON FUNCTION reciclaje2.obtener_estado_finanza(p_company_id uuid, p_finanza_id uuid) IS 'Consulta saldo y asigna los pagos/cobros reales a vencimientos en orden FIFO, sin persistir aplicaciones.';


--
-- Name: obtener_operacion(uuid, uuid); Type: FUNCTION; Schema: reciclaje2; Owner: -
--

CREATE FUNCTION reciclaje2.obtener_operacion(p_company_id uuid, p_operacion_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'reciclaje2'
    AS $$
DECLARE r jsonb;
BEGIN
 SELECT to_jsonb(o)||jsonb_build_object(
  'tipo',jsonb_build_object('id',ti.id,'codigo',ti.codigo,'nombre',ti.nombre),
  'etapa',jsonb_build_object('id',e.id,'codigo',e.codigo,'nombre',e.nombre,'orden',e.orden),
  'socio',CASE WHEN s.id IS NULL THEN NULL ELSE jsonb_build_object('id',s.id,'codigo',s.codigo,'nombre',s.nombre,'documento',s.documento,'telefono',s.telefono,'direccion',s.direccion,'latitud',s.latitud,'longitud',s.longitud) END,
  'transportista',CASE WHEN t.id IS NULL THEN NULL ELSE jsonb_build_object('id',t.id,'codigo',t.codigo,'nombre',t.nombre,'telefono',t.telefono,'placa',t.placa) END,
  'deposito',CASE WHEN d.id IS NULL THEN NULL ELSE jsonb_build_object('id',d.id,'codigo',d.codigo,'nombre',d.nombre,'direccion',d.direccion) END,
  'moneda',CASE WHEN m.id IS NULL THEN NULL ELSE jsonb_build_object('id',m.id,'codigo',m.codigo,'nombre',m.nombre,'simbolo',m.simbolo) END,
  'forma_pago',CASE WHEN fp.id IS NULL THEN NULL ELSE jsonb_build_object('id',fp.id,'codigo',fp.codigo,'nombre',fp.nombre) END,
  'salida',CASE WHEN st.id IS NULL THEN NULL ELSE jsonb_build_object('id',st.id,'grupo_transporte_id',st.grupo_transporte_id,'grupo_dinero_id',st.grupo_dinero_id,'estado',st.estado) END,
  'rendicion',rd.rendicion,
  'materiales',COALESCE((SELECT jsonb_agg(jsonb_build_object('operacion_material_id',om.id,'material_id',mt.id,'material_codigo',mt.codigo,'material_nombre',mt.nombre,'unidad',mt.unidad,'imagen_url',mt.imagen_url,'cantidad',om.cantidad,'precio_unitario',om.precio_unitario,'subtotal',om.subtotal,'observaciones',om.observaciones) ORDER BY mt.nombre) FROM reciclaje2.operacion_materiales om JOIN reciclaje2.materiales mt ON mt.company_id=om.company_id AND mt.id=om.material_id WHERE om.company_id=o.company_id AND om.operacion_id=o.id),'[]'::jsonb),
  'recepcion_fisica',COALESCE((SELECT jsonb_agg(jsonb_build_object('movimiento_stock_id',ms.id,'salida_id',ms.salida_id,'operacion_material_id',ms.operacion_material_id,'material_id',mt2.id,'material_codigo',mt2.codigo,'material_nombre',mt2.nombre,'unidad',mt2.unidad,'deposito_id',d2.id,'deposito_codigo',d2.codigo,'deposito_nombre',d2.nombre,'tipo',ms.tipo,'cantidad',ms.cantidad,'fecha',ms.created_at) ORDER BY ms.created_at,ms.id) FROM reciclaje2.movimientos_stock ms JOIN reciclaje2.materiales mt2 ON mt2.company_id=ms.company_id AND mt2.id=ms.material_id JOIN reciclaje2.depositos d2 ON d2.company_id=ms.company_id AND d2.id=ms.deposito_id WHERE ms.company_id=o.company_id AND ms.operacion_id=o.id),'[]'::jsonb)) INTO r
 FROM reciclaje2.operaciones o JOIN reciclaje2.tipos_operacion ti ON ti.id=o.tipo_operacion_id JOIN reciclaje2.etapas_operacion e ON e.id=o.etapa_operacion_id
 LEFT JOIN reciclaje2.socios s ON s.company_id=o.company_id AND s.id=o.socio_id LEFT JOIN reciclaje2.transportistas t ON t.company_id=o.company_id AND t.id=o.transportista_id
 LEFT JOIN reciclaje2.depositos d ON d.company_id=o.company_id AND d.id=o.deposito_id LEFT JOIN reciclaje2.monedas m ON m.id=o.moneda_id LEFT JOIN reciclaje2.formas_pago fp ON fp.id=o.forma_pago_id
 LEFT JOIN reciclaje2.salida_operaciones so ON so.company_id=o.company_id AND so.operacion_id=o.id AND so.estado='activa' LEFT JOIN reciclaje2.salidas_transporte st ON st.company_id=so.company_id AND st.id=so.salida_id
 LEFT JOIN LATERAL (
  SELECT jsonb_build_object(
   'liquidacion_evento_id',l.evento_id,'monto_comercial',l.monto,
   'moneda_comercial',jsonb_build_object('id',ml.id,'codigo',ml.codigo,'nombre',ml.nombre,'simbolo',ml.simbolo),
   'pagos_fisicos',COALESCE((SELECT jsonb_agg(jsonb_build_object('hecho_id',hp.id,'evento_id',hp.evento_id,'monto',hp.monto,'moneda_id',hp.moneda_id,'moneda_codigo',mp.codigo,'moneda_simbolo',mp.simbolo,'tipo_cambio',hp.tipo_cambio,'monto_base',hp.monto_base,'origen_fondos',hp.origen_fondos) ORDER BY hp.created_at,hp.id) FROM reciclaje2.hechos_dinero hp JOIN reciclaje2.monedas mp ON mp.id=hp.moneda_id WHERE hp.company_id=o.company_id AND hp.operacion_id=o.id AND hp.tipo='pago_fisico_operacion'),'[]'::jsonb),
   'vueltos',COALESCE((SELECT jsonb_agg(jsonb_build_object('hecho_id',hv.id,'evento_id',hv.evento_id,'monto',hv.monto,'moneda_id',hv.moneda_id,'moneda_codigo',mv.codigo,'moneda_simbolo',mv.simbolo,'tipo_cambio',hv.tipo_cambio,'monto_base',hv.monto_base) ORDER BY hv.created_at,hv.id) FROM reciclaje2.hechos_dinero hv JOIN reciclaje2.monedas mv ON mv.id=hv.moneda_id WHERE hv.company_id=o.company_id AND hv.operacion_id=o.id AND hv.tipo='vuelto_recibido'),'[]'::jsonb),
   'monto_aplicado',l.monto-l.monto_pendiente,'monto_pendiente',l.monto_pendiente,
   'responsable_pendiente',CASE WHEN l.monto_pendiente>0 THEN jsonb_build_object('tipo',l.responsable_tipo,'id',l.responsable_id,'nombre',l.responsable_nombre) ELSE NULL END,
   'modelo_version',l.modelo_version) rendicion
  FROM reciclaje2.hechos_dinero l JOIN reciclaje2.monedas ml ON ml.id=l.moneda_id
  WHERE l.company_id=o.company_id AND l.operacion_id=o.id AND l.tipo='liquidacion_operacion'
  ORDER BY l.created_at DESC,l.id DESC LIMIT 1) rd ON true
 WHERE o.company_id=p_company_id AND o.id=p_operacion_id;
 IF r IS NULL THEN RAISE EXCEPTION 'operación no pertenece a company_id' USING ERRCODE='23503'; END IF; RETURN r;
END;$$;


--
-- Name: obtener_posicion_fondos(uuid, uuid); Type: FUNCTION; Schema: reciclaje2; Owner: -
--

CREATE FUNCTION reciclaje2.obtener_posicion_fondos(p_company_id uuid, p_grupo_dinero_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'reciclaje2'
    AS $$
 WITH posiciones AS (
  SELECT h.moneda_id,m.codigo,m.nombre,m.simbolo,
   sum(CASE WHEN h.tipo='entrega' THEN h.monto WHEN h.tipo='vuelto_recibido' THEN h.monto
    WHEN h.tipo='pago_fisico_operacion' AND h.origen_fondos='entrega' THEN -h.monto
    WHEN h.tipo='gasto' AND COALESCE(h.origen_fondos,'entrega')='entrega' THEN -h.monto
    WHEN h.tipo='devolucion' THEN -h.monto WHEN h.tipo='justificacion_operacion' THEN -h.monto
    WHEN h.tipo='liquidacion_operacion' AND h.modelo_version=1 AND h.impacto_caja IS NULL THEN -(h.monto-h.monto_pendiente)
    WHEN h.tipo='diferencia' AND h.afecta_posicion_fisica IS TRUE AND h.sentido_diferencia='a_cargo_responsable' THEN -h.monto
    WHEN h.tipo='diferencia' AND h.afecta_posicion_fisica IS TRUE AND h.sentido_diferencia='a_favor_responsable' THEN h.monto ELSE 0 END) saldo,
   sum(CASE WHEN h.tipo='entrega' THEN h.monto_base WHEN h.tipo='vuelto_recibido' THEN h.monto_base
    WHEN h.tipo='pago_fisico_operacion' AND h.origen_fondos='entrega' THEN -h.monto_base
    WHEN h.tipo='gasto' AND COALESCE(h.origen_fondos,'entrega')='entrega' THEN -h.monto_base
    WHEN h.tipo='devolucion' THEN -h.monto_base WHEN h.tipo='justificacion_operacion' THEN -h.monto_base
    WHEN h.tipo='liquidacion_operacion' AND h.modelo_version=1 AND h.impacto_caja IS NULL THEN -round((h.monto-h.monto_pendiente)*h.tipo_cambio,2)
    WHEN h.tipo='diferencia' AND h.afecta_posicion_fisica IS TRUE AND h.sentido_diferencia='a_cargo_responsable' THEN -h.monto_base
    WHEN h.tipo='diferencia' AND h.afecta_posicion_fisica IS TRUE AND h.sentido_diferencia='a_favor_responsable' THEN h.monto_base ELSE 0 END) equivalente_ars
  FROM reciclaje2.hechos_dinero h JOIN reciclaje2.monedas m ON m.id=h.moneda_id
  WHERE h.company_id=p_company_id AND h.grupo_dinero_id=p_grupo_dinero_id GROUP BY h.moneda_id,m.codigo,m.nombre,m.simbolo),
 valuadas AS (SELECT posiciones.*,CASE WHEN saldo=0 THEN NULL
  WHEN (saldo>0 AND equivalente_ars>0) OR (saldo<0 AND equivalente_ars<0) THEN equivalente_ars/NULLIF(saldo,0) ELSE NULL END tipo_cambio_efectivo FROM posiciones)
 SELECT jsonb_build_object('posicion_por_moneda',COALESCE(jsonb_agg(to_jsonb(valuadas) ORDER BY codigo),'[]'::jsonb),'consolidado_base',COALESCE(sum(equivalente_ars),0)) FROM valuadas;
$$;


--
-- Name: obtener_resumen_operativo(uuid, date); Type: FUNCTION; Schema: reciclaje2; Owner: -
--

CREATE FUNCTION reciclaje2.obtener_resumen_operativo(p_company_id uuid, p_fecha date) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'reciclaje2'
    AS $$
DECLARE r jsonb; desde timestamptz; hasta timestamptz;
BEGIN
 IF p_company_id IS NULL OR p_fecha IS NULL THEN RAISE EXCEPTION 'company_id y fecha son obligatorios' USING ERRCODE='22004'; END IF;
 desde:=p_fecha::timestamp AT TIME ZONE 'America/Argentina/Buenos_Aires'; hasta:=(p_fecha+1)::timestamp AT TIME ZONE 'America/Argentina/Buenos_Aires';
 SELECT jsonb_build_object('fecha',p_fecha,'entregado',COALESCE(sum(h.monto_base) FILTER(WHERE h.tipo='entrega'),0),
  'compras',COALESCE(sum(h.monto_base) FILTER(WHERE h.tipo IN('justificacion_operacion','pago_fisico_operacion') AND (h.tipo<>'pago_fisico_operacion' OR h.origen_fondos='entrega')),0)+COALESCE(sum(round((h.monto-h.monto_pendiente)*h.tipo_cambio,2)) FILTER(WHERE h.tipo='liquidacion_operacion' AND h.modelo_version=1 AND h.impacto_caja IS NULL),0),
  'gastos',COALESCE(sum(h.monto_base) FILTER(WHERE h.tipo='gasto' AND COALESCE(h.origen_fondos,'entrega')='entrega'),0),'vuelto_recibido',COALESCE(sum(h.monto_base) FILTER(WHERE h.tipo='vuelto_recibido'),0),'devuelto',COALESCE(sum(h.monto_base) FILTER(WHERE h.tipo='devolucion'),0),
  'pendiente',COALESCE(sum(CASE WHEN h.tipo IN('entrega','vuelto_recibido') THEN h.monto_base WHEN h.tipo IN('justificacion_operacion','devolucion') THEN -h.monto_base WHEN h.tipo='pago_fisico_operacion' AND h.origen_fondos='entrega' THEN -h.monto_base WHEN h.tipo='gasto' AND COALESCE(h.origen_fondos,'entrega')='entrega' THEN -h.monto_base WHEN h.tipo='liquidacion_operacion' AND h.modelo_version=1 AND h.impacto_caja IS NULL THEN -round((h.monto-h.monto_pendiente)*h.tipo_cambio,2) WHEN h.tipo='diferencia' AND h.afecta_posicion_fisica IS TRUE AND h.sentido_diferencia='a_cargo_responsable' THEN -h.monto_base WHEN h.tipo='diferencia' AND h.afecta_posicion_fisica IS TRUE AND h.sentido_diferencia='a_favor_responsable' THEN h.monto_base ELSE 0 END),0),
  'operaciones',jsonb_build_object('compras',COALESCE((SELECT count(*) FROM reciclaje2.operaciones o JOIN reciclaje2.tipos_operacion ti ON ti.id=o.tipo_operacion_id WHERE o.company_id=p_company_id AND o.eliminada=false AND ti.codigo='COMPRA' AND o.created_at>=desde AND o.created_at<hasta),0),'por_etapa',COALESCE((SELECT jsonb_object_agg(x.codigo,x.cantidad) FROM(SELECT e.codigo,count(*) cantidad FROM reciclaje2.operaciones o JOIN reciclaje2.etapas_operacion e ON e.id=o.etapa_operacion_id WHERE o.company_id=p_company_id AND o.eliminada=false GROUP BY e.codigo)x),'{}'::jsonb),'salidas_activas',(SELECT count(*) FROM reciclaje2.salidas_transporte st WHERE st.company_id=p_company_id AND st.estado='abierta')),
  'materiales_comprados',COALESCE((SELECT jsonb_agg(jsonb_build_object('material_id',x.id,'codigo',x.codigo,'nombre',x.nombre,'unidad',x.unidad,'cantidad',x.cantidad) ORDER BY x.nombre) FROM(SELECT mt.id,mt.codigo,mt.nombre,mt.unidad,sum(om.cantidad) cantidad FROM reciclaje2.operaciones o JOIN reciclaje2.tipos_operacion ti ON ti.id=o.tipo_operacion_id JOIN reciclaje2.operacion_materiales om ON om.company_id=o.company_id AND om.operacion_id=o.id JOIN reciclaje2.materiales mt ON mt.company_id=om.company_id AND mt.id=om.material_id WHERE o.company_id=p_company_id AND o.eliminada=false AND ti.codigo='COMPRA' AND o.created_at>=desde AND o.created_at<hasta GROUP BY mt.id,mt.codigo,mt.nombre,mt.unidad)x),'[]'::jsonb),
  'por_moneda',jsonb_build_object(
    'entregado',COALESCE((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.codigo) FROM(SELECT hd.moneda_id,m.codigo,m.simbolo,sum(hd.monto) monto FROM reciclaje2.hechos_dinero hd JOIN reciclaje2.monedas m ON m.id=hd.moneda_id WHERE hd.company_id=p_company_id AND hd.created_at>=desde AND hd.created_at<hasta AND hd.tipo='entrega' GROUP BY hd.moneda_id,m.codigo,m.simbolo)x),'[]'::jsonb),
    'compras',COALESCE((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.codigo) FROM(SELECT o.moneda_id,m.codigo,m.simbolo,sum(o.monto) monto FROM reciclaje2.operaciones o JOIN reciclaje2.tipos_operacion ti ON ti.id=o.tipo_operacion_id JOIN reciclaje2.salida_operaciones so ON so.company_id=o.company_id AND so.operacion_id=o.id AND so.estado='activa' JOIN reciclaje2.salidas_transporte st ON st.company_id=so.company_id AND st.id=so.salida_id JOIN reciclaje2.monedas m ON m.id=o.moneda_id WHERE o.company_id=p_company_id AND o.eliminada=false AND ti.codigo='COMPRA' AND st.estado='finalizada' AND st.fecha_finalizacion>=desde AND st.fecha_finalizacion<hasta GROUP BY o.moneda_id,m.codigo,m.simbolo)x),'[]'::jsonb),
    'gastos',COALESCE((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.codigo) FROM(SELECT hd.moneda_id,m.codigo,m.simbolo,sum(hd.monto) monto FROM reciclaje2.hechos_dinero hd JOIN reciclaje2.monedas m ON m.id=hd.moneda_id WHERE hd.company_id=p_company_id AND hd.created_at>=desde AND hd.created_at<hasta AND hd.tipo='gasto' AND COALESCE(hd.origen_fondos,'entrega')='entrega' GROUP BY hd.moneda_id,m.codigo,m.simbolo)x),'[]'::jsonb),
    'devuelto',COALESCE((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.codigo) FROM(SELECT hd.moneda_id,m.codigo,m.simbolo,sum(hd.monto) monto FROM reciclaje2.hechos_dinero hd JOIN reciclaje2.monedas m ON m.id=hd.moneda_id WHERE hd.company_id=p_company_id AND hd.created_at>=desde AND hd.created_at<hasta AND hd.tipo='devolucion' GROUP BY hd.moneda_id,m.codigo,m.simbolo)x),'[]'::jsonb),
    'pendiente_rendicion',COALESCE((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.codigo) FROM(SELECT p.moneda_id,p.codigo,p.simbolo,sum(p.saldo) monto FROM reciclaje2.salidas_transporte st CROSS JOIN LATERAL jsonb_to_recordset(reciclaje2.obtener_posicion_fondos(st.company_id,st.grupo_dinero_id)->'posicion_por_moneda') AS p(moneda_id uuid,codigo text,simbolo text,saldo numeric) WHERE st.company_id=p_company_id AND st.estado='abierta' AND st.fecha_salida>=desde AND st.fecha_salida<hasta GROUP BY p.moneda_id,p.codigo,p.simbolo HAVING sum(p.saldo)<>0)x),'[]'::jsonb),
    'le_debemos',COALESCE((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.codigo) FROM(SELECT f.moneda_id,m.codigo,m.simbolo,sum((reciclaje2.obtener_estado_finanza(f.company_id,f.id)->>'saldo')::numeric) monto FROM reciclaje2.finanzas f JOIN reciclaje2.monedas m ON m.id=f.moneda_id WHERE f.company_id=p_company_id AND f.tipo='por_pagar' AND f.fecha_emision>=desde AND f.fecha_emision<hasta GROUP BY f.moneda_id,m.codigo,m.simbolo HAVING sum((reciclaje2.obtener_estado_finanza(f.company_id,f.id)->>'saldo')::numeric)<>0)x),'[]'::jsonb),
    'nos_deben',COALESCE((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.codigo) FROM(SELECT f.moneda_id,m.codigo,m.simbolo,sum((reciclaje2.obtener_estado_finanza(f.company_id,f.id)->>'saldo')::numeric) monto FROM reciclaje2.finanzas f JOIN reciclaje2.monedas m ON m.id=f.moneda_id WHERE f.company_id=p_company_id AND f.tipo='por_cobrar' AND f.fecha_emision>=desde AND f.fecha_emision<hasta GROUP BY f.moneda_id,m.codigo,m.simbolo HAVING sum((reciclaje2.obtener_estado_finanza(f.company_id,f.id)->>'saldo')::numeric)<>0)x),'[]'::jsonb)
  )) INTO r
 FROM reciclaje2.hechos_dinero h WHERE h.company_id=p_company_id AND h.created_at>=desde AND h.created_at<hasta; RETURN r;
END;$$;


--
-- Name: obtener_salida(uuid, uuid); Type: FUNCTION; Schema: reciclaje2; Owner: -
--

CREATE FUNCTION reciclaje2.obtener_salida(p_company_id uuid, p_salida_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'reciclaje2'
    AS $$
DECLARE r jsonb;
BEGIN
 SELECT to_jsonb(st)||jsonb_build_object('transportista',jsonb_build_object('id',t.id,'codigo',t.codigo,'nombre',t.nombre,'placa',t.placa,'telefono',t.telefono),
  'deposito',CASE WHEN d.id IS NULL THEN NULL ELSE jsonb_build_object('id',d.id,'codigo',d.codigo,'nombre',d.nombre,'direccion',d.direccion) END,
  'dinero',jsonb_build_object('entregado',COALESCE(h.entregado,0),'utilizado',COALESCE(h.usado,0),'compras',COALESCE(h.usado,0),'gastos',COALESCE(h.gastos,0),'vuelto_recibido',COALESCE(h.vueltos,0),'devuelto',COALESCE(h.devuelto,0),
   'entregado_por_moneda',COALESCE(ep.entregas,'[]'::jsonb),'gastos_detalle',COALESCE(h.gastos_detalle,'[]'::jsonb),'devoluciones_detalle',COALESCE(h.devoluciones_detalle,'[]'::jsonb),'diferencias_fisicas',COALESCE(h.diferencias_fisicas,'[]'::jsonb),
   'pendiente',(pos.j->>'consolidado_base')::numeric,'posicion_por_moneda',pos.j->'posicion_por_moneda','consolidado_base',(pos.j->>'consolidado_base')::numeric,'hechos',COALESCE(h.hechos,'[]'::jsonb)),
  'cargas',COALESCE(c.cargas,'[]'::jsonb),'materiales_consolidados',COALESCE(mc.materiales,'[]'::jsonb)) INTO r
 FROM reciclaje2.salidas_transporte st JOIN reciclaje2.transportistas t ON t.company_id=st.company_id AND t.id=st.transportista_id LEFT JOIN reciclaje2.depositos d ON d.company_id=st.company_id AND d.id=st.deposito_id
 LEFT JOIN LATERAL (SELECT sum(hd.monto_base) FILTER(WHERE hd.tipo='entrega') entregado,
  COALESCE(sum(hd.monto_base) FILTER(WHERE hd.tipo IN('justificacion_operacion','pago_fisico_operacion') AND (hd.tipo<>'pago_fisico_operacion' OR hd.origen_fondos='entrega')),0)+COALESCE(sum(round((hd.monto-hd.monto_pendiente)*hd.tipo_cambio,2)) FILTER(WHERE hd.tipo='liquidacion_operacion' AND hd.modelo_version=1 AND hd.impacto_caja IS NULL),0) usado,
  sum(hd.monto_base) FILTER(WHERE hd.tipo='gasto' AND COALESCE(hd.origen_fondos,'entrega')='entrega') gastos,sum(hd.monto_base) FILTER(WHERE hd.tipo='vuelto_recibido') vueltos,sum(hd.monto_base) FILTER(WHERE hd.tipo='devolucion') devuelto,
  jsonb_agg(to_jsonb(hd) ORDER BY hd.created_at,hd.id) FILTER(WHERE hd.tipo='gasto') gastos_detalle,
  jsonb_agg(to_jsonb(hd) ORDER BY hd.created_at,hd.id) FILTER(WHERE hd.tipo='devolucion') devoluciones_detalle,
  jsonb_agg(to_jsonb(hd) ORDER BY hd.created_at,hd.id) FILTER(WHERE hd.tipo='diferencia' AND hd.afecta_posicion_fisica IS TRUE) diferencias_fisicas,
  jsonb_agg(to_jsonb(hd) ORDER BY hd.created_at,hd.id) hechos
  FROM reciclaje2.hechos_dinero hd WHERE hd.company_id=st.company_id AND hd.grupo_dinero_id=st.grupo_dinero_id) h ON true
 LEFT JOIN LATERAL (SELECT jsonb_agg(jsonb_build_object('moneda_id',z.moneda_id,'codigo',z.codigo,'simbolo',z.simbolo,'monto',z.monto,'monto_base',z.monto_base) ORDER BY z.codigo) entregas FROM (SELECT hd.moneda_id,m.codigo,m.simbolo,sum(hd.monto) monto,sum(hd.monto_base) monto_base FROM reciclaje2.hechos_dinero hd JOIN reciclaje2.monedas m ON m.id=hd.moneda_id WHERE hd.company_id=st.company_id AND hd.grupo_dinero_id=st.grupo_dinero_id AND hd.tipo='entrega' GROUP BY hd.moneda_id,m.codigo,m.simbolo) z) ep ON true
 CROSS JOIN LATERAL (SELECT reciclaje2.obtener_posicion_fondos(st.company_id,st.grupo_dinero_id) j) pos
 LEFT JOIN LATERAL (SELECT jsonb_agg(reciclaje2.obtener_operacion(st.company_id,so.operacion_id) ORDER BY so.agregado_at) cargas FROM reciclaje2.salida_operaciones so WHERE so.company_id=st.company_id AND so.salida_id=st.id AND so.estado='activa') c ON true
 LEFT JOIN LATERAL (SELECT jsonb_agg(jsonb_build_object('material_id',mt.id,'material_codigo',mt.codigo,'material_nombre',mt.nombre,'unidad',mt.unidad,'cantidad',sumas.cantidad) ORDER BY mt.nombre) materiales FROM (SELECT om.material_id,sum(om.cantidad) cantidad FROM reciclaje2.salida_operaciones so JOIN reciclaje2.operacion_materiales om ON om.company_id=so.company_id AND om.operacion_id=so.operacion_id WHERE so.company_id=st.company_id AND so.salida_id=st.id AND so.estado='activa' GROUP BY om.material_id) sumas JOIN reciclaje2.materiales mt ON mt.company_id=st.company_id AND mt.id=sumas.material_id) mc ON true
 WHERE st.company_id=p_company_id AND st.id=p_salida_id;
 IF r IS NULL THEN RAISE EXCEPTION 'salida no pertenece a company_id' USING ERRCODE='23503'; END IF; RETURN r;
END;$$;


--
-- Name: FUNCTION obtener_salida(p_company_id uuid, p_salida_id uuid); Type: COMMENT; Schema: reciclaje2; Owner: -
--

COMMENT ON FUNCTION reciclaje2.obtener_salida(p_company_id uuid, p_salida_id uuid) IS 'Detalle de grupo de transporte real con cargas, materiales y conciliación.';


--
-- Name: obtener_valuacion_posicion_moneda(uuid, uuid, uuid); Type: FUNCTION; Schema: reciclaje2; Owner: -
--

CREATE FUNCTION reciclaje2.obtener_valuacion_posicion_moneda(p_company_id uuid, p_grupo_dinero_id uuid, p_moneda_id uuid) RETURNS TABLE(saldo_fisico numeric, valor_base_remanente numeric, tipo_cambio_efectivo numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'reciclaje2'
    AS $$
 WITH posicion AS (
  SELECT COALESCE(sum(CASE
   WHEN tipo='entrega' THEN monto WHEN tipo='vuelto_recibido' THEN monto
   WHEN tipo='pago_fisico_operacion' AND origen_fondos='entrega' THEN -monto
   WHEN tipo='gasto' AND COALESCE(origen_fondos,'entrega')='entrega' THEN -monto
   WHEN tipo='devolucion' THEN -monto WHEN tipo='justificacion_operacion' THEN -monto
   WHEN tipo='liquidacion_operacion' AND modelo_version=1 AND impacto_caja IS NULL THEN -(monto-monto_pendiente)
   WHEN tipo='diferencia' AND afecta_posicion_fisica IS TRUE AND sentido_diferencia='a_cargo_responsable' THEN -monto
   WHEN tipo='diferencia' AND afecta_posicion_fisica IS TRUE AND sentido_diferencia='a_favor_responsable' THEN monto ELSE 0 END),0) saldo,
   COALESCE(sum(CASE
   WHEN tipo='entrega' THEN monto_base WHEN tipo='vuelto_recibido' THEN monto_base
   WHEN tipo='pago_fisico_operacion' AND origen_fondos='entrega' THEN -monto_base
   WHEN tipo='gasto' AND COALESCE(origen_fondos,'entrega')='entrega' THEN -monto_base
   WHEN tipo='devolucion' THEN -monto_base WHEN tipo='justificacion_operacion' THEN -monto_base
   WHEN tipo='liquidacion_operacion' AND modelo_version=1 AND impacto_caja IS NULL THEN -round((monto-monto_pendiente)*tipo_cambio,2)
   WHEN tipo='diferencia' AND afecta_posicion_fisica IS TRUE AND sentido_diferencia='a_cargo_responsable' THEN -monto_base
   WHEN tipo='diferencia' AND afecta_posicion_fisica IS TRUE AND sentido_diferencia='a_favor_responsable' THEN monto_base ELSE 0 END),0) valor_base
  FROM reciclaje2.hechos_dinero WHERE company_id=p_company_id AND grupo_dinero_id=p_grupo_dinero_id AND moneda_id=p_moneda_id)
 SELECT saldo,valor_base,CASE WHEN saldo=0 THEN NULL
  WHEN (saldo>0 AND valor_base>0) OR (saldo<0 AND valor_base<0) THEN valor_base/NULLIF(saldo,0) ELSE NULL END
 FROM posicion;
$$;


--
-- Name: FUNCTION obtener_valuacion_posicion_moneda(p_company_id uuid, p_grupo_dinero_id uuid, p_moneda_id uuid); Type: COMMENT; Schema: reciclaje2; Owner: -
--

COMMENT ON FUNCTION reciclaje2.obtener_valuacion_posicion_moneda(p_company_id uuid, p_grupo_dinero_id uuid, p_moneda_id uuid) IS 'Obtiene saldo, valor base y TC promedio contable por moneda sin reconstruir lotes.';


--
-- Name: orquestar_dinero(uuid, uuid, character varying, jsonb); Type: FUNCTION; Schema: reciclaje2; Owner: -
--

CREATE FUNCTION reciclaje2.orquestar_dinero(p_company_id uuid, p_evento_id uuid, p_accion character varying, p_datos jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'reciclaje2'
    AS $$
DECLARE
    v_hecho reciclaje2.hechos_dinero%ROWTYPE;
    v_caja reciclaje2.movimientos_caja%ROWTYPE;
    v_finanza reciclaje2.finanzas%ROWTYPE;
    v_operacion reciclaje2.operaciones%ROWTYPE;
    v_cotizacion reciclaje2.tipos_cambio%ROWTYPE;
    v_cotizacion_aplicacion reciclaje2.tipos_cambio%ROWTYPE;

    v_monto numeric(14,2);
    v_moneda_id uuid;
    v_tipo_cambio numeric(14,6);
    v_monto_base numeric(14,2);
    v_tipo_cambio_id uuid;
    v_monto_aplicado numeric(14,2);
    v_tipo_cambio_aplicacion numeric(14,6);
    v_tipo_cambio_aplicacion_id uuid;
    v_operacion_id uuid;
    v_finanza_id uuid;
    v_tipo_gasto_id uuid;
    v_grupo_dinero_id uuid;
    v_grupo_transporte_id uuid;
    v_responsable_tipo varchar(50);
    v_sentido_diferencia varchar(30);
    v_responsable_id uuid;
    v_responsable_nombre text;
    v_forma_pago_id uuid;
    v_referencia text;
    v_comprobante_url text;
    v_observaciones text;
    v_impacto_caja varchar(20);
    v_concepto text;
    v_tipo_caja varchar(20);
    v_disponible_base numeric(14,2);
    v_aplicado numeric(14,2);
    v_saldo numeric(14,2);
    v_estado varchar(30);
    v_monto_liquidado numeric(14,2);
    v_monto_caja numeric(14,2);
    v_monto_pendiente numeric(14,2);
    v_tipo_operacion_codigo varchar(50);
    v_finanza_tipo varchar(30);
    v_origen_fondos varchar(20);
    v_modelo_version smallint;
    v_aplicado_base numeric(14,2);
    v_pago_eventos jsonb;
    v_vuelto_eventos jsonb;
    v_saldo_fisico numeric;
    v_valor_base_remanente numeric;
    v_tipo_cambio_efectivo numeric;
    v_afecta_posicion_fisica boolean;
BEGIN
    IF p_company_id IS NULL OR p_evento_id IS NULL THEN
        RAISE EXCEPTION 'company_id y evento_id son obligatorios' USING ERRCODE='22004';
    END IF;
    IF p_datos IS NULL OR jsonb_typeof(p_datos) <> 'object' THEN
        RAISE EXCEPTION 'datos debe ser un objeto JSON' USING ERRCODE='22023';
    END IF;
    IF p_accion NOT IN ('entrega','devolucion','justificacion_operacion','gasto','gasto_pendiente',
                        'cobro','pago','diferencia','ajuste','liquidacion_operacion',
                        'pago_fisico_operacion','vuelto_recibido') THEN
        RAISE EXCEPTION 'acción de dinero no admitida: %',p_accion USING ERRCODE='22023';
    END IF;

    -- Serializa reintentos concurrentes del mismo evento.
    PERFORM pg_advisory_xact_lock(hashtextextended(p_company_id::text||':'||p_evento_id::text,0));

    SELECT * INTO v_hecho
    FROM reciclaje2.hechos_dinero
    WHERE company_id=p_company_id AND evento_id=p_evento_id;
    IF FOUND THEN
        IF v_hecho.tipo <> p_accion
           OR v_hecho.monto IS DISTINCT FROM (p_datos->>'monto')::numeric
           OR v_hecho.moneda_id IS DISTINCT FROM (p_datos->>'moneda_id')::uuid
           OR (NOT (p_datos ? 'grupo_dinero_id' AND
                    (p_accion='devolucion' OR (p_accion='diferencia' AND NOT (p_datos ? 'tipo_cambio'))))
               AND v_hecho.tipo_cambio IS DISTINCT FROM (p_datos->>'tipo_cambio')::numeric)
           OR v_hecho.operacion_id IS DISTINCT FROM (p_datos->>'operacion_id')::uuid
           OR (p_accion<>'gasto_pendiente' AND v_hecho.finanza_id IS DISTINCT FROM (p_datos->>'finanza_id')::uuid)
           OR v_hecho.tipo_gasto_id IS DISTINCT FROM (p_datos->>'tipo_gasto_id')::uuid
           OR (p_datos ? 'grupo_dinero_id'
               AND v_hecho.grupo_dinero_id IS DISTINCT FROM (p_datos->>'grupo_dinero_id')::uuid)
           OR (p_datos ? 'grupo_transporte_id'
               AND v_hecho.grupo_transporte_id IS DISTINCT FROM (p_datos->>'grupo_transporte_id')::uuid)
           OR v_hecho.monto_aplicado IS DISTINCT FROM (p_datos->>'monto_aplicado')::numeric
           OR (COALESCE((p_datos->>'modelo_version')::smallint,1)=1
               AND v_hecho.monto_pendiente IS DISTINCT FROM (p_datos->>'monto_pendiente')::numeric)
           OR (p_datos ? 'origen_fondos' AND v_hecho.origen_fondos IS DISTINCT FROM p_datos->>'origen_fondos')
           OR (p_datos ? 'modelo_version' AND v_hecho.modelo_version IS DISTINCT FROM (p_datos->>'modelo_version')::smallint)
           OR (p_datos ? 'sentido_diferencia'
               AND v_hecho.sentido_diferencia IS DISTINCT FROM p_datos->>'sentido_diferencia')
           OR (p_accion='liquidacion_operacion'
               AND (p_datos->>'monto_liquidado_ahora')::numeric>0
               AND ((COALESCE(p_datos->>'origen_fondos','caja')='entrega') <> (v_hecho.impacto_caja IS NULL))) THEN
            RAISE EXCEPTION 'evento_id ya fue utilizado con datos diferentes' USING ERRCODE='23505';
        END IF;
        SELECT * INTO v_caja FROM reciclaje2.movimientos_caja
        WHERE company_id=p_company_id AND hecho_dinero_id=v_hecho.id;
        SELECT * INTO v_finanza FROM reciclaje2.finanzas
        WHERE company_id=p_company_id
          AND (id=v_hecho.finanza_id OR hecho_dinero_id=v_hecho.id)
        ORDER BY (hecho_dinero_id=v_hecho.id) DESC
        LIMIT 1;
        RETURN jsonb_build_object('idempotente',true,'hecho',to_jsonb(v_hecho),
                                  'caja',to_jsonb(v_caja),'finanza',to_jsonb(v_finanza),
                                  'monto_aplicado_comercial',CASE WHEN p_accion='liquidacion_operacion' THEN v_hecho.monto-v_hecho.monto_pendiente ELSE NULL END,
                                  'monto_pendiente_comercial',CASE WHEN p_accion='liquidacion_operacion' THEN v_hecho.monto_pendiente ELSE NULL END);
    END IF;

    v_monto := (p_datos->>'monto')::numeric;
    v_moneda_id := (p_datos->>'moneda_id')::uuid;
    v_tipo_cambio := (p_datos->>'tipo_cambio')::numeric;
    v_monto_base := CASE WHEN v_tipo_cambio IS NULL THEN NULL ELSE round(v_monto*v_tipo_cambio,2) END;
    v_tipo_cambio_id := (p_datos->>'tipo_cambio_id')::uuid;
    v_monto_aplicado := (p_datos->>'monto_aplicado')::numeric;
    v_tipo_cambio_aplicacion := (p_datos->>'tipo_cambio_aplicacion')::numeric;
    v_tipo_cambio_aplicacion_id := (p_datos->>'tipo_cambio_aplicacion_id')::uuid;
    v_operacion_id := (p_datos->>'operacion_id')::uuid;
    v_finanza_id := (p_datos->>'finanza_id')::uuid;
    v_tipo_gasto_id := (p_datos->>'tipo_gasto_id')::uuid;
    v_grupo_dinero_id := (p_datos->>'grupo_dinero_id')::uuid;
    v_grupo_transporte_id := (p_datos->>'grupo_transporte_id')::uuid;
    v_responsable_tipo := p_datos->>'responsable_tipo';
    v_sentido_diferencia := p_datos->>'sentido_diferencia';
    v_responsable_id := (p_datos->>'responsable_id')::uuid;
    v_responsable_nombre := p_datos->>'responsable_nombre';
    v_forma_pago_id := (p_datos->>'forma_pago_id')::uuid;
    v_referencia := p_datos->>'referencia';
    v_comprobante_url := p_datos->>'comprobante_url';
    v_observaciones := p_datos->>'observaciones';
    v_monto_liquidado := (p_datos->>'monto_liquidado_ahora')::numeric;
    v_monto_pendiente := (p_datos->>'monto_pendiente')::numeric;
    v_origen_fondos := p_datos->>'origen_fondos';
    v_modelo_version := COALESCE((p_datos->>'modelo_version')::smallint,1);

    IF v_monto IS NULL OR v_monto<=0 OR v_moneda_id IS NULL THEN
        RAISE EXCEPTION 'monto positivo y moneda_id son obligatorios' USING ERRCODE='23514';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM reciclaje2.monedas WHERE id=v_moneda_id) THEN
        RAISE EXCEPTION 'moneda_id no existe' USING ERRCODE='23503';
    END IF;
    IF v_operacion_id IS NOT NULL THEN
        SELECT * INTO v_operacion FROM reciclaje2.operaciones
        WHERE id=v_operacion_id AND company_id=p_company_id;
        IF NOT FOUND THEN RAISE EXCEPTION 'operacion_id no pertenece a company_id' USING ERRCODE='23503'; END IF;
        SELECT codigo INTO v_tipo_operacion_codigo
        FROM reciclaje2.tipos_operacion
        WHERE id=v_operacion.tipo_operacion_id;
        v_grupo_dinero_id := COALESCE(v_grupo_dinero_id,v_operacion.grupo_dinero_id);
        v_grupo_transporte_id := COALESCE(v_grupo_transporte_id,v_operacion.grupo_transporte_id);
        IF p_datos ? 'grupo_dinero_id' AND v_operacion.grupo_dinero_id IS NOT NULL
           AND v_grupo_dinero_id<>v_operacion.grupo_dinero_id THEN
            RAISE EXCEPTION 'grupo_dinero_id contradice la operación' USING ERRCODE='23514';
        END IF;
    END IF;

    IF v_responsable_id IS NOT NULL THEN
        IF v_responsable_tipo='socio' THEN
            SELECT nombre INTO v_responsable_nombre FROM reciclaje2.socios
            WHERE id=v_responsable_id AND company_id=p_company_id;
        ELSIF v_responsable_tipo='transportista' THEN
            SELECT nombre INTO v_responsable_nombre FROM reciclaje2.transportistas
            WHERE id=v_responsable_id AND company_id=p_company_id;
        ELSE
            RAISE EXCEPTION 'responsable_id solo puede validarse para socio o transportista' USING ERRCODE='23514';
        END IF;
        IF NOT FOUND THEN RAISE EXCEPTION 'responsable_id no pertenece a company_id' USING ERRCODE='23503'; END IF;
    END IF;

    IF p_accion IN ('entrega','devolucion','justificacion_operacion')
       AND v_grupo_dinero_id IS NULL THEN
        RAISE EXCEPTION 'grupo_dinero_id es obligatorio para %',p_accion USING ERRCODE='23514';
    END IF;
    IF p_accion='diferencia' AND v_sentido_diferencia NOT IN ('a_cargo_responsable','a_favor_responsable') THEN
      RAISE EXCEPTION 'diferencia requiere sentido_diferencia válido' USING ERRCODE='23514';
    END IF;
    IF p_accion='diferencia' THEN
      v_afecta_posicion_fisica := v_grupo_dinero_id IS NOT NULL AND v_tipo_cambio IS NULL;
    END IF;

    -- Una descarga/corrección ligada a custodia se valúa bajo lock con el
    -- promedio contable de la posición remanente. Una cotización enviada por
    -- el cliente no es autoridad en este contexto.
    IF v_grupo_dinero_id IS NOT NULL
       AND (p_accion='devolucion' OR (p_accion='diferencia' AND v_tipo_cambio IS NULL)) THEN
      PERFORM pg_advisory_xact_lock(hashtextextended(p_company_id::text||':'||v_grupo_dinero_id::text,1));
      SELECT saldo_fisico,valor_base_remanente,tipo_cambio_efectivo
      INTO v_saldo_fisico,v_valor_base_remanente,v_tipo_cambio_efectivo
      FROM reciclaje2.obtener_valuacion_posicion_moneda(p_company_id,v_grupo_dinero_id,v_moneda_id);
      IF p_accion='devolucion' OR v_sentido_diferencia='a_cargo_responsable' THEN
        IF v_saldo_fisico<=0 THEN RAISE EXCEPTION 'no existe saldo físico positivo en la moneda para descargar' USING ERRCODE='23514'; END IF;
        IF v_valor_base_remanente<=0 OR v_tipo_cambio_efectivo IS NULL OR v_tipo_cambio_efectivo<=0 THEN
          RAISE EXCEPTION 'posición física positiva con valuación base incoherente' USING ERRCODE='23514'; END IF;
        IF v_monto>v_saldo_fisico THEN RAISE EXCEPTION 'el hecho excede el saldo físico disponible en su moneda' USING ERRCODE='23514'; END IF;
      ELSE
        IF v_saldo_fisico>=0 THEN RAISE EXCEPTION 'diferencia a favor requiere una posición física negativa' USING ERRCODE='23514'; END IF;
        IF v_valor_base_remanente>=0 OR v_tipo_cambio_efectivo IS NULL OR v_tipo_cambio_efectivo<=0 THEN
          RAISE EXCEPTION 'posición física negativa con valuación base incoherente' USING ERRCODE='23514'; END IF;
        IF v_monto>abs(v_saldo_fisico) THEN RAISE EXCEPTION 'diferencia a favor no puede atravesar el saldo cero' USING ERRCODE='23514'; END IF;
      END IF;
      v_tipo_cambio:=round(v_tipo_cambio_efectivo,6);
      v_monto_base:=CASE WHEN v_monto=abs(v_saldo_fisico) THEN abs(v_valor_base_remanente)
                         ELSE round(v_monto*v_tipo_cambio,2) END;
      IF abs(v_monto_base-round(v_monto*v_tipo_cambio,2))>0.01 THEN
        RAISE EXCEPTION 'la precisión disponible no permite descargar exactamente la valuación remanente' USING ERRCODE='23514'; END IF;
      v_tipo_cambio_id:=NULL;
    ELSE
      IF v_tipo_cambio IS NULL OR v_tipo_cambio<=0 THEN
        RAISE EXCEPTION 'tipo_cambio positivo es obligatorio para un hecho independiente' USING ERRCODE='23514'; END IF;
      v_monto_base:=round(v_monto*v_tipo_cambio,2);
    END IF;
    IF v_tipo_cambio_id IS NOT NULL THEN
      SELECT * INTO v_cotizacion FROM reciclaje2.tipos_cambio
      WHERE id=v_tipo_cambio_id AND company_id=p_company_id AND moneda_id=v_moneda_id;
      IF NOT FOUND OR v_cotizacion.tipo_cambio<>v_tipo_cambio THEN
        RAISE EXCEPTION 'cotización no coincide con empresa, moneda o valor' USING ERRCODE='23503'; END IF;
    END IF;
    IF p_accion='justificacion_operacion' AND v_operacion_id IS NULL THEN
        RAISE EXCEPTION 'operacion_id es obligatorio para una justificación' USING ERRCODE='23514';
    END IF;
    IF p_accion='liquidacion_operacion' THEN
        IF v_operacion_id IS NULL OR v_tipo_operacion_codigo NOT IN ('COMPRA','VENTA') THEN
            RAISE EXCEPTION 'liquidación requiere una operación COMPRA o VENTA de la empresa' USING ERRCODE='23514';
        END IF;
        IF upper(COALESCE(p_datos->>'tipo_operacion',''))<>v_tipo_operacion_codigo THEN
            RAISE EXCEPTION 'tipo_operacion solicitado no coincide con la operación' USING ERRCODE='23514';
        END IF;
        IF v_operacion.socio_id IS NULL THEN
            RAISE EXCEPTION 'liquidación requiere socio en la operación' USING ERRCODE='23514';
        END IF;
        IF v_operacion.monto IS NULL OR v_operacion.moneda_id IS NULL
           OR v_monto<>v_operacion.monto OR v_moneda_id<>v_operacion.moneda_id THEN
            RAISE EXCEPTION 'monto y moneda deben coincidir con la operación' USING ERRCODE='23514';
        END IF;
        IF v_modelo_version=1 THEN
          IF v_monto_liquidado IS NULL OR v_monto_liquidado<0
             OR v_monto_pendiente IS NULL OR v_monto_pendiente<0
             OR v_monto_liquidado+v_monto_pendiente<>v_monto THEN
              RAISE EXCEPTION 'monto_liquidado_ahora + monto_pendiente debe igualar el total' USING ERRCODE='23514';
          END IF;
        ELSIF v_modelo_version=2 THEN
          v_pago_eventos:=COALESCE(p_datos->'pago_evento_ids','[]'::jsonb);
          v_vuelto_eventos:=COALESCE(p_datos->'vuelto_evento_ids','[]'::jsonb);
          IF jsonb_typeof(v_pago_eventos)<>'array' OR jsonb_typeof(v_vuelto_eventos)<>'array' THEN RAISE EXCEPTION 'eventos físicos deben ser arreglos' USING ERRCODE='22023'; END IF;
          SELECT COALESCE(sum(CASE WHEN h.tipo='pago_fisico_operacion' THEN h.monto_base ELSE -h.monto_base END),0)
          INTO v_aplicado_base FROM reciclaje2.hechos_dinero h
          WHERE h.company_id=p_company_id AND h.operacion_id=v_operacion_id
            AND ((h.tipo='pago_fisico_operacion' AND h.evento_id IN(SELECT (value#>>'{}')::uuid FROM jsonb_array_elements(v_pago_eventos)))
              OR (h.tipo='vuelto_recibido' AND h.evento_id IN(SELECT (value#>>'{}')::uuid FROM jsonb_array_elements(v_vuelto_eventos))));
          IF (SELECT count(*) FROM reciclaje2.hechos_dinero h WHERE h.company_id=p_company_id AND h.operacion_id=v_operacion_id
              AND h.tipo='pago_fisico_operacion' AND h.evento_id IN(SELECT (value#>>'{}')::uuid FROM jsonb_array_elements(v_pago_eventos)))<>jsonb_array_length(v_pago_eventos)
             OR (SELECT count(*) FROM reciclaje2.hechos_dinero h WHERE h.company_id=p_company_id AND h.operacion_id=v_operacion_id
              AND h.tipo='vuelto_recibido' AND h.evento_id IN(SELECT (value#>>'{}')::uuid FROM jsonb_array_elements(v_vuelto_eventos)))<>jsonb_array_length(v_vuelto_eventos) THEN
            RAISE EXCEPTION 'liquidación referencia hechos físicos inexistentes o ajenos' USING ERRCODE='23503'; END IF;
          v_monto_liquidado:=round(v_aplicado_base/v_operacion.tipo_cambio,2);
          IF v_aplicado_base<0 OR v_monto_liquidado>v_operacion.monto THEN
            RAISE EXCEPTION 'aplicación física neta inválida o superior al total comercial' USING ERRCODE='23514';
          END IF;
          v_monto_pendiente:=v_operacion.monto-v_monto_liquidado;
        ELSE
          RAISE EXCEPTION 'modelo_version de liquidación no admitido' USING ERRCODE='23514';
        END IF;
        v_responsable_tipo:=COALESCE(NULLIF(v_responsable_tipo,''),'socio');
        IF v_responsable_tipo='socio' THEN
          v_responsable_id:=v_operacion.socio_id;
          SELECT nombre INTO v_responsable_nombre FROM reciclaje2.socios
          WHERE id=v_responsable_id AND company_id=p_company_id;
          IF NOT FOUND THEN RAISE EXCEPTION 'socio de operación no pertenece a company_id' USING ERRCODE='23503'; END IF;
        ELSIF v_responsable_tipo='transportista' THEN
          IF v_responsable_id IS NULL THEN RAISE EXCEPTION 'responsable transportista requiere responsable_id' USING ERRCODE='23514'; END IF;
          SELECT nombre INTO v_responsable_nombre FROM reciclaje2.transportistas
          WHERE id=v_responsable_id AND company_id=p_company_id;
          IF NOT FOUND THEN RAISE EXCEPTION 'transportista responsable no pertenece a company_id' USING ERRCODE='23503'; END IF;
        ELSIF v_responsable_tipo='otro' THEN
          v_responsable_id:=NULL;
          IF btrim(COALESCE(v_responsable_nombre,''))='' THEN RAISE EXCEPTION 'otro responsable requiere responsable_nombre' USING ERRCODE='23514'; END IF;
        ELSE
          RAISE EXCEPTION 'responsable_tipo de pendiente no admitido' USING ERRCODE='23514';
        END IF;
    END IF;
    IF p_accion IN ('pago_fisico_operacion','vuelto_recibido') THEN
      IF v_operacion_id IS NULL OR v_tipo_operacion_codigo NOT IN('COMPRA','VENTA')
         OR (p_accion='vuelto_recibido' AND v_tipo_operacion_codigo<>'COMPRA') THEN
        RAISE EXCEPTION '% no es compatible con el tipo de operación',p_accion USING ERRCODE='23514';
      END IF;
      IF p_accion='pago_fisico_operacion' THEN
        v_origen_fondos:=COALESCE(v_origen_fondos,'entrega');
        IF v_origen_fondos NOT IN('entrega','caja') THEN RAISE EXCEPTION 'origen_fondos no admitido' USING ERRCODE='23514'; END IF;
        IF v_origen_fondos='entrega' AND (v_grupo_dinero_id IS NULL OR v_grupo_transporte_id IS NULL) THEN
          RAISE EXCEPTION 'pago_fisico_operacion con fondos entregados requiere grupos de dinero y transporte' USING ERRCODE='23514';
        END IF;
        IF v_origen_fondos='caja' AND ((v_grupo_dinero_id IS NULL)<>(v_grupo_transporte_id IS NULL)) THEN
          RAISE EXCEPTION 'el contexto de Caja debe informar ambos grupos o ninguno' USING ERRCODE='23514';
        END IF;
        IF v_origen_fondos='caja' AND v_grupo_dinero_id IS NULL THEN
          IF v_tipo_operacion_codigo<>'COMPRA' OR v_operacion.eliminada
             OR NOT EXISTS(SELECT 1 FROM reciclaje2.etapas_operacion e
                           WHERE e.id=v_operacion.etapa_operacion_id AND e.codigo='PRECARGA')
             OR EXISTS(SELECT 1 FROM reciclaje2.salida_operaciones so
                       WHERE so.company_id=p_company_id AND so.operacion_id=v_operacion_id AND so.estado='activa') THEN
            RAISE EXCEPTION 'pago directo desde Caja requiere una COMPRA activa en PRECARGA y sin salida' USING ERRCODE='23514';
          END IF;
        END IF;
        IF v_tipo_operacion_codigo='VENTA' AND v_origen_fondos<>'caja' THEN RAISE EXCEPTION 'cobro físico de VENTA debe ingresar a Caja' USING ERRCODE='23514'; END IF;
      ELSE
        IF v_grupo_dinero_id IS NULL OR v_grupo_transporte_id IS NULL THEN
          RAISE EXCEPTION 'vuelto_recibido requiere grupos de dinero y transporte' USING ERRCODE='23514';
        END IF;
        v_origen_fondos:='entrega';
        IF v_responsable_id IS NULL THEN v_responsable_tipo:='transportista'; v_responsable_id:=v_operacion.transportista_id; END IF;
        IF v_responsable_id IS NULL THEN RAISE EXCEPTION 'vuelto requiere transportista responsable' USING ERRCODE='23514'; END IF;
        SELECT nombre INTO v_responsable_nombre FROM reciclaje2.transportistas
        WHERE id=v_responsable_id AND company_id=p_company_id;
        IF NOT FOUND THEN RAISE EXCEPTION 'transportista responsable no pertenece a company_id' USING ERRCODE='23503'; END IF;
      END IF;
      v_modelo_version:=2;
    END IF;
    IF p_accion IN ('gasto','gasto_pendiente') THEN
        IF v_tipo_gasto_id IS NULL OR NOT EXISTS (SELECT 1 FROM reciclaje2.tipos_gasto WHERE id=v_tipo_gasto_id) THEN
            RAISE EXCEPTION 'tipo_gasto_id válido es obligatorio para un gasto' USING ERRCODE='23503';
        END IF;
    ELSIF v_tipo_gasto_id IS NOT NULL THEN
        RAISE EXCEPTION 'tipo_gasto_id solo corresponde a gastos' USING ERRCODE='23514';
    END IF;

    -- Bloqueo lógico de la rendición y control de fondos disponibles en ARS.
    IF v_grupo_dinero_id IS NOT NULL THEN
        PERFORM pg_advisory_xact_lock(hashtextextended(p_company_id::text||':'||v_grupo_dinero_id::text,1));
        SELECT COALESCE(sum(monto_base) FILTER (WHERE tipo='entrega'),0)
             - COALESCE(sum(monto_base) FILTER (WHERE tipo IN ('justificacion_operacion','gasto') AND impacto_caja IS NULL),0)
             - COALESCE(sum(monto_base) FILTER (WHERE tipo='devolucion'),0)
        INTO v_disponible_base
        FROM reciclaje2.hechos_dinero
        WHERE company_id=p_company_id AND grupo_dinero_id=v_grupo_dinero_id;
        IF p_accion='justificacion_operacion'
           OR (p_accion='gasto' AND COALESCE(p_datos->>'origen_fondos','entrega')='entrega') THEN
            IF v_monto_base>v_disponible_base THEN
                RAISE EXCEPTION 'el hecho excede el dinero disponible en la rendición' USING ERRCODE='23514';
            END IF;
        END IF;
    END IF;

    -- V2: la custodia física se controla por moneda; equivalencias ARS de otras
    -- monedas no habilitan una compensación silenciosa.
    IF v_grupo_dinero_id IS NOT NULL
       AND ((p_accion='pago_fisico_operacion' AND v_origen_fondos='entrega')
            OR (p_accion='gasto' AND COALESCE(v_origen_fondos,'entrega')='entrega')) THEN
      SELECT COALESCE(sum(CASE
        WHEN tipo='entrega' THEN monto
        WHEN tipo='vuelto_recibido' THEN monto
        WHEN tipo='pago_fisico_operacion' AND origen_fondos='entrega' THEN -monto
        WHEN tipo='gasto' AND COALESCE(origen_fondos,'entrega')='entrega' THEN -monto
        WHEN tipo='devolucion' THEN -monto
        WHEN tipo='justificacion_operacion' THEN -monto
        WHEN tipo='liquidacion_operacion' AND modelo_version=1 AND impacto_caja IS NULL
          THEN -(monto-monto_pendiente)
        ELSE 0 END),0)
      INTO v_disponible_base
      FROM reciclaje2.hechos_dinero
      WHERE company_id=p_company_id AND grupo_dinero_id=v_grupo_dinero_id AND moneda_id=v_moneda_id;
      IF v_monto>v_disponible_base THEN
        RAISE EXCEPTION 'el hecho excede los fondos físicos disponibles en su moneda' USING ERRCODE='23514';
      END IF;
    END IF;

    CASE p_accion
      WHEN 'entrega' THEN v_impacto_caja:='salida'; v_concepto:='Entrega de dinero a '||COALESCE(v_responsable_nombre,'responsable');
      WHEN 'devolucion' THEN v_impacto_caja:='entrada'; v_concepto:='Devolución de dinero de '||COALESCE(v_responsable_nombre,'responsable');
      WHEN 'justificacion_operacion' THEN v_impacto_caja:=NULL; v_concepto:='Justificación de dinero mediante operación';
      WHEN 'gasto' THEN
        IF COALESCE(p_datos->>'origen_fondos','entrega') NOT IN ('entrega','caja','responsable') THEN
          RAISE EXCEPTION 'origen_fondos de gasto no admitido' USING ERRCODE='23514'; END IF;
        v_origen_fondos:=COALESCE(v_origen_fondos,'entrega');
        IF v_origen_fondos='caja' THEN v_impacto_caja:='salida'; ELSE v_impacto_caja:=NULL; END IF;
        v_concepto:='Gasto '||(SELECT nombre FROM reciclaje2.tipos_gasto WHERE id=v_tipo_gasto_id);
      WHEN 'gasto_pendiente' THEN
        v_impacto_caja:=NULL;
        v_origen_fondos:=NULL;
        v_concepto:='Gasto '||(SELECT nombre FROM reciclaje2.tipos_gasto WHERE id=v_tipo_gasto_id);
        IF v_responsable_id IS NULL THEN
          IF btrim(COALESCE(v_responsable_nombre,''))='' THEN
            RAISE EXCEPTION 'Indicá a quién le debemos' USING ERRCODE='23514';
          END IF;
          v_responsable_tipo:='otro';
        ELSIF v_responsable_tipo<>'socio' THEN
          RAISE EXCEPTION 'el cliente de un gasto pendiente debe ser un socio de la empresa' USING ERRCODE='23514';
        END IF;
      WHEN 'pago_fisico_operacion' THEN
        v_impacto_caja:=CASE WHEN v_origen_fondos='caja' AND v_tipo_operacion_codigo='COMPRA' THEN 'salida' WHEN v_origen_fondos='caja' THEN 'entrada' ELSE NULL END;
        v_concepto:='Pago físico de operación';
      WHEN 'vuelto_recibido' THEN
        v_impacto_caja:=NULL;
        v_concepto:='Vuelto recibido del proveedor por el transportista';
      WHEN 'cobro' THEN v_impacto_caja:='entrada'; v_concepto:='Cobro de cuenta por cobrar';
      WHEN 'pago' THEN v_impacto_caja:='salida'; v_concepto:='Pago de cuenta por pagar';
      WHEN 'liquidacion_operacion' THEN
        IF v_modelo_version=2 THEN
          v_impacto_caja:=NULL;
          v_origen_fondos:=NULL;
        ELSE
        v_impacto_caja:=CASE
          WHEN v_monto_liquidado=0 THEN NULL
          WHEN COALESCE(p_datos->>'origen_fondos','caja')='entrega' THEN NULL
          WHEN v_tipo_operacion_codigo='COMPRA' THEN 'salida'
          ELSE 'entrada'
        END;
        v_origen_fondos:=COALESCE(p_datos->>'origen_fondos','caja');
        IF v_origen_fondos='entrega' THEN
          IF v_tipo_operacion_codigo<>'COMPRA' OR v_grupo_dinero_id IS NULL THEN
            RAISE EXCEPTION 'fondos entregados solo pueden justificar una COMPRA con grupo_dinero_id' USING ERRCODE='23514';
          END IF;
          PERFORM pg_advisory_xact_lock(hashtextextended(p_company_id::text||':'||v_grupo_dinero_id::text,1));
          SELECT COALESCE(sum(monto_base) FILTER (WHERE tipo='entrega'),0)
               - COALESCE(sum(monto_base) FILTER (WHERE tipo IN ('justificacion_operacion','gasto') AND impacto_caja IS NULL),0)
               - COALESCE(sum(round((monto-monto_pendiente)*tipo_cambio,2))
                          FILTER (WHERE tipo='liquidacion_operacion' AND impacto_caja IS NULL),0)
               - COALESCE(sum(monto_base) FILTER (WHERE tipo='devolucion'),0)
          INTO v_disponible_base
          FROM reciclaje2.hechos_dinero
          WHERE company_id=p_company_id AND grupo_dinero_id=v_grupo_dinero_id;
          IF round(v_monto_liquidado*v_tipo_cambio,2)>v_disponible_base THEN
            RAISE EXCEPTION 'la compra excede los fondos entregados disponibles' USING ERRCODE='23514';
          END IF;
        ELSIF v_origen_fondos<>'caja' THEN
          RAISE EXCEPTION 'origen_fondos no admitido' USING ERRCODE='23514';
        END IF;
        END IF;
        v_concepto:=CASE WHEN v_tipo_operacion_codigo='COMPRA'
          THEN 'Liquidación de compra' ELSE 'Liquidación de venta' END;
      WHEN 'diferencia' THEN
        v_impacto_caja:=NULL; v_concepto:='Diferencia pendiente en rendición';
        IF v_grupo_dinero_id IS NULL OR btrim(COALESCE(v_observaciones,''))='' THEN
          RAISE EXCEPTION 'diferencia requiere grupo_dinero_id y observaciones' USING ERRCODE='23514'; END IF;
        IF v_sentido_diferencia IS NOT NULL
           AND v_sentido_diferencia NOT IN ('a_cargo_responsable','a_favor_responsable') THEN
          RAISE EXCEPTION 'sentido_diferencia no admitido' USING ERRCODE='23514'; END IF;
      WHEN 'ajuste' THEN
        v_impacto_caja:=NULLIF(p_datos->>'impacto_caja',''); v_concepto:='Ajuste de dinero';
        IF v_impacto_caja IS NOT NULL AND v_impacto_caja NOT IN ('entrada','salida') THEN
          RAISE EXCEPTION 'impacto_caja de ajuste no admitido' USING ERRCODE='23514'; END IF;
        IF btrim(COALESCE(v_observaciones,''))='' THEN RAISE EXCEPTION 'ajuste requiere observaciones' USING ERRCODE='23514'; END IF;
    END CASE;

    IF p_accion IN ('cobro','pago') THEN
        SELECT * INTO v_finanza FROM reciclaje2.finanzas
        WHERE id=v_finanza_id AND company_id=p_company_id FOR UPDATE;
        IF NOT FOUND THEN RAISE EXCEPTION 'finanza_id no pertenece a company_id' USING ERRCODE='23503'; END IF;
        IF v_finanza.operacion_id IS NOT NULL
           AND NOT EXISTS (SELECT 1 FROM reciclaje2.operaciones
                           WHERE id=v_finanza.operacion_id AND company_id=p_company_id) THEN
            RAISE EXCEPTION 'la operación de la finanza no pertenece a company_id' USING ERRCODE='23503';
        END IF;
        v_operacion_id:=COALESCE(v_operacion_id,v_finanza.operacion_id);
        v_grupo_dinero_id:=COALESCE(v_grupo_dinero_id,v_finanza.grupo_dinero_id);
        v_grupo_transporte_id:=COALESCE(v_grupo_transporte_id,v_finanza.grupo_transporte_id);
        v_responsable_tipo:=COALESCE(v_responsable_tipo,v_finanza.responsable_tipo);
        v_responsable_id:=COALESCE(v_responsable_id,v_finanza.responsable_id);
        v_responsable_nombre:=COALESCE(v_responsable_nombre,v_finanza.responsable_nombre);
        IF (p_accion='cobro' AND v_finanza.tipo<>'por_cobrar')
           OR (p_accion='pago' AND v_finanza.tipo<>'por_pagar') THEN
            RAISE EXCEPTION 'acción incompatible con el tipo de finanza' USING ERRCODE='23514';
        END IF;
        IF v_monto_aplicado IS NULL OR v_monto_aplicado<=0 THEN
            RAISE EXCEPTION 'monto_aplicado positivo es obligatorio' USING ERRCODE='23514';
        END IF;
        IF v_moneda_id=v_finanza.moneda_id THEN
            IF v_monto_aplicado<>v_monto THEN RAISE EXCEPTION 'misma moneda exige monto_aplicado=monto' USING ERRCODE='23514'; END IF;
            v_tipo_cambio_aplicacion:=v_tipo_cambio;
        ELSE
            IF v_tipo_cambio_aplicacion IS NULL OR v_tipo_cambio_aplicacion<=0
               OR abs(v_monto_base-round(v_monto_aplicado*v_tipo_cambio_aplicacion,2))>0.01 THEN
                RAISE EXCEPTION 'aplicación multimoneda sin cotización coherente' USING ERRCODE='23514';
            END IF;
            IF v_tipo_cambio_aplicacion_id IS NOT NULL THEN
                SELECT * INTO v_cotizacion_aplicacion FROM reciclaje2.tipos_cambio
                WHERE id=v_tipo_cambio_aplicacion_id AND company_id=p_company_id
                  AND moneda_id=v_finanza.moneda_id AND tipo_cambio=v_tipo_cambio_aplicacion;
                IF NOT FOUND THEN RAISE EXCEPTION 'cotización de aplicación inválida' USING ERRCODE='23503'; END IF;
            END IF;
        END IF;
        SELECT COALESCE(sum(monto_aplicado),0) INTO v_aplicado
        FROM reciclaje2.hechos_dinero WHERE company_id=p_company_id AND finanza_id=v_finanza.id
          AND tipo=CASE WHEN v_finanza.tipo='por_cobrar' THEN 'cobro' ELSE 'pago' END;
        v_saldo:=v_finanza.monto_original-v_aplicado;
        IF v_monto_aplicado>v_saldo THEN RAISE EXCEPTION 'monto_aplicado excede saldo pendiente' USING ERRCODE='23514'; END IF;
    END IF;

    IF p_accion='gasto_pendiente' THEN
      v_finanza:=reciclaje2.upsert_finanza(NULL,p_company_id,NULL,'por_pagar',v_responsable_tipo,
        v_responsable_nombre,v_concepto,v_monto,v_moneda_id,v_tipo_cambio,now(),NULL,'pendiente',v_observaciones);
      UPDATE reciclaje2.finanzas
      SET evento_id=p_evento_id,responsable_id=v_responsable_id,updated_at=now()
      WHERE company_id=p_company_id AND id=v_finanza.id
      RETURNING * INTO v_finanza;
      v_finanza_id:=v_finanza.id;
    END IF;

    INSERT INTO reciclaje2.hechos_dinero(company_id,evento_id,tipo,operacion_id,grupo_transporte_id,
      grupo_dinero_id,finanza_id,tipo_gasto_id,monto,moneda_id,tipo_cambio,monto_base,tipo_cambio_id,
      monto_aplicado,monto_pendiente,tipo_cambio_aplicacion,tipo_cambio_aplicacion_id,impacto_caja,responsable_tipo,
      responsable_id,responsable_nombre,sentido_diferencia,concepto,observaciones,origen_fondos,modelo_version,
      afecta_posicion_fisica)
    VALUES(p_company_id,p_evento_id,p_accion,v_operacion_id,v_grupo_transporte_id,v_grupo_dinero_id,
      v_finanza_id,v_tipo_gasto_id,v_monto,v_moneda_id,v_tipo_cambio,v_monto_base,v_tipo_cambio_id,
      v_monto_aplicado,v_monto_pendiente,v_tipo_cambio_aplicacion,v_tipo_cambio_aplicacion_id,v_impacto_caja,
      v_responsable_tipo,v_responsable_id,v_responsable_nombre,v_sentido_diferencia,v_concepto,v_observaciones,
      v_origen_fondos,v_modelo_version,v_afecta_posicion_fisica)
    RETURNING * INTO v_hecho;

    IF p_accion='gasto_pendiente' THEN
      UPDATE reciclaje2.finanzas
      SET hecho_dinero_id=v_hecho.id,updated_at=now()
      WHERE company_id=p_company_id AND id=v_finanza_id
      RETURNING * INTO v_finanza;
    END IF;

    IF p_accion='liquidacion_operacion' AND v_monto_pendiente>0 THEN
        v_finanza_tipo:=CASE WHEN v_tipo_operacion_codigo='COMPRA' THEN 'por_pagar' ELSE 'por_cobrar' END;
        v_finanza:=reciclaje2.upsert_finanza(
          NULL,p_company_id,v_operacion_id,v_finanza_tipo,v_responsable_tipo,v_responsable_nombre,
          CASE WHEN v_tipo_operacion_codigo='COMPRA' THEN 'Saldo pendiente de compra' ELSE 'Saldo pendiente de venta' END,
          v_monto_pendiente,v_moneda_id,v_tipo_cambio,now(),NULL,'pendiente',
          'Cuenta originada por liquidación comercial');
        UPDATE reciclaje2.finanzas
        SET evento_id=p_evento_id,
            hecho_dinero_id=v_hecho.id,
            grupo_dinero_id=v_grupo_dinero_id,
            grupo_transporte_id=v_grupo_transporte_id,
            responsable_id=v_responsable_id
        WHERE id=v_finanza.id AND company_id=p_company_id
        RETURNING * INTO v_finanza;
    END IF;

    IF v_impacto_caja IS NOT NULL THEN
        v_tipo_caja:=v_impacto_caja;
        v_monto_caja:=CASE WHEN p_accion='liquidacion_operacion' THEN v_monto_liquidado ELSE v_monto END;
        v_caja:=reciclaje2.upsert_movimiento_caja(NULL,p_company_id,v_operacion_id,v_finanza_id,
          v_tipo_caja,v_monto_caja,v_moneda_id,v_tipo_cambio,round(v_monto_caja*v_tipo_cambio,2),v_forma_pago_id,v_referencia,
          v_concepto,v_responsable_tipo,v_responsable_id,v_responsable_nombre,v_comprobante_url,
          v_observaciones,NULL);
        UPDATE reciclaje2.movimientos_caja SET evento_id=p_evento_id,hecho_dinero_id=v_hecho.id,
          grupo_dinero_id=v_grupo_dinero_id,grupo_transporte_id=v_grupo_transporte_id
        WHERE id=v_caja.id AND company_id=p_company_id RETURNING * INTO v_caja;
    END IF;

    IF p_accion IN ('cobro','pago') THEN
        v_aplicado:=v_aplicado+v_monto_aplicado;
        v_estado:=CASE WHEN v_aplicado=v_finanza.monto_original THEN 'saldada' ELSE 'parcial' END;
        v_finanza:=reciclaje2.upsert_finanza(v_finanza.id,p_company_id,v_finanza.operacion_id,
          v_finanza.tipo,v_finanza.responsable_tipo,v_finanza.responsable_nombre,v_finanza.concepto,
          v_finanza.monto_original,v_finanza.moneda_id,v_finanza.tipo_cambio,v_finanza.fecha_emision,
          v_finanza.fecha_vencimiento,v_estado,v_finanza.observaciones);
    END IF;

    RETURN jsonb_build_object('idempotente',false,'hecho',to_jsonb(v_hecho),
                              'caja',to_jsonb(v_caja),'finanza',to_jsonb(v_finanza),
                              'monto_aplicado_comercial',CASE WHEN p_accion='liquidacion_operacion' THEN v_monto_liquidado ELSE NULL END,
                              'monto_pendiente_comercial',CASE WHEN p_accion='liquidacion_operacion' THEN v_monto_pendiente ELSE NULL END);
END;
$$;


--
-- Name: FUNCTION orquestar_dinero(p_company_id uuid, p_evento_id uuid, p_accion character varying, p_datos jsonb); Type: COMMENT; Schema: reciclaje2; Owner: -
--

COMMENT ON FUNCTION reciclaje2.orquestar_dinero(p_company_id uuid, p_evento_id uuid, p_accion character varying, p_datos jsonb) IS 'Registra atómicamente un hecho económico y sus consecuencias reales en Caja o Finanzas.';


--
-- Name: orquestar_finanzas(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: reciclaje2; Owner: -
--

CREATE FUNCTION reciclaje2.orquestar_finanzas(p_company_id uuid, p_evento_id uuid, p_accion text, p_datos jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'reciclaje2'
    AS $$
DECLARE e reciclaje2.eventos_operacion%ROWTYPE; f reciclaje2.finanzas%ROWTYPE; item jsonb; r jsonb; fid uuid; total numeric(14,2):=0; v_tipo_finanza text; rn text;
BEGIN
 IF p_company_id IS NULL OR p_evento_id IS NULL OR p_datos IS NULL OR jsonb_typeof(p_datos)<>'object' THEN RAISE EXCEPTION 'parámetros obligatorios inválidos' USING ERRCODE='22023'; END IF;
 IF p_accion NOT IN('crear_obligacion','definir_plan_pago','modificar_plan_pago','anular_obligacion') THEN RAISE EXCEPTION 'acción financiera no admitida' USING ERRCODE='22023'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_company_id::text||':'||p_evento_id::text,20));
 SELECT ev.* INTO e FROM reciclaje2.eventos_operacion AS ev WHERE ev.company_id=p_company_id AND ev.evento_id=p_evento_id;
 IF FOUND THEN IF e.accion<>p_accion OR e.datos<>p_datos THEN RAISE EXCEPTION 'evento reutilizado con datos diferentes' USING ERRCODE='23505'; END IF; RETURN e.resultado; END IF;
 INSERT INTO reciclaje2.eventos_operacion(company_id,evento_id,accion,datos) VALUES(p_company_id,p_evento_id,p_accion,p_datos) RETURNING * INTO e;
 IF p_accion='crear_obligacion' THEN
  v_tipo_finanza:=CASE upper(p_datos->>'tipo') WHEN 'CXP' THEN 'por_pagar' WHEN 'CXC' THEN 'por_cobrar' ELSE p_datos->>'tipo' END;
  IF p_datos->>'responsable_tipo'='socio' AND (p_datos->>'responsable_id')::uuid IS NOT NULL THEN
   SELECT s.nombre INTO rn FROM reciclaje2.socios AS s WHERE s.company_id=p_company_id AND s.id=(p_datos->>'responsable_id')::uuid;
   IF NOT FOUND THEN RAISE EXCEPTION 'socio no pertenece a company_id' USING ERRCODE='23503'; END IF;
  ELSIF p_datos->>'responsable_tipo'='transportista' AND (p_datos->>'responsable_id')::uuid IS NOT NULL THEN
   SELECT t.nombre INTO rn FROM reciclaje2.transportistas AS t WHERE t.company_id=p_company_id AND t.id=(p_datos->>'responsable_id')::uuid;
   IF NOT FOUND THEN RAISE EXCEPTION 'transportista no pertenece a company_id' USING ERRCODE='23503'; END IF;
  ELSE
   IF (p_datos->>'responsable_id')::uuid IS NOT NULL THEN RAISE EXCEPTION 'responsable_id requiere responsable_tipo socio o transportista' USING ERRCODE='23514'; END IF;
   rn:=p_datos->>'responsable_nombre';
  END IF;
  IF (p_datos->>'operacion_id')::uuid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM reciclaje2.operaciones AS o WHERE o.company_id=p_company_id AND o.id=(p_datos->>'operacion_id')::uuid) THEN RAISE EXCEPTION 'operación no pertenece a company_id' USING ERRCODE='23503'; END IF;
  f:=reciclaje2.upsert_finanza(NULL,p_company_id,(p_datos->>'operacion_id')::uuid,v_tipo_finanza,p_datos->>'responsable_tipo',rn,p_datos->>'concepto',(p_datos->>'monto_original')::numeric,(p_datos->>'moneda_id')::uuid,(p_datos->>'tipo_cambio')::numeric,COALESCE((p_datos->>'fecha_emision')::timestamptz,now()),NULL,'pendiente',p_datos->>'observaciones');
  UPDATE reciclaje2.finanzas AS fn SET responsable_id=(p_datos->>'responsable_id')::uuid WHERE fn.company_id=p_company_id AND fn.id=f.id RETURNING fn.* INTO f; fid:=f.id;
 ELSE fid:=(p_datos->>'finanza_id')::uuid; SELECT fn.* INTO f FROM reciclaje2.finanzas AS fn WHERE fn.company_id=p_company_id AND fn.id=fid FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'finanza no pertenece a company_id' USING ERRCODE='23503'; END IF; END IF;
 IF p_accion IN('definir_plan_pago','modificar_plan_pago') OR (p_accion='crear_obligacion' AND p_datos?'vencimientos') THEN
  IF f.estado='anulada' OR EXISTS(SELECT 1 FROM reciclaje2.hechos_dinero AS h WHERE h.company_id=p_company_id AND h.finanza_id=f.id AND h.tipo IN('pago','cobro')) THEN RAISE EXCEPTION 'plan no modificable después de movimientos reales o anulación' USING ERRCODE='23514'; END IF;
  IF jsonb_typeof(p_datos->'vencimientos')<>'array' OR jsonb_array_length(p_datos->'vencimientos')=0 THEN RAISE EXCEPTION 'vencimientos no puede ser vacío' USING ERRCODE='23514'; END IF;
  IF p_accion='definir_plan_pago' AND EXISTS(SELECT 1 FROM reciclaje2.finanza_vencimientos AS v WHERE v.company_id=p_company_id AND v.finanza_id=f.id) THEN RAISE EXCEPTION 'plan ya definido' USING ERRCODE='23505'; END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(p_datos->'vencimientos') LOOP total:=total+(item->>'monto_programado')::numeric; IF (item->>'monto_programado')::numeric<=0 OR (item->>'fecha_vencimiento')::timestamptz IS NULL THEN RAISE EXCEPTION 'vencimiento inválido' USING ERRCODE='23514'; END IF; END LOOP;
  IF total<>f.monto_original THEN RAISE EXCEPTION 'suma del plan debe igualar monto_original' USING ERRCODE='23514'; END IF;
  DELETE FROM reciclaje2.finanza_vencimientos AS v WHERE v.company_id=p_company_id AND v.finanza_id=f.id;
  FOR item IN SELECT value FROM jsonb_array_elements(p_datos->'vencimientos') LOOP INSERT INTO reciclaje2.finanza_vencimientos(company_id,finanza_id,numero,fecha_vencimiento,monto_programado) VALUES(p_company_id,f.id,(item->>'numero')::integer,(item->>'fecha_vencimiento')::timestamptz,(item->>'monto_programado')::numeric); END LOOP;
 ELSIF p_accion='anular_obligacion' THEN
  IF f.estado='anulada' THEN RAISE EXCEPTION 'obligación ya anulada' USING ERRCODE='23514'; END IF;
  IF EXISTS(SELECT 1 FROM reciclaje2.hechos_dinero AS h WHERE h.company_id=p_company_id AND h.finanza_id=f.id AND h.tipo IN('pago','cobro')) THEN RAISE EXCEPTION 'obligación con movimientos reales no puede anularse' USING ERRCODE='23514'; END IF;
  UPDATE reciclaje2.finanzas AS fn SET estado='anulada',updated_at=now() WHERE fn.company_id=p_company_id AND fn.id=f.id RETURNING fn.* INTO f;
 END IF;
 r:=reciclaje2.obtener_estado_finanza(p_company_id,f.id); UPDATE reciclaje2.eventos_operacion AS ev SET resultado=r,completed_at=now() WHERE ev.company_id=p_company_id AND ev.id=e.id; RETURN r;
END;$$;


--
-- Name: FUNCTION orquestar_finanzas(p_company_id uuid, p_evento_id uuid, p_accion text, p_datos jsonb); Type: COMMENT; Schema: reciclaje2; Owner: -
--

COMMENT ON FUNCTION reciclaje2.orquestar_finanzas(p_company_id uuid, p_evento_id uuid, p_accion text, p_datos jsonb) IS 'Administra obligaciones y planes; delega todo movimiento real de dinero a orquestar_dinero.';


--
-- Name: orquestar_inventario(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: reciclaje2; Owner: -
--

CREATE FUNCTION reciclaje2.orquestar_inventario(p_company_id uuid, p_evento_id uuid, p_accion text, p_datos jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'reciclaje2'
    AS $$
DECLARE
    v_evento reciclaje2.eventos_operacion%ROWTYPE;
    v_movimiento reciclaje2.movimientos_stock%ROWTYPE;
    v_item jsonb;
    v_resultado jsonb;
    v_movimientos jsonb := '[]'::jsonb;
    v_grupo_id uuid;
    v_deposito_id uuid;
    v_origen_id uuid;
    v_destino_id uuid;
    v_material_id uuid;
    v_cantidad numeric(14,3);
    v_saldo numeric(14,3);
    v_lock record;
BEGIN
    IF p_company_id IS NULL OR p_evento_id IS NULL THEN
        RAISE EXCEPTION 'company_id y evento_id son obligatorios' USING ERRCODE='22004';
    END IF;
    IF p_datos IS NULL OR jsonb_typeof(p_datos)<>'object' THEN
        RAISE EXCEPTION 'datos debe ser un objeto JSON' USING ERRCODE='22023';
    END IF;
    IF p_accion NOT IN ('transferencia','ajuste','transformacion') THEN
        RAISE EXCEPTION 'acción de inventario no admitida: %',p_accion USING ERRCODE='22023';
    END IF;

    -- Serializa reintentos concurrentes del mismo evento y comparte el espacio
    -- idempotente existente con el Orquestador de Operaciones.
    PERFORM pg_advisory_xact_lock(hashtextextended(p_company_id::text||':'||p_evento_id::text,20));
    SELECT * INTO v_evento
    FROM reciclaje2.eventos_operacion
    WHERE company_id=p_company_id AND evento_id=p_evento_id;
    IF FOUND THEN
        IF v_evento.accion<>p_accion OR v_evento.datos<>p_datos THEN
            RAISE EXCEPTION 'evento_id ya utilizado con acción o datos diferentes' USING ERRCODE='23505';
        END IF;
        RETURN v_evento.resultado;
    END IF;

    INSERT INTO reciclaje2.eventos_operacion(company_id,evento_id,accion,operacion_id,datos)
    VALUES(p_company_id,p_evento_id,p_accion,NULL,p_datos)
    RETURNING * INTO v_evento;

    v_grupo_id:=COALESCE((p_datos->>'movimiento_grupo_id')::uuid,gen_random_uuid());
    IF EXISTS(SELECT 1 FROM reciclaje2.movimientos_stock WHERE movimiento_grupo_id=v_grupo_id) THEN
        IF EXISTS(SELECT 1 FROM reciclaje2.movimientos_stock
                  WHERE movimiento_grupo_id=v_grupo_id AND company_id<>p_company_id) THEN
            RAISE EXCEPTION 'movimiento_grupo_id pertenece a otra empresa' USING ERRCODE='23503';
        END IF;
        RAISE EXCEPTION 'movimiento_grupo_id ya fue utilizado por otro hecho físico' USING ERRCODE='23505';
    END IF;

    IF p_accion='transferencia' THEN
        v_origen_id:=(p_datos->>'deposito_origen_id')::uuid;
        v_destino_id:=(p_datos->>'deposito_destino_id')::uuid;
        v_material_id:=(p_datos->>'material_id')::uuid;
        v_cantidad:=(p_datos->>'cantidad')::numeric;

        IF v_cantidad IS NULL OR v_cantidad<=0 THEN
            RAISE EXCEPTION 'cantidad de transferencia debe ser mayor que cero' USING ERRCODE='23514';
        END IF;
        IF v_origen_id IS NULL OR v_destino_id IS NULL OR v_origen_id=v_destino_id THEN
            RAISE EXCEPTION 'origen y destino distintos son obligatorios' USING ERRCODE='23514';
        END IF;
        IF NOT EXISTS(SELECT 1 FROM reciclaje2.depositos WHERE id=v_origen_id AND company_id=p_company_id)
           OR NOT EXISTS(SELECT 1 FROM reciclaje2.depositos WHERE id=v_destino_id AND company_id=p_company_id) THEN
            RAISE EXCEPTION 'depósito de transferencia no pertenece a company_id' USING ERRCODE='23503';
        END IF;
        IF NOT EXISTS(SELECT 1 FROM reciclaje2.materiales WHERE id=v_material_id AND company_id=p_company_id) THEN
            RAISE EXCEPTION 'material no pertenece a company_id' USING ERRCODE='23503';
        END IF;

        -- Orden estable: evita deadlocks entre transferencias opuestas.
        FOR v_lock IN
            SELECT d FROM (VALUES(v_origen_id),(v_destino_id)) x(d) ORDER BY d
        LOOP
            PERFORM pg_advisory_xact_lock(hashtextextended(p_company_id::text||':'||v_lock.d::text||':'||v_material_id::text,21));
        END LOOP;
        SELECT COALESCE(sum(cantidad),0) INTO v_saldo FROM reciclaje2.movimientos_stock
        WHERE company_id=p_company_id AND deposito_id=v_origen_id AND material_id=v_material_id;
        IF v_saldo<v_cantidad THEN
            RAISE EXCEPTION 'stock insuficiente en depósito origen' USING ERRCODE='23514';
        END IF;

        v_movimiento:=reciclaje2.upsert_movimiento_stock(NULL,p_company_id,NULL,NULL,v_origen_id,v_material_id,'traslado',-v_cantidad,v_grupo_id);
        UPDATE reciclaje2.movimientos_stock SET evento_operacion_id=v_evento.id
        WHERE id=v_movimiento.id AND company_id=p_company_id RETURNING * INTO v_movimiento;
        v_movimientos:=v_movimientos||jsonb_build_array(to_jsonb(v_movimiento));

        v_movimiento:=reciclaje2.upsert_movimiento_stock(NULL,p_company_id,NULL,NULL,v_destino_id,v_material_id,'traslado',v_cantidad,v_grupo_id);
        UPDATE reciclaje2.movimientos_stock SET evento_operacion_id=v_evento.id
        WHERE id=v_movimiento.id AND company_id=p_company_id RETURNING * INTO v_movimiento;
        v_movimientos:=v_movimientos||jsonb_build_array(to_jsonb(v_movimiento));

    ELSIF p_accion='ajuste' THEN
        v_deposito_id:=(p_datos->>'deposito_id')::uuid;
        v_material_id:=(p_datos->>'material_id')::uuid;
        v_cantidad:=(p_datos->>'cantidad')::numeric;
        IF v_cantidad IS NULL OR v_cantidad=0 THEN
            RAISE EXCEPTION 'cantidad de ajuste no puede ser cero' USING ERRCODE='23514';
        END IF;
        IF btrim(COALESCE(p_datos->>'motivo',''))='' THEN
            RAISE EXCEPTION 'motivo es obligatorio para un ajuste' USING ERRCODE='23514';
        END IF;
        IF NOT EXISTS(SELECT 1 FROM reciclaje2.depositos WHERE id=v_deposito_id AND company_id=p_company_id) THEN
            RAISE EXCEPTION 'depósito no pertenece a company_id' USING ERRCODE='23503';
        END IF;
        IF NOT EXISTS(SELECT 1 FROM reciclaje2.materiales WHERE id=v_material_id AND company_id=p_company_id) THEN
            RAISE EXCEPTION 'material no pertenece a company_id' USING ERRCODE='23503';
        END IF;
        PERFORM pg_advisory_xact_lock(hashtextextended(p_company_id::text||':'||v_deposito_id::text||':'||v_material_id::text,21));
        IF v_cantidad<0 THEN
            SELECT COALESCE(sum(cantidad),0) INTO v_saldo FROM reciclaje2.movimientos_stock
            WHERE company_id=p_company_id AND deposito_id=v_deposito_id AND material_id=v_material_id;
            IF v_saldo+v_cantidad<0 THEN
                RAISE EXCEPTION 'ajuste dejaría stock negativo' USING ERRCODE='23514';
            END IF;
        END IF;
        v_movimiento:=reciclaje2.upsert_movimiento_stock(NULL,p_company_id,NULL,NULL,v_deposito_id,v_material_id,'ajuste',v_cantidad,v_grupo_id);
        UPDATE reciclaje2.movimientos_stock SET evento_operacion_id=v_evento.id
        WHERE id=v_movimiento.id AND company_id=p_company_id RETURNING * INTO v_movimiento;
        v_movimientos:=jsonb_build_array(to_jsonb(v_movimiento));

    ELSE -- transformacion
        v_deposito_id:=(p_datos->>'deposito_id')::uuid;
        IF btrim(COALESCE(p_datos->>'motivo',''))='' THEN
            RAISE EXCEPTION 'motivo es obligatorio para una transformación' USING ERRCODE='23514';
        END IF;
        IF jsonb_typeof(p_datos->'consumos')<>'array' OR jsonb_array_length(p_datos->'consumos')=0
           OR jsonb_typeof(p_datos->'producciones')<>'array' OR jsonb_array_length(p_datos->'producciones')=0 THEN
            RAISE EXCEPTION 'transformación requiere consumos y producciones no vacíos' USING ERRCODE='23514';
        END IF;
        IF NOT EXISTS(SELECT 1 FROM reciclaje2.depositos WHERE id=v_deposito_id AND company_id=p_company_id) THEN
            RAISE EXCEPTION 'depósito no pertenece a company_id' USING ERRCODE='23503';
        END IF;

        -- Valida todas las líneas antes de escribir y bloquea cada saldo afectado
        -- en orden de UUID para serializar transformaciones concurrentes.
        FOR v_item IN
            SELECT value FROM jsonb_array_elements(p_datos->'consumos')
            UNION ALL
            SELECT value FROM jsonb_array_elements(p_datos->'producciones')
        LOOP
            v_material_id:=(v_item->>'material_id')::uuid;
            v_cantidad:=(v_item->>'cantidad')::numeric;
            IF v_cantidad IS NULL OR v_cantidad<=0 THEN
                RAISE EXCEPTION 'cantidades de transformación deben ser positivas' USING ERRCODE='23514';
            END IF;
            IF NOT EXISTS(SELECT 1 FROM reciclaje2.materiales WHERE id=v_material_id AND company_id=p_company_id) THEN
                RAISE EXCEPTION 'material de transformación no pertenece a company_id' USING ERRCODE='23503';
            END IF;
            IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_datos->'consumos') c WHERE (c->>'material_id')::uuid=v_material_id)
               AND NOT EXISTS(SELECT 1 FROM reciclaje2.materiales WHERE id=v_material_id AND company_id=p_company_id AND compuesto=true) THEN
                RAISE EXCEPTION 'material de consumo no es procesable' USING ERRCODE='23514';
            END IF;
        END LOOP;
        FOR v_lock IN
            SELECT DISTINCT (value->>'material_id')::uuid AS material_id
            FROM (
                SELECT value FROM jsonb_array_elements(p_datos->'consumos')
                UNION ALL
                SELECT value FROM jsonb_array_elements(p_datos->'producciones')
            ) q ORDER BY material_id
        LOOP
            PERFORM pg_advisory_xact_lock(hashtextextended(p_company_id::text||':'||v_deposito_id::text||':'||v_lock.material_id::text,21));
        END LOOP;
        FOR v_lock IN
            SELECT (value->>'material_id')::uuid AS material_id,
                   sum((value->>'cantidad')::numeric) AS cantidad
            FROM jsonb_array_elements(p_datos->'consumos')
            GROUP BY (value->>'material_id')::uuid
        LOOP
            SELECT COALESCE(sum(cantidad),0) INTO v_saldo FROM reciclaje2.movimientos_stock
            WHERE company_id=p_company_id AND deposito_id=v_deposito_id AND material_id=v_lock.material_id;
            IF v_saldo<v_lock.cantidad THEN
                RAISE EXCEPTION 'stock insuficiente para consumo de material %',v_lock.material_id USING ERRCODE='23514';
            END IF;
        END LOOP;

        FOR v_item IN SELECT value FROM jsonb_array_elements(p_datos->'consumos') LOOP
            v_movimiento:=reciclaje2.upsert_movimiento_stock(NULL,p_company_id,NULL,NULL,v_deposito_id,
                (v_item->>'material_id')::uuid,'salida',-(v_item->>'cantidad')::numeric,v_grupo_id);
            UPDATE reciclaje2.movimientos_stock SET evento_operacion_id=v_evento.id
            WHERE id=v_movimiento.id AND company_id=p_company_id RETURNING * INTO v_movimiento;
            v_movimientos:=v_movimientos||jsonb_build_array(to_jsonb(v_movimiento));
        END LOOP;
        FOR v_item IN SELECT value FROM jsonb_array_elements(p_datos->'producciones') LOOP
            v_movimiento:=reciclaje2.upsert_movimiento_stock(NULL,p_company_id,NULL,NULL,v_deposito_id,
                (v_item->>'material_id')::uuid,'entrada',(v_item->>'cantidad')::numeric,v_grupo_id);
            UPDATE reciclaje2.movimientos_stock SET evento_operacion_id=v_evento.id
            WHERE id=v_movimiento.id AND company_id=p_company_id RETURNING * INTO v_movimiento;
            v_movimientos:=v_movimientos||jsonb_build_array(to_jsonb(v_movimiento));
        END LOOP;
    END IF;

    v_resultado:=jsonb_build_object('accion',p_accion,'movimiento_grupo_id',v_grupo_id,'movimientos',v_movimientos);
    UPDATE reciclaje2.eventos_operacion
    SET resultado=v_resultado,completed_at=now()
    WHERE id=v_evento.id AND company_id=p_company_id;
    RETURN v_resultado;
END;
$$;


--
-- Name: FUNCTION orquestar_inventario(p_company_id uuid, p_evento_id uuid, p_accion text, p_datos jsonb); Type: COMMENT; Schema: reciclaje2; Owner: -
--

COMMENT ON FUNCTION reciclaje2.orquestar_inventario(p_company_id uuid, p_evento_id uuid, p_accion text, p_datos jsonb) IS 'Orquesta hechos físicos internos: transferencia, ajuste y transformación; no crea consecuencias comerciales ni financieras.';


--
-- Name: orquestar_operacion(uuid, uuid, character varying, jsonb); Type: FUNCTION; Schema: reciclaje2; Owner: -
--

CREATE FUNCTION reciclaje2.orquestar_operacion(p_company_id uuid, p_evento_id uuid, p_accion character varying, p_datos jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'reciclaje2'
    AS $$
DECLARE
 v_evento reciclaje2.eventos_operacion%ROWTYPE;
 v_operacion reciclaje2.operaciones%ROWTYPE;
 v_linea reciclaje2.operacion_materiales%ROWTYPE;
 v_salida reciclaje2.salidas_transporte%ROWTYPE;
 v_stock reciclaje2.movimientos_stock%ROWTYPE;
 v_transportista reciclaje2.transportistas%ROWTYPE;
 v_socio reciclaje2.socios%ROWTYPE;
 v_item jsonb; v_subitem jsonb; v_resultado jsonb; v_resultados jsonb:='[]'; v_posiciones jsonb:='[]';
 v_operacion_id uuid; v_salida_id uuid; v_transportista_id uuid; v_deposito_id uuid;
 v_grupo_transporte_id uuid; v_grupo_dinero_id uuid; v_tipo_id uuid; v_etapa_id uuid;
 v_material_id uuid; v_linea_id uuid; v_movimiento_grupo_id uuid; v_evento_dinero_id uuid;
 v_tipo_codigo text; v_etapa_codigo text; v_tipo_stock text; v_motivo text;
 v_cantidad numeric(14,3); v_precio numeric(14,2); v_subtotal numeric(14,2); v_total numeric(14,2):=0;
 v_dinero numeric(14,2); v_dinero_json jsonb; v_fin_result jsonb;
 v_posicion_base numeric(14,2); v_diferencia_base numeric(14,2);
 v_aplicado_base numeric(14,2); v_pago_base numeric(14,2); v_vuelto_base numeric(14,2);
 v_count integer;
 v_salida_operacion reciclaje2.salida_operaciones%ROWTYPE;
BEGIN
 IF p_company_id IS NULL OR p_evento_id IS NULL OR p_datos IS NULL OR jsonb_typeof(p_datos)<>'object' THEN
   RAISE EXCEPTION 'company_id, evento_id y datos objeto son obligatorios' USING ERRCODE='22023';
 END IF;
 IF p_accion NOT IN('registrar_operacion','actualizar_operacion','preparar_salida','agregar_a_salida',
                    'cancelar_operacion','eliminar_operacion','cancelar_salida','finalizar_salida',
                    'finalizar_compra_directa') THEN
   RAISE EXCEPTION 'acción operativa no admitida' USING ERRCODE='22023';
 END IF;

 PERFORM pg_advisory_xact_lock(hashtextextended(p_company_id::text||':'||p_evento_id::text,20));
 SELECT * INTO v_evento FROM reciclaje2.eventos_operacion
 WHERE company_id=p_company_id AND evento_id=p_evento_id;
 IF FOUND THEN
   IF v_evento.accion<>p_accion OR v_evento.datos<>p_datos THEN
     RAISE EXCEPTION 'evento_id ya utilizado con datos diferentes' USING ERRCODE='23505';
   END IF;
   RETURN v_evento.resultado;
 END IF;
 INSERT INTO reciclaje2.eventos_operacion(company_id,evento_id,accion,operacion_id,datos)
 VALUES(p_company_id,p_evento_id,p_accion,NULL,p_datos)
 RETURNING * INTO v_evento;

 IF p_accion IN('registrar_operacion','actualizar_operacion') THEN
   v_operacion_id:=(p_datos->>'operacion_id')::uuid;
   v_tipo_codigo:=upper(p_datos->>'tipo');
   IF v_tipo_codigo NOT IN('COMPRA','VENTA') THEN RAISE EXCEPTION 'tipo debe ser COMPRA o VENTA' USING ERRCODE='23514'; END IF;
   SELECT id INTO v_tipo_id FROM reciclaje2.tipos_operacion WHERE codigo=v_tipo_codigo;
   SELECT id INTO v_etapa_id FROM reciclaje2.etapas_operacion WHERE codigo='PRECARGA';
   SELECT * INTO v_socio FROM reciclaje2.socios
   WHERE id=(p_datos->>'socio_id')::uuid AND company_id=p_company_id;
   IF NOT FOUND OR (v_tipo_codigo='COMPRA' AND NOT v_socio.es_socio_compra)
      OR (v_tipo_codigo='VENTA' AND NOT v_socio.es_socio_venta) THEN
     RAISE EXCEPTION 'socio no válido para el tipo de operación' USING ERRCODE='23503';
   END IF;
   IF jsonb_typeof(p_datos->'materiales')<>'array' OR jsonb_array_length(p_datos->'materiales')=0 THEN
     RAISE EXCEPTION 'materiales debe contener al menos una línea' USING ERRCODE='23514';
   END IF;
   IF (p_datos->>'moneda_id')::uuid IS NULL OR (p_datos->>'tipo_cambio')::numeric IS NULL
      OR (p_datos->>'tipo_cambio')::numeric<=0 THEN
     RAISE EXCEPTION 'moneda_id y tipo_cambio positivo son obligatorios' USING ERRCODE='23514';
   END IF;
   IF p_accion='actualizar_operacion' THEN
     SELECT * INTO v_operacion FROM reciclaje2.operaciones
     WHERE id=v_operacion_id AND company_id=p_company_id FOR UPDATE;
     IF NOT FOUND OR v_operacion.eliminada OR EXISTS(SELECT 1 FROM reciclaje2.salida_operaciones
                            WHERE company_id=p_company_id AND operacion_id=v_operacion_id AND estado='activa') THEN
       RAISE EXCEPTION 'solo puede actualizarse una PRECARGA no incorporada a salida' USING ERRCODE='23514';
     END IF;
   END IF;
   FOR v_item IN SELECT value FROM jsonb_array_elements(p_datos->'materiales') LOOP
     v_material_id:=(v_item->>'material_id')::uuid; v_cantidad:=(v_item->>'cantidad')::numeric;
     v_precio:=(v_item->>'precio_unitario')::numeric;
     IF (p_accion='registrar_operacion' AND v_item ? 'id')
        OR (p_accion='actualizar_operacion' AND v_item ? 'id' AND NOT EXISTS(
            SELECT 1 FROM reciclaje2.operacion_materiales
            WHERE id=(v_item->>'id')::uuid AND company_id=p_company_id AND operacion_id=v_operacion_id)) THEN
       RAISE EXCEPTION 'id de línea no corresponde a la operación editable' USING ERRCODE='23503';
     END IF;
     IF NOT EXISTS(SELECT 1 FROM reciclaje2.materiales WHERE id=v_material_id AND company_id=p_company_id) THEN
       RAISE EXCEPTION 'material no pertenece a company_id' USING ERRCODE='23503';
     END IF;
     IF v_cantidad<=0 OR v_precio<0 THEN RAISE EXCEPTION 'cantidad/precio inválidos' USING ERRCODE='23514'; END IF;
     v_total:=v_total+round(v_cantidad*v_precio,2);
   END LOOP;
   -- upsert_operacion interpreta p_id no nulo exclusivamente como UPDATE.
   -- En registrar se inserta primero y luego se adopta, si fue solicitado, el UUID
   -- externo antes de crear líneas o relaciones dependientes.
   v_operacion:=reciclaje2.upsert_operacion(
     CASE WHEN p_accion='registrar_operacion' THEN NULL ELSE v_operacion_id END,
     p_company_id,v_tipo_id,v_etapa_id,v_socio.id,
     NULL,NULL,NULL,(p_datos->>'deposito_id')::uuid,p_datos->>'direccion',p_datos->>'ubicacion',v_total,
     (p_datos->>'moneda_id')::uuid,(p_datos->>'tipo_cambio')::numeric,
     round(v_total*(p_datos->>'tipo_cambio')::numeric,2),(p_datos->>'forma_pago_id')::uuid,
     p_datos->>'referencia',p_datos->>'descripcion',p_datos->>'observaciones',COALESCE(p_datos->'detalles','{}'));
   IF p_accion='registrar_operacion' AND v_operacion_id IS NOT NULL THEN
     UPDATE reciclaje2.operaciones
     SET id=v_operacion_id
     WHERE id=v_operacion.id AND company_id=p_company_id
     RETURNING * INTO v_operacion;
   END IF;
   IF p_accion='actualizar_operacion' THEN
     DELETE FROM reciclaje2.operacion_materiales om
     WHERE om.company_id=p_company_id AND om.operacion_id=v_operacion.id
       AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_datos->'materiales') j
                      WHERE j ? 'id' AND (j->>'id')::uuid=om.id);
   END IF;
   FOR v_item IN SELECT value FROM jsonb_array_elements(p_datos->'materiales') LOOP
     v_cantidad:=(v_item->>'cantidad')::numeric; v_precio:=(v_item->>'precio_unitario')::numeric;
     v_linea:=reciclaje2.upsert_operacion_material((v_item->>'id')::uuid,p_company_id,v_operacion.id,
       (v_item->>'material_id')::uuid,v_cantidad,v_precio,round(v_cantidad*v_precio,2),v_item->>'observaciones');
     v_resultados:=v_resultados||jsonb_build_array(to_jsonb(v_linea));
   END LOOP;
   v_resultado:=jsonb_build_object('operacion',to_jsonb(v_operacion),'materiales',v_resultados);

 ELSIF p_accion IN('preparar_salida','agregar_a_salida') THEN
   IF jsonb_typeof(COALESCE(p_datos->'operacion_ids','[]'))<>'array' THEN
     RAISE EXCEPTION 'operacion_ids debe ser un arreglo' USING ERRCODE='22023';
   END IF;
   IF p_accion='preparar_salida' AND jsonb_array_length(COALESCE(p_datos->'operacion_ids','[]'))=0 THEN
     RAISE EXCEPTION 'preparar_salida requiere al menos una operación' USING ERRCODE='23514';
   END IF;
   IF p_accion='agregar_a_salida'
      AND jsonb_array_length(COALESCE(p_datos->'operacion_ids','[]'))=0
      AND COALESCE((p_datos->'dinero'->>'monto')::numeric,0)<=0 THEN
     RAISE EXCEPTION 'agregar_a_salida no puede ser una acción vacía' USING ERRCODE='23514';
   END IF;
   IF p_accion='preparar_salida' THEN
     v_transportista_id:=(p_datos->>'transportista_id')::uuid;
     SELECT * INTO v_transportista FROM reciclaje2.transportistas WHERE id=v_transportista_id AND company_id=p_company_id;
     IF NOT FOUND THEN RAISE EXCEPTION 'transportista no pertenece a company_id' USING ERRCODE='23503'; END IF;
     v_deposito_id:=(p_datos->>'deposito_id')::uuid;
     IF v_deposito_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM reciclaje2.depositos WHERE id=v_deposito_id AND company_id=p_company_id) THEN
       RAISE EXCEPTION 'depósito no pertenece a company_id' USING ERRCODE='23503'; END IF;
     v_grupo_transporte_id:=COALESCE((p_datos->>'grupo_transporte_id')::uuid,gen_random_uuid());
     v_grupo_dinero_id:=COALESCE((p_datos->>'grupo_dinero_id')::uuid,gen_random_uuid());
     INSERT INTO reciclaje2.salidas_transporte(company_id,grupo_transporte_id,grupo_dinero_id,transportista_id,deposito_id,observaciones)
     VALUES(p_company_id,v_grupo_transporte_id,v_grupo_dinero_id,v_transportista_id,v_deposito_id,p_datos->>'observaciones') RETURNING * INTO v_salida;
   ELSE
     v_salida_id:=(p_datos->>'salida_id')::uuid;
     SELECT * INTO v_salida FROM reciclaje2.salidas_transporte WHERE id=v_salida_id AND company_id=p_company_id FOR UPDATE;
     IF NOT FOUND OR v_salida.estado<>'abierta' THEN RAISE EXCEPTION 'salida no existe o no está abierta' USING ERRCODE='23514'; END IF;
     v_transportista_id:=v_salida.transportista_id; v_grupo_transporte_id:=v_salida.grupo_transporte_id;
     v_grupo_dinero_id:=v_salida.grupo_dinero_id;
   END IF;
   SELECT id INTO v_etapa_id FROM reciclaje2.etapas_operacion WHERE codigo='EN_PROCESO';
   FOR v_operacion_id IN SELECT (value#>>'{}')::uuid FROM jsonb_array_elements(COALESCE(p_datos->'operacion_ids','[]')) LOOP
     SELECT * INTO v_operacion FROM reciclaje2.operaciones WHERE id=v_operacion_id AND company_id=p_company_id FOR UPDATE;
     IF NOT FOUND OR v_operacion.eliminada
        OR NOT EXISTS(SELECT 1 FROM reciclaje2.etapas_operacion WHERE id=v_operacion.etapa_operacion_id AND codigo='PRECARGA')
        OR EXISTS(SELECT 1 FROM reciclaje2.salida_operaciones
                  WHERE company_id=p_company_id AND operacion_id=v_operacion_id AND estado='activa') THEN
       RAISE EXCEPTION 'operación no incorporable a salida' USING ERRCODE='23514';
     END IF;
     INSERT INTO reciclaje2.salida_operaciones(company_id,salida_id,operacion_id) VALUES(p_company_id,v_salida.id,v_operacion_id);
     UPDATE reciclaje2.operaciones SET grupo_transporte_id=v_grupo_transporte_id,grupo_dinero_id=v_grupo_dinero_id,
       transportista_id=v_transportista_id,etapa_operacion_id=v_etapa_id,updated_at=now()
     WHERE id=v_operacion_id AND company_id=p_company_id;
   END LOOP;
   v_dinero:=COALESCE((p_datos->'dinero'->>'monto')::numeric,0);
   IF v_dinero>0 THEN
     v_evento_dinero_id:=(p_datos->'dinero'->>'evento_id')::uuid;
     IF v_evento_dinero_id IS NULL THEN RAISE EXCEPTION 'dinero requiere evento_id' USING ERRCODE='22004'; END IF;
     v_dinero_json:=(p_datos->'dinero')-ARRAY['evento_id']||jsonb_build_object('grupo_dinero_id',v_grupo_dinero_id,
       'grupo_transporte_id',v_grupo_transporte_id,'responsable_tipo','transportista','responsable_id',v_transportista_id);
     v_fin_result:=reciclaje2.orquestar_dinero(p_company_id,v_evento_dinero_id,'entrega',v_dinero_json);
   END IF;
   v_resultado:=jsonb_build_object('salida',to_jsonb(v_salida),'dinero',v_fin_result);

 ELSIF p_accion='finalizar_compra_directa' THEN
   v_operacion_id:=(p_datos->>'operacion_id')::uuid;
   SELECT o.* INTO v_operacion
   FROM reciclaje2.operaciones o
   WHERE o.id=v_operacion_id AND o.company_id=p_company_id
   FOR UPDATE;
   IF NOT FOUND THEN
     RAISE EXCEPTION 'operación no pertenece a company_id' USING ERRCODE='23503';
   END IF;
   SELECT t.codigo,e.codigo INTO v_tipo_codigo,v_etapa_codigo
   FROM reciclaje2.tipos_operacion t, reciclaje2.etapas_operacion e
   WHERE t.id=v_operacion.tipo_operacion_id AND e.id=v_operacion.etapa_operacion_id;
   IF v_operacion.eliminada OR v_tipo_codigo<>'COMPRA' OR v_etapa_codigo<>'PRECARGA' THEN
     RAISE EXCEPTION 'sólo puede finalizarse directamente una COMPRA activa en PRECARGA' USING ERRCODE='23514';
   END IF;
   IF EXISTS(SELECT 1 FROM reciclaje2.salida_operaciones
             WHERE company_id=p_company_id AND operacion_id=v_operacion_id AND estado='activa') THEN
     RAISE EXCEPTION 'la compra pertenece a una salida activa' USING ERRCODE='23514';
   END IF;
   IF EXISTS(SELECT 1 FROM reciclaje2.movimientos_stock
             WHERE company_id=p_company_id AND operacion_id=v_operacion_id)
      OR EXISTS(SELECT 1 FROM reciclaje2.hechos_dinero
                WHERE company_id=p_company_id AND operacion_id=v_operacion_id AND tipo='liquidacion_operacion') THEN
     RAISE EXCEPTION 'la compra ya posee consecuencias físicas o económicas' USING ERRCODE='23505';
   END IF;
   IF jsonb_typeof(COALESCE(p_datos->'fisico','null'::jsonb))<>'array'
      OR jsonb_array_length(p_datos->'fisico')=0 THEN
     RAISE EXCEPTION 'fisico debe contener al menos una recepción' USING ERRCODE='23514';
   END IF;
   v_movimiento_grupo_id:=p_evento_id;
   FOR v_item IN SELECT value FROM jsonb_array_elements(p_datos->'fisico') LOOP
     v_linea_id:=(v_item->>'operacion_material_id')::uuid;
     v_material_id:=(v_item->>'material_id')::uuid;
     v_deposito_id:=(v_item->>'deposito_id')::uuid;
     v_tipo_stock:=COALESCE(v_item->>'tipo','entrada');
     v_cantidad:=(v_item->>'cantidad')::numeric;
     IF v_linea_id IS NULL OR v_material_id IS NULL OR v_deposito_id IS NULL THEN
       RAISE EXCEPTION 'cada recepción requiere operación_material, material y depósito' USING ERRCODE='22004';
     END IF;
     IF v_tipo_stock<>'entrada' OR v_cantidad IS NULL OR v_cantidad<=0 THEN
       RAISE EXCEPTION 'la compra directa sólo admite entradas con cantidad positiva' USING ERRCODE='23514';
     END IF;
     IF NOT EXISTS(SELECT 1 FROM reciclaje2.operacion_materiales om
                   WHERE om.id=v_linea_id AND om.company_id=p_company_id
                     AND om.operacion_id=v_operacion_id AND om.material_id=v_material_id) THEN
       RAISE EXCEPTION 'operacion_material_id no corresponde a la compra y material' USING ERRCODE='23503';
     END IF;
     IF NOT EXISTS(SELECT 1 FROM reciclaje2.depositos
                   WHERE id=v_deposito_id AND company_id=p_company_id) THEN
       RAISE EXCEPTION 'depósito no pertenece a company_id' USING ERRCODE='23503';
     END IF;
     PERFORM pg_advisory_xact_lock(hashtextextended(p_company_id::text||':'||v_deposito_id::text||':'||v_material_id::text,21));
     v_stock:=reciclaje2.upsert_movimiento_stock(NULL,p_company_id,v_operacion_id,v_linea_id,
       v_deposito_id,v_material_id,'entrada',v_cantidad,v_movimiento_grupo_id);
     UPDATE reciclaje2.movimientos_stock
     SET salida_id=NULL,evento_operacion_id=v_evento.id
     WHERE id=v_stock.id RETURNING * INTO v_stock;
     v_resultados:=v_resultados||jsonb_build_array(to_jsonb(v_stock));
   END LOOP;

   v_pago_base:=0;
   IF p_datos ? 'pago' AND p_datos->'pago' IS NOT NULL THEN
     IF jsonb_typeof(p_datos->'pago')<>'object' OR COALESCE((p_datos->'pago'->>'monto')::numeric,0)<=0 THEN
       RAISE EXCEPTION 'pago debe ser un objeto con monto positivo; para crédito total debe omitirse' USING ERRCODE='23514';
     END IF;
     v_evento_dinero_id:=(p_datos->'pago'->>'evento_id')::uuid;
     IF v_evento_dinero_id IS NULL THEN RAISE EXCEPTION 'pago requiere evento_id técnico' USING ERRCODE='22004'; END IF;
     v_fin_result:=reciclaje2.orquestar_dinero(p_company_id,v_evento_dinero_id,'pago_fisico_operacion',
       ((p_datos->'pago')-ARRAY['evento_id','origen_fondos','grupo_dinero_id','grupo_transporte_id'])
       ||jsonb_build_object('operacion_id',v_operacion_id,'origen_fondos','caja'));
     v_pago_base:=round((p_datos->'pago'->>'monto')::numeric*(p_datos->'pago'->>'tipo_cambio')::numeric,2);
   END IF;

   v_evento_dinero_id:=(p_datos->>'liquidacion_evento_id')::uuid;
   IF v_evento_dinero_id IS NULL THEN RAISE EXCEPTION 'liquidación requiere evento_id técnico' USING ERRCODE='22004'; END IF;
   v_dinero_json:=jsonb_build_object(
     'operacion_id',v_operacion_id,'tipo_operacion','COMPRA','monto',v_operacion.monto,
     'moneda_id',v_operacion.moneda_id,'tipo_cambio',v_operacion.tipo_cambio,
     'pago_evento_ids',CASE WHEN p_datos ? 'pago' AND p_datos->'pago' IS NOT NULL
       THEN jsonb_build_array(p_datos->'pago'->>'evento_id') ELSE '[]'::jsonb END,
     'vuelto_evento_ids','[]'::jsonb,'modelo_version',2,
     'responsable_tipo',COALESCE(p_datos->'responsable_pendiente'->>'tipo','socio'),
     'responsable_id',(p_datos->'responsable_pendiente'->>'id')::uuid,
     'responsable_nombre',p_datos->'responsable_pendiente'->>'nombre');
   v_fin_result:=reciclaje2.orquestar_dinero(p_company_id,v_evento_dinero_id,
     'liquidacion_operacion',v_dinero_json);
   SELECT id INTO v_etapa_id FROM reciclaje2.etapas_operacion WHERE codigo='FINALIZADA';
   UPDATE reciclaje2.operaciones SET etapa_operacion_id=v_etapa_id,updated_at=now()
   WHERE id=v_operacion_id AND company_id=p_company_id RETURNING * INTO v_operacion;
   v_resultado:=jsonb_build_object('operacion',to_jsonb(v_operacion),'stock',v_resultados,
     'pago_evento_id',CASE WHEN p_datos ? 'pago' THEN p_datos->'pago'->>'evento_id' ELSE NULL END,
     'liquidacion',v_fin_result);

 ELSIF p_accion='cancelar_operacion' THEN
   v_operacion_id:=(p_datos->>'operacion_id')::uuid; v_motivo:=p_datos->>'motivo';
   SELECT s.* INTO v_salida FROM reciclaje2.salidas_transporte s JOIN reciclaje2.salida_operaciones so ON so.salida_id=s.id
   WHERE so.company_id=p_company_id AND so.operacion_id=v_operacion_id AND so.estado='activa' FOR UPDATE OF s;
   IF NOT FOUND OR v_salida.estado<>'abierta' OR btrim(COALESCE(v_motivo,''))='' THEN RAISE EXCEPTION 'cancelación individual inválida' USING ERRCODE='23514'; END IF;
   IF EXISTS(SELECT 1 FROM reciclaje2.movimientos_stock WHERE company_id=p_company_id AND operacion_id=v_operacion_id)
      OR EXISTS(SELECT 1 FROM reciclaje2.hechos_dinero WHERE company_id=p_company_id AND operacion_id=v_operacion_id AND tipo='liquidacion_operacion') THEN
     RAISE EXCEPTION 'operación con consecuencias físicas/económicas requiere compensación explícita' USING ERRCODE='23514';
   END IF;
   IF p_datos ? 'devolucion' THEN
     v_dinero_json:=p_datos->'devolucion';
     IF v_dinero_json IS NULL OR jsonb_typeof(v_dinero_json)<>'object' THEN
       RAISE EXCEPTION 'devolucion debe ser un objeto' USING ERRCODE='22023';
     END IF;
     v_evento_dinero_id:=(v_dinero_json->>'evento_id')::uuid;
     IF v_evento_dinero_id IS NULL THEN
       RAISE EXCEPTION 'devolucion requiere evento_id' USING ERRCODE='22004';
     END IF;
     v_fin_result:=reciclaje2.orquestar_dinero(p_company_id,v_evento_dinero_id,'devolucion',
       (v_dinero_json-ARRAY['evento_id'])||jsonb_build_object(
       'grupo_dinero_id',v_salida.grupo_dinero_id,
       'grupo_transporte_id',v_salida.grupo_transporte_id,
       'responsable_tipo','transportista',
       'responsable_id',v_salida.transportista_id,
       'observaciones',COALESCE(v_dinero_json->>'observaciones','Cancelación de operación: '||v_motivo)));
   END IF;
   UPDATE reciclaje2.salida_operaciones SET estado='cancelada',cancelado_at=now(),motivo_cancelacion=v_motivo
   WHERE company_id=p_company_id AND operacion_id=v_operacion_id;
   SELECT id INTO v_etapa_id FROM reciclaje2.etapas_operacion WHERE codigo='PRECARGA';
   UPDATE reciclaje2.operaciones SET grupo_transporte_id=NULL,grupo_dinero_id=NULL,transportista_id=NULL,
     etapa_operacion_id=v_etapa_id,updated_at=now() WHERE id=v_operacion_id AND company_id=p_company_id RETURNING * INTO v_operacion;
   v_resultado:=jsonb_build_object('operacion',to_jsonb(v_operacion),
     'dinero_revertido',p_datos ? 'devolucion','devolucion',v_fin_result);

 ELSIF p_accion='eliminar_operacion' THEN
   v_operacion_id:=(p_datos->>'operacion_id')::uuid;
   v_motivo:=COALESCE(NULLIF(btrim(p_datos->>'motivo'),''),'Operación eliminada');
   SELECT o.* INTO v_operacion
   FROM reciclaje2.operaciones o
   WHERE o.id=v_operacion_id AND o.company_id=p_company_id
   FOR UPDATE;
   IF NOT FOUND THEN
     RAISE EXCEPTION 'operación no pertenece a company_id' USING ERRCODE='23503';
   END IF;
   IF v_operacion.eliminada THEN
     RAISE EXCEPTION 'operación ya eliminada' USING ERRCODE='23514';
   END IF;
   SELECT e.codigo INTO v_etapa_codigo
   FROM reciclaje2.etapas_operacion e WHERE e.id=v_operacion.etapa_operacion_id;

   SELECT so.* INTO v_salida_operacion
   FROM reciclaje2.salida_operaciones so
   WHERE so.company_id=p_company_id AND so.operacion_id=v_operacion_id AND so.estado='activa'
   FOR UPDATE;

   IF FOUND THEN
     SELECT * INTO v_salida FROM reciclaje2.salidas_transporte
     WHERE company_id=p_company_id AND id=v_salida_operacion.salida_id FOR UPDATE;
     IF NOT FOUND OR v_salida.estado<>'abierta' THEN
       RAISE EXCEPTION 'la operación pertenece a una salida histórica cerrada y no puede alterarse retroactivamente'
         USING ERRCODE='23514';
     END IF;
     IF EXISTS(SELECT 1 FROM reciclaje2.movimientos_stock
               WHERE company_id=p_company_id AND operacion_id=v_operacion_id)
        OR EXISTS(SELECT 1 FROM reciclaje2.hechos_dinero
                  WHERE company_id=p_company_id AND operacion_id=v_operacion_id AND tipo='liquidacion_operacion') THEN
       RAISE EXCEPTION 'operación con consecuencias físicas/económicas requiere compensación explícita' USING ERRCODE='23514';
     END IF;

     SELECT count(*) INTO v_count FROM reciclaje2.salida_operaciones
     WHERE company_id=p_company_id AND salida_id=v_salida.id AND estado='activa';

     IF v_count=1 THEN
       IF EXISTS(SELECT 1 FROM reciclaje2.hechos_dinero
                 WHERE company_id=p_company_id AND grupo_dinero_id=v_salida.grupo_dinero_id
                   AND tipo NOT IN('entrega','devolucion'))
          OR EXISTS(SELECT 1 FROM reciclaje2.movimientos_stock
                    WHERE company_id=p_company_id AND salida_id=v_salida.id) THEN
         RAISE EXCEPTION 'última carga con rendición/stock requiere compensación explícita' USING ERRCODE='23514';
       END IF;
       SELECT COALESCE(sum(CASE WHEN tipo='entrega' THEN monto_base WHEN tipo='devolucion' THEN -monto_base ELSE 0 END),0)
       INTO v_total FROM reciclaje2.hechos_dinero
       WHERE company_id=p_company_id AND grupo_dinero_id=v_salida.grupo_dinero_id;
       IF v_total>0 THEN
         v_dinero_json:=p_datos->'devolucion';
         IF v_dinero_json IS NULL OR jsonb_typeof(v_dinero_json)<>'object' THEN
           RAISE EXCEPTION 'eliminación de última carga con fondos requiere devolución explícita' USING ERRCODE='22004';
         END IF;
         v_evento_dinero_id:=(v_dinero_json->>'evento_id')::uuid;
         IF v_evento_dinero_id IS NULL THEN
           RAISE EXCEPTION 'devolucion requiere evento_id' USING ERRCODE='22004';
         END IF;
         IF abs(round((v_dinero_json->>'monto')::numeric*(v_dinero_json->>'tipo_cambio')::numeric,2)-v_total)>0.01 THEN
           RAISE EXCEPTION 'la devolución debe compensar exactamente los fondos pendientes' USING ERRCODE='23514';
         END IF;
         v_fin_result:=reciclaje2.orquestar_dinero(p_company_id,v_evento_dinero_id,'devolucion',
           (v_dinero_json-ARRAY['evento_id'])||jsonb_build_object(
           'grupo_dinero_id',v_salida.grupo_dinero_id,
           'grupo_transporte_id',v_salida.grupo_transporte_id,
           'responsable_tipo','transportista','responsable_id',v_salida.transportista_id,
           'observaciones',COALESCE(v_dinero_json->>'observaciones','Eliminación de última carga: '||v_motivo)));
       ELSIF p_datos ? 'devolucion' THEN
         RAISE EXCEPTION 'la salida no tiene fondos pendientes para devolver' USING ERRCODE='23514';
       END IF;
       UPDATE reciclaje2.salidas_transporte
       SET estado='cancelada',fecha_cancelacion=now(),motivo_cancelacion=v_motivo,updated_at=now()
       WHERE company_id=p_company_id AND id=v_salida.id RETURNING * INTO v_salida;
     ELSIF p_datos ? 'devolucion' THEN
       v_dinero_json:=p_datos->'devolucion';
       IF jsonb_typeof(v_dinero_json)<>'object' OR (v_dinero_json->>'evento_id')::uuid IS NULL THEN
         RAISE EXCEPTION 'devolucion requiere objeto y evento_id' USING ERRCODE='22004';
       END IF;
       v_fin_result:=reciclaje2.orquestar_dinero(p_company_id,(v_dinero_json->>'evento_id')::uuid,'devolucion',
         (v_dinero_json-ARRAY['evento_id'])||jsonb_build_object(
         'grupo_dinero_id',v_salida.grupo_dinero_id,
         'grupo_transporte_id',v_salida.grupo_transporte_id,
         'responsable_tipo','transportista','responsable_id',v_salida.transportista_id,
         'observaciones',COALESCE(v_dinero_json->>'observaciones','Eliminación de operación: '||v_motivo)));
     END IF;

     UPDATE reciclaje2.salida_operaciones
     SET estado='cancelada',cancelado_at=now(),motivo_cancelacion=v_motivo
     WHERE company_id=p_company_id AND id=v_salida_operacion.id;
     SELECT id INTO v_etapa_id FROM reciclaje2.etapas_operacion WHERE codigo='PRECARGA';
   ELSE
     IF v_etapa_codigo IS DISTINCT FROM 'PRECARGA'
        OR v_operacion.grupo_transporte_id IS NOT NULL
        OR v_operacion.grupo_dinero_id IS NOT NULL
        OR v_operacion.transportista_id IS NOT NULL THEN
       RAISE EXCEPTION 'operación sin membresía activa no está desligada del circuito operativo' USING ERRCODE='23514';
     END IF;
     v_etapa_id:=v_operacion.etapa_operacion_id;
   END IF;

   UPDATE reciclaje2.operaciones
   SET eliminada=true,eliminada_at=now(),motivo_eliminacion=v_motivo,
       grupo_transporte_id=NULL,grupo_dinero_id=NULL,transportista_id=NULL,
       etapa_operacion_id=v_etapa_id,updated_at=now()
   WHERE company_id=p_company_id AND id=v_operacion_id
   RETURNING * INTO v_operacion;
   v_resultado:=jsonb_build_object('operacion',to_jsonb(v_operacion),'eliminada',true,
     'salida',CASE WHEN v_salida.id IS NULL THEN NULL ELSE to_jsonb(v_salida) END,
     'devolucion',v_fin_result);

 ELSIF p_accion='cancelar_salida' THEN
   v_salida_id:=(p_datos->>'salida_id')::uuid; v_motivo:=p_datos->>'motivo';
   SELECT * INTO v_salida FROM reciclaje2.salidas_transporte WHERE id=v_salida_id AND company_id=p_company_id FOR UPDATE;
   IF NOT FOUND OR v_salida.estado<>'abierta' OR btrim(COALESCE(v_motivo,''))='' THEN RAISE EXCEPTION 'salida no cancelable' USING ERRCODE='23514'; END IF;
   IF EXISTS(SELECT 1 FROM reciclaje2.hechos_dinero WHERE company_id=p_company_id AND grupo_dinero_id=v_salida.grupo_dinero_id
             AND tipo NOT IN('entrega','devolucion')) OR EXISTS(SELECT 1 FROM reciclaje2.movimientos_stock WHERE company_id=p_company_id AND salida_id=v_salida.id) THEN
     RAISE EXCEPTION 'salida con rendición/stock requiere compensación explícita' USING ERRCODE='23514';
   END IF;
   SELECT COALESCE(sum(CASE WHEN tipo='entrega' THEN monto_base WHEN tipo='devolucion' THEN -monto_base ELSE 0 END),0)
   INTO v_total FROM reciclaje2.hechos_dinero WHERE company_id=p_company_id AND grupo_dinero_id=v_salida.grupo_dinero_id;
   IF v_total>0 THEN
     v_dinero_json:=p_datos->'devolucion'; v_evento_dinero_id:=(v_dinero_json->>'evento_id')::uuid;
     IF v_evento_dinero_id IS NULL THEN RAISE EXCEPTION 'cancelación con fondos requiere devolución explícita' USING ERRCODE='22004'; END IF;
     IF abs(round((v_dinero_json->>'monto')::numeric*(v_dinero_json->>'tipo_cambio')::numeric,2)-v_total)>0.01 THEN
       RAISE EXCEPTION 'la devolución de cancelación debe compensar exactamente los fondos pendientes' USING ERRCODE='23514'; END IF;
     v_fin_result:=reciclaje2.orquestar_dinero(p_company_id,v_evento_dinero_id,'devolucion',
       (v_dinero_json-ARRAY['evento_id'])||jsonb_build_object('grupo_dinero_id',v_salida.grupo_dinero_id,
       'grupo_transporte_id',v_salida.grupo_transporte_id,'responsable_tipo','transportista','responsable_id',v_salida.transportista_id,
       'observaciones','Cancelación de salida: '||v_motivo));
   END IF;
   UPDATE reciclaje2.salidas_transporte SET estado='cancelada',fecha_cancelacion=now(),motivo_cancelacion=v_motivo,updated_at=now()
   WHERE id=v_salida.id RETURNING * INTO v_salida;
   UPDATE reciclaje2.salida_operaciones SET estado='cancelada',cancelado_at=now(),motivo_cancelacion=v_motivo
   WHERE company_id=p_company_id AND salida_id=v_salida.id AND estado='activa';
   SELECT id INTO v_etapa_id FROM reciclaje2.etapas_operacion WHERE codigo='PRECARGA';
   UPDATE reciclaje2.operaciones o
   SET grupo_transporte_id=NULL,grupo_dinero_id=NULL,transportista_id=NULL,
       etapa_operacion_id=v_etapa_id,updated_at=now()
   FROM reciclaje2.salida_operaciones so
   WHERE so.company_id=p_company_id AND so.salida_id=v_salida.id
     AND so.operacion_id=o.id AND o.company_id=p_company_id;
   v_resultado:=jsonb_build_object('salida',to_jsonb(v_salida),'devolucion',v_fin_result);

 ELSE -- finalizar_salida
   v_salida_id:=(p_datos->>'salida_id')::uuid;
   SELECT * INTO v_salida FROM reciclaje2.salidas_transporte WHERE id=v_salida_id AND company_id=p_company_id FOR UPDATE;
   IF NOT FOUND OR v_salida.estado<>'abierta' THEN RAISE EXCEPTION 'salida no finalizable' USING ERRCODE='23514'; END IF;
   v_movimiento_grupo_id:=COALESCE((p_datos->>'movimiento_grupo_id')::uuid,gen_random_uuid());
   FOR v_item IN SELECT value FROM jsonb_array_elements(COALESCE(p_datos->'fisico','[]')) LOOP
     v_operacion_id:=(v_item->>'operacion_id')::uuid;
     v_linea_id:=(v_item->>'operacion_material_id')::uuid;
     v_material_id:=(v_item->>'material_id')::uuid; v_deposito_id:=COALESCE((v_item->>'deposito_id')::uuid,v_salida.deposito_id);
     v_tipo_stock:=v_item->>'tipo'; v_cantidad:=(v_item->>'cantidad')::numeric;
     IF v_tipo_stock NOT IN('entrada','salida') OR v_deposito_id IS NULL
       OR NOT EXISTS(SELECT 1 FROM reciclaje2.materiales WHERE id=v_material_id AND company_id=p_company_id)
       OR NOT EXISTS(SELECT 1 FROM reciclaje2.depositos WHERE id=v_deposito_id AND company_id=p_company_id) THEN
       RAISE EXCEPTION 'movimiento físico agregado inválido' USING ERRCODE='23514';
     END IF;
     IF v_operacion_id IS NULL AND v_linea_id IS NOT NULL THEN
       RAISE EXCEPTION 'operacion_id es obligatorio al informar operacion_material_id' USING ERRCODE='23514';
     END IF;
     IF v_operacion_id IS NOT NULL THEN
       IF NOT EXISTS(
         SELECT 1 FROM reciclaje2.salida_operaciones so
         JOIN reciclaje2.operaciones o ON o.company_id=so.company_id AND o.id=so.operacion_id
         WHERE so.company_id=p_company_id AND so.salida_id=v_salida.id
           AND so.operacion_id=v_operacion_id AND so.estado='activa' AND o.eliminada=false
       ) THEN RAISE EXCEPTION 'operación física ajena a la salida o empresa' USING ERRCODE='23503'; END IF;
       IF v_linea_id IS NULL THEN
         SELECT count(*),(array_agg(om.id))[1] INTO v_count,v_linea_id
         FROM reciclaje2.operacion_materiales om
         WHERE om.company_id=p_company_id AND om.operacion_id=v_operacion_id AND om.material_id=v_material_id;
         IF v_count=0 THEN RAISE EXCEPTION 'material ajeno a la operación' USING ERRCODE='23503'; END IF;
         IF v_count>1 THEN RAISE EXCEPTION 'operacion_material_id es obligatorio cuando el material se repite en la operación' USING ERRCODE='23514'; END IF;
       ELSIF NOT EXISTS(
         SELECT 1 FROM reciclaje2.operacion_materiales om
         WHERE om.company_id=p_company_id AND om.id=v_linea_id
           AND om.operacion_id=v_operacion_id AND om.material_id=v_material_id
       ) THEN RAISE EXCEPTION 'operacion_material_id no corresponde a operación y material' USING ERRCODE='23503'; END IF;
     END IF;
     IF (v_tipo_stock='entrada' AND v_cantidad<=0) OR (v_tipo_stock='salida' AND v_cantidad>=0) THEN
       RAISE EXCEPTION 'signo físico incompatible' USING ERRCODE='23514'; END IF;
     PERFORM pg_advisory_xact_lock(hashtextextended(p_company_id::text||':'||v_deposito_id::text||':'||v_material_id::text,21));
     IF v_tipo_stock='salida' AND (SELECT COALESCE(sum(cantidad),0) FROM reciclaje2.movimientos_stock
       WHERE company_id=p_company_id AND deposito_id=v_deposito_id AND material_id=v_material_id)+v_cantidad<0 THEN
       RAISE EXCEPTION 'stock insuficiente' USING ERRCODE='23514'; END IF;
     v_stock:=reciclaje2.upsert_movimiento_stock(NULL,p_company_id,v_operacion_id,v_linea_id,v_deposito_id,v_material_id,v_tipo_stock,v_cantidad,v_movimiento_grupo_id);
     UPDATE reciclaje2.movimientos_stock SET salida_id=v_salida.id,evento_operacion_id=v_evento.id WHERE id=v_stock.id RETURNING * INTO v_stock;
     v_resultados:=v_resultados||jsonb_build_array(to_jsonb(v_stock));
   END LOOP;
   FOR v_item IN SELECT value FROM jsonb_array_elements(COALESCE(p_datos->'liquidaciones','[]')) LOOP
     v_operacion_id:=(v_item->>'operacion_id')::uuid; v_evento_dinero_id:=(v_item->>'evento_id')::uuid;
     IF NOT EXISTS(SELECT 1 FROM reciclaje2.salida_operaciones WHERE company_id=p_company_id AND salida_id=v_salida.id AND operacion_id=v_operacion_id AND estado='activa') THEN
       RAISE EXCEPTION 'liquidación ajena a la salida' USING ERRCODE='23503'; END IF;
     IF EXISTS(SELECT 1 FROM reciclaje2.hechos_dinero WHERE company_id=p_company_id
               AND operacion_id=v_operacion_id AND tipo='liquidacion_operacion') THEN
       RAISE EXCEPTION 'la operación ya posee una liquidación comercial' USING ERRCODE='23505'; END IF;
     SELECT * INTO v_operacion FROM reciclaje2.operaciones
     WHERE company_id=p_company_id AND id=v_operacion_id FOR UPDATE;
     SELECT codigo INTO v_tipo_codigo FROM reciclaje2.tipos_operacion WHERE id=v_operacion.tipo_operacion_id;
     IF COALESCE((v_item->>'modelo_version')::int,1)=2 THEN
       v_pago_base:=0; v_vuelto_base:=0;
       FOR v_subitem IN SELECT value FROM jsonb_array_elements(COALESCE(v_item->'pagos_fisicos','[]')) LOOP
         IF COALESCE((v_subitem->>'monto')::numeric,0)<=0 THEN RAISE EXCEPTION 'pago físico debe ser positivo' USING ERRCODE='23514'; END IF;
         v_fin_result:=reciclaje2.orquestar_dinero(p_company_id,(v_subitem->>'evento_id')::uuid,'pago_fisico_operacion',
           (v_subitem-ARRAY['evento_id'])||jsonb_build_object('operacion_id',v_operacion_id,
           'grupo_dinero_id',v_salida.grupo_dinero_id,'grupo_transporte_id',v_salida.grupo_transporte_id,
           'responsable_tipo','transportista','responsable_id',v_salida.transportista_id));
         v_pago_base:=v_pago_base+round((v_subitem->>'monto')::numeric*(v_subitem->>'tipo_cambio')::numeric,2);
       END LOOP;
       FOR v_subitem IN SELECT value FROM jsonb_array_elements(COALESCE(v_item->'vueltos','[]')) LOOP
         IF COALESCE((v_subitem->>'monto')::numeric,0)<=0 THEN RAISE EXCEPTION 'vuelto debe ser positivo' USING ERRCODE='23514'; END IF;
         v_fin_result:=reciclaje2.orquestar_dinero(p_company_id,(v_subitem->>'evento_id')::uuid,'vuelto_recibido',
           (v_subitem-ARRAY['evento_id'])||jsonb_build_object('operacion_id',v_operacion_id,
           'grupo_dinero_id',v_salida.grupo_dinero_id,'grupo_transporte_id',v_salida.grupo_transporte_id,
           'responsable_tipo','transportista','responsable_id',v_salida.transportista_id));
         v_vuelto_base:=v_vuelto_base+round((v_subitem->>'monto')::numeric*(v_subitem->>'tipo_cambio')::numeric,2);
       END LOOP;
       v_aplicado_base:=v_pago_base-v_vuelto_base;
       IF v_aplicado_base<0 THEN RAISE EXCEPTION 'el vuelto no puede superar el pago físico de la operación' USING ERRCODE='23514'; END IF;
       v_dinero_json:=jsonb_build_object('operacion_id',v_operacion_id,'tipo_operacion',v_tipo_codigo,
         'monto',v_operacion.monto,'moneda_id',v_operacion.moneda_id,'tipo_cambio',v_operacion.tipo_cambio,
         'pago_evento_ids',COALESCE((SELECT jsonb_agg(value->>'evento_id') FROM jsonb_array_elements(COALESCE(v_item->'pagos_fisicos','[]'))),'[]'::jsonb),
         'vuelto_evento_ids',COALESCE((SELECT jsonb_agg(value->>'evento_id') FROM jsonb_array_elements(COALESCE(v_item->'vueltos','[]'))),'[]'::jsonb),'modelo_version',2,
         'grupo_dinero_id',v_salida.grupo_dinero_id,'grupo_transporte_id',v_salida.grupo_transporte_id,
         'responsable_tipo',COALESCE(v_item->'responsable_pendiente'->>'tipo','socio'),
         'responsable_id',(v_item->'responsable_pendiente'->>'id')::uuid,
         'responsable_nombre',v_item->'responsable_pendiente'->>'nombre');
     ELSE
       v_dinero_json:=(v_item-ARRAY['evento_id'])||jsonb_build_object('grupo_dinero_id',v_salida.grupo_dinero_id,'grupo_transporte_id',v_salida.grupo_transporte_id);
     END IF;
     v_fin_result:=reciclaje2.orquestar_dinero(p_company_id,v_evento_dinero_id,'liquidacion_operacion',v_dinero_json);
   END LOOP;
   SELECT count(*) INTO v_count FROM reciclaje2.salida_operaciones WHERE company_id=p_company_id AND salida_id=v_salida.id AND estado='activa';
   IF v_count<>jsonb_array_length(COALESCE(p_datos->'liquidaciones','[]'))
      OR v_count<>(SELECT count(DISTINCT value->>'operacion_id')
                   FROM jsonb_array_elements(COALESCE(p_datos->'liquidaciones','[]'))) THEN
     RAISE EXCEPTION 'cada operación activa requiere exactamente una liquidación' USING ERRCODE='23514'; END IF;
   FOR v_item IN SELECT value FROM jsonb_array_elements(COALESCE(p_datos->'gastos','[]')) LOOP
     v_fin_result:=reciclaje2.orquestar_dinero(p_company_id,(v_item->>'evento_id')::uuid,'gasto',
       (v_item-ARRAY['evento_id'])||jsonb_build_object('grupo_dinero_id',v_salida.grupo_dinero_id,'grupo_transporte_id',v_salida.grupo_transporte_id,
       'responsable_tipo','transportista','responsable_id',v_salida.transportista_id,
       'origen_fondos',COALESCE(v_item->>'origen_fondos','entrega')));
   END LOOP;
   FOR v_item IN SELECT value FROM jsonb_array_elements(
     CASE WHEN p_datos ? 'devoluciones' THEN p_datos->'devoluciones'
          WHEN p_datos ? 'devolucion' THEN jsonb_build_array(p_datos->'devolucion') ELSE '[]'::jsonb END) LOOP
     v_fin_result:=reciclaje2.orquestar_dinero(p_company_id,(v_item->>'evento_id')::uuid,'devolucion',
       (v_item-ARRAY['evento_id'])||jsonb_build_object('grupo_dinero_id',v_salida.grupo_dinero_id,'grupo_transporte_id',v_salida.grupo_transporte_id,
       'responsable_tipo','transportista','responsable_id',v_salida.transportista_id));
   END LOOP;

   SELECT COALESCE(jsonb_agg(jsonb_build_object('moneda_id',q.moneda_id,'codigo',m.codigo,
     'saldo',q.saldo,'equivalente_ars',q.equivalente_ars) ORDER BY m.codigo),'[]'::jsonb),
     COALESCE(sum(q.equivalente_ars),0)
   INTO v_posiciones,v_posicion_base
   FROM (
     SELECT moneda_id,sum(CASE
       WHEN tipo='entrega' THEN monto WHEN tipo='vuelto_recibido' THEN monto
       WHEN tipo='pago_fisico_operacion' AND origen_fondos='entrega' THEN -monto
       WHEN tipo='gasto' AND COALESCE(origen_fondos,'entrega')='entrega' THEN -monto
       WHEN tipo='devolucion' THEN -monto WHEN tipo='justificacion_operacion' THEN -monto
       WHEN tipo='liquidacion_operacion' AND modelo_version=1 AND impacto_caja IS NULL THEN -(monto-monto_pendiente)
       ELSE 0 END) saldo,
       sum(CASE
       WHEN tipo='entrega' THEN monto_base WHEN tipo='vuelto_recibido' THEN monto_base
       WHEN tipo='pago_fisico_operacion' AND origen_fondos='entrega' THEN -monto_base
       WHEN tipo='gasto' AND COALESCE(origen_fondos,'entrega')='entrega' THEN -monto_base
       WHEN tipo='devolucion' THEN -monto_base WHEN tipo='justificacion_operacion' THEN -monto_base
       WHEN tipo='liquidacion_operacion' AND modelo_version=1 AND impacto_caja IS NULL THEN -round((monto-monto_pendiente)*tipo_cambio,2)
       ELSE 0 END) equivalente_ars
     FROM reciclaje2.hechos_dinero WHERE company_id=p_company_id AND grupo_dinero_id=v_salida.grupo_dinero_id
     GROUP BY moneda_id HAVING abs(sum(CASE
       WHEN tipo='entrega' THEN monto WHEN tipo='vuelto_recibido' THEN monto
       WHEN tipo='pago_fisico_operacion' AND origen_fondos='entrega' THEN -monto
       WHEN tipo='gasto' AND COALESCE(origen_fondos,'entrega')='entrega' THEN -monto
       WHEN tipo='devolucion' THEN -monto WHEN tipo='justificacion_operacion' THEN -monto
       WHEN tipo='liquidacion_operacion' AND modelo_version=1 AND impacto_caja IS NULL THEN -(monto-monto_pendiente)
       ELSE 0 END))>0.000001) q JOIN reciclaje2.monedas m ON m.id=q.moneda_id;

   IF jsonb_array_length(v_posiciones)>0 THEN
     IF NOT (p_datos ? 'diferencias') AND NOT (p_datos ? 'diferencia') THEN
       RAISE EXCEPTION 'la rendición conserva posiciones físicas y requiere diferencias por moneda' USING ERRCODE='23514';
     END IF;
     FOR v_item IN SELECT value FROM jsonb_array_elements(
       CASE WHEN p_datos ? 'diferencias' THEN p_datos->'diferencias' ELSE jsonb_build_array(p_datos->'diferencia') END) LOOP
       SELECT (x->>'saldo')::numeric INTO v_dinero FROM jsonb_array_elements(v_posiciones) x
       WHERE (x->>'moneda_id')::uuid=(v_item->>'moneda_id')::uuid;
       IF NOT FOUND OR abs(v_dinero-CASE WHEN v_item->>'sentido_diferencia'='a_cargo_responsable' THEN (v_item->>'monto')::numeric ELSE -(v_item->>'monto')::numeric END)>0.000001 THEN
         RAISE EXCEPTION 'diferencia no coincide con la posición física de su moneda' USING ERRCODE='23514'; END IF;
       v_fin_result:=reciclaje2.orquestar_dinero(p_company_id,(v_item->>'evento_id')::uuid,'diferencia',
         (v_item-ARRAY['evento_id'])||jsonb_build_object('grupo_dinero_id',v_salida.grupo_dinero_id,'grupo_transporte_id',v_salida.grupo_transporte_id,
         'responsable_tipo','transportista','responsable_id',v_salida.transportista_id));
     END LOOP;
     IF (SELECT count(*) FROM jsonb_array_elements(v_posiciones))<>(SELECT count(*) FROM jsonb_array_elements(
       CASE WHEN p_datos ? 'diferencias' THEN p_datos->'diferencias' ELSE jsonb_build_array(p_datos->'diferencia') END))
        OR (SELECT count(*) FROM jsonb_array_elements(v_posiciones))<>(SELECT count(DISTINCT (x->>'moneda_id')::uuid) FROM jsonb_array_elements(
       CASE WHEN p_datos ? 'diferencias' THEN p_datos->'diferencias' ELSE jsonb_build_array(p_datos->'diferencia') END) x) THEN
       RAISE EXCEPTION 'cada posición física requiere exactamente una diferencia' USING ERRCODE='23514'; END IF;
   ELSIF p_datos ? 'diferencias' OR p_datos ? 'diferencia' THEN
     RAISE EXCEPTION 'no corresponde registrar diferencias sin posiciones físicas' USING ERRCODE='23514';
   END IF;
   SELECT id INTO v_etapa_id FROM reciclaje2.etapas_operacion WHERE codigo='FINALIZADA';
   UPDATE reciclaje2.operaciones o SET etapa_operacion_id=v_etapa_id,updated_at=now()
   FROM reciclaje2.salida_operaciones so WHERE so.company_id=p_company_id AND so.salida_id=v_salida.id AND so.estado='activa' AND o.id=so.operacion_id;
   UPDATE reciclaje2.salidas_transporte SET estado='finalizada',fecha_finalizacion=now(),updated_at=now()
   WHERE id=v_salida.id RETURNING * INTO v_salida;
   v_resultado:=jsonb_build_object('salida',to_jsonb(v_salida),'stock',v_resultados,
     'posicion_por_moneda_antes_resolucion',v_posiciones,'consolidado_base',v_posicion_base);
 END IF;

 UPDATE reciclaje2.eventos_operacion
 SET operacion_id=CASE WHEN p_accion IN('registrar_operacion','actualizar_operacion','cancelar_operacion','eliminar_operacion','finalizar_compra_directa')
                       THEN COALESCE(v_operacion.id,v_operacion_id) ELSE NULL END,
     resultado=v_resultado,completed_at=now()
 WHERE id=v_evento.id;
 RETURN v_resultado;
END;
$$;


--
-- Name: FUNCTION orquestar_operacion(p_company_id uuid, p_evento_id uuid, p_accion character varying, p_datos jsonb); Type: COMMENT; Schema: reciclaje2; Owner: -
--

COMMENT ON FUNCTION reciclaje2.orquestar_operacion(p_company_id uuid, p_evento_id uuid, p_accion character varying, p_datos jsonb) IS 'Orquesta atómicamente el ciclo comercial, la salida, el stock y la delegación a Dinero.';


--
-- Name: upsert_catalogo(text, uuid, jsonb); Type: FUNCTION; Schema: reciclaje2; Owner: -
--

CREATE FUNCTION reciclaje2.upsert_catalogo(p_entidad text, p_id uuid, p_datos jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'reciclaje2'
    AS $$
DECLARE
    v_result jsonb;
    v_tipo_operacion reciclaje2.tipos_operacion%ROWTYPE;
    v_etapa reciclaje2.etapas_operacion%ROWTYPE;
    v_moneda reciclaje2.monedas%ROWTYPE;
    v_forma reciclaje2.formas_pago%ROWTYPE;
    v_gasto reciclaje2.tipos_gasto%ROWTYPE;
BEGIN
    IF p_datos IS NULL OR jsonb_typeof(p_datos)<>'object' THEN
        RAISE EXCEPTION 'datos debe ser un objeto JSON' USING ERRCODE='22023';
    END IF;
    IF p_entidad IS NULL OR p_entidad NOT IN
       ('tipo_operacion','etapa_operacion','moneda','forma_pago','tipo_gasto') THEN
        RAISE EXCEPTION 'catálogo no admitido: %',p_entidad USING ERRCODE='22023';
    END IF;
    IF btrim(COALESCE(p_datos->>'codigo',''))='' OR btrim(COALESCE(p_datos->>'nombre',''))='' THEN
        RAISE EXCEPTION 'codigo y nombre son obligatorios' USING ERRCODE='23514';
    END IF;
    IF length(p_datos->>'nombre') > 100 THEN
        RAISE EXCEPTION 'nombre no puede superar 100 caracteres' USING ERRCODE='22001';
    END IF;
    IF p_entidad='moneda' AND length(p_datos->>'codigo') > 10 THEN
        RAISE EXCEPTION 'codigo de moneda no puede superar 10 caracteres' USING ERRCODE='22001';
    ELSIF p_entidad<>'moneda' AND length(p_datos->>'codigo') > 50 THEN
        RAISE EXCEPTION 'codigo no puede superar 50 caracteres' USING ERRCODE='22001';
    END IF;
    IF p_entidad='moneda' AND length(p_datos->>'simbolo') > 10 THEN
        RAISE EXCEPTION 'simbolo no puede superar 10 caracteres' USING ERRCODE='22001';
    END IF;

    CASE p_entidad
    WHEN 'tipo_operacion' THEN
        IF EXISTS (SELECT 1 FROM jsonb_object_keys(p_datos) AS k(campo)
                   WHERE campo NOT IN ('codigo','nombre','activo')) THEN
            RAISE EXCEPTION 'campos no admitidos para tipo_operacion' USING ERRCODE='22023';
        END IF;
        IF EXISTS (SELECT 1 FROM reciclaje2.tipos_operacion WHERE codigo=p_datos->>'codigo' AND id IS DISTINCT FROM p_id) THEN
            RAISE EXCEPTION 'codigo de tipo_operacion ya existe' USING ERRCODE='23505';
        END IF;
        IF p_id IS NULL THEN
            INSERT INTO reciclaje2.tipos_operacion(codigo,nombre,activo)
            VALUES(p_datos->>'codigo',p_datos->>'nombre',COALESCE((p_datos->>'activo')::boolean,true))
            RETURNING * INTO v_tipo_operacion;
        ELSE
            UPDATE reciclaje2.tipos_operacion SET codigo=p_datos->>'codigo',nombre=p_datos->>'nombre',
                activo=COALESCE((p_datos->>'activo')::boolean,true),updated_at=now()
            WHERE id=p_id RETURNING * INTO v_tipo_operacion;
            IF NOT FOUND THEN RAISE EXCEPTION 'tipo_operacion no encontrado' USING ERRCODE='P0002'; END IF;
        END IF;
        v_result:=to_jsonb(v_tipo_operacion);

    WHEN 'etapa_operacion' THEN
        IF EXISTS (SELECT 1 FROM jsonb_object_keys(p_datos) AS k(campo)
                   WHERE campo NOT IN ('codigo','nombre','orden','activo')) THEN
            RAISE EXCEPTION 'campos no admitidos para etapa_operacion' USING ERRCODE='22023';
        END IF;
        IF COALESCE((p_datos->>'orden')::integer,0)<0 THEN
            RAISE EXCEPTION 'orden debe ser mayor o igual a cero' USING ERRCODE='23514';
        END IF;
        IF EXISTS (SELECT 1 FROM reciclaje2.etapas_operacion WHERE codigo=p_datos->>'codigo' AND id IS DISTINCT FROM p_id) THEN
            RAISE EXCEPTION 'codigo de etapa_operacion ya existe' USING ERRCODE='23505';
        END IF;
        IF p_id IS NULL THEN
            INSERT INTO reciclaje2.etapas_operacion(codigo,nombre,orden,activo)
            VALUES(p_datos->>'codigo',p_datos->>'nombre',COALESCE((p_datos->>'orden')::integer,0),
                   COALESCE((p_datos->>'activo')::boolean,true)) RETURNING * INTO v_etapa;
        ELSE
            UPDATE reciclaje2.etapas_operacion SET codigo=p_datos->>'codigo',nombre=p_datos->>'nombre',
                orden=COALESCE((p_datos->>'orden')::integer,0),activo=COALESCE((p_datos->>'activo')::boolean,true),
                updated_at=now() WHERE id=p_id RETURNING * INTO v_etapa;
            IF NOT FOUND THEN RAISE EXCEPTION 'etapa_operacion no encontrada' USING ERRCODE='P0002'; END IF;
        END IF;
        v_result:=to_jsonb(v_etapa);

    WHEN 'moneda' THEN
        IF EXISTS (SELECT 1 FROM jsonb_object_keys(p_datos) AS k(campo)
                   WHERE campo NOT IN ('codigo','nombre','simbolo','activo')) THEN
            RAISE EXCEPTION 'campos no admitidos para moneda' USING ERRCODE='22023';
        END IF;
        IF EXISTS (SELECT 1 FROM reciclaje2.monedas WHERE codigo=p_datos->>'codigo' AND id IS DISTINCT FROM p_id) THEN
            RAISE EXCEPTION 'codigo de moneda ya existe' USING ERRCODE='23505';
        END IF;
        IF p_id IS NULL THEN
            INSERT INTO reciclaje2.monedas(codigo,nombre,simbolo,activo)
            VALUES(p_datos->>'codigo',p_datos->>'nombre',p_datos->>'simbolo',
                   COALESCE((p_datos->>'activo')::boolean,true)) RETURNING * INTO v_moneda;
        ELSE
            UPDATE reciclaje2.monedas SET codigo=p_datos->>'codigo',nombre=p_datos->>'nombre',
                simbolo=p_datos->>'simbolo',activo=COALESCE((p_datos->>'activo')::boolean,true),updated_at=now()
            WHERE id=p_id RETURNING * INTO v_moneda;
            IF NOT FOUND THEN RAISE EXCEPTION 'moneda no encontrada' USING ERRCODE='P0002'; END IF;
        END IF;
        v_result:=to_jsonb(v_moneda);

    WHEN 'forma_pago' THEN
        IF EXISTS (SELECT 1 FROM jsonb_object_keys(p_datos) AS k(campo)
                   WHERE campo NOT IN ('codigo','nombre','activo')) THEN
            RAISE EXCEPTION 'campos no admitidos para forma_pago' USING ERRCODE='22023';
        END IF;
        IF EXISTS (SELECT 1 FROM reciclaje2.formas_pago WHERE codigo=p_datos->>'codigo' AND id IS DISTINCT FROM p_id) THEN
            RAISE EXCEPTION 'codigo de forma_pago ya existe' USING ERRCODE='23505';
        END IF;
        IF p_id IS NULL THEN
            INSERT INTO reciclaje2.formas_pago(codigo,nombre,activo)
            VALUES(p_datos->>'codigo',p_datos->>'nombre',COALESCE((p_datos->>'activo')::boolean,true)) RETURNING * INTO v_forma;
        ELSE
            UPDATE reciclaje2.formas_pago SET codigo=p_datos->>'codigo',nombre=p_datos->>'nombre',
                activo=COALESCE((p_datos->>'activo')::boolean,true),updated_at=now()
            WHERE id=p_id RETURNING * INTO v_forma;
            IF NOT FOUND THEN RAISE EXCEPTION 'forma_pago no encontrada' USING ERRCODE='P0002'; END IF;
        END IF;
        v_result:=to_jsonb(v_forma);

    WHEN 'tipo_gasto' THEN
        IF EXISTS (SELECT 1 FROM jsonb_object_keys(p_datos) AS k(campo)
                   WHERE campo NOT IN ('codigo','nombre','activo')) THEN
            RAISE EXCEPTION 'campos no admitidos para tipo_gasto' USING ERRCODE='22023';
        END IF;
        IF EXISTS (SELECT 1 FROM reciclaje2.tipos_gasto WHERE codigo=p_datos->>'codigo' AND id IS DISTINCT FROM p_id) THEN
            RAISE EXCEPTION 'codigo de tipo_gasto ya existe' USING ERRCODE='23505';
        END IF;
        IF p_id IS NULL THEN
            INSERT INTO reciclaje2.tipos_gasto(codigo,nombre,activo)
            VALUES(p_datos->>'codigo',p_datos->>'nombre',COALESCE((p_datos->>'activo')::boolean,true)) RETURNING * INTO v_gasto;
        ELSE
            UPDATE reciclaje2.tipos_gasto SET codigo=p_datos->>'codigo',nombre=p_datos->>'nombre',
                activo=COALESCE((p_datos->>'activo')::boolean,true),updated_at=now()
            WHERE id=p_id RETURNING * INTO v_gasto;
            IF NOT FOUND THEN RAISE EXCEPTION 'tipo_gasto no encontrado' USING ERRCODE='P0002'; END IF;
        END IF;
        v_result:=to_jsonb(v_gasto);
    ELSE
        RAISE EXCEPTION 'catálogo no admitido: %',p_entidad USING ERRCODE='22023';
    END CASE;
    RETURN v_result;
END;
$$;


--
-- Name: FUNCTION upsert_catalogo(p_entidad text, p_id uuid, p_datos jsonb); Type: COMMENT; Schema: reciclaje2; Owner: -
--

COMMENT ON FUNCTION reciclaje2.upsert_catalogo(p_entidad text, p_id uuid, p_datos jsonb) IS 'Persiste uno de cinco catálogos globales autorizados mediante SQL estático.';


--
-- Name: upsert_configuracion(uuid, text, uuid, jsonb); Type: FUNCTION; Schema: reciclaje2; Owner: -
--

CREATE FUNCTION reciclaje2.upsert_configuracion(p_company_id uuid, p_entidad text, p_id uuid, p_datos jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'reciclaje2'
    AS $$
DECLARE
    v_result jsonb;
    v_socio reciclaje2.socios%ROWTYPE;
    v_transportista reciclaje2.transportistas%ROWTYPE;
    v_deposito reciclaje2.depositos%ROWTYPE;
    v_material reciclaje2.materiales%ROWTYPE;
    v_precio reciclaje2.precios_socios%ROWTYPE;
    v_socio_id uuid;
    v_material_id uuid;
    v_latitud numeric(10,7);
    v_longitud numeric(10,7);
    v_metadata jsonb;
BEGIN
    IF p_company_id IS NULL THEN
        RAISE EXCEPTION 'company_id es obligatorio' USING ERRCODE = '22004';
    END IF;
    IF p_datos IS NULL OR jsonb_typeof(p_datos) <> 'object' THEN
        RAISE EXCEPTION 'datos debe ser un objeto JSON' USING ERRCODE = '22023';
    END IF;
    IF p_entidad IS NULL OR p_entidad NOT IN
       ('socio','transportista','deposito','material','precio_socio') THEN
        RAISE EXCEPTION 'entidad de configuración no admitida: %', p_entidad
            USING ERRCODE='22023';
    END IF;

    CASE p_entidad
    WHEN 'socio' THEN
        IF EXISTS (
            SELECT 1 FROM jsonb_object_keys(p_datos) AS k(campo)
            WHERE campo NOT IN ('codigo','nombre','documento','telefono','direccion',
                'observaciones','activo','latitud','longitud','es_socio_compra','es_socio_venta')
        ) THEN
            RAISE EXCEPTION 'datos contiene campos no admitidos para socio' USING ERRCODE = '22023';
        END IF;
        IF btrim(COALESCE(p_datos->>'codigo','')) = '' THEN
            RAISE EXCEPTION 'codigo de socio es obligatorio' USING ERRCODE = '23514';
        END IF;
        IF btrim(COALESCE(p_datos->>'nombre','')) = '' THEN
            RAISE EXCEPTION 'nombre de socio es obligatorio' USING ERRCODE = '23514';
        END IF;
        v_latitud := (p_datos->>'latitud')::numeric;
        v_longitud := (p_datos->>'longitud')::numeric;
        IF v_latitud IS NOT NULL AND v_latitud NOT BETWEEN -90 AND 90 THEN
            RAISE EXCEPTION 'latitud debe estar entre -90 y 90' USING ERRCODE = '23514';
        END IF;
        IF v_longitud IS NOT NULL AND v_longitud NOT BETWEEN -180 AND 180 THEN
            RAISE EXCEPTION 'longitud debe estar entre -180 y 180' USING ERRCODE = '23514';
        END IF;
        IF EXISTS (SELECT 1 FROM reciclaje2.socios
                   WHERE company_id = p_company_id AND codigo = p_datos->>'codigo'
                     AND id IS DISTINCT FROM p_id) THEN
            RAISE EXCEPTION 'codigo de socio ya existe para company_id' USING ERRCODE = '23505';
        END IF;
        IF p_id IS NULL THEN
            INSERT INTO reciclaje2.socios (
                company_id,codigo,nombre,documento,telefono,direccion,observaciones,
                activo,latitud,longitud,es_socio_compra,es_socio_venta
            ) VALUES (
                p_company_id,p_datos->>'codigo',p_datos->>'nombre',p_datos->>'documento',
                p_datos->>'telefono',p_datos->>'direccion',p_datos->>'observaciones',
                COALESCE((p_datos->>'activo')::boolean,true),v_latitud,v_longitud,
                COALESCE((p_datos->>'es_socio_compra')::boolean,true),
                COALESCE((p_datos->>'es_socio_venta')::boolean,false)
            ) RETURNING * INTO v_socio;
        ELSE
            UPDATE reciclaje2.socios SET
                codigo=p_datos->>'codigo', nombre=p_datos->>'nombre',
                documento=p_datos->>'documento', telefono=p_datos->>'telefono',
                direccion=p_datos->>'direccion', observaciones=p_datos->>'observaciones',
                activo=COALESCE((p_datos->>'activo')::boolean,true), latitud=v_latitud,
                longitud=v_longitud,
                es_socio_compra=COALESCE((p_datos->>'es_socio_compra')::boolean,true),
                es_socio_venta=COALESCE((p_datos->>'es_socio_venta')::boolean,false),
                updated_at=now()
            WHERE id=p_id AND company_id=p_company_id RETURNING * INTO v_socio;
            IF NOT FOUND THEN RAISE EXCEPTION 'socio no encontrado para company_id' USING ERRCODE='P0002'; END IF;
        END IF;
        v_result := to_jsonb(v_socio);

    WHEN 'transportista' THEN
        IF EXISTS (SELECT 1 FROM jsonb_object_keys(p_datos) AS k(campo)
                   WHERE campo NOT IN ('codigo','nombre','telefono','placa','activo')) THEN
            RAISE EXCEPTION 'datos contiene campos no admitidos para transportista' USING ERRCODE='22023';
        END IF;
        IF btrim(COALESCE(p_datos->>'codigo',''))='' OR btrim(COALESCE(p_datos->>'nombre',''))=''
           OR btrim(COALESCE(p_datos->>'placa',''))='' THEN
            RAISE EXCEPTION 'codigo, nombre y placa son obligatorios para transportista' USING ERRCODE='23514';
        END IF;
        IF EXISTS (SELECT 1 FROM reciclaje2.transportistas
                   WHERE company_id=p_company_id AND codigo=p_datos->>'codigo' AND id IS DISTINCT FROM p_id) THEN
            RAISE EXCEPTION 'codigo de transportista ya existe para company_id' USING ERRCODE='23505';
        END IF;
        IF p_id IS NULL THEN
            INSERT INTO reciclaje2.transportistas(company_id,codigo,nombre,telefono,placa,activo)
            VALUES(p_company_id,p_datos->>'codigo',p_datos->>'nombre',p_datos->>'telefono',
                   p_datos->>'placa',COALESCE((p_datos->>'activo')::boolean,true))
            RETURNING * INTO v_transportista;
        ELSE
            UPDATE reciclaje2.transportistas SET codigo=p_datos->>'codigo',nombre=p_datos->>'nombre',
                telefono=p_datos->>'telefono',placa=p_datos->>'placa',
                activo=COALESCE((p_datos->>'activo')::boolean,true),updated_at=now()
            WHERE id=p_id AND company_id=p_company_id RETURNING * INTO v_transportista;
            IF NOT FOUND THEN RAISE EXCEPTION 'transportista no encontrado para company_id' USING ERRCODE='P0002'; END IF;
        END IF;
        v_result := to_jsonb(v_transportista);

    WHEN 'deposito' THEN
        IF EXISTS (SELECT 1 FROM jsonb_object_keys(p_datos) AS k(campo)
                   WHERE campo NOT IN ('codigo','nombre','direccion','activo')) THEN
            RAISE EXCEPTION 'datos contiene campos no admitidos para deposito' USING ERRCODE='22023';
        END IF;
        IF btrim(COALESCE(p_datos->>'codigo',''))='' OR btrim(COALESCE(p_datos->>'nombre',''))='' THEN
            RAISE EXCEPTION 'codigo y nombre son obligatorios para deposito' USING ERRCODE='23514';
        END IF;
        IF EXISTS (SELECT 1 FROM reciclaje2.depositos
                   WHERE company_id=p_company_id AND codigo=p_datos->>'codigo' AND id IS DISTINCT FROM p_id) THEN
            RAISE EXCEPTION 'codigo de deposito ya existe para company_id' USING ERRCODE='23505';
        END IF;
        IF p_id IS NULL THEN
            INSERT INTO reciclaje2.depositos(company_id,codigo,nombre,direccion,activo)
            VALUES(p_company_id,p_datos->>'codigo',p_datos->>'nombre',p_datos->>'direccion',
                   COALESCE((p_datos->>'activo')::boolean,true)) RETURNING * INTO v_deposito;
        ELSE
            UPDATE reciclaje2.depositos SET codigo=p_datos->>'codigo',nombre=p_datos->>'nombre',
                direccion=p_datos->>'direccion',activo=COALESCE((p_datos->>'activo')::boolean,true),updated_at=now()
            WHERE id=p_id AND company_id=p_company_id RETURNING * INTO v_deposito;
            IF NOT FOUND THEN RAISE EXCEPTION 'deposito no encontrado para company_id' USING ERRCODE='P0002'; END IF;
        END IF;
        v_result := to_jsonb(v_deposito);

    WHEN 'material' THEN
        IF EXISTS (SELECT 1 FROM jsonb_object_keys(p_datos) AS k(campo)
                   WHERE campo NOT IN ('codigo','nombre','unidad','metadata','activo','precio_base',
                                       'precio_mayorista','imagen_url','compuesto')) THEN
            RAISE EXCEPTION 'datos contiene campos no admitidos para material' USING ERRCODE='22023';
        END IF;
        IF btrim(COALESCE(p_datos->>'codigo',''))='' OR btrim(COALESCE(p_datos->>'nombre',''))=''
           OR btrim(COALESCE(p_datos->>'unidad',''))='' THEN
            RAISE EXCEPTION 'codigo, nombre y unidad son obligatorios para material' USING ERRCODE='23514';
        END IF;
        v_metadata := COALESCE(p_datos->'metadata','{}'::jsonb);
        IF jsonb_typeof(v_metadata)<>'object' THEN
            RAISE EXCEPTION 'metadata debe ser un objeto JSON' USING ERRCODE='23514';
        END IF;
        IF COALESCE((p_datos->>'precio_base')::numeric,0)<0
           OR COALESCE((p_datos->>'precio_mayorista')::numeric,0)<0 THEN
            RAISE EXCEPTION 'los precios de material no pueden ser negativos' USING ERRCODE='23514';
        END IF;
        IF EXISTS (SELECT 1 FROM reciclaje2.materiales
                   WHERE company_id=p_company_id AND codigo=p_datos->>'codigo' AND id IS DISTINCT FROM p_id) THEN
            RAISE EXCEPTION 'codigo de material ya existe para company_id' USING ERRCODE='23505';
        END IF;
        IF p_id IS NULL THEN
            INSERT INTO reciclaje2.materiales(company_id,codigo,nombre,unidad,metadata,activo,
                precio_base,precio_mayorista,imagen_url,compuesto)
            VALUES(p_company_id,p_datos->>'codigo',p_datos->>'nombre',p_datos->>'unidad',v_metadata,
                COALESCE((p_datos->>'activo')::boolean,true),COALESCE((p_datos->>'precio_base')::numeric,0),
                COALESCE((p_datos->>'precio_mayorista')::numeric,0),p_datos->>'imagen_url',
                COALESCE((p_datos->>'compuesto')::boolean,false)) RETURNING * INTO v_material;
        ELSE
            UPDATE reciclaje2.materiales SET codigo=p_datos->>'codigo',nombre=p_datos->>'nombre',
                unidad=p_datos->>'unidad',metadata=v_metadata,activo=COALESCE((p_datos->>'activo')::boolean,true),
                precio_base=COALESCE((p_datos->>'precio_base')::numeric,0),
                precio_mayorista=COALESCE((p_datos->>'precio_mayorista')::numeric,0),
                imagen_url=p_datos->>'imagen_url',compuesto=COALESCE((p_datos->>'compuesto')::boolean,false),
                updated_at=now()
            WHERE id=p_id AND company_id=p_company_id RETURNING * INTO v_material;
            IF NOT FOUND THEN RAISE EXCEPTION 'material no encontrado para company_id' USING ERRCODE='P0002'; END IF;
        END IF;
        v_result := to_jsonb(v_material);

    WHEN 'precio_socio' THEN
        IF EXISTS (SELECT 1 FROM jsonb_object_keys(p_datos) AS k(campo)
                   WHERE campo NOT IN ('socio_id','material_id','precio','moneda_id','observaciones')) THEN
            RAISE EXCEPTION 'datos contiene campos no admitidos para precio_socio' USING ERRCODE='22023';
        END IF;
        v_socio_id := (p_datos->>'socio_id')::uuid;
        v_material_id := (p_datos->>'material_id')::uuid;
        IF NOT EXISTS (SELECT 1 FROM reciclaje2.socios WHERE id=v_socio_id AND company_id=p_company_id) THEN
            RAISE EXCEPTION 'socio_id no es válido para company_id' USING ERRCODE='23503';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM reciclaje2.materiales WHERE id=v_material_id AND company_id=p_company_id) THEN
            RAISE EXCEPTION 'material_id no es válido para company_id' USING ERRCODE='23503';
        END IF;
        IF (p_datos->>'precio') IS NULL OR (p_datos->>'precio')::numeric<0 THEN
            RAISE EXCEPTION 'precio debe ser mayor o igual a cero' USING ERRCODE='23514';
        END IF;
        IF (p_datos->>'moneda_id') IS NULL OR NOT EXISTS (
            SELECT 1 FROM reciclaje2.monedas WHERE id=(p_datos->>'moneda_id')::uuid
        ) THEN
            RAISE EXCEPTION 'moneda_id no existe' USING ERRCODE='23503';
        END IF;
        INSERT INTO reciclaje2.precios_socios(company_id,socio_id,material_id,precio,moneda_id,observaciones)
        VALUES(p_company_id,v_socio_id,v_material_id,(p_datos->>'precio')::numeric,
               (p_datos->>'moneda_id')::uuid,p_datos->>'observaciones')
        ON CONFLICT (company_id,socio_id,material_id) DO UPDATE
        SET precio=EXCLUDED.precio,moneda_id=EXCLUDED.moneda_id,
            observaciones=EXCLUDED.observaciones,updated_at=now()
        RETURNING * INTO v_precio;
        v_result := to_jsonb(v_precio);

    ELSE
        RAISE EXCEPTION 'entidad de configuración no admitida: %', p_entidad USING ERRCODE='22023';
    END CASE;
    RETURN v_result;
END;
$$;


--
-- Name: FUNCTION upsert_configuracion(p_company_id uuid, p_entidad text, p_id uuid, p_datos jsonb); Type: COMMENT; Schema: reciclaje2; Owner: -
--

COMMENT ON FUNCTION reciclaje2.upsert_configuracion(p_company_id uuid, p_entidad text, p_id uuid, p_datos jsonb) IS 'Persiste una entidad autorizada de configuración mediante SQL estático y devuelve JSON.';


--
-- Name: finanzas; Type: TABLE; Schema: reciclaje2; Owner: -
--

CREATE TABLE reciclaje2.finanzas (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    evento_id uuid,
    hecho_dinero_id uuid,
    grupo_dinero_id uuid,
    grupo_transporte_id uuid,
    responsable_id uuid,
    operacion_id uuid,
    tipo character varying(30) NOT NULL,
    responsable_tipo character varying(50) NOT NULL,
    responsable_nombre text NOT NULL,
    concepto text NOT NULL,
    monto_original numeric(14,2) NOT NULL,
    moneda_id uuid NOT NULL,
    tipo_cambio numeric(14,6) DEFAULT 1,
    fecha_emision timestamp with time zone DEFAULT now() NOT NULL,
    fecha_vencimiento timestamp with time zone,
    estado character varying(30) DEFAULT 'pendiente'::character varying NOT NULL,
    observaciones text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT finanzas_concepto_no_vacio CHECK ((btrim(concepto) <> ''::text)),
    CONSTRAINT finanzas_estado_valido CHECK (((estado)::text = ANY ((ARRAY['pendiente'::character varying, 'parcial'::character varying, 'saldada'::character varying, 'anulada'::character varying])::text[]))),
    CONSTRAINT finanzas_monto_original_positivo CHECK ((monto_original > (0)::numeric)),
    CONSTRAINT finanzas_responsable_nombre_no_vacio CHECK ((btrim(responsable_nombre) <> ''::text)),
    CONSTRAINT finanzas_responsable_tipo_no_vacio CHECK ((btrim((responsable_tipo)::text) <> ''::text)),
    CONSTRAINT finanzas_tipo_cambio_valido CHECK (((tipo_cambio IS NULL) OR (tipo_cambio > (0)::numeric))),
    CONSTRAINT finanzas_tipo_valido CHECK (((tipo)::text = ANY ((ARRAY['por_pagar'::character varying, 'por_cobrar'::character varying])::text[]))),
    CONSTRAINT finanzas_vencimiento_valido CHECK (((fecha_vencimiento IS NULL) OR (fecha_vencimiento >= fecha_emision)))
);


--
-- Name: upsert_finanza(uuid, uuid, uuid, character varying, character varying, text, text, numeric, uuid, numeric, timestamp with time zone, timestamp with time zone, character varying, text); Type: FUNCTION; Schema: reciclaje2; Owner: -
--

CREATE FUNCTION reciclaje2.upsert_finanza(p_id uuid, p_company_id uuid, p_operacion_id uuid, p_tipo character varying, p_responsable_tipo character varying, p_responsable_nombre text, p_concepto text, p_monto_original numeric, p_moneda_id uuid, p_tipo_cambio numeric, p_fecha_emision timestamp with time zone, p_fecha_vencimiento timestamp with time zone, p_estado character varying, p_observaciones text) RETURNS reciclaje2.finanzas
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'reciclaje2'
    AS $$
DECLARE
    v_result reciclaje2.finanzas%ROWTYPE;
BEGIN
    IF p_company_id IS NULL THEN
        RAISE EXCEPTION 'company_id es obligatorio'
            USING ERRCODE = '22004';
    END IF;

    IF p_tipo IS NULL OR p_tipo NOT IN ('por_pagar', 'por_cobrar') THEN
        RAISE EXCEPTION 'tipo de finanza no admitido' USING ERRCODE = '23514';
    END IF;
    IF p_estado IS NULL OR p_estado NOT IN ('pendiente', 'parcial', 'saldada', 'anulada') THEN
        RAISE EXCEPTION 'estado de finanza no admitido' USING ERRCODE = '23514';
    END IF;
    IF p_monto_original IS NULL OR p_monto_original <= 0 THEN
        RAISE EXCEPTION 'monto_original debe ser mayor que cero' USING ERRCODE = '23514';
    END IF;
    IF p_tipo_cambio IS NOT NULL AND p_tipo_cambio <= 0 THEN
        RAISE EXCEPTION 'tipo_cambio debe ser mayor que cero' USING ERRCODE = '23514';
    END IF;
    IF p_responsable_tipo IS NULL OR btrim(p_responsable_tipo) = '' THEN
        RAISE EXCEPTION 'responsable_tipo es obligatorio' USING ERRCODE = '23514';
    END IF;
    IF p_responsable_nombre IS NULL OR btrim(p_responsable_nombre) = '' THEN
        RAISE EXCEPTION 'responsable_nombre es obligatorio' USING ERRCODE = '23514';
    END IF;
    IF p_concepto IS NULL OR btrim(p_concepto) = '' THEN
        RAISE EXCEPTION 'concepto es obligatorio' USING ERRCODE = '23514';
    END IF;
    IF p_fecha_emision IS NULL THEN
        RAISE EXCEPTION 'fecha_emision es obligatoria' USING ERRCODE = '23514';
    END IF;
    IF p_fecha_vencimiento IS NOT NULL AND p_fecha_vencimiento < p_fecha_emision THEN
        RAISE EXCEPTION 'fecha_vencimiento no puede ser anterior a fecha_emision'
            USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM reciclaje2.monedas WHERE id = p_moneda_id) THEN
        RAISE EXCEPTION 'moneda_id no existe' USING ERRCODE = '23503';
    END IF;

    IF p_operacion_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM reciclaje2.operaciones
        WHERE id = p_operacion_id AND company_id = p_company_id
    ) THEN
        RAISE EXCEPTION 'operacion_id no es válido para company_id'
            USING ERRCODE = '23503';
    END IF;

    IF p_id IS NULL THEN
        INSERT INTO reciclaje2.finanzas (
            company_id, operacion_id, tipo, responsable_tipo,
            responsable_nombre, concepto, monto_original, moneda_id,
            tipo_cambio, fecha_emision, fecha_vencimiento, estado,
            observaciones
        ) VALUES (
            p_company_id, p_operacion_id, p_tipo, p_responsable_tipo,
            p_responsable_nombre, p_concepto, p_monto_original, p_moneda_id,
            p_tipo_cambio, p_fecha_emision, p_fecha_vencimiento, p_estado,
            p_observaciones
        )
        RETURNING * INTO v_result;
    ELSE
        UPDATE reciclaje2.finanzas
        SET operacion_id = p_operacion_id,
            tipo = p_tipo,
            responsable_tipo = p_responsable_tipo,
            responsable_nombre = p_responsable_nombre,
            concepto = p_concepto,
            monto_original = p_monto_original,
            moneda_id = p_moneda_id,
            tipo_cambio = p_tipo_cambio,
            fecha_emision = p_fecha_emision,
            fecha_vencimiento = p_fecha_vencimiento,
            estado = p_estado,
            observaciones = p_observaciones,
            updated_at = now()
        WHERE id = p_id
          AND company_id = p_company_id
        RETURNING * INTO v_result;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'finanza no encontrada para company_id'
                USING ERRCODE = 'P0002';
        END IF;
    END IF;

    RETURN v_result;
END;
$$;


--
-- Name: FUNCTION upsert_finanza(p_id uuid, p_company_id uuid, p_operacion_id uuid, p_tipo character varying, p_responsable_tipo character varying, p_responsable_nombre text, p_concepto text, p_monto_original numeric, p_moneda_id uuid, p_tipo_cambio numeric, p_fecha_emision timestamp with time zone, p_fecha_vencimiento timestamp with time zone, p_estado character varying, p_observaciones text); Type: COMMENT; Schema: reciclaje2; Owner: -
--

COMMENT ON FUNCTION reciclaje2.upsert_finanza(p_id uuid, p_company_id uuid, p_operacion_id uuid, p_tipo character varying, p_responsable_tipo character varying, p_responsable_nombre text, p_concepto text, p_monto_original numeric, p_moneda_id uuid, p_tipo_cambio numeric, p_fecha_emision timestamp with time zone, p_fecha_vencimiento timestamp with time zone, p_estado character varying, p_observaciones text) IS 'Persiste una obligación financiera sin generar movimientos de caja.';


--
-- Name: movimientos_caja; Type: TABLE; Schema: reciclaje2; Owner: -
--

CREATE TABLE reciclaje2.movimientos_caja (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    evento_id uuid,
    hecho_dinero_id uuid,
    grupo_dinero_id uuid,
    grupo_transporte_id uuid,
    operacion_id uuid,
    finanza_id uuid,
    tipo character varying(20) NOT NULL,
    monto numeric(14,2) NOT NULL,
    moneda_id uuid NOT NULL,
    tipo_cambio numeric(14,6) DEFAULT 1 NOT NULL,
    monto_base numeric(14,2) NOT NULL,
    forma_pago_id uuid,
    tipo_gasto_id uuid,
    referencia text,
    concepto text NOT NULL,
    responsable_tipo character varying(50),
    responsable_id uuid,
    responsable_nombre text,
    comprobante_url text,
    observaciones text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT movimientos_caja_concepto_no_vacio CHECK ((btrim(concepto) <> ''::text)),
    CONSTRAINT movimientos_caja_monto_base_positivo CHECK ((monto_base > (0)::numeric)),
    CONSTRAINT movimientos_caja_monto_positivo CHECK ((monto > (0)::numeric)),
    CONSTRAINT movimientos_caja_tipo_cambio_valido CHECK ((tipo_cambio > (0)::numeric)),
    CONSTRAINT movimientos_caja_tipo_valido CHECK (((tipo)::text = ANY ((ARRAY['entrada'::character varying, 'salida'::character varying])::text[])))
);


--
-- Name: upsert_movimiento_caja(uuid, uuid, uuid, uuid, character varying, numeric, uuid, numeric, numeric, uuid, text, text, character varying, uuid, text, text, text, uuid); Type: FUNCTION; Schema: reciclaje2; Owner: -
--

CREATE FUNCTION reciclaje2.upsert_movimiento_caja(p_id uuid, p_company_id uuid, p_operacion_id uuid, p_finanza_id uuid, p_tipo character varying, p_monto numeric, p_moneda_id uuid, p_tipo_cambio numeric, p_monto_base numeric, p_forma_pago_id uuid, p_referencia text, p_concepto text, p_responsable_tipo character varying, p_responsable_id uuid, p_responsable_nombre text, p_comprobante_url text, p_observaciones text, p_tipo_gasto_id uuid) RETURNS reciclaje2.movimientos_caja
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'reciclaje2'
    AS $$
DECLARE
    v_result reciclaje2.movimientos_caja%ROWTYPE;
    v_finanza reciclaje2.finanzas%ROWTYPE;
BEGIN
    IF p_company_id IS NULL THEN
        RAISE EXCEPTION 'company_id es obligatorio'
            USING ERRCODE = '22004';
    END IF;

    IF p_tipo IS NULL OR p_tipo NOT IN ('entrada', 'salida') THEN
        RAISE EXCEPTION 'tipo de movimiento de caja no admitido' USING ERRCODE = '23514';
    END IF;
    IF p_monto IS NULL OR p_monto <= 0 THEN
        RAISE EXCEPTION 'monto debe ser mayor que cero' USING ERRCODE = '23514';
    END IF;
    IF p_tipo_cambio IS NULL OR p_tipo_cambio <= 0 THEN
        RAISE EXCEPTION 'tipo_cambio debe ser mayor que cero' USING ERRCODE = '23514';
    END IF;
    IF p_monto_base IS NULL OR p_monto_base <= 0 THEN
        RAISE EXCEPTION 'monto_base debe ser mayor que cero' USING ERRCODE = '23514';
    END IF;
    IF p_concepto IS NULL OR btrim(p_concepto) = '' THEN
        RAISE EXCEPTION 'concepto es obligatorio' USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM reciclaje2.monedas WHERE id = p_moneda_id) THEN
        RAISE EXCEPTION 'moneda_id no existe' USING ERRCODE = '23503';
    END IF;
    IF p_forma_pago_id IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM reciclaje2.formas_pago WHERE id = p_forma_pago_id) THEN
        RAISE EXCEPTION 'forma_pago_id no existe' USING ERRCODE = '23503';
    END IF;
    IF p_tipo_gasto_id IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM reciclaje2.tipos_gasto WHERE id = p_tipo_gasto_id) THEN
        RAISE EXCEPTION 'tipo_gasto_id no existe' USING ERRCODE = '23503';
    END IF;

    IF p_operacion_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM reciclaje2.operaciones
        WHERE id = p_operacion_id AND company_id = p_company_id
    ) THEN
        RAISE EXCEPTION 'operacion_id no es válido para company_id'
            USING ERRCODE = '23503';
    END IF;

    IF p_finanza_id IS NOT NULL THEN
        SELECT * INTO v_finanza
        FROM reciclaje2.finanzas
        WHERE id = p_finanza_id AND company_id = p_company_id;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'finanza_id no es válido para company_id'
                USING ERRCODE = '23503';
        END IF;
        IF p_operacion_id IS NOT NULL
           AND v_finanza.operacion_id IS NOT NULL
           AND v_finanza.operacion_id <> p_operacion_id THEN
            RAISE EXCEPTION 'finanza_id no está asociada a operacion_id'
                USING ERRCODE = '23514';
        END IF;
    END IF;

    IF p_id IS NULL THEN
        INSERT INTO reciclaje2.movimientos_caja (
            company_id, operacion_id, finanza_id, tipo, monto, moneda_id,
            tipo_cambio, monto_base, forma_pago_id, referencia, concepto,
            responsable_tipo, responsable_id, responsable_nombre,
            comprobante_url, observaciones, tipo_gasto_id
        ) VALUES (
            p_company_id, p_operacion_id, p_finanza_id, p_tipo, p_monto,
            p_moneda_id, p_tipo_cambio, p_monto_base, p_forma_pago_id,
            p_referencia, p_concepto, p_responsable_tipo, p_responsable_id,
            p_responsable_nombre, p_comprobante_url, p_observaciones,
            p_tipo_gasto_id
        )
        RETURNING * INTO v_result;
    ELSE
        UPDATE reciclaje2.movimientos_caja
        SET operacion_id = p_operacion_id,
            finanza_id = p_finanza_id,
            tipo = p_tipo,
            monto = p_monto,
            moneda_id = p_moneda_id,
            tipo_cambio = p_tipo_cambio,
            monto_base = p_monto_base,
            forma_pago_id = p_forma_pago_id,
            referencia = p_referencia,
            concepto = p_concepto,
            responsable_tipo = p_responsable_tipo,
            responsable_id = p_responsable_id,
            responsable_nombre = p_responsable_nombre,
            comprobante_url = p_comprobante_url,
            observaciones = p_observaciones,
            tipo_gasto_id = p_tipo_gasto_id
        WHERE id = p_id
          AND company_id = p_company_id
        RETURNING * INTO v_result;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'movimiento de caja no encontrado para company_id'
                USING ERRCODE = 'P0002';
        END IF;
    END IF;

    RETURN v_result;
END;
$$;


--
-- Name: FUNCTION upsert_movimiento_caja(p_id uuid, p_company_id uuid, p_operacion_id uuid, p_finanza_id uuid, p_tipo character varying, p_monto numeric, p_moneda_id uuid, p_tipo_cambio numeric, p_monto_base numeric, p_forma_pago_id uuid, p_referencia text, p_concepto text, p_responsable_tipo character varying, p_responsable_id uuid, p_responsable_nombre text, p_comprobante_url text, p_observaciones text, p_tipo_gasto_id uuid); Type: COMMENT; Schema: reciclaje2; Owner: -
--

COMMENT ON FUNCTION reciclaje2.upsert_movimiento_caja(p_id uuid, p_company_id uuid, p_operacion_id uuid, p_finanza_id uuid, p_tipo character varying, p_monto numeric, p_moneda_id uuid, p_tipo_cambio numeric, p_monto_base numeric, p_forma_pago_id uuid, p_referencia text, p_concepto text, p_responsable_tipo character varying, p_responsable_id uuid, p_responsable_nombre text, p_comprobante_url text, p_observaciones text, p_tipo_gasto_id uuid) IS 'Persiste un movimiento real de dinero sin modificar finanzas.';


--
-- Name: movimientos_stock; Type: TABLE; Schema: reciclaje2; Owner: -
--

CREATE TABLE reciclaje2.movimientos_stock (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    salida_id uuid,
    evento_operacion_id uuid,
    operacion_id uuid,
    operacion_material_id uuid,
    deposito_id uuid NOT NULL,
    material_id uuid NOT NULL,
    tipo character varying(30) NOT NULL,
    cantidad numeric(14,3) NOT NULL,
    movimiento_grupo_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT movimientos_stock_cantidad_no_cero CHECK ((cantidad <> (0)::numeric)),
    CONSTRAINT movimientos_stock_tipo_valido CHECK (((tipo)::text = ANY ((ARRAY['entrada'::character varying, 'salida'::character varying, 'ajuste'::character varying, 'traslado'::character varying])::text[])))
);


--
-- Name: upsert_movimiento_stock(uuid, uuid, uuid, uuid, uuid, uuid, character varying, numeric, uuid); Type: FUNCTION; Schema: reciclaje2; Owner: -
--

CREATE FUNCTION reciclaje2.upsert_movimiento_stock(p_id uuid, p_company_id uuid, p_operacion_id uuid, p_operacion_material_id uuid, p_deposito_id uuid, p_material_id uuid, p_tipo character varying, p_cantidad numeric, p_movimiento_grupo_id uuid) RETURNS reciclaje2.movimientos_stock
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'reciclaje2'
    AS $$
DECLARE
    v_result reciclaje2.movimientos_stock%ROWTYPE;
    v_linea reciclaje2.operacion_materiales%ROWTYPE;
BEGIN
    IF p_company_id IS NULL THEN
        RAISE EXCEPTION 'company_id es obligatorio'
            USING ERRCODE = '22004';
    END IF;

    IF p_tipo IS NULL OR p_tipo NOT IN ('entrada', 'salida', 'ajuste', 'traslado') THEN
        RAISE EXCEPTION 'tipo de movimiento de stock no admitido' USING ERRCODE = '23514';
    END IF;
    IF p_cantidad IS NULL OR p_cantidad = 0 THEN
        RAISE EXCEPTION 'cantidad no puede ser cero ni NULL' USING ERRCODE = '23514';
    END IF;

    IF p_operacion_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM reciclaje2.operaciones
        WHERE id = p_operacion_id AND company_id = p_company_id
    ) THEN
        RAISE EXCEPTION 'operacion_id no es válido para company_id'
            USING ERRCODE = '23503';
    END IF;

    IF p_operacion_material_id IS NOT NULL THEN
        SELECT * INTO v_linea
        FROM reciclaje2.operacion_materiales
        WHERE id = p_operacion_material_id AND company_id = p_company_id;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'operacion_material_id no es válido para company_id'
                USING ERRCODE = '23503';
        END IF;
        IF p_operacion_id IS NOT NULL AND v_linea.operacion_id <> p_operacion_id THEN
            RAISE EXCEPTION 'operacion_material_id no pertenece a operacion_id'
                USING ERRCODE = '23514';
        END IF;
        IF v_linea.material_id <> p_material_id THEN
            RAISE EXCEPTION 'material_id no coincide con el material de operacion_material_id'
                USING ERRCODE = '23514';
        END IF;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM reciclaje2.depositos
        WHERE id = p_deposito_id AND company_id = p_company_id
    ) THEN
        RAISE EXCEPTION 'deposito_id no es válido para company_id'
            USING ERRCODE = '23503';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM reciclaje2.materiales
        WHERE id = p_material_id AND company_id = p_company_id
    ) THEN
        RAISE EXCEPTION 'material_id no es válido para company_id'
            USING ERRCODE = '23503';
    END IF;

    IF p_id IS NULL THEN
        INSERT INTO reciclaje2.movimientos_stock (
            company_id, operacion_id, operacion_material_id, deposito_id,
            material_id, tipo, cantidad, movimiento_grupo_id
        ) VALUES (
            p_company_id, p_operacion_id, p_operacion_material_id, p_deposito_id,
            p_material_id, p_tipo, p_cantidad, p_movimiento_grupo_id
        )
        RETURNING * INTO v_result;
    ELSE
        UPDATE reciclaje2.movimientos_stock
        SET operacion_id = p_operacion_id,
            operacion_material_id = p_operacion_material_id,
            deposito_id = p_deposito_id,
            material_id = p_material_id,
            tipo = p_tipo,
            cantidad = p_cantidad,
            movimiento_grupo_id = p_movimiento_grupo_id
        WHERE id = p_id
          AND company_id = p_company_id
        RETURNING * INTO v_result;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'movimiento de stock no encontrado para company_id'
                USING ERRCODE = 'P0002';
        END IF;
    END IF;

    RETURN v_result;
END;
$$;


--
