--
-- Name: operaciones; Type: TABLE; Schema: reciclaje2; Owner: -
--

CREATE TABLE reciclaje2.operaciones (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    tipo_operacion_id uuid NOT NULL,
    etapa_operacion_id uuid NOT NULL,
    socio_id uuid,
    grupo_transporte_id uuid,
    grupo_dinero_id uuid,
    transportista_id uuid,
    deposito_id uuid,
    direccion text,
    ubicacion text,
    monto numeric(14,2) DEFAULT 0,
    moneda_id uuid,
    tipo_cambio numeric(14,6) DEFAULT 1,
    monto_ars numeric(14,2),
    forma_pago_id uuid,
    referencia text,
    descripcion text,
    observaciones text,
    detalles jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    eliminada boolean DEFAULT false NOT NULL,
    eliminada_at timestamp with time zone,
    motivo_eliminacion text,
    CONSTRAINT operaciones_detalles_objeto CHECK ((jsonb_typeof(detalles) = 'object'::text)),
    CONSTRAINT operaciones_eliminacion_coherente CHECK ((((eliminada = false) AND (eliminada_at IS NULL) AND (motivo_eliminacion IS NULL)) OR ((eliminada = true) AND (eliminada_at IS NOT NULL) AND (motivo_eliminacion IS NOT NULL) AND (btrim(motivo_eliminacion) <> ''::text)))),
    CONSTRAINT operaciones_monto_ars_no_negativo CHECK (((monto_ars IS NULL) OR (monto_ars >= (0)::numeric))),
    CONSTRAINT operaciones_monto_no_negativo CHECK (((monto IS NULL) OR (monto >= (0)::numeric))),
    CONSTRAINT operaciones_tipo_cambio_valido CHECK (((tipo_cambio IS NULL) OR (tipo_cambio > (0)::numeric)))
);


--
-- Name: upsert_operacion(uuid, uuid, uuid, uuid, uuid, uuid, uuid, uuid, uuid, text, text, numeric, uuid, numeric, numeric, uuid, text, text, text, jsonb); Type: FUNCTION; Schema: reciclaje2; Owner: -
--

CREATE FUNCTION reciclaje2.upsert_operacion(p_id uuid, p_company_id uuid, p_tipo_operacion_id uuid, p_etapa_operacion_id uuid, p_socio_id uuid, p_grupo_transporte_id uuid, p_grupo_dinero_id uuid, p_transportista_id uuid, p_deposito_id uuid, p_direccion text, p_ubicacion text, p_monto numeric, p_moneda_id uuid, p_tipo_cambio numeric, p_monto_ars numeric, p_forma_pago_id uuid, p_referencia text, p_descripcion text, p_observaciones text, p_detalles jsonb) RETURNS reciclaje2.operaciones
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'reciclaje2'
    AS $$
DECLARE
    v_result reciclaje2.operaciones%ROWTYPE;
BEGIN
    IF p_company_id IS NULL THEN
        RAISE EXCEPTION 'company_id es obligatorio'
            USING ERRCODE = '22004';
    END IF;

    IF NOT EXISTS (SELECT 1 FROM reciclaje2.tipos_operacion WHERE id = p_tipo_operacion_id) THEN
        RAISE EXCEPTION 'tipo_operacion_id no existe' USING ERRCODE = '23503';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM reciclaje2.etapas_operacion WHERE id = p_etapa_operacion_id) THEN
        RAISE EXCEPTION 'etapa_operacion_id no existe' USING ERRCODE = '23503';
    END IF;
    IF p_moneda_id IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM reciclaje2.monedas WHERE id = p_moneda_id) THEN
        RAISE EXCEPTION 'moneda_id no existe' USING ERRCODE = '23503';
    END IF;
    IF p_forma_pago_id IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM reciclaje2.formas_pago WHERE id = p_forma_pago_id) THEN
        RAISE EXCEPTION 'forma_pago_id no existe' USING ERRCODE = '23503';
    END IF;
    IF p_monto IS NOT NULL AND p_monto < 0 THEN
        RAISE EXCEPTION 'monto debe ser mayor o igual a cero' USING ERRCODE = '23514';
    END IF;
    IF p_tipo_cambio IS NOT NULL AND p_tipo_cambio <= 0 THEN
        RAISE EXCEPTION 'tipo_cambio debe ser mayor que cero' USING ERRCODE = '23514';
    END IF;
    IF p_monto_ars IS NOT NULL AND p_monto_ars < 0 THEN
        RAISE EXCEPTION 'monto_ars debe ser mayor o igual a cero' USING ERRCODE = '23514';
    END IF;
    IF p_detalles IS NULL OR jsonb_typeof(p_detalles) <> 'object' THEN
        RAISE EXCEPTION 'detalles debe ser un objeto JSON' USING ERRCODE = '23514';
    END IF;

    IF p_socio_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM reciclaje2.socios
        WHERE id = p_socio_id AND company_id = p_company_id
    ) THEN
        RAISE EXCEPTION 'socio_id no es válido para company_id'
            USING ERRCODE = '23503';
    END IF;

    IF p_transportista_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM reciclaje2.transportistas
        WHERE id = p_transportista_id AND company_id = p_company_id
    ) THEN
        RAISE EXCEPTION 'transportista_id no es válido para company_id'
            USING ERRCODE = '23503';
    END IF;

    IF p_deposito_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM reciclaje2.depositos
        WHERE id = p_deposito_id AND company_id = p_company_id
    ) THEN
        RAISE EXCEPTION 'deposito_id no es válido para company_id'
            USING ERRCODE = '23503';
    END IF;

    IF p_id IS NULL THEN
        INSERT INTO reciclaje2.operaciones (
            company_id, tipo_operacion_id, etapa_operacion_id, socio_id,
            grupo_transporte_id, grupo_dinero_id, transportista_id,
            deposito_id, direccion, ubicacion, monto, moneda_id,
            tipo_cambio, monto_ars, forma_pago_id, referencia,
            descripcion, observaciones, detalles
        ) VALUES (
            p_company_id, p_tipo_operacion_id, p_etapa_operacion_id, p_socio_id,
            p_grupo_transporte_id, p_grupo_dinero_id, p_transportista_id,
            p_deposito_id, p_direccion, p_ubicacion, p_monto, p_moneda_id,
            p_tipo_cambio, p_monto_ars, p_forma_pago_id, p_referencia,
            p_descripcion, p_observaciones, p_detalles
        )
        RETURNING * INTO v_result;
    ELSE
        UPDATE reciclaje2.operaciones
        SET tipo_operacion_id = p_tipo_operacion_id,
            etapa_operacion_id = p_etapa_operacion_id,
            socio_id = p_socio_id,
            grupo_transporte_id = p_grupo_transporte_id,
            grupo_dinero_id = p_grupo_dinero_id,
            transportista_id = p_transportista_id,
            deposito_id = p_deposito_id,
            direccion = p_direccion,
            ubicacion = p_ubicacion,
            monto = p_monto,
            moneda_id = p_moneda_id,
            tipo_cambio = p_tipo_cambio,
            monto_ars = p_monto_ars,
            forma_pago_id = p_forma_pago_id,
            referencia = p_referencia,
            descripcion = p_descripcion,
            observaciones = p_observaciones,
            detalles = p_detalles,
            updated_at = now()
        WHERE id = p_id
          AND company_id = p_company_id
        RETURNING * INTO v_result;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'operación no encontrada para company_id'
                USING ERRCODE = 'P0002';
        END IF;
    END IF;

    RETURN v_result;
END;
$$;


--
-- Name: FUNCTION upsert_operacion(p_id uuid, p_company_id uuid, p_tipo_operacion_id uuid, p_etapa_operacion_id uuid, p_socio_id uuid, p_grupo_transporte_id uuid, p_grupo_dinero_id uuid, p_transportista_id uuid, p_deposito_id uuid, p_direccion text, p_ubicacion text, p_monto numeric, p_moneda_id uuid, p_tipo_cambio numeric, p_monto_ars numeric, p_forma_pago_id uuid, p_referencia text, p_descripcion text, p_observaciones text, p_detalles jsonb); Type: COMMENT; Schema: reciclaje2; Owner: -
