--
-- Name: upsert_operacion_material(uuid, uuid, uuid, uuid, numeric, numeric, numeric, text); Type: FUNCTION; Schema: reciclaje2; Owner: -
--

CREATE FUNCTION reciclaje2.upsert_operacion_material(p_id uuid, p_company_id uuid, p_operacion_id uuid, p_material_id uuid, p_cantidad numeric, p_precio_unitario numeric, p_subtotal numeric, p_observaciones text) RETURNS reciclaje2.operacion_materiales
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'reciclaje2'
    AS $$
DECLARE
    v_result reciclaje2.operacion_materiales%ROWTYPE;
BEGIN
    IF p_company_id IS NULL THEN
        RAISE EXCEPTION 'company_id es obligatorio'
            USING ERRCODE = '22004';
    END IF;

    IF p_cantidad IS NULL OR p_cantidad <= 0 THEN
        RAISE EXCEPTION 'cantidad debe ser mayor que cero' USING ERRCODE = '23514';
    END IF;
    IF p_precio_unitario IS NULL OR p_precio_unitario < 0 THEN
        RAISE EXCEPTION 'precio_unitario debe ser mayor o igual a cero' USING ERRCODE = '23514';
    END IF;
    IF p_subtotal IS NULL OR p_subtotal < 0 THEN
        RAISE EXCEPTION 'subtotal debe ser mayor o igual a cero' USING ERRCODE = '23514';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM reciclaje2.operaciones
        WHERE id = p_operacion_id AND company_id = p_company_id
    ) THEN
        RAISE EXCEPTION 'operacion_id no es válido para company_id'
            USING ERRCODE = '23503';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM reciclaje2.materiales
        WHERE id = p_material_id AND company_id = p_company_id
    ) THEN
        RAISE EXCEPTION 'material_id no es válido para company_id'
            USING ERRCODE = '23503';
    END IF;

    IF p_id IS NULL THEN
        INSERT INTO reciclaje2.operacion_materiales (
            company_id, operacion_id, material_id, cantidad,
            precio_unitario, subtotal, observaciones
        ) VALUES (
            p_company_id, p_operacion_id, p_material_id, p_cantidad,
            p_precio_unitario, p_subtotal, p_observaciones
        )
        RETURNING * INTO v_result;
    ELSE
        UPDATE reciclaje2.operacion_materiales
        SET operacion_id = p_operacion_id,
            material_id = p_material_id,
            cantidad = p_cantidad,
            precio_unitario = p_precio_unitario,
            subtotal = p_subtotal,
            observaciones = p_observaciones,
            updated_at = now()
        WHERE id = p_id
          AND company_id = p_company_id
        RETURNING * INTO v_result;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'material de operación no encontrado para company_id'
                USING ERRCODE = 'P0002';
        END IF;
    END IF;

    RETURN v_result;
END;
$$;


