--
-- Name: upsert_presupuesto_gasto(uuid, date, uuid, numeric); Type: FUNCTION; Schema: reciclaje2; Owner: -
--

CREATE FUNCTION reciclaje2.upsert_presupuesto_gasto(p_company_id uuid, p_periodo date, p_moneda_id uuid, p_limite numeric) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'reciclaje2'
    AS $$
DECLARE v_periodo date; v_result reciclaje2.presupuestos_gastos%ROWTYPE;
BEGIN
 IF p_company_id IS NULL OR p_periodo IS NULL OR p_moneda_id IS NULL OR p_limite IS NULL THEN
   RAISE EXCEPTION 'company_id, periodo, moneda_id y limite son obligatorios' USING ERRCODE='22004'; END IF;
 IF p_limite<0 THEN RAISE EXCEPTION 'limite no puede ser negativo' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS(SELECT 1 FROM reciclaje2.monedas WHERE id=p_moneda_id) THEN RAISE EXCEPTION 'moneda_id no existe' USING ERRCODE='23503'; END IF;
 v_periodo:=date_trunc('month',p_periodo)::date;
 INSERT INTO reciclaje2.presupuestos_gastos(company_id,periodo,moneda_id,limite)
 VALUES(p_company_id,v_periodo,p_moneda_id,p_limite)
 ON CONFLICT(company_id,periodo,moneda_id) DO UPDATE SET limite=EXCLUDED.limite,updated_at=now()
 RETURNING * INTO v_result;
 RETURN to_jsonb(v_result);
END;$$;


--
-- Name: adjust_stock(uuid, uuid, integer, text); Type: FUNCTION; Schema: tenant; Owner: -
--

CREATE FUNCTION tenant.adjust_stock(p_company_id uuid, p_product_id uuid, p_quantity integer, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_user uuid;
BEGIN
  v_user := current_setting('app.user_id', true)::uuid;

  INSERT INTO tenant.stock_movements (
    company_id,
    product_id,
    movement_type,
    quantity,
    reason,
    created_by
  )
  VALUES (
    p_company_id,
    p_product_id,
    'adjustment',
    p_quantity,
    p_reason,
    v_user
  );

  UPDATE tenant.products
  SET stock = stock + p_quantity
  WHERE id = p_product_id
    AND company_id = p_company_id;
END;
$$;


--
-- Name: bootstrap_company(text, text, text, text, text, text); Type: FUNCTION; Schema: tenant; Owner: -
--

CREATE FUNCTION tenant.bootstrap_company(p_bootstrap_key text, p_company_name text, p_company_slug text, p_admin_email text, p_admin_password text, p_admin_nombre text) RETURNS TABLE(company_id uuid, user_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_company_id uuid;
  v_user_id uuid;
  v_expected_key text;
begin

  -- 🔐 leer clave esperada desde config
  v_expected_key := current_setting('app.bootstrap_key', true);

  if v_expected_key is null or v_expected_key <> p_bootstrap_key then
    raise exception 'invalid bootstrap key';
  end if;

  insert into tenant.companies (name, slug)
  values (p_company_name, p_company_slug)
  returning id into v_company_id;

  insert into tenant.users (
    company_id,
    email,
    password,
    nombre,
    tipo_usuario
  )
  values (
    v_company_id,
    p_admin_email,
    p_admin_password,
    p_admin_nombre,
    'admin'
  )
  returning id into v_user_id;

  -- 🚀 SEED CRM DEFAULT
  perform tenant.crm_seed_default(v_company_id);

  return query
  select v_company_id, v_user_id;

end;
$$;


--
-- Name: bootstrap_demo_company(); Type: FUNCTION; Schema: tenant; Owner: -
--

CREATE FUNCTION tenant.bootstrap_demo_company() RETURNS TABLE(company_id uuid, user_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_company_id uuid;
  v_user_id uuid;
  v_slug text := 'demo_' || substr(gen_random_uuid()::text,1,8);
  v_now timestamptz := now();
  v_active_demos int;
begin

  perform set_config('search_path', 'tenant, public', true);

  -- 🔥 1️⃣ Contar demos activas
  select count(*)::int
  into v_active_demos
  from tenant.companies
  where is_demo = true
    and demo_expires_at > now();

  if v_active_demos >= 10 then
    raise exception 'demo_capacity_reached'
      using errcode = 'P0001';
  end if;

  -- 2️⃣ Crear empresa demo
  insert into tenant.companies(
    name,
    slug,
    is_demo,
    demo_expires_at
  )
  values (
    'Demo Company',
    v_slug,
    true,
    v_now + interval '30 minutes'
  )
  returning id into v_company_id;

  -- 3️⃣ Crear usuario admin demo
  insert into tenant.users(
    company_id,
    email,
    password,
    nombre,
    tipo_usuario
  )
  values (
    v_company_id,
    v_slug || '@demo.local',
    crypt(gen_random_uuid()::text, gen_salt('bf')),
    'Demo',
    'admin'
  )
  returning id into v_user_id;

  -- 🚀 SEED CRM DEFAULT
  perform tenant.crm_seed_default(v_company_id);

  return query
  select v_company_id, v_user_id;

end;
$$;


--
-- Name: calculate_combo_stock(uuid); Type: FUNCTION; Schema: tenant; Owner: -
--

CREATE FUNCTION tenant.calculate_combo_stock(p_product_id uuid) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare
  v_component jsonb;
  v_min_stock integer := null;
  v_component_stock integer;
  v_qty integer;
begin

  for v_component in
    select *
    from jsonb_array_elements(
      (
        select coalesce(metadata->'components','[]'::jsonb)
        from tenant.product_metadata
        where product_id = p_product_id
      )
    )
  loop

    v_qty := (v_component->>'quantity')::int;

    select stock
    into v_component_stock
    from tenant.products
    where id = (v_component->>'product_id')::uuid;

    v_component_stock := floor(v_component_stock / v_qty);

    if v_min_stock is null or v_component_stock < v_min_stock then
      v_min_stock := v_component_stock;
    end if;

  end loop;

  return coalesce(v_min_stock, 0);
end;
$$;


--
-- Name: cancel_order(uuid, uuid); Type: FUNCTION; Schema: tenant; Owner: -
--

CREATE FUNCTION tenant.cancel_order(p_company_id uuid, p_order_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
    v_order tenant.orders;
    v_item record;
begin

    -- =========================================
    -- VALIDAR
    -- =========================================

    select *
    into v_order
    from tenant.orders
    where id = p_order_id
      and company_id = p_company_id
      and status = 'reserved'
    for update;

    if not found then
        raise exception 'order_not_found';
    end if;

    -- =========================================
    -- LIBERAR STOCK
    -- =========================================

    for v_item in
        select *
        from tenant.order_items
        where order_id = p_order_id
    loop

        update tenant.products
        set reserved_stock =
            greatest(
                0,
                reserved_stock - v_item.quantity
            )
        where id = v_item.product_id
          and company_id = p_company_id;

    end loop;

    -- =========================================
    -- CANCELAR
    -- =========================================

    update tenant.orders
    set
        status = 'cancelled',
        cancelled_at = now()
    where id = p_order_id;

    return true;

end;
$$;


--
-- Name: cancel_sale(uuid, uuid); Type: FUNCTION; Schema: tenant; Owner: -
--

CREATE FUNCTION tenant.cancel_sale(p_company_id uuid, p_sale_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_role text;
  v_item record;
BEGIN

  v_role := current_setting('app.current_role', true);

  IF v_role NOT IN ('admin', 'supervisor') THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  -- 🔁 devolver stock
  FOR v_item IN
    SELECT product_id, quantity
    FROM tenant.sale_items
    WHERE sale_id = p_sale_id
  LOOP

    UPDATE tenant.products
    SET stock = stock + v_item.quantity
    WHERE id = v_item.product_id
      AND company_id = p_company_id;

    INSERT INTO tenant.stock_movements (
      company_id,
      product_id,
      movement_type,
      quantity,
      reference_id
    )
    VALUES (
      p_company_id,
      v_item.product_id,
      'cancel',
      v_item.quantity,
      p_sale_id
    );

  END LOOP;

  -- 🔥 marcar cancelada
  UPDATE tenant.sales
  SET status = 'cancelled'
  WHERE id = p_sale_id
    AND company_id = p_company_id;

END;
$$;


--
-- Name: cash_closing_report(uuid, date); Type: FUNCTION; Schema: tenant; Owner: -
--

CREATE FUNCTION tenant.cash_closing_report(p_company_id uuid, p_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_role text;
BEGIN
    -- Configurar contexto
    PERFORM set_config('search_path', 'tenant, public', true);
    PERFORM set_config('row_security', 'off', true);

    v_role := current_setting('app.current_role', true);

    -- Solo administradores y supervisores
    IF v_role NOT IN ('admin', 'supervisor') THEN
        RAISE EXCEPTION 'forbidden';
    END IF;

    RETURN (
        SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb)
        FROM (
            SELECT
                u.id AS user_id,
                u.nombre AS operador,
                u.codigo_empleado,
                MIN(s.created_at) AS hora_ingreso,
                MAX(s.created_at) AS hora_ultima_venta,
                COUNT(s.id) AS total_ventas,
                COALESCE(SUM(s.total) FILTER (
                    WHERE s.payment_method = 'cash'
                ), 0) AS efectivo,
                COALESCE(SUM(s.total) FILTER (
                    WHERE s.payment_method = 'card'
                ), 0) AS tarjeta,
                COALESCE(SUM(s.total) FILTER (
                    WHERE s.payment_method = 'transfer'
                ), 0) AS transferencia,
                COALESCE(SUM(s.total), 0) AS total_facturado
            FROM tenant.users u
            LEFT JOIN tenant.sales s
                ON s.created_by = u.id
                AND s.company_id = p_company_id
                AND s.created_at::date = p_date
                AND COALESCE(s.status, 'pending') IN ('pending', 'confirmed')
            WHERE u.company_id = p_company_id
              AND u.tipo_usuario IN ('operador', 'supervisor', 'admin')
            GROUP BY u.id, u.nombre, u.codigo_empleado
        ) t
    );
END;
$$;


--
-- Name: cleanup_expired_demos(); Type: FUNCTION; Schema: tenant; Owner: -
--

CREATE FUNCTION tenant.cleanup_expired_demos() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_company_id uuid;
BEGIN
  FOR v_company_id IN
    SELECT id
    FROM tenant.companies
    WHERE is_demo = true
      AND demo_expires_at < now()
  LOOP
    -- Eliminar movimientos de stock
    DELETE FROM tenant.stock_movements
    WHERE company_id = v_company_id;

    -- Eliminar items de venta
    DELETE FROM tenant.sale_items
    WHERE sale_id IN (
      SELECT id FROM tenant.sales
      WHERE company_id = v_company_id
    );

    -- Eliminar ventas
    DELETE FROM tenant.sales
    WHERE company_id = v_company_id;

    -- Eliminar productos
    DELETE FROM tenant.products
    WHERE company_id = v_company_id;

    -- Eliminar usuarios
    DELETE FROM tenant.users
    WHERE company_id = v_company_id;

    -- Eliminar datos del CRM
    DELETE FROM tenant.crm_activities WHERE company_id = v_company_id;
    DELETE FROM tenant.crm_contacts WHERE company_id = v_company_id;
    DELETE FROM tenant.crm_leads WHERE company_id = v_company_id;
    DELETE FROM tenant.crm_stages WHERE company_id = v_company_id;
    DELETE FROM tenant.crm_pipelines WHERE company_id = v_company_id;

    -- Eliminar perfil
    DELETE FROM tenant.company_profile
    WHERE company_id = v_company_id;

    -- Finalmente eliminar la empresa
    DELETE FROM tenant.companies
    WHERE id = v_company_id;
  END LOOP;
END;
$$;


--
-- Name: confirm_order(uuid, uuid, text); Type: FUNCTION; Schema: tenant; Owner: -
--

CREATE FUNCTION tenant.confirm_order(p_company_id uuid, p_order_id uuid, p_payment_method text DEFAULT 'transfer'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
    v_order tenant.orders;
    v_items jsonb;
    v_sale_id uuid;
    v_item record;
begin

    -- =========================================
    -- VALIDAR ORDER
    -- =========================================

    select *
    into v_order
    from tenant.orders
    where id = p_order_id
      and company_id = p_company_id
      and status = 'reserved'
      and expires_at > now()
    for update;

    if not found then
        raise exception 'order_not_available';
    end if;

    -- =========================================
    -- ARMAR ITEMS JSON
    -- =========================================

    select jsonb_agg(
        jsonb_build_object(
            'product_id', oi.product_id,
            'quantity', oi.quantity,
            'price', oi.unit_price
        )
    )
    into v_items
    from tenant.order_items oi
    where oi.order_id = p_order_id;

    if v_items is null then
        raise exception 'empty_order';
    end if;

    -- =========================================
    -- CREAR SALE
    -- =========================================

    v_sale_id := tenant.create_sale(
        p_company_id,
        v_items,
        p_payment_method
    );

    -- =========================================
    -- LIBERAR RESERVED STOCK
    -- =========================================

    for v_item in
        select *
        from tenant.order_items
        where order_id = p_order_id
    loop

        update tenant.products
        set reserved_stock =
            greatest(
                0,
                reserved_stock - v_item.quantity
            )
        where id = v_item.product_id
          and company_id = p_company_id;

    end loop;

    -- =========================================
    -- CERRAR ORDER
    -- =========================================

    update tenant.orders
    set
        status = 'paid',
        confirmed_at = now()
    where id = p_order_id;

    return v_sale_id;

end;
$$;


--
-- Name: confirm_sale(uuid, uuid); Type: FUNCTION; Schema: tenant; Owner: -
--

CREATE FUNCTION tenant.confirm_sale(p_company_id uuid, p_sale_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_role text;
BEGIN

  v_role := current_setting('app.current_role', true);

  -- solo admin o caja
  IF v_role NOT IN ('admin','supervisor') THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  UPDATE tenant.sales
  SET status = 'confirmed'
  WHERE id = p_sale_id
    AND company_id = p_company_id;

END;
$$;


