CREATE TABLE tenant.orders (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    lead_id uuid NOT NULL,
    status text DEFAULT 'reserved'::text NOT NULL,
    total numeric(12,2) DEFAULT 0 NOT NULL,
    expires_at timestamp with time zone DEFAULT (now() + '24:00:00'::interval) NOT NULL,
    created_by uuid,
    confirmed_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    confirmed_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    expired_at timestamp with time zone,
    notes text,
    CONSTRAINT orders_status_check CHECK ((status = ANY (ARRAY['reserved'::text, 'paid'::text, 'cancelled'::text, 'expired'::text])))
);


--
-- Name: create_order_from_lead(uuid, uuid, uuid); Type: FUNCTION; Schema: tenant; Owner: -
--

CREATE FUNCTION tenant.create_order_from_lead(p_company_id uuid, p_lead_id uuid, p_created_by uuid) RETURNS tenant.orders
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
    v_order tenant.orders;
begin

    -- =========================================
    -- VALIDAR LEAD
    -- =========================================
    if not exists (
        select 1
        from tenant.crm_leads l
        where l.id = p_lead_id
          and l.company_id = p_company_id
    ) then
        raise exception 'lead_not_found';
    end if;

    -- =========================================
    -- CANCELAR ÓRDENES RESERVADAS VENCIDAS
    -- =========================================
    update tenant.orders
    set
        status = 'expired',
        expired_at = now()
    where company_id = p_company_id
      and status = 'reserved'
      and expires_at < now();

    -- =========================================
    -- BUSCAR ÚLTIMA ORDEN DEL LEAD
    -- =========================================
    select *
    into v_order
    from tenant.orders
    where company_id = p_company_id
      and lead_id = p_lead_id
    order by created_at desc
    limit 1;

    -- =========================================
    -- VALIDAR ÚLTIMA ORDEN
    -- =========================================
    if found then

        if v_order.status = 'confirmed' then
            raise exception 'order_already_confirmed';
        end if;

        if v_order.status = 'paid' then
            raise exception 'order_already_paid';
        end if;

        if v_order.status = 'reserved'
           and v_order.expires_at > now()
        then
            return v_order;
        end if;

    end if;

    -- =========================================
    -- CREAR ORDER
    -- =========================================
    insert into tenant.orders (
        company_id,
        lead_id,
        status,
        expires_at,
        created_by
    )
    values (
        p_company_id,
        p_lead_id,
        'reserved',
        now() + interval '24 hours',
        p_created_by
    )
    returning *
    into v_order;

    return v_order;

end;
$$;


