CREATE TABLE tenant.users (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    email text NOT NULL,
    password text NOT NULL,
    nombre text,
    apellido text,
    avatar text,
    codigo_empleado text,
    tipo_usuario text,
    active boolean DEFAULT true NOT NULL,
    created_at timestamp without time zone DEFAULT now()
);


--
-- Name: create_user(uuid, text, text, text); Type: FUNCTION; Schema: tenant; Owner: -
--

CREATE FUNCTION tenant.create_user(p_company_id uuid, p_nombre text, p_tipo_usuario text, p_password text) RETURNS tenant.users
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_role text;
  v_user tenant.users;
  v_email text;
  v_codigo text;
begin

  v_role := current_setting('app.current_role', true);

  if v_role <> 'admin' then
    raise exception 'forbidden';
  end if;

  if p_tipo_usuario not in ('operador','supervisor') then
    raise exception 'invalid role';
  end if;

  -- 🔥 email interno
  v_email := lower(replace(p_nombre, ' ', '')) 
             || '_' 
             || substr(gen_random_uuid()::text,1,6) 
             || '@local';

  -- 🔥 codigo empleado (6 chars alfanuméricos)
  v_codigo := upper(substr(md5(random()::text), 1, 6));

  insert into tenant.users (
    company_id,
    nombre,
    tipo_usuario,
    password,
    email,
    codigo_empleado
  )
  values (
    p_company_id,
    p_nombre,
    p_tipo_usuario,
    p_password,
    v_email,
    v_codigo
  )
  returning * into v_user;

  return v_user;

end;
$$;


--
-- Name: create_user_simple(uuid, text); Type: FUNCTION; Schema: tenant; Owner: -
--

CREATE FUNCTION tenant.create_user_simple(p_company_id uuid, p_nombre text) RETURNS tenant.users
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_role text;
  v_user tenant.users;
BEGIN

  -- validar admin
  v_role := current_setting('app.current_role', true);

  IF v_role <> 'admin' THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  INSERT INTO tenant.users (
    company_id,
    nombre,
    tipo_usuario
  )
  VALUES (
    p_company_id,
    p_nombre,
    'vendedor'
  )
  RETURNING * INTO v_user;

  RETURN v_user;

END;
$$;


