-- Name: hechos_dinero; Type: TABLE; Schema: reciclaje2; Owner: -
--

CREATE TABLE reciclaje2.hechos_dinero (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    evento_id uuid NOT NULL,
    tipo character varying(30) NOT NULL,
    operacion_id uuid,
    grupo_transporte_id uuid,
    grupo_dinero_id uuid,
    finanza_id uuid,
    tipo_gasto_id uuid,
    monto numeric(14,2) NOT NULL,
    moneda_id uuid NOT NULL,
    tipo_cambio numeric(14,6) NOT NULL,
    monto_base numeric(14,2) NOT NULL,
    tipo_cambio_id uuid,
    monto_aplicado numeric(14,2),
    monto_pendiente numeric(14,2),
    tipo_cambio_aplicacion numeric(14,6),
    tipo_cambio_aplicacion_id uuid,
    impacto_caja character varying(20),
    responsable_tipo character varying(50),
    responsable_id uuid,
    responsable_nombre text,
    sentido_diferencia character varying(30),
    concepto text NOT NULL,
    observaciones text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    origen_fondos character varying(20),
    modelo_version smallint DEFAULT 1 NOT NULL,
    afecta_posicion_fisica boolean,
    CONSTRAINT hechos_dinero_aplicado_requiere_finanza CHECK (((monto_aplicado IS NULL) OR (finanza_id IS NOT NULL))),
    CONSTRAINT hechos_dinero_concepto_no_vacio CHECK ((btrim(concepto) <> ''::text)),
    CONSTRAINT hechos_dinero_impacto_caja_valido CHECK (((impacto_caja IS NULL) OR ((impacto_caja)::text = ANY ((ARRAY['entrada'::character varying, 'salida'::character varying])::text[])))),
    CONSTRAINT hechos_dinero_liquidacion_coherente CHECK ((((tipo)::text <> 'liquidacion_operacion'::text) OR ((monto_pendiente IS NOT NULL) AND (monto_pendiente <= monto)))),
    CONSTRAINT hechos_dinero_modelo_version_positivo CHECK ((modelo_version > 0)),
    CONSTRAINT hechos_dinero_monto_aplicado_valido CHECK (((monto_aplicado IS NULL) OR (monto_aplicado > (0)::numeric))),
    CONSTRAINT hechos_dinero_monto_base_coherente CHECK ((abs((monto_base - round((monto * tipo_cambio), 2))) <= 0.01)),
    CONSTRAINT hechos_dinero_monto_base_no_negativo CHECK ((monto_base >= (0)::numeric)),
    CONSTRAINT hechos_dinero_monto_pendiente_valido CHECK (((monto_pendiente IS NULL) OR (monto_pendiente >= (0)::numeric))),
    CONSTRAINT hechos_dinero_monto_positivo CHECK ((monto > (0)::numeric)),
    CONSTRAINT hechos_dinero_origen_fondos_valido CHECK (((origen_fondos IS NULL) OR ((origen_fondos)::text = ANY ((ARRAY['entrega'::character varying, 'caja'::character varying, 'responsable'::character varying])::text[])))),
    CONSTRAINT hechos_dinero_responsable_contexto CHECK (((responsable_id IS NULL) OR ((responsable_tipo IS NOT NULL) AND (btrim((responsable_tipo)::text) <> ''::text) AND (responsable_nombre IS NOT NULL) AND (btrim(responsable_nombre) <> ''::text)))),
    CONSTRAINT hechos_dinero_sentido_diferencia_valido CHECK (((sentido_diferencia IS NULL) OR (((tipo)::text = 'diferencia'::text) AND ((sentido_diferencia)::text = ANY ((ARRAY['a_cargo_responsable'::character varying, 'a_favor_responsable'::character varying])::text[]))))),
    CONSTRAINT hechos_dinero_tipo_cambio_aplicacion_positivo CHECK (((tipo_cambio_aplicacion IS NULL) OR (tipo_cambio_aplicacion > (0)::numeric))),
    CONSTRAINT hechos_dinero_tipo_cambio_positivo CHECK ((tipo_cambio > (0)::numeric)),
    CONSTRAINT hechos_dinero_tipo_no_vacio CHECK ((btrim((tipo)::text) <> ''::text))
);


--
-- Name: COLUMN hechos_dinero.afecta_posicion_fisica; Type: COMMENT; Schema: reciclaje2; Owner: -
--

COMMENT ON COLUMN reciclaje2.hechos_dinero.afecta_posicion_fisica IS 'Clasifica exclusivamente diferencias: true descarga/corrige custodia; false es documental; NULL conserva historia no clasificable o no aplica.';


